<style>
/* Riders-Live = compact panel of ROWS (fits ~5 riders on the right of row 2,
   like the old board). Row click = dispatch tracker; filter icon = filter table. */
#nfRiderCards{border:1px solid #e2e8f0;border-radius:11px;background:#fff;box-shadow:0 1px 2px rgba(15,23,42,.05);overflow:hidden;min-width:300px;max-width:460px}
#nfRiderCards > div:first-child{padding:6px 12px;border-bottom:1px solid #eef2f7;background:#f8fafc;margin-bottom:0 !important}
#nfRiderCardsRow{flex-direction:column !important;gap:0 !important;flex-wrap:nowrap !important;justify-content:flex-start !important;max-height:190px;overflow-y:auto}
#nfRiderCards .nfrc-row{display:flex;align-items:center;gap:9px;padding:7px 12px;border-bottom:1px solid #f3f4f6;cursor:pointer;transition:background .12s}
#nfRiderCards .nfrc-row:last-child{border-bottom:0}
/* Off duty = holds open orders but has NOT checked in today. Deliberately the
   QUIETEST row style, and deliberately declared BEFORE :hover/.nfrc-sel/.nfrc-red/
   .nfrc-amber (same specificity, later wins) so hover, selection and the two alert
   colours all still out-rank it — an off-duty rider who left without dispatching
   must stay red. */
#nfRiderCards .nfrc-row.nfrc-off{background:#fcfcfd}
/* The off-duty tag costs ~55px of a row that is already tight at the panel's 300px
   minimum, so give those rows a shorter name cell (it already ellipsises) rather
   than let a row run past the panel edge. */
#nfRiderCards .nfrc-row.nfrc-off .nfrc-nm{color:#64748b;font-weight:600;max-width:96px}
#nfRiderCards .nfrc-offtag{font-size:8.5px;font-weight:800;letter-spacing:.03em;text-transform:uppercase;color:#64748b;background:#f1f5f9;border:1px solid #e2e8f0;border-radius:999px;padding:1px 5px;flex:none;line-height:1.5}
#nfRiderCards .nfrc-row:hover{background:#f8fafc}
#nfRiderCards .nfrc-row.nfrc-sel{background:#eff4ff;box-shadow:inset 3px 0 0 #2563eb}
#nfRiderCards .nfrc-row.nfrc-red{background:#fef2f2;box-shadow:inset 3px 0 0 #ef4444}
#nfRiderCards .nfrc-row.nfrc-amber{background:#fff7ed;box-shadow:inset 3px 0 0 #f59e0b}
#nfRiderCards .nfrc-dot{width:8px;height:8px;border-radius:50%;flex:none}
#nfRiderCards .nfrc-nm{font-weight:650;font-size:12.5px;color:#0f172a;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:120px}
#nfRiderCards .nfrc-row.nfrc-red .nfrc-nm{color:#b91c1c}
#nfRiderCards .nfrc-row.nfrc-amber .nfrc-nm{color:#b45309}
#nfRiderCards .nfrc-st{font-size:11.5px;color:#475569;white-space:nowrap;margin-left:auto;font-variant-numeric:tabular-nums}
#nfRiderCards .nfrc-f{width:24px;height:24px;border-radius:6px;border:1px solid #e2e8f0;background:#fff;color:#94a3b8;flex:none;display:inline-flex;align-items:center;justify-content:center;cursor:pointer}
#nfRiderCards .nfrc-f:hover{border-color:#2563eb;color:#2563eb;background:#eff4ff}
#nfRiderCards .nfrc-row.nfrc-sel .nfrc-f{border-color:#2563eb;color:#2563eb}
#nfRiderChip{display:inline-flex;align-items:center;gap:6px;font-size:11.5px;font-weight:600;color:#2563eb;background:#eff4ff;border:1px solid #ddd6fe;padding:3px 9px;border-radius:999px;cursor:pointer;margin-left:8px}
</style>
<script>
(function(){
  function esc(s){ var d=document.createElement('div'); d.textContent=(s==null?'':String(s)); return d.innerHTML; }

  window.nfRenderRiderCards = function(sorted, gps, disp){
    var row = document.getElementById('nfRiderCardsRow');
    if(!row) return;
    var cards = (sorted||[]).map(function(r){ return nfRiderCardHtml(r, (gps||{})[r.rider_id], (disp||{})[r.rider_id]); });
    // Aggregate "Unassigned" card from the currently-loaded open orders.
    var unassigned = (window.ordersData||[]).filter(function(o){
      return !o.assigned_rider_user_id && ['delivered','completed','cancelled','refunded'].indexOf(o.order_status) === -1;
    }).length;
    cards.push(nfUnassignedCardHtml(unassigned));
    row.innerHTML = cards.join('');
    // Re-apply an active filter after a refresh so the selection sticks.
    if(window.__nfRiderFilter != null){
      var sel = row.querySelector('[data-rider="'+window.__nfRiderFilter+'"]');
      if(sel) sel.classList.add('nfrc-sel');
    }
    var meta = document.getElementById('nfRiderCardsMeta');
    if(meta) meta.textContent = 'updated ' + new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'});
  };

  // A compact ROW per rider. Two clear affordances:
  //   • click the row body  -> FILTER the table to just this rider's orders
  //                            (the frequent action; row gets a selected highlight)
  //   • the map-pin icon     -> open the dispatch tracker + map popup
  //                            (the "dispatch level details" the old board showed)
  function nfRiderCardHtml(rider, gps, disp){
    var id = rider.rider_id;
    var name = rider.rider_name || ('Rider #'+id);
    var safe = String(name).replace(/'/g, "\\'");
    var status = (disp||{}).status;
    var ageMin = (gps && gps.age_minutes != null) ? gps.age_minutes : null;
    var dot = '#9ca3af';
    if(gps && gps.is_fresh){ dot = '#10b981'; }
    else if(ageMin != null && ageMin <= 60){ dot = '#f59e0b'; }

    // Aug-2026: the panel now lists riders who have NOT checked in (loadRiderLiveBoard
    // keeps them when they hold open orders), so every row states which it is.
    // is_checked_in is set there; the `=== false` test means "known to be off duty"
    // and leaves anything rendered without the flag looking exactly as before.
    var offDuty = (rider.is_checked_in === false);
    var open = rider.total_count || 0;

    // Opening line for a rider with NO dispatch entry — i.e. nothing of his is out
    // for delivery, so the tracker has nothing to say about him. The old blanket
    // "No active dispatch" was true but useless; these three say why he is listed.
    var st = offDuty ? (open + ' order' + (open === 1 ? '' : 's') + ' waiting')
           : (open > 0 ? ('📋 ' + open + ' assigned') : '✓ On duty · free');
    var cls = '';
    var gpsLost = (typeof riderGpsLostMidDelivery === 'function') && riderGpsLostMidDelivery(gps, disp);
    /* 🔧⭐⭐ THE WORKSHOP ERRAND, on the card the owner asked for (10-Sep-2026).
         Checked BEFORE everything else, including the red warning and the GPS-lost line:
         a man riding to the workshop has left the office without dispatching and his GPS is
         moving away, which is exactly what those two alarms look for — and here it is not an
         alarm, it is the instruction he was given. Amber, because "do not give this man an
         order" is the one thing the dispatcher must read off this row.
         ⚠ The sentence is the SERVER's (`workshop_trip.label`) — the same words the store
         phone, the van board and the push all use, so the ETA cannot be phrased two ways. */
    /* ⚠ `disp` is UNDEFINED for every rider with nothing out for delivery — off-duty riders holding
       orders and free on-duty riders alike (the live-status map is keyed only by dispatch rows).
       Reading `.workshop_trip` off it threw, the whole map() aborted, and the panel went blank
       (11-Sep-2026). Every sibling helper already guards with `(disp||{})`; so does this now. */
    var wsTrip = (disp || {}).workshop_trip || null;
    if(status === 'workshop_en_route' || status === 'at_workshop'){
      st = (wsTrip && wsTrip.label) ? wsTrip.label
         : (status === 'at_workshop' ? '🔧 At the workshop' : '🔧 Going to the workshop');
      if(open > 0){ st += ' · ' + open + ' assigned'; }
      cls = 'nfrc-amber';
    }
    else if(status === 'left_without_dispatch'){ st = '⚠ Left w/o dispatch · ' + (disp.undispatched_count||0); cls = 'nfrc-red'; }
    else if(gpsLost){ st = '📍 GPS lost · ' + (disp.dispatched_count||0) + ' left'; cls = 'nfrc-amber'; dot = '#ef4444'; }
    else if(status === 'on_route'){ st = '🚚 On route · ' + (disp.dispatched_count||0) + ' left'; }
    else if(status === 'returning'){ var m = (disp.return_to_office && disp.return_to_office.minutes != null) ? disp.return_to_office.minutes : null; st = '↩️ Returning' + (m != null ? (' · ~' + m + 'min') : '') + (disp.undispatched_count > 0 ? (' · ' + disp.undispatched_count + ' to go') : ''); cls = 'nfrc-blue'; }
    else if(status === 'waiting_at_office'){ st = '🏠 At office · ' + (disp.undispatched_count||0) + ' to dispatch'; cls = 'nfrc-amber'; }
    else if(status === 'at_office'){ st = '🏠 At office'; }

    var selCls = (String(window.__nfRiderFilter) === String(id)) ? ' nfrc-sel' : '';
    // nfrc-off is kept SEPARATE from cls: a rider can be off duty AND mid-alert
    // (dispatch tracking keys off out_for_delivery orders, not attendance), and
    // that combination — out delivering without checking in — is the one you most
    // need to see. So the alert colour and the off-duty tag stack, never replace.
    var offCls = offDuty ? ' nfrc-off' : '';
    var offTag = offDuty ? '<span class="nfrc-offtag" title="No attendance check-in today">off duty</span>' : '';
    var rowTitle = 'Click to show only ' + name + "'s orders" + (offDuty ? ' — not checked in today' : '');
    /* The hover line spells the errand out in full: where, since when, and the ETA. The chip
       itself has to stay short enough to sit in a 300px card. */
    if(wsTrip){
      rowTitle = (wsTrip.label || 'At the workshop')
        + (wsTrip.visit_time ? ' · appointment ' + wsTrip.visit_time : '')
        + (wsTrip.vehicle_name ? ' · ' + wsTrip.vehicle_name : '')
        /* ⚠⚠ WAS "do not assign him orders" — wrong as of 11-Sep. Assigning and marking out
             for delivery are desk actions and are explicitly allowed; the only thing that has
             to wait for him is DISPATCH. This tooltip sits on the very card a dispatcher uses
             to pick a rider, so it was telling him not to do what the release had unblocked. */
        + ' — assign freely; dispatch when he is back.';
    }
    return '<div class="nfrc-row '+cls+offCls+selCls+'" data-rider="'+id+'" onclick="nfFilterTableByRider('+id+", '"+safe+"')\" title=\""+esc(rowTitle)+"\">"
      + '<span class="nfrc-dot" style="background:'+dot+'"></span>'
      + '<span class="nfrc-nm" title="'+esc(name)+'">'+esc(name)+'</span>'
      + offTag
      + '<span class="nfrc-st">'+esc(st)+'</span>'
      + '<button class="nfrc-f" title="Dispatch details + map" onclick="event.stopPropagation(); openRiderDispatchPopup('+id+", '"+safe+"')\">"
      + '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 21s-7-6.5-7-11a7 7 0 0114 0c0 4.5-7 11-7 11z"/><circle cx="12" cy="10" r="2.5"/></svg></button>'
      + '</div>';
  }

  function nfUnassignedCardHtml(n){
    var selCls = (window.__nfRiderFilter === '__unassigned__') ? ' nfrc-sel' : '';
    return '<div class="nfrc-row nfrc-unassigned'+selCls+'" data-rider="__unassigned__" onclick="nfFilterTableByRider(\'__unassigned__\', \'Unassigned\')" title="Click to show unassigned open orders">'
      + '<span class="nfrc-dot" style="background:#94a3b8"></span>'
      + '<span class="nfrc-nm">Unassigned</span>'
      + '<span class="nfrc-st">'+(n||0)+' need a rider</span>'
      + '</div>';
  }

  window.nfFilterTableByRider = function(riderId, label){
    if(String(window.__nfRiderFilter) === String(riderId)){ nfClearRiderFilter(); return; }
    window.__nfRiderFilter = riderId;
    window.__nfRiderLabel = label;
    document.querySelectorAll('#nfRiderCardsRow .nfrc-row').forEach(function(c){ c.classList.remove('nfrc-sel'); });
    var card = document.querySelector('#nfRiderCardsRow [data-rider="'+riderId+'"]');
    if(card) card.classList.add('nfrc-sel');
    window.nfRenderActiveFilters();
    // Refresh the open-orders data BEFORE filtering, so the filter reflects LIVE
    // assignments/dispatch rather than the page's load-time snapshot. This is
    // what fixes "click a rider -> table filters to empty" when the order was
    // assigned/dispatched/created after the page loaded (the Riders-Live board
    // polls fresh every 30s; the table snapshot did not). Fails safe: if the
    // refresh can't run, it filters whatever rows are already on screen (the
    // old behaviour). Self-contained so it can't destabilise the render pipeline.
    nfRefreshThenApplyRiderFilter();
  };
  // Re-pull the current open-orders view then apply the rider show/hide on the
  // FRESH rows. Only fires from a rider click. Delegates the refetch to the
  // shared helper so the rider filter and the "new orders" pill stay in lock-step.
  function nfRefreshThenApplyRiderFilter(){
    if(typeof window.nfRefreshCurrentOrdersView === 'function'){
      window.nfRefreshCurrentOrdersView().then(function(){ nfApplyRiderFilter(); });
    } else {
      nfApplyRiderFilter();
    }
  }
  // Shared: re-pull the CURRENT orders view (source/tab + any active search /
  // status / date filters) and re-render it via the shared renderer. Returns a
  // Promise that resolves once the table has been refreshed (resolves false on
  // failure — fail safe). Used by the rider filter AND the "new orders" pill.
  window.nfRefreshCurrentOrdersView = function(){
    return new Promise(function(resolve){
      try{
        var cur = new URL(window.location);
        var source = window.currentSource || cur.searchParams.get('source') || 'other';
        var tab = window.currentTab || cur.searchParams.get('tab') || 'open';
        var params = new URLSearchParams();
        params.append('source', source);
        params.append('tab', tab);
        var searchEl = document.getElementById('orderSearch');
        var term = searchEl ? String(searchEl.value || '').trim() : '';
        if(term) params.append('search', term);
        // Prefer the funnel status CARD (window.__nfStatusCard) so a rider click
        // made while a status card is active refetches WITHIN that status; fall
        // back to the "All status" dropdown otherwise.
        if(window.__nfStatusCard){ params.append('status', window.__nfStatusCard); }
        else { var statusEl = document.getElementById('statusFilter'); if(statusEl && statusEl.value) params.append('status', statusEl.value); }
        var dateEl = document.getElementById('dateFilter'); if(dateEl && dateEl.value) params.append('date', dateEl.value);
        var ddEl = document.getElementById('deliveryDateFilter'); if(ddEl && ddEl.value) params.append('delivery_date', ddEl.value);
        var container = document.querySelector('.orders-table-container');
        if(container) container.classList.add('opacity-60');
        fetch('/orders/filter?' + params.toString(), { headers:{ 'X-Requested-With':'XMLHttpRequest', 'Accept':'application/json' }, credentials:'same-origin' })
          .then(function(r){ return r.json(); })
          .then(function(d){
            if(d && d.success && Array.isArray(d.orders) && typeof renderOrdersWithFilters === 'function'){
              renderOrdersWithFilters(d.orders); // sets window.ordersData + re-renders the table body
            }
            resolve(true);
          })
          .catch(function(){ resolve(false); })
          .finally(function(){ if(container) container.classList.remove('opacity-60'); });
      }catch(e){ resolve(false); }
    });
  };
  function nfApplyRiderFilter(){
    var rid = window.__nfRiderFilter;
    var byId = {}; (window.ordersData||[]).forEach(function(o){ byId[String(o.id)] = o; });
    document.querySelectorAll('#table-body tr[data-order-id]').forEach(function(tr){
      var o = byId[tr.getAttribute('data-order-id')];
      var show = true;
      if(rid === '__unassigned__') show = !!(o && !o.assigned_rider_user_id);
      else if(rid != null) show = !!(o && String(o.assigned_rider_user_id) === String(rid));
      tr.style.display = show ? '' : 'none';
    });
  }
  // Exposed so any table rebuild (e.g. a status-card refetch) can re-apply the
  // active rider overlay on the fresh rows — this is what lets the rider filter
  // and the funnel status filter compose.
  window.nfReapplyRiderFilter = nfApplyRiderFilter;
  window.nfClearRiderFilter = function(){
    window.__nfRiderFilter = null;
    window.__nfRiderLabel = null;
    document.querySelectorAll('#nfRiderCardsRow .nfrc-row').forEach(function(c){ c.classList.remove('nfrc-sel'); });
    document.querySelectorAll('#table-body tr[data-order-id]').forEach(function(tr){ tr.style.display = ''; });
    // Re-render the unified chip (a status pill stays if a funnel status is active).
    window.nfRenderActiveFilters();
  };
  // Human label for a funnel status code (falls back to a prettified code).
  function nfStatusLabel(code){
    var m = { all:'All open', delivered_today:'Delivered today', out_for_delivery:'Out for delivery',
              new:'New', on_hold:'On hold', pending:'Pending', confirmed:'Confirmed',
              processing:'Processing', ready:'Ready', cancelled:'Cancelled' };
    if(m[code]) return m[code];
    return String(code||'').replace(/_/g,' ').replace(/\b\w/g, function(c){ return c.toUpperCase(); });
  }
  // Unified "active filters" chip. Single source of truth for what is narrowing
  // the orders table: the rider filter and/or the funnel status filter, each as
  // its own independently-removable pill. Lives where the rider chip already sat
  // (Riders-Live panel header). Additive: removed entirely when nothing active.
  window.nfRenderActiveFilters = function(){
    var host = document.getElementById('nfRiderCardsMeta');
    if(!host) return;
    var riderOn = (window.__nfRiderFilter != null);
    var statusOn = !!window.__nfStatusCard;
    var chip = document.getElementById('nfRiderChip');
    if(!riderOn && !statusOn){ if(chip) chip.remove(); return; }
    if(!chip){ chip = document.createElement('span'); chip.id = 'nfRiderChip'; host.parentNode.appendChild(chip); }
    chip.style.cursor = 'default';
    var xStyle = 'cursor:pointer;opacity:.75;margin-left:4px;font-weight:700;';
    var parts = [];
    if(riderOn){
      parts.push('🛵 ' + esc(window.__nfRiderLabel || 'Rider')
        + '<span title="Remove rider filter" style="'+xStyle+'" onclick="event.stopPropagation(); window.nfClearRiderFilter();">✕</span>');
    }
    if(statusOn){
      parts.push('📦 ' + esc(nfStatusLabel(window.__nfStatusCard))
        + '<span title="Remove status filter" style="'+xStyle+'" onclick="event.stopPropagation(); window.nfClearStatusFilter();">✕</span>');
    }
    chip.innerHTML = '<span style="opacity:.7;margin-right:2px;">Filtered:</span> '
      + parts.join(' <span style="opacity:.45">·</span> ');
  };
  // Clear ONLY the funnel status filter (keeps any rider filter). Reuses
  // filterByStatus('all'), which reloads the all-status rows and — via its own
  // tail — re-applies the rider overlay and re-renders this chip.
  window.nfClearStatusFilter = function(){
    if(typeof filterByStatus === 'function'){ filterByStatus('all'); }
    else { window.__nfStatusCard = null; window.nfRenderActiveFilters(); }
  };
})();
</script>

<script>
// NF (2026-07): "N new orders — click to load" pill for the open-orders table.
// Detects NEW orders by highest order id (which only ever increases), NOT by a
// churny open-order count — so heavy delivery volume can never mask a new
// arrival (a delivery leaving the open set never mints a higher id). Cheap: one
// tiny COUNT/MAX probe every 30s, ONLY while the tab is visible and on a live
// (non-Shopify) open-orders view. Nothing on screen moves until the user clicks
// the pill; the click reuses window.nfRefreshCurrentOrdersView(). Fail-open.
(function(){
  var baselineId = null;    // highest order id the user has "seen" in this view
  var lastScopeKey = null;  // source|tab — auto-reseed when the view changes
  var timer = null;

  function scope(){
    var cur = new URL(window.location);
    return {
      source: window.currentSource || cur.searchParams.get('source') || 'other',
      tab: window.currentTab || cur.searchParams.get('tab') || 'open'
    };
  }
  // Only watch the LIVE orders table (NF + accepted-Shopify land here). Pending
  // Shopify staging is the approvals badge's job. Watch open/riders/all tabs.
  function watching(){
    var s = scope();
    return s.source !== 'shopify' && (s.tab === 'open' || s.tab === 'riders' || s.tab === 'all');
  }
  function ensurePill(){
    var pill = document.getElementById('nfNewOrdersPill');
    if(pill) return pill;
    pill = document.createElement('button');
    pill.id = 'nfNewOrdersPill';
    pill.type = 'button';
    pill.style.cssText = 'display:none;align-items:center;gap:8px;margin:6px 0 10px;padding:8px 14px;background:#2563eb;color:#fff;border:none;border-radius:999px;font-size:13px;font-weight:600;cursor:pointer;box-shadow:0 2px 10px rgba(37,99,235,.3);';
    pill.onclick = onClick;
    var container = document.querySelector('.orders-table-container');
    if(container && container.parentNode){ container.parentNode.insertBefore(pill, container); }
    else { document.body.appendChild(pill); }
    return pill;
  }
  function show(n){
    var pill = ensurePill();
    pill.innerHTML = '↻ ' + n + ' new order' + (n === 1 ? '' : 's') + ' — click to load';
    pill.style.display = 'inline-flex';
  }
  function hide(){
    var pill = document.getElementById('nfNewOrdersPill');
    if(pill) pill.style.display = 'none';
  }
  function probe(afterId){
    var s = scope();
    var params = new URLSearchParams();
    params.append('after_id', afterId == null ? 0 : afterId);
    params.append('source', s.source);
    params.append('tab', s.tab);
    return fetch('/orders/new-since?' + params.toString(), { headers:{ 'X-Requested-With':'XMLHttpRequest', 'Accept':'application/json' }, credentials:'same-origin' })
      .then(function(r){ return r.json(); })
      .catch(function(){ return null; });
  }
  // Establish (or re-establish) the baseline as the current highest id for this
  // view, and clear the pill. Called on load, on view change, and after a load.
  function reseed(){
    var s = scope();
    lastScopeKey = s.source + '|' + s.tab;
    return probe(0).then(function(d){
      if(d && d.success){ baselineId = d.max_id; }
      hide();
    });
  }
  window.nfNewOrdersReseed = reseed; // exposed so a manual refresh can reset it
  function onClick(){
    hide();
    if(typeof window.nfRefreshCurrentOrdersView === 'function'){
      window.nfRefreshCurrentOrdersView().then(function(){ reseed(); });
    } else { reseed(); }
  }
  function poll(){
    if(document.hidden) return;              // don't poll hidden tabs
    if(!watching()){ hide(); return; }       // not a live open-orders view
    var key = scope().source + '|' + scope().tab;
    if(key !== lastScopeKey){ reseed(); return; }  // view changed -> new baseline
    if(baselineId == null){ reseed(); return; }
    probe(baselineId).then(function(d){
      if(!d || !d.success) return;
      if(d.count > 0) show(d.count); else hide();
    });
  }
  function start(){ reseed(); if(timer) clearInterval(timer); timer = setInterval(poll, 30000); }
  if(document.readyState === 'loading'){ document.addEventListener('DOMContentLoaded', start); }
  else { start(); }
})();
</script>

<script>
// NF (Aug-2026) — "a rider is waiting on a locked pin" banner.
//
// Riders used to have to PHONE a manager to get a verified pin unlocked. Now the
// refusal on his phone raises a request and this strip offers the unlock.
//
// The one rule that matters here: THE BANNER IS NEVER STATE WE HOLD. Every 30s we
// re-ask the server for the open requests and repaint from that answer, so a
// request answered anywhere — this page, another manager's browser, store mode on
// a phone, or by the rider saving the pin — is gone from here within one poll. A
// dead banner would need the server to keep returning something it no longer does.
(function(){
  var box = document.getElementById('nfPinUnlockBanners');
  if(!box) return;
  var timer = null;
  var busy = false;   // a click is in flight — don't let a poll repaint under it

  function csrfToken(){
    var m = document.querySelector('meta[name="csrf-token"]');
    return m ? (m.getAttribute('content') || '') : '';
  }
  function esc(s){
    return String(s == null ? '' : s).replace(/[&<>"']/g, function(c){
      return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
    });
  }
  // Server sends 'YYYY-MM-DD HH:MM:SS' PKT wall-clock. Read the parts as LOCAL so
  // the shown time matches the server (the UTC round-trip renders it hours off).
  function shortTime(s){
    if(!s) return '';
    var m = String(s).replace('T',' ').match(/^(\d{4})-(\d{2})-(\d{2})[ ](\d{2}):(\d{2})/);
    if(!m) return '';
    var d = new Date(+m[1], +m[2]-1, +m[3], +m[4], +m[5]);
    if(isNaN(d.getTime())) return '';
    return d.toLocaleTimeString([], {hour:'numeric', minute:'2-digit'});
  }

  function render(list){
    if(!list || !list.length){ box.style.display = 'none'; box.innerHTML = ''; return; }
    var html = '';
    for(var i=0; i<list.length; i++){
      var r = list[i];
      var at = shortTime(r.requested_at);
      html += '<div style="display:flex;align-items:center;gap:10px;padding:8px 12px;margin-bottom:6px;'
           +  'background:#fffbeb;border:1px solid #fcd34d;border-left:3px solid #f59e0b;border-radius:8px;'
           +  'font-size:12.5px;color:#78350f;">'
           +  '<span style="font-size:14px;line-height:1;">🔒</span>'
           +  '<span><strong>' + esc(r.rider_name) + '</strong> is at <strong>' + esc(r.customer_name) + '</strong>'
           +  (r.order_number ? ' (' + esc(r.order_number) + ')' : '')
           +  ' and needs the verified location unlocked'
           +  (at ? ' — asked at ' + esc(at) : '') + '.</span>'
           +  '<span style="margin-left:auto;display:flex;align-items:center;gap:6px;">'
           +  '<button type="button" data-unlock="' + r.customer_id + '" '
           +  'style="background:#f59e0b;border:1px solid #d97706;color:#fff;padding:3px 12px;border-radius:6px;'
           +  'font-size:11.5px;font-weight:700;cursor:pointer;">Unlock</button>'
           +  '<button type="button" data-dismiss="' + r.customer_id + '" title="Dismiss without unlocking" '
           +  'style="background:none;border:none;color:#b45309;font-size:14px;line-height:1;cursor:pointer;padding:0 2px;">✕</button>'
           +  '</span></div>';
    }
    box.innerHTML = html;
    box.style.display = 'block';
  }

  function poll(){
    if(document.hidden || busy) return;
    fetch('{{ route('orders.pin-unlock-requests') }}', {
      headers: {'X-Requested-With':'XMLHttpRequest','Accept':'application/json'},
      credentials: 'same-origin'
    })
      .then(function(r){ return r.json(); })
      .then(function(d){ if(d && d.success) render(d.requests || []); })
      .catch(function(){});   // a failed poll leaves the last answer on screen
  }

  function act(url, btn, failMsg){
    busy = true;
    if(btn){ btn.disabled = true; btn.style.opacity = '0.6'; }
    return fetch(url, {
      method: 'POST',
      headers: {'Content-Type':'application/json','X-CSRF-TOKEN':csrfToken(),'Accept':'application/json'},
      credentials: 'same-origin'
    })
      .then(function(r){ return r.json(); })
      .then(function(d){
        busy = false;
        if(!d || !d.success){ alert(failMsg + (d && d.message ? ': ' + d.message : '')); }
        poll();   // repaint from the server, never from an assumption
      })
      .catch(function(){
        busy = false;
        if(btn){ btn.disabled = false; btn.style.opacity = '1'; }
        alert(failMsg + ' — please try again.');
      });
  }

  box.addEventListener('click', function(ev){
    var el = ev.target.closest('button[data-unlock], button[data-dismiss]');
    if(!el) return;
    var unlockId = el.getAttribute('data-unlock');
    if(unlockId){
      act('/customers/' + unlockId + '/unlock-verified-pin', el, 'Could not unlock');
      return;
    }
    var dismissId = el.getAttribute('data-dismiss');
    if(dismissId && confirm('Dismiss this request without unlocking? The pin stays locked.')){
      act('/customers/' + dismissId + '/dismiss-pin-unlock-request', el, 'Could not dismiss');
    }
  });

  function start(){ poll(); if(timer) clearInterval(timer); timer = setInterval(poll, 30000); }
  if(document.readyState === 'loading'){ document.addEventListener('DOMContentLoaded', start); }
  else { start(); }
  // Coming back to the tab is exactly when a manager wants the truth, and the
  // poll skips hidden tabs — so re-ask immediately rather than waiting up to 30s.
  document.addEventListener('visibilitychange', function(){ if(!document.hidden) poll(); });
})();
</script>

{{-- 🔁 The vehicle-handover approval strip now lives in ONE partial, included
     below near the top of the page (it renders the #nfVehicleReqBanners div
     itself). Moved out of this file so the Bikes screen can show the very
     same banner — see partials/vehicle-request-banner.blade.php. --}}

<script>
// NF (Jul-2026, S4e): rebuild the orders top bar into a shape that can never run
// off-screen. The earlier version right-aligned search+filters+riders into the
// header's narrow right slot; with a full rider roster that content grew wider
// than the viewport and got CLIPPED by the content wrapper's overflow-x:clip
// (riders + filters invisible). New shape, per owner:
//   Row 1 : tabs + actions            (existing, untouched)
//   Row 2 : LEFT column  = status cards, then the search + filters row beneath them
//           RIGHT        = the Riders-Live panel (wraps below the left column when
//                          space is tight, so it is always visible)
// Everything is a runtime node-move (appendChild) — every id + inline handler is
// preserved. Fail-open: any missing piece leaves the original layout intact.
document.addEventListener('DOMContentLoaded', function(){
  // NF (Jul-2026): (a) collapse the Order/Delivery date controls into a compact
  // "📅 Date" popover; (b) move the Riders-Live cards to the header's right so the
  // top balances (left = tabs + status cards, right = search/filters + riders).
  // Both are runtime node-moves — every id + handler is preserved. Own try-block
  // so a failure here can't affect the search relocation above.
  try {
    var hr = document.getElementById('nfHeaderRight');

    // (a) Date popover — moves the mode toggle + date/month inputs behind a button.
    var modeWrap = (document.getElementById('dateModeDateBtn') || {}).parentElement;
    var dateC = document.getElementById('dateFiltersContainer');
    var monthC = document.getElementById('monthFiltersContainer');
    if (modeWrap && dateC && monthC) {
      var filtersGroup = dateC.parentElement;
      var wrap = document.createElement('div'); wrap.style.position = 'relative';
      var btn = document.createElement('button'); btn.type = 'button'; btn.id = 'nfDateBtn';
      btn.className = 'inline-flex items-center gap-1 px-2.5 py-2 text-sm font-medium border border-gray-300 rounded-lg bg-white shadow-sm hover:bg-gray-50 whitespace-nowrap';
      btn.innerHTML = '📅 Date <span style="opacity:.55;font-size:11px;">▾</span>';
      var pop = document.createElement('div'); pop.id = 'nfDatePop';
      // position:fixed + appended to <body> so NO ancestor overflow (the sticky
      // header / content wrapper's overflow-x:clip) can ever cut the popover off —
      // the earlier absolute-in-header version got clipped and "wouldn't open".
      pop.style.cssText = 'position:fixed;top:0;left:0;background:#fff;border:1px solid #e2e8f0;border-radius:10px;box-shadow:0 10px 28px rgba(15,23,42,.18);padding:12px;z-index:200;display:none;min-width:250px;max-height:80vh;overflow:auto;';
      var lbl = document.createElement('div');
      lbl.style.cssText = 'font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;color:#94a3b8;margin-bottom:8px;';
      lbl.textContent = 'Filter by date';
      modeWrap.style.marginBottom = '8px';
      pop.appendChild(lbl); pop.appendChild(modeWrap); pop.appendChild(dateC); pop.appendChild(monthC);
      // Stack Order/Delivery inputs vertically inside the popover so it stays narrow + never clips.
      [dateC, monthC].forEach(function (c) { c.style.flexDirection = 'column'; c.style.alignItems = 'stretch'; c.style.gap = '8px'; });
      wrap.appendChild(btn);
      document.body.appendChild(pop);            // <-- escape all clipping ancestors
      var clearBtn = filtersGroup.querySelector('button[onclick*="clearFilters"]');
      if (clearBtn) filtersGroup.insertBefore(wrap, clearBtn); else filtersGroup.appendChild(wrap);
      var nfPositionDatePop = function () {
        var r = btn.getBoundingClientRect();
        var w = pop.offsetWidth || 260;
        var left = Math.max(8, Math.min(r.left, window.innerWidth - w - 8)); // clamp inside viewport
        pop.style.left = left + 'px';
        pop.style.top = (r.bottom + 6) + 'px';
      };
      btn.addEventListener('click', function (e) {
        e.stopPropagation();
        if (pop.style.display === 'block') { pop.style.display = 'none'; return; }
        pop.style.display = 'block'; nfPositionDatePop();
      });
      document.addEventListener('click', function (e) { if (!wrap.contains(e.target) && !pop.contains(e.target)) pop.style.display = 'none'; });
      window.addEventListener('resize', function () { if (pop.style.display === 'block') nfPositionDatePop(); });
      var nfDateActive = function () {
        var a = (document.getElementById('dateFilter') || {}).value || (document.getElementById('deliveryDateFilter') || {}).value
             || (document.getElementById('orderMonthFilter') || {}).value || (document.getElementById('deliveryMonthFilter') || {}).value;
        btn.style.borderColor = a ? '#2563eb' : ''; btn.style.color = a ? '#2563eb' : ''; btn.style.background = a ? '#eff4ff' : '#fff';
      };
      ['dateFilter', 'deliveryDateFilter', 'orderMonthFilter', 'deliveryMonthFilter'].forEach(function (id) {
        var el = document.getElementById(id); if (el) el.addEventListener('change', nfDateActive);
      });
      nfDateActive();
    }

    // (b) TOP layout — two columns that share the FULL header height so the
    //   Riders-Live panel TOP-ALIGNS with the tabs / Create-Order row. Previously
    //   riders sat in a second row, leaving an empty band above them and pushing the
    //   table down; top-aligning pulls everything up and reclaims that vertical space.
    //     LEFT  = [tabs + actions row] + status cards + search/filters (stacked)
    //     RIGHT = Riders-Live panel, top-aligned (wraps below on narrow screens)
    //   All runtime node-moves (parse-safe); every id + inline handler is preserved.
    var statusCards = document.getElementById('openOrdersStatusCards');
    var riders = document.getElementById('nfRiderCards');
    var host = document.querySelector('.sticky.top-0.z-30 .px-4');
    var search = document.getElementById('orderSearch');
    var filterRow = search ? search.closest('.flex.flex-wrap.items-center.gap-3') : null;
    if (statusCards && host && !document.getElementById('nfTopFlex')) {
      // The existing tabs/actions row = the host's direct child that holds the tabs.
      var tabsAnchor = document.querySelector('.flex.space-x-1.bg-gray-100');
      var tabsRow = tabsAnchor ? tabsAnchor.closest('.px-4 > *') : null;

      var topFlex = document.createElement('div');
      topFlex.id = 'nfTopFlex';
      topFlex.style.cssText = 'display:flex;align-items:flex-start;justify-content:flex-start;gap:24px;flex-wrap:wrap;padding:2px 0 8px;';

      // LEFT column — tabs row on top, then status cards, then the filters row.
      // Bounded width so the Riders panel keeps its (owner-approved) centre-ish
      // position and the tabs stay on one line.
      var left = document.createElement('div');
      left.id = 'nfTopLeft';
      left.style.cssText = 'display:flex;flex-direction:column;gap:10px;flex:0 1 700px;max-width:740px;min-width:0;';

      if (tabsRow) {
        tabsRow.style.margin = '0';
        // The old empty right slot (#nfHeaderRight) inside the tabs row is a flex-1
        // spacer; in the narrower left column it steals width and wraps the tabs onto
        // two lines. It's unused now — hide it so the tabs keep a single line.
        var hrSlot = document.getElementById('nfHeaderRight');
        if (hrSlot) hrSlot.style.display = 'none';
        left.appendChild(tabsRow);
      }

      statusCards.style.margin = '0'; statusCards.style.minWidth = '0';
      var scont = document.getElementById('statusCardsContainer');
      if (scont) { scont.style.overflowX = 'auto'; scont.style.flexWrap = 'nowrap'; scont.style.paddingBottom = '4px'; }
      left.appendChild(statusCards);

      if (filterRow) {
        var oldWrapper = filterRow.parentElement;   // padded wrapper that held only the filter row
        filterRow.style.justifyContent = 'flex-start';
        filterRow.style.margin = '0';
        var searchWrap = search.closest('.relative');
        if (searchWrap) { searchWrap.style.flex = '1 1 240px'; searchWrap.style.maxWidth = '340px'; searchWrap.style.minWidth = '180px'; }
        left.appendChild(filterRow);
        // Collapse the now-empty wrapper — ONLY if truly empty. NEVER hide the sticky
        // bar itself: this div-imbalanced blade parses the orders table as a sibling
        // inside that bar, so hiding the bar would hide the table.
        if (oldWrapper && oldWrapper.children.length === 0) oldWrapper.style.display = 'none';
      }
      topFlex.appendChild(left);

      // RIGHT column — the Riders-Live panel, TOP-aligned with the tabs row.
      if (riders) { riders.style.margin = '0'; riders.style.flex = '0 1 auto'; topFlex.appendChild(riders); }

      // Place the whole two-column block at the very TOP of the header.
      host.insertBefore(topFlex, host.firstChild);
    }
  } catch (e) { /* leave the row as-is on any failure */ }
});
</script>

