<script>
// Modal functions
function closeModal(modalId) {
    // If in pop-out mode, close the entire tab instead of just hiding the modal
    if (window.isPopoutMode && modalId === 'editOrderModal') {
        // Refresh the parent window if it exists
        if (window.opener && !window.opener.closed) {
            try {
                window.opener.location.reload();
            } catch (e) {
                // Ignore cross-origin errors
            }
        }
        // Close the pop-out tab
        window.close();
        return;
    }
    
    // Normal modal close behavior
    const modal = document.getElementById(modalId);
    if (modal) {
        modal.style.display = 'none';
        
        // Reset pop-out styling if it was applied
        if (modalId === 'editOrderModal' && window.isPopoutMode) {
            resetModalStyling(modal);
            window.isPopoutMode = false;
        }
    }
}
// Format date helper
function formatDate(dateString) {
    if (!dateString) return '';
    try {
        // Handle ISO format: "2025-09-09T17:41:03.000000Z"
        let cleanDate = dateString;
        
        if (dateString.includes('T')) {
            // Extract date and time parts
            const [datePart, timePart] = dateString.split('T');
            const [year, month, day] = datePart.split('-');
            const timeOnly = timePart.split('.')[0]; // Remove microseconds
            const [hour, minute] = timeOnly.split(':');
            
            // Format as: "09 Sep 2025, 17:41"
            const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 
                              'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
            const monthName = monthNames[parseInt(month, 10) - 1];
            cleanDate = day + ' ' + monthName + ' ' + year + ', ' + hour + ':' + minute;
        } else if (dateString.includes(' ')) {
            // Handle format: "2025-09-09 17:41:03"
            const [datePart, timePart] = dateString.split(' ');
            const [year, month, day] = datePart.split('-');
            const [hour, minute] = timePart.split(':');
            
            const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 
                              'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
            const monthName = monthNames[parseInt(month, 10) - 1];
            
            cleanDate = day + ' ' + monthName + ' ' + year + ', ' + hour + ':' + minute;
        }
        
        return cleanDate;
    } catch (error) {
        console.error('Date parsing error:', error, 'for date:', dateString);
        return dateString;
    }
}

// Add formatDateLocal function for consistency with customer page
window.formatDateLocal = function(dateString) {
    if (!dateString) return 'N/A';
    
    try {
        // Handle different date formats
        let date;
        if (dateString.includes('T')) {
            // ISO format
            date = new Date(dateString);
        } else if (dateString.includes(' ')) {
            // MySQL datetime format
            const [datePart, timePart] = dateString.split(' ');
            const [year, month, day] = datePart.split('-');
            const [hour, minute, second] = timePart.split(':');
            date = new Date(year, month - 1, day, hour, minute, second);
        } else {
            // Fallback
            date = new Date(dateString);
        }
        
        return date.toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'short',
            day: 'numeric',
            hour: '2-digit',
            minute: '2-digit'
        });
    } catch (error) {
        console.error('Date formatting error:', error);
        return dateString;
    }
};

// Format currency helper
function formatCurrency(amount, currency = 'PKR') {
    const num = isNaN(parseFloat(amount)) ? 0 : parseFloat(amount);
    return currency + ' ' + num.toFixed(2);
}

// Normalize payment method for display
function normalizePaymentMethodDisplay(paymentMethod) {
    if (!paymentMethod) return 'Cash';
    
    const method = paymentMethod.toLowerCase().trim();
    
    // Mapping for display
    const displayMap = {
        'cash': 'Cash',
        'cash_on_delivery': 'Cash on Delivery',
        'cod': 'Cash on Delivery',
        'bank_transfer': 'Bank Transfer',
        'direct_bank_transfer': 'Bank Transfer',
        'bacs': 'Bank Transfer',
        'card': 'Card Payment',
        'credit_card': 'Card Payment',
        'debit_card': 'Card Payment',
        'online': 'Online Payment',
        'online_payment': 'Online Payment',
        'paypal': 'Online Payment',
        'stripe': 'Online Payment',
        'razorpay': 'Online Payment'
    };
    
    // Check for partial matches if exact match not found
    if (!displayMap[method]) {
        if (method.includes('bank') || method.includes('transfer')) {
            return 'Bank Transfer';
        } else if (method.includes('cash') || method.includes('cod')) {
            return 'Cash';
        } else if (method.includes('card') || method.includes('visa') || method.includes('master')) {
            return 'Card Payment';
        } else if (method.includes('online') || method.includes('paypal') || method.includes('stripe')) {
            return 'Online Payment';
        }
    }
    
    return displayMap[method] || 'Cash'; // Default to Cash if unknown
}

// Initialize the runtime source/tab context from the server-rendered values on
// EVERY page load. This is critical: the intended assignment further down in
// this file lives inside a commented-out /* ... */ block (dead code), so the
// only other place that set window.currentSource ran on a manual tab switch.
// That meant a freshly loaded page (including a popped-out edit tab opened at
// /orders?edit_order_id=ID&source=shopify) had window.currentSource === undefined,
// so ordersDetailUrl() dropped ?source=shopify and resolved the id against the
// LIVE production table — showing/editing a completely unrelated order, because
// the Shopify approval queue (t_crm_shopify_order) and the live orders table
// (t_crm_prod_order) share overlapping ids.
(function initOrdersSourceContext() {
    try {
        var params = new URLSearchParams(window.location.search);
        var serverSource = @json($source ?? 'other');
        var serverTab = @json($tab ?? 'all');
        window.currentSource = serverSource || params.get('source') || 'other';
        window.currentTab = serverTab || params.get('tab') || 'all';
    } catch (e) {}
})();

// Resolve the current source robustly: prefer the runtime context, but fall
// back to the URL param so we never accidentally resolve a Shopify order
// against the production table even if the global wasn't set yet.
function currentOrderSource() {
    var src = (window.currentSource || '').toLowerCase();
    if (!src) {
        try { src = (new URLSearchParams(window.location.search).get('source') || '').toLowerCase(); } catch (e) {}
    }
    return src;
}

// Build the GET /orders/{id} detail URL. The Shopify approval queue
// (t_crm_shopify_order) and the live orders table (t_crm_prod_order) have
// overlapping ids, so the backend can't guess which one we mean — we must tell
// it explicitly based on which screen we're on. Shopify Approvals view sets
// window.currentSource='shopify'; everywhere else reads live production orders.
function ordersDetailUrl(orderId) {
    const base = '/orders/' + encodeURIComponent(orderId);
    return currentOrderSource() === 'shopify' ? base + '?source=shopify' : base;
}

// Build the full-page pop-out / "open in tab" URL while PRESERVING the current
// source. Shopify staging orders and live production orders share overlapping
// ids, so a bare /orders?edit_order_id=ID would re-open the page in production
// mode and resolve the id against the WRONG table (showing an unrelated order).
// Carrying &source=shopify makes the popped-out page boot in Shopify mode so the
// auto-opened edit form fetches /orders/ID?source=shopify (the staging row).
function editOrderTabUrl(orderId) {
    const base = '/orders?edit_order_id=' + encodeURIComponent(String(orderId));
    return currentOrderSource() === 'shopify' ? base + '&source=shopify' : base;
}

// Build the /orders/{id}/invoice URL (print / PDF / PNG) carrying the current
// source. Without this, printing from a Shopify approval order's edit pop-out
// would render the unrelated PRODUCTION order that happens to share the id —
// i.e. the wrong customer's invoice. `query` is an optional extra query string
// (e.g. 'print_pdf=1') without a leading '?'.
function ordersInvoiceUrl(orderId, query) {
    let url = '/orders/' + encodeURIComponent(orderId) + '/invoice';
    const parts = [];
    if (query) parts.push(query);
    if (currentOrderSource() === 'shopify') parts.push('source=shopify');
    if (parts.length) url += '?' + parts.join('&');
    return url;
}

// View Order Details
// ===== Verified-pin lock (Jul-2026): grant / cancel a rider unlock window =====
// Same web endpoints as the customers page; refreshes the open order modal so
// the 🔒/🔓 chip reflects the new state immediately.
function unlockOrderCustomerPin(customerId) {
    if (!confirm('Unlock this customer\'s location so the RIDER can change the pin?\n\nIt locks again automatically after one save (or 6 hours).')) return;
    fetch(`/customers/${customerId}/unlock-verified-pin`, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content
        }
    })
    .then(r => r.json())
    .then(data => {
        if (data.success) {
            if (currentOrderId) viewOrderDetails(currentOrderId);
        } else {
            alert('Error: ' + (data.message || 'Failed to unlock location'));
        }
    })
    .catch(() => alert('Failed to unlock location. Please try again.'));
}

function relockOrderCustomerPin(customerId) {
    fetch(`/customers/${customerId}/relock-verified-pin`, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content
        }
    })
    .then(r => r.json())
    .then(data => {
        if (data.success) {
            if (currentOrderId) viewOrderDetails(currentOrderId);
        } else {
            alert('Error: ' + (data.message || 'Failed to re-lock location'));
        }
    })
    .catch(() => alert('Failed to re-lock location. Please try again.'));
}

function viewOrderDetails(orderId) {
    console.log('View order details clicked for order:', orderId);
    currentOrderId = orderId; // Store the order ID for invoice viewing
    const modal = document.getElementById('viewOrderModal');
    const content = document.getElementById('viewOrderContent');
    
    // Show loading
    content.innerHTML = '<div style="text-align: center; padding: 40px;"><div style="display: inline-block; width: 32px; height: 32px; border: 3px solid #e5e7eb; border-top: 3px solid #2563eb; border-radius: 50%; animation: spin 1s linear infinite;"></div></div>';
    modal.style.display = 'block';
    
    // Fetch order details via AJAX
    fetch(ordersDetailUrl(orderId), {
        method: 'GET',
        headers: {
            'Accept': 'application/json',
            'Content-Type': 'application/json',
            'X-Requested-With': 'XMLHttpRequest'
        }
    })
    .then(response => response.json())
    .then(data => {
        if (data.success) {
            const order = data.order;
            
            // Attach discounts to order if they're at root level (for backward compat)
            if (!order.discounts && data.discounts) {
                order.discounts = data.discounts;
            }
            
            // Attach verified_location to order if it's at root level
            if (!order.verified_location && data.verified_location) {
                order.verified_location = data.verified_location;
            }
            
            console.log('Order data:', order);
            console.log('Order discounts:', order.discounts);
            console.log('Verified location:', order.verified_location);
            
            // Update modal header buttons based on order type
            updateViewModalButtons(order);
            
            // Build HTML using string concatenation to avoid Blade conflicts
            let html = '<div>';
            
            // Invoice Header
            html += '<div style="display: flex; justify-content: space-between; align-items: flex-start; padding-bottom: 16px; border-bottom: 1px solid #e5e7eb; margin-bottom: 20px;">';
            html += '<div>';
            html += '<h2 style="font-size: 24px; font-weight: bold; color: #111827; margin: 0;">Invoice #' + (order.order_number || order.id) + '</h2>';
            html += '<p style="font-size: 14px; color: #6b7280; margin: 8px 0 0 0;">Date: ' + formatDate(order.order_date) + '</p>';
            html += '</div>';
            html += '<div style="text-align: right;">';
            const sourceStyle = order.external_source === 'shopify' ? 'background-color: #dcfce7; color: #166534;'
                : order.external_source === 'khaas_storage' ? 'background-color: #dbeafe; color: #1e40af;'
                : 'background-color: #fed7aa; color: #9a3412;';
            const sourceLabel = order.external_source === 'khaas_storage' ? 'FROZEN MEAT' : (order.external_source || 'manual').toUpperCase();
            html += '<span style="display: inline-flex; align-items: center; padding: 4px 12px; border-radius: 20px; font-size: 14px; font-weight: 500; ' + sourceStyle + '">';
            html += sourceLabel;
            html += '</span>';
            html += '<p style="font-size: 24px; font-weight: bold; color: #2563eb; margin: 8px 0 0 0;">' + formatCurrency(order.total_price, order.currency) + '</p>';
            html += '</div>';
            html += '</div>';

            
            // Add basic order details (avoiding template literal conflicts)
            html += '<div style="padding: 20px; background-color: #f9fafb; border-radius: 8px; margin: 20px 0;">';
            html += '<h3 style="margin: 0 0 16px 0; color: #111827;">Order Details</h3>';
            html += '<div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px;">';
            html += '<div>';
            // Build customer name from address fields if order.name is not available
            var customerName = order.name || 'N/A';
            if ((!order.name || order.name === 'N/A') && (order.address_first_name || order.address_last_name)) {
                customerName = ((order.address_first_name || '') + ' ' + (order.address_last_name || '')).trim();
            }
            
            // Build address from address fields (excluding postal code and country)
            var addressParts = [];
            if (order.address_line1) addressParts.push(order.address_line1);
            if (order.address_line2) addressParts.push(order.address_line2);
            if (order.address_city) addressParts.push(order.address_city);
            if (order.address_province) addressParts.push(order.address_province);
            var fullAddress = addressParts.length > 0 ? addressParts.join(', ') : 'N/A';
            
            // Make customer name clickable if customer_id exists
            var customerDisplay = customerName;
            if (order.customer_id && order.customer_id !== 'N/A' && order.customer_id !== null) {
                customerDisplay = '<span onclick="openCustomerInNewTab(' + order.customer_id + ')" class="customer-name-link text-blue-600 hover:text-blue-800 hover:underline font-medium cursor-pointer" title="View customer details">' + customerName + '</span>';
            }
            html += '<p><strong>Customer:</strong> ' + customerDisplay + '</p>';
            html += '<p><strong>Address:</strong> ' + fullAddress + '</p>';
            
            // Phone with WhatsApp button
            var phoneNumber = order.address_phone || order.customer_phone || '';
            html += '<p><strong>Phone:</strong> ' + (phoneNumber || 'N/A');
            if (phoneNumber) {
                html += ' <button onclick="openWhatsAppMenu(\'' + escapeForJs(customerName) + '\', \'' + escapeForJs(phoneNumber) + '\', \'' + escapeForJs(order.order_number || '') + '\')" style="padding: 2px 8px; background: #25D366; color: white; border: none; border-radius: 4px; font-size: 11px; cursor: pointer; margin-left: 6px;" title="Send WhatsApp Message">💬 WhatsApp</button>';
            }
            html += '</p>';
            
            // Add verified location if available
            if (order.verified_location) {
                html += '<div style="margin-top: 12px; padding: 10px; background-color: #f0fdf4; border-radius: 6px; border: 1px solid #10b981;">';
                html += '<div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px; gap: 6px; flex-wrap: wrap;">';
                html += '<strong style="color: #059669; font-size: 13px;">✅ Verified Location</strong>';
                // Verified-pin lock chip + unlock/re-lock action (Jul-2026):
                // riders can't change an existing pin unless staff unlocks it here.
                if (order.verified_location.unlock_active) {
                    var vlUntil = order.verified_location.unlocked_until ? new Date(order.verified_location.unlocked_until).toLocaleTimeString([], {hour: '2-digit', minute: '2-digit'}) : '';
                    html += '<span style="font-size: 10px; font-weight: 700; color: #b45309; background: #fef3c7; border: 1px solid #fcd34d; padding: 2px 8px; border-radius: 999px;" title="A rider can change this pin until ' + vlUntil + '">🔓 Rider unlock until ' + vlUntil + '</span>';
                } else {
                    html += '<span style="font-size: 10px; font-weight: 600; color: #6b7280; background: #f3f4f6; border: 1px solid #e5e7eb; padding: 2px 8px; border-radius: 999px;" title="Riders cannot change this pin unless you unlock it">🔒 Rider-locked</span>';
                }
                html += '<span style="flex: 1;"></span>';
                if (order.customer_id) {
                    if (order.verified_location.unlock_active) {
                        html += '<button onclick="relockOrderCustomerPin(' + order.customer_id + ')" style="padding: 4px 8px; background: #fff; color: #b45309; border: 1px solid #fcd34d; border-radius: 4px; font-size: 11px; cursor: pointer; font-weight: 600;" title="Cancel the unlock">🔒 Re-lock</button>';
                    } else {
                        html += '<button onclick="unlockOrderCustomerPin(' + order.customer_id + ')" style="padding: 4px 8px; background: #fff; color: #d97706; border: 1px solid #fbbf24; border-radius: 4px; font-size: 11px; cursor: pointer; font-weight: 600;" title="Let the rider change this pin (auto-locks after one save or 6 hours)">🔓 Unlock for rider</button>';
                    }
                    html += '<button onclick="updateVerifiedLocation(' + order.customer_id + ')" style="padding: 4px 8px; background-color: #3b82f6; color: white; border: none; border-radius: 4px; font-size: 11px; cursor: pointer; font-weight: 500;">Update</button>';
                }
                html += '</div>';
                
                if (order.verified_location.url) {
                    html += '<p style="margin: 4px 0; font-size: 12px;">';
                    html += '<a href="' + order.verified_location.url + '" target="_blank" style="color: #3b82f6; text-decoration: none; font-weight: 500;">';
                    html += '<i class="fas fa-external-link-alt"></i> Open in Google Maps';
                    html += '</a>';
                    html += '</p>';
                } else if (order.verified_location.latitude && order.verified_location.longitude) {
                    html += '<p style="margin: 4px 0; font-size: 11px; font-family: monospace; color: #059669;">';
                    html += order.verified_location.latitude + ', ' + order.verified_location.longitude;
                    html += '</p>';
                    html += '<p style="margin: 4px 0; font-size: 12px;">';
                    html += '<a href="' + order.verified_location.google_maps_url + '" target="_blank" style="color: #3b82f6; text-decoration: none; font-weight: 500;">';
                    html += '<i class="fas fa-external-link-alt"></i> Open in Google Maps';
                    html += '</a>';
                    html += '</p>';
                }
                
                // ⭐ Aug-2026 — a pin the CUSTOMER sent that we did not save.
                // Never overwriting a verified pin is the right rule, but the
                // refusal used to be invisible: on Aug-2 a customer replied with a
                // pin ~1 km from her stale one and the order shipped to the old
                // address the next day. Now it says so, right above the pin it
                // would have replaced.
                if (order.verified_location.pin_reply_pending) {
                    var prp = order.verified_location.pin_reply_pending;
                    html += '<div onclick="openPinHistory(' + order.customer_id + ')" style="margin-top: 8px; padding: 7px 9px; background: #fffbeb; border: 1px solid #f59e0b; border-radius: 6px; cursor: pointer;" title="Click to check it">';
                    html += '<span style="font-size: 11px; font-weight: 700; color: #92400e;">⚠️ Customer sent a new location' + (prp.away_text ? ' — ' + prp.away_text : '') + '</span>';
                    html += '<div style="font-size: 10.5px; color: #78350f; margin-top: 2px;">It was not saved — the old pin is still being used. Click to check it.</div>';
                    html += '</div>';
                }

                // Footer: who set the pin, and the way in to the full story. The
