                html += '<div style="margin-top: 6px;"><a href="javascript:void(0)" onclick="openPinHistory(' + order.customer_id + ')" style="color: #4f46e5; font-weight: 700; text-decoration: none; font-size: 10.5px;">🕘 History</a></div>';
                html += '</div>';
            }
            
            html += '</div>';
            html += '<div>';
            html += '<p><strong>Status:</strong> ' + (order.order_status || 'N/A') + '</p>';
            html += '<p><strong>Payment Method:</strong> ' + normalizePaymentMethodDisplay(order.payment_method) + '</p>';
            html += '<p><strong>Total:</strong> ' + formatCurrency(order.total_price, order.currency) + '</p>';
            html += '<p><strong>Items:</strong> ' + (order.line_items ? order.line_items.length : 0) + '</p>';
            
            // Region in order detail
            var regionDisplay = data.delivery_region_name || '<span style="color:#dc2626;">Not assigned</span>';
            html += '<div style="margin-top:10px; padding:8px 10px; background:' + (data.delivery_region_name ? '#eef2ff' : '#fef2f2') + '; border-radius:6px; border:1px solid ' + (data.delivery_region_name ? '#c7d2fe' : '#fecaca') + ';">';
            html += '<p style="margin:0;"><strong>🚚 Region:</strong> ' + regionDisplay + '</p>';
            html += '<button onclick="openQuickRegionChange(' + order.id + ', ' + (order.delivery_region_id || 'null') + ')" style="margin-top:6px; padding:4px 10px; background:#4f46e5; color:#fff; border:none; border-radius:4px; font-size:11px; cursor:pointer; font-weight:500;">Change Region</button>';
            html += '</div>';
            
            html += '</div>';
            html += '</div>';
            
            // Qurbani order info
            if (order.qurbani_day || order.qurbani_slot || order.qurbani_region || order.qurbani_delivery_type) {
                html += '<div style="margin-top:12px; padding:10px 12px; background:#fffbeb; border-radius:8px; border:1px solid #fcd34d;">';
                html += '<div style="display:flex; align-items:center; gap:6px; margin-bottom:6px;"><span style="font-size:14px;">🐄</span><strong style="color:#92400e; font-size:13px;">Qurbani Details</strong></div>';
                html += '<div style="display:flex; flex-wrap:wrap; gap:6px;">';
                if (order.qurbani_day) html += '<span style="padding:3px 8px; background:#fef3c7; border-radius:6px; font-size:12px; font-weight:600; color:#92400e;">' + escapeHtml(order.qurbani_day) + '</span>';
                if (order.qurbani_slot) html += '<span style="padding:3px 8px; background:#fef3c7; border-radius:6px; font-size:12px; font-weight:600; color:#92400e;">' + escapeHtml(order.qurbani_slot) + '</span>';
                if (order.qurbani_region) html += '<span style="padding:3px 8px; background:#dbeafe; border-radius:6px; font-size:12px; font-weight:600; color:#1e40af;">' + escapeHtml(order.qurbani_region) + '</span>';
                if (order.qurbani_delivery_type) html += '<span style="padding:3px 8px; background:#d1fae5; border-radius:6px; font-size:12px; font-weight:600; color:#065f46;">' + escapeHtml(order.qurbani_delivery_type) + '</span>';
                html += '</div>';
                if (order.payment_status) {
                    var psBg = order.payment_status === 'paid' ? '#d1fae5' : order.payment_status === 'partial' ? '#fef3c7' : '#fee2e2';
                    var psColor = order.payment_status === 'paid' ? '#065f46' : order.payment_status === 'partial' ? '#92400e' : '#991b1b';
                    html += '<div style="margin-top:8px; display:flex; justify-content:space-between; align-items:center;">';
                    html += '<span style="padding:3px 10px; background:' + psBg + '; color:' + psColor + '; border-radius:12px; font-size:12px; font-weight:700;">' + (order.payment_status || 'unpaid').toUpperCase() + '</span>';
                    html += '<span style="font-size:13px; color:#374151;">Paid: <strong>Rs. ' + Number(order.total_paid || 0).toLocaleString() + '</strong> / Rs. ' + Number(order.total_price || 0).toLocaleString() + '</span>';
                    html += '</div>';
                }
                // Qurbani "Add Payment" button
                html += '<div style="margin-top:10px; display:flex; gap:8px;">';
                html += '<button onclick="openQurbaniPaymentModal(' + order.id + ')" style="flex:1; padding:6px 12px; background:#d97706; color:#fff; border:none; border-radius:6px; font-size:12px; font-weight:700; cursor:pointer;">+ Add Payment</button>';
                html += '</div>';
                // Qurbani payment history
                if (data.qurbani_payments && data.qurbani_payments.length > 0) {
                    html += '<div style="margin-top:10px; border-top:1px solid #fcd34d; padding-top:8px;">';
                    html += '<div style="font-size:12px; font-weight:700; color:#92400e; margin-bottom:6px;">Payment History</div>';
                    data.qurbani_payments.forEach(function(p) {
                        var mBg = p.payment_method === 'cash' ? '#d1fae5' : '#dbeafe';
                        var mColor = p.payment_method === 'cash' ? '#065f46' : '#1e40af';
                        html += '<div style="display:flex; justify-content:space-between; align-items:center; padding:4px 0; font-size:12px; border-bottom:1px solid #fef3c7;">';
                        html += '<span style="font-weight:600; color:#059669;">Rs. ' + Number(p.amount).toLocaleString() + '</span>';
                        html += '<span style="padding:2px 6px; background:' + mBg + '; color:' + mColor + '; border-radius:8px; font-size:11px; font-weight:600;">' + escapeHtml(p.payment_method) + '</span>';
                        html += '<span style="color:#6b7280;">' + (p.payment_date || '') + '</span>';
                        html += '<span style="color:#9ca3af;">' + escapeHtml(p.created_by_name || '') + '</span>';
                        html += '</div>';
                    });
                    html += '</div>';
                }
                html += '</div>';
            }
            
            // ⭐ Customer Notes - Important customer-level information (from API response)
            if (data.customer_notes) {
                html += '<div style="margin-top: 16px; padding: 12px; background-color: #fef3c7; border-radius: 8px; border-left: 4px solid #f59e0b;">';
                html += '<div style="display: flex; align-items: center; gap: 6px; margin-bottom: 6px;">';
                html += '<span style="font-size: 14px;">👤</span>';
                html += '<strong style="color: #92400e; font-size: 13px;">Customer Notes</strong>';
                html += '</div>';
                html += '<p style="margin: 0; color: #78350f; font-size: 13px; line-height: 1.5;">' + escapeHtml(data.customer_notes) + '</p>';
                html += '</div>';
            }
            
            // ⭐ Order Notes - Order-specific notes
            if (data.order_note) {
                html += '<div style="margin-top: 12px; padding: 12px; background-color: #f3f4f6; border-radius: 8px; border-left: 4px solid #6b7280;">';
                html += '<div style="display: flex; align-items: center; gap: 6px; margin-bottom: 6px;">';
                html += '<span style="font-size: 14px;">📝</span>';
                html += '<strong style="color: #374151; font-size: 13px;">Order Notes</strong>';
                html += '</div>';
                html += '<p style="margin: 0; color: #4b5563; font-size: 13px; line-height: 1.5;">' + escapeHtml(data.order_note) + '</p>';
                html += '</div>';
            }

            // ⭐ Customer WhatsApp reply (Confirm / Split / Cancel) — Jun-2026.
            // The exact button the customer tapped, so the approver knows what to do.
            if (data.customer_reply && data.customer_reply.text) {
                html += '<div style="margin-top: 12px; padding: 12px; background-color: #ecfdf5; border-radius: 8px; border-left: 4px solid #10b981;">';
                html += '<div style="display: flex; align-items: center; gap: 6px; margin-bottom: 6px;">';
                html += '<span style="font-size: 14px;">💬</span>';
                html += '<strong style="color: #065f46; font-size: 13px;">Customer reply</strong>';
                html += '</div>';
                html += '<p style="margin: 0; color: #047857; font-size: 14px; font-weight: 600; line-height: 1.5;">' + escapeHtml(data.customer_reply.text) + '</p>';
                if (data.customer_reply.at) {
                    html += '<p style="margin: 6px 0 0 0; font-size: 11px; color: #6b7280;">Received ' + escapeHtml(String(data.customer_reply.at)) + '</p>';
                }
                html += '</div>';
            }

            html += '</div>';
            html += '</div>';
            // Line Items with preparation status (only for open orders, not Shopify)
            var items = (order.line_items && Array.isArray(order.line_items)) ? order.line_items : [];
            var isOpenOrder = !['delivered', 'completed', 'cancelled', 'refunded'].includes(order.order_status);
            var isInApprovalQueue = window.currentSource === 'shopify' && (order.external_source === 'shopify' || order.external_source === 'khaas_storage');
            var showPreparationControls = isOpenOrder && !isInApprovalQueue;
            
            html += '<div style="padding: 20px; background-color: #ffffff; border: 1px solid #e5e7eb; border-radius: 8px; margin: 0 0 20px 0;">';
            html += '<div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px;">';
            html += '<h3 style="margin: 0; color: #111827;">Line Items</h3>';
            
            // Only show preparation controls for open non-Shopify orders
            if (showPreparationControls) {
                html += '<div style="display: flex; gap: 8px; align-items: center;">';
                html += '<label style="display: flex; align-items: center; gap: 6px; font-size: 13px; color: #6b7280; cursor: pointer;">';
                html += '<input type="checkbox" id="selectAllLineItems" style="cursor: pointer;" onchange="toggleSelectAllLineItems()">';
                html += '<span>Select All</span>';
                html += '</label>';
                html += '<button onclick="markSelectedAsPreparing()" style="padding: 6px 12px; background: #10b981; color: white; border: none; border-radius: 6px; font-size: 13px; font-weight: 600; cursor: pointer; transition: background 0.2s;" onmouseover="this.style.background=\'#059669\'" onmouseout="this.style.background=\'#10b981\'">Mark as Prepared</button>';
                html += '<button onclick="clearSelectedPreparingStatus()" style="padding: 6px 12px; background: #6b7280; color: white; border: none; border-radius: 6px; font-size: 13px; font-weight: 600; cursor: pointer; transition: background 0.2s;" onmouseover="this.style.background=\'#4b5563\'" onmouseout="this.style.background=\'#6b7280\'">Clear Status</button>';
                html += '</div>';
            }
            
            html += '</div>';
            if (items.length > 0) {
                html += '<div style="overflow-x: auto;">';
                html += '<table id="lineItemsTable" style="width: 100%; border-collapse: collapse;">';
                html += '<thead><tr>';
                
                // Only show Select and Status columns for open non-Shopify orders
                if (showPreparationControls) {
                    html += '<th style="text-align:center; padding: 8px; border-bottom: 1px solid #e5e7eb; color:#6b7280; font-size:12px; width: 40px;">Select</th>';
                }
                
                html += '<th style="text-align:left; padding: 8px; border-bottom: 1px solid #e5e7eb; color:#6b7280; font-size:12px;">Item</th>';
                
                if (showPreparationControls) {
                    html += '<th style="text-align:center; padding: 8px; border-bottom: 1px solid #e5e7eb; color:#6b7280; font-size:12px; width: 100px;">Status</th>';
                }
                
                html += '<th style="text-align:right; padding: 8px; border-bottom: 1px solid #e5e7eb; color:#6b7280; font-size:12px;">Qty</th>' +
                        '<th style="text-align:right; padding: 8px; border-bottom: 1px solid #e5e7eb; color:#6b7280; font-size:12px;">Unit</th>' +
                        '<th style="text-align:right; padding: 8px; border-bottom: 1px solid #e5e7eb; color:#6b7280; font-size:12px;">Total</th>' +
                        '</tr></thead>';
                html += '<tbody>';
                var itemsSubtotal = 0;
                for (var i = 0; i < items.length; i++) {
                    var it = items[i] || {};
                    var name = (it.name || it.title || 'Item');
                    var isFreeItem = it.is_free == 1;
                    var qty = parseFloat(it.quantity || 0);
                    var unit = parseFloat((it.unit_price != null ? it.unit_price : (it.price != null ? it.price : 0)));
                    // Use the same calculation logic as the invoice: prefer line_total, fallback to qty * unit_price
                    var lineTotal = isFreeItem ? 0 : parseFloat(it.line_total || 0);
                    if (!isFreeItem && (!lineTotal || lineTotal === 0)) {
                        lineTotal = qty * unit;
                    }
                    if (!isFinite(qty)) qty = 0;
                    if (!isFinite(unit)) unit = 0;
                    if (!isFinite(lineTotal)) lineTotal = 0;
                    itemsSubtotal += lineTotal;
                    
                    html += '<tr>';
                    
                    // Only show checkbox for open non-Shopify orders
                    if (showPreparationControls) {
                        html += '<td style="padding: 8px; border-bottom: 1px solid #f3f4f6; text-align: center;"><input type="checkbox" class="lineItemCheckbox" data-item-id="' + (it.id || '') + '" style="cursor: pointer;"></td>';
                    }
                    
                    var freeBadge = isFreeItem ? ' <span style="display: inline-block; padding: 2px 6px; background: #dcfce7; color: #16a34a; border-radius: 4px; font-size: 10px; font-weight: 700; margin-left: 6px;">FREE</span>' : '';
                    // 📦 bundle (approval queue only): what this line becomes on Accept
                    var bundleHint = it.bundle_hint ? '<div style="color:#92400e; font-size:11px; margin-top:2px;">📦 ' + escapeHtml(String(it.bundle_hint)) + '</div>' : '';
                    html += '<td style="padding: 8px; border-bottom: 1px solid #f3f4f6;">' + name + freeBadge + bundleHint + '</td>';
                    
                    // Only show status badge for open non-Shopify orders
                    if (showPreparationControls) {
                        var statusBadge = '';
                        if (it.preparation_status === 'preparing') {
                            statusBadge = '<span style="display: inline-block; padding: 4px 8px; background: #d1fae5; color: #065f46; border-radius: 4px; font-size: 11px; font-weight: 600;">Prepared</span>';
                        } else {
                            statusBadge = '<span style="display: inline-block; padding: 4px 8px; background: #f3f4f6; color: #6b7280; border-radius: 4px; font-size: 11px; font-weight: 600;">Not Started</span>';
                        }
                        html += '<td style="padding: 8px; border-bottom: 1px solid #f3f4f6; text-align: center;">' + statusBadge + '</td>';
                    }
                    
                    var lineTotalDisplay = isFreeItem ? '<span style="color: #16a34a; font-weight: 700;">FREE</span>' : formatCurrency(lineTotal, order.currency);
                    var scannedKgView = it.quantity_source === 'barcode' ? decodeScannedWeightKg(it.quantity_scanned_barcode) : null;
                    var scanTitleView = scannedKgView !== null ? ('Set by barcode scan — scanned ' + scannedKgView.toFixed(3) + ' kg') : 'Set by barcode scan';
                    // 📦 'box_scan' is a COUNTED product whose box was scanned to confirm the
                    // product — the quantity is the ordered one and NO weight was read, so this
                    // badge must never show a kg figure (the label's digits are a piece count).
                    var qtySrcBadge = it.quantity_source === 'barcode' ? ' <span title="' + scanTitleView + '" style="display:inline-block; padding:1px 5px; background:#dcfce7; color:#15803d; border-radius:3px; font-size:9px; font-weight:700;">🔖</span>' : it.quantity_source === 'box_scan' ? ' <span title="' + (orderedQtyIfChanged(it) === null ? 'Box scanned — quantity is as ordered' : 'Box scanned — box count confirmed by the packer') + '" style="display:inline-block; padding:1px 5px; background:#e0f2fe; color:#0369a1; border-radius:3px; font-size:9px; font-weight:700;">📦</span>' : it.quantity_source === 'manual' ? ' <span title="Set manually" style="display:inline-block; padding:1px 5px; background:#f1f5f9; color:#64748b; border-radius:3px; font-size:9px; font-weight:700;">✏️</span>' : '';
                    // 📋 What the customer ordered, under the quantity, once it has changed (screen only).
                    var orderedView = orderedQtyIfChanged(it);
                    var orderedNote = orderedView === null ? '' : '<div title="Quantity the customer ordered, before it was scanned / changed" style="font-size:10px; color:#b45309; font-weight:600; white-space:nowrap;">ordered ' + orderedView + '</div>';
                    html += '<td style="padding: 8px; border-bottom: 1px solid #f3f4f6; text-align:right;">' + qty + qtySrcBadge + orderedNote + '</td>' +
                        '<td style="padding: 8px; border-bottom: 1px solid #f3f4f6; text-align:right;">' + (isFreeItem ? '<s style="color:#9ca3af;">' + formatCurrency(unit, order.currency) + '</s>' : formatCurrency(unit, order.currency)) + '</td>' +
                        '<td style="padding: 8px; border-bottom: 1px solid #f3f4f6; text-align:right; font-weight:600;">' + lineTotalDisplay + '</td>' +
                    '</tr>';
                }
                html += '</tbody>';
                html += '<tfoot>';
                // Use calculated subtotal from line items only (exclude shipping/fees)
                html += '<tr><td></td><td></td><td style="padding: 8px; text-align:right; color:#6b7280;">Subtotal</td><td style="padding: 8px; text-align:right; font-weight:600;">' + formatCurrency(itemsSubtotal, order.currency) + '</td></tr>';
                // Show discount breakdown if available
                if (order.discounts && order.discounts.length > 0) {
                    // Multiple discounts - show each one
                    order.discounts.forEach(function(discount) {
                        html += '<tr><td></td><td></td><td style="padding: 8px; text-align:right; color:#6b7280;">' + discount.discount_title + '</td><td style="padding: 8px; text-align:right;">-' + formatCurrency(discount.discount_amount, order.currency) + '</td></tr>';
                    });
                } else if (order.discount_total) {
                    // Single discount - show as before (backward compatible)
                    const discountLabel = order.coupon_code ? 'Discount (' + order.coupon_code + ')' : 'Discount';
                    html += '<tr><td></td><td></td><td style="padding: 8px; text-align:right; color:#6b7280;">' + discountLabel + '</td><td style="padding: 8px; text-align:right;">-' + formatCurrency(order.discount_total, order.currency) + '</td></tr>';
                }
                if (order.shipping_total) {
                    html += '<tr><td></td><td></td><td style="padding: 8px; text-align:right; color:#6b7280;">Shipping</td><td style="padding: 8px; text-align:right;">' + formatCurrency(order.shipping_total, order.currency) + '</td></tr>';
                }
                if (order.tip_amount && order.tip_amount > 0) {
                    html += '<tr><td></td><td></td><td style="padding: 8px; text-align:right; color:#6b7280;">Tip</td><td style="padding: 8px; text-align:right;">' + formatCurrency(order.tip_amount, order.currency) + '</td></tr>';
                }
                html += '<tr><td></td><td></td><td style="padding: 8px; text-align:right; color:#111827; font-weight:700;">Total</td><td style="padding: 8px; text-align:right; font-weight:700;">' + formatCurrency(order.total_price, order.currency) + '</td></tr>';
                html += '</tfoot>';
                html += '</table>';
                html += '</div>';
            } else {
                html += '<div style="text-align:center; color:#6b7280; padding: 10px 0;">No line items</div>';
            }
            html += '</div>';

            // Order Notes Section (if notes exist)
            if (order.note && order.note.trim() !== '') {
                html += '<div style="padding: 20px; background-color: #f8fafc; border: 1px solid #e5e7eb; border-radius: 8px; margin: 20px 0 0 0;">';
                html += '<h3 style="margin: 0 0 12px 0; color: #111827; font-size: 16px;">Order Notes</h3>';
                html += '<div style="background-color: white; padding: 12px; border-radius: 6px; border-left: 4px solid #3b82f6;">';
                html += '<p style="margin: 0; color: #374151; line-height: 1.5; white-space: pre-wrap;">' + (order.note || '') + '</p>';
                html += '</div>';
                html += '</div>';
            }

            // Packet Tracking Section (if packet data exists OR a dispatch hand-over scan was recorded)
            if (order.expected_packets || order.actual_packets || order.dispatch_scanned_at || order.delivery_scanned_at) {
                html += '<div style="padding: 20px; background-color: #fef3c7; border: 1px solid #fbbf24; border-radius: 8px; margin: 20px 0 0 0;">';
                html += '<h3 style="margin: 0 0 12px 0; color: #92400e; font-size: 16px; display: flex; align-items: center; gap: 8px;"><span>📦</span> Packet Tracking</h3>';
                html += '<div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px;">';
                html += '<div style="background-color: white; padding: 12px; border-radius: 6px;">';
                html += '<div style="font-size: 12px; color: #6b7280; margin-bottom: 4px;">Expected Packets (Manager)</div>';
                html += '<div style="font-size: 24px; font-weight: 700; color: #111827;">' + (order.expected_packets || '-') + '</div>';
                html += '</div>';
                html += '<div style="background-color: white; padding: 12px; border-radius: 6px;">';
                html += '<div style="font-size: 12px; color: #6b7280; margin-bottom: 4px;">Actual Packets Delivered (Rider)</div>';
                html += '<div style="font-size: 24px; font-weight: 700; color: #111827;">' + (order.actual_packets || '-') + '</div>';
                if (order.expected_packets && order.actual_packets) {
                    if (order.expected_packets != order.actual_packets) {
                        html += '<div style="margin-top: 8px; padding: 6px 10px; background-color: #fee2e2; color: #dc2626; border-radius: 4px; font-size: 12px; font-weight: 600;">⚠️ Mismatch Detected</div>';
                    } else {
                        html += '<div style="margin-top: 8px; padding: 6px 10px; background-color: #d1fae5; color: #059669; border-radius: 4px; font-size: 12px; font-weight: 600;">✅ Verified</div>';
                    }
                }
                html += '</div>';
                html += '</div>';
                // Enh-2: dispatch hand-over audit — who scanned this order ready to leave, and when.
                // Lets management trace a wrong order back to the person who scanned it out.
                if (order.dispatch_scanned_at) {
                    html += '<div style="margin-top: 12px; padding: 10px 12px; background-color: white; border-radius: 6px; font-size: 13px; color: #374151;">';
                    html += '<span style="color: #6b7280;">Dispatch hand-over scan:</span> <strong>' + (order.dispatch_scanned_by_name ? escapeHtml(order.dispatch_scanned_by_name) : 'Done') + '</strong>';
                    html += ' · ' + formatDate(order.dispatch_scanned_at);
                    html += '</div>';
                }
                if (order.delivery_scanned_at) {
                    html += '<div style="margin-top: 8px; padding: 10px 12px; background-color: white; border-radius: 6px; font-size: 13px; color: #374151;">';
                    html += '<span style="color: #6b7280;">Delivery scan (rider):</span> <strong>' + (order.delivery_scanned_by_name ? escapeHtml(order.delivery_scanned_by_name) : 'Done') + '</strong>';
                    html += ' · ' + formatDate(order.delivery_scanned_at);
                    // Aug-2026: how many packets that scan actually covered. Older deliveries kept
                    // only the timestamp, so this stays hidden for them rather than showing "0 of N".
                    if (Number(order.delivery_scanned_count) > 0) {
                        html += ' · <span style="color:#6b7280;">' + Number(order.delivery_scanned_count) + ' of ' + (order.expected_packets || '?') + ' scanned</span>';
                    }
                    html += '</div>';
                }
                // A short delivery that a manager signed off on. Shown as its own amber line: the
                // red "Mismatch Detected" chip above says WHAT happened, this says it was allowed
                // and by whom — the two must never be confused when reviewing an order.
                if (order.scan_bypass_used_at && order.scan_bypass_status === 'approved') {
                    html += '<div style="margin-top: 8px; padding: 10px 12px; background-color: #fffbeb; border: 1px solid #fbbf24; border-radius: 6px; font-size: 13px; color: #92400e;">';
                    html += '<strong>Short delivery approved</strong>';
                    if (order.scan_bypass_decided_by_name) html += ' by ' + escapeHtml(order.scan_bypass_decided_by_name);
                    if (order.scan_bypass_packets != null && order.expected_packets) {
                        html += ' · ' + Number(order.scan_bypass_packets) + ' of ' + Number(order.expected_packets) + ' packets';
                    }
                    if (order.scan_bypass_reason) html += '<br><span style="color:#b45309;">Reason: ' + escapeHtml(order.scan_bypass_reason) + '</span>';
                    html += '</div>';
                }
                html += '</div>';
            }

            // Delivery Location Section (if available)
            if (data.delivery_location) {
                var loc = data.delivery_location;
                html += '<div style="padding: 20px; background-color: #dbeafe; border: 1px solid #3b82f6; border-radius: 8px; margin: 20px 0 0 0;">';
                html += '<h3 style="margin: 0 0 12px 0; color: #1e40af; font-size: 16px; display: flex; align-items: center; gap: 8px;"><span>📍</span> Delivery Location</h3>';
                html += '<div style="background-color: white; padding: 16px; border-radius: 6px;">';
                html += '<div style="display: grid; grid-template-columns: auto 1fr; gap: 12px; align-items: start;">';
                html += '<div style="font-size: 14px; color: #6b7280;">Coordinates:</div>';
                html += '<div style="font-size: 14px; color: #111827; font-family: monospace;">' + loc.latitude + ', ' + loc.longitude + '</div>';
                html += '<div style="font-size: 14px; color: #6b7280;">Delivered At:</div>';
                html += '<div style="font-size: 14px; color: #111827;">' + formatDate(loc.delivered_at) + '</div>';
                html += '</div>';
                html += '<a href="' + loc.google_maps_url + '" target="_blank" style="display: inline-flex; align-items: center; gap: 6px; margin-top: 12px; padding: 8px 16px; background-color: #3b82f6; color: white; text-decoration: none; border-radius: 6px; font-size: 14px; font-weight: 500;">';
                html += '<span>🗺️</span> View on Google Maps';
                html += '</a>';
                html += '</div>';
                html += '</div>';
            }

            // Rider Assignment Section
            html += '<div style="padding: 20px; background-color: #f0f9ff; border: 1px solid #0891b2; border-radius: 8px; margin: 20px 0 0 0;">';
            html += '<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;">';
            html += '<div style="flex:1;">';
            html += '<h3 style="margin: 0 0 4px 0; color: #111827; font-size: 16px;">Assigned Rider</h3>';
            html += '<div id="viewOrderRiderName" style="font-size:14px;font-weight:600;color:#0891b2;">Loading...</div>';
            html += '</div>';
            html += '<button id="viewOrderAssignRiderBtn" style="padding:10px 16px;background:#0ea5e9;color:#fff;border:0;border-radius:6px;cursor:pointer;font-weight:500;font-size:14px;">Assign / Change</button>';
            html += '</div>';
            html += '</div>';
            
            // Timeline Section with Tabs
            html += '<div style="padding: 20px; background-color: #f9fafb; border-radius: 8px; margin: 20px 0 0 0;">';
            
            // Tab buttons
            html += '<div style="display: flex; gap: 8px; margin-bottom: 16px; border-bottom: 2px solid #e5e7eb; padding-bottom: 8px;">';
            html += '<button id="viewOrderTabStatus" onclick="switchViewOrderTab(\'status\')" style="padding: 8px 16px; background: #10b981; color: white; border: none; border-radius: 6px 6px 0 0; cursor: pointer; font-weight: 600; font-size: 13px;">📋 Status History</button>';
            html += '<button id="viewOrderTabEvents" onclick="switchViewOrderTab(\'events\')" style="padding: 8px 16px; background: #e5e7eb; color: #374151; border: none; border-radius: 6px 6px 0 0; cursor: pointer; font-weight: 500; font-size: 13px;">📜 Full Event Timeline</button>';
            html += '</div>';
            
            // Status History Tab Content
            html += '<div id="viewOrderStatusContent" style="display: block;">';
            html += '<div id="viewOrderTimeline" style="max-height: 300px; overflow-y: auto;">';
            html += '<div style="text-align:center;color:#6b7280;font-size:13px;padding:20px;">Loading timeline...</div>';
            html += '</div>';
            html += '</div>';
            
            // Full Event Timeline Tab Content
            html += '<div id="viewOrderEventsContent" style="display: none;">';
            html += '<div id="viewOrderEventTimeline" style="max-height: 300px; overflow-y: auto;">';
            html += '<div style="text-align:center;color:#6b7280;font-size:13px;padding:20px;">Click to load full event timeline...</div>';
            html += '</div>';
            html += '</div>';
            
            html += '</div>';

            html += '</div>';
            html += '</div>';
            html += '</div>';
            
            content.innerHTML = html;
            
            // Store orderId for tab switching and reset event timeline loaded flag
            window._viewOrderId = orderId;
            _eventTimelineLoaded = false;
            
            // Load status timeline after content is rendered
            try {
                loadViewOrderTimeline(orderId);
            } catch (e) {
                console.warn('Failed to load view timeline', e);
            }
            
            // Wire up rider bar after content is loaded
            try {
                const riderNameEl = document.getElementById('viewOrderRiderName');
                const btn = document.getElementById('viewOrderAssignRiderBtn');
                if (riderNameEl && btn) {
                    const rname = order.rider_name || (order.assigned_rider && (order.assigned_rider.fullname || order.assigned_rider.name)) || (order.assigned_rider_user_id ? ('User #' + order.assigned_rider_user_id) : 'Unassigned');
                    riderNameEl.textContent = rname;
                    btn.onclick = function(){ openQuickRiderAssign(order.id, order.assigned_rider_user_id || null, rname); };
                }
            } catch(e) { console.warn('view rider bar update failed', e); }
        } else {
            content.innerHTML = `
                <div class="text-center py-8">
                    <div class="text-red-600 mb-4">
                        <svg class="mx-auto h-12 w-12" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path>
                        </svg>
                    </div>
                    <h3 class="text-lg font-medium text-gray-900 mb-2">Error Loading Order</h3>
                    <p class="text-gray-500">Unable to load order details</p>
                </div>
            `;
        }
    })
    .catch(error => {
        console.error('Error fetching order details:', error);
        content.innerHTML = `
            <div class="text-center py-8">
                <div class="text-red-600 mb-4">
                    <svg class="mx-auto h-12 w-12" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path>
                    </svg>
                </div>
                <h3 class="text-lg font-medium text-gray-900 mb-2">Network Error</h3>
                <p class="text-gray-500">Unable to connect to server. Please try again.</p>
            </div>
        `;
    });
}

// Line Item Status Management Functions
function toggleSelectAllLineItems() {
    const selectAll = document.getElementById('selectAllLineItems');
    const checkboxes = document.querySelectorAll('.lineItemCheckbox');
    checkboxes.forEach(cb => {
        cb.checked = selectAll.checked;
    });
}

function getSelectedLineItemIds() {
    const checkboxes = document.querySelectorAll('.lineItemCheckbox:checked');
    const ids = [];
    checkboxes.forEach(cb => {
        const itemId = cb.getAttribute('data-item-id');
        if (itemId) {
            ids.push(parseInt(itemId));
        }
    });
    return ids;
}

function markSelectedAsPreparing() {
    const selectedIds = getSelectedLineItemIds();
    if (selectedIds.length === 0) {
        alert('Please select at least one line item');
        return;
    }
    
    if (!currentOrderId) {
        alert('Order ID not found');
        return;
    }
    
    // Show loading state
    const button = event.target;
    const originalText = button.innerHTML;
    button.innerHTML = '⏳ Updating...';
    button.disabled = true;
    
    // Call API to update status
    fetch(`/orders/${currentOrderId}/line-items/bulk-update-status`, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json',
            'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').getAttribute('content'),
            'X-Requested-With': 'XMLHttpRequest'
        },
        credentials: 'same-origin',
        body: JSON.stringify({
            line_item_ids: selectedIds,
            preparation_status: 'preparing'
        })
    })
    .then(response => {
        if (!response.ok) {
            return response.json().then(err => {
                throw new Error(err.message || `HTTP error! status: ${response.status}`);
            });
        }
        return response.json();
    })
    .then(data => {
        if (data.success) {
            alert(`Updated ${data.updated_count} item(s) to Prepared status`);
            // Reload order details to show updated status
            viewOrderDetails(currentOrderId);
        } else {
            alert('Failed to update: ' + (data.message || 'Unknown error'));
        }
    })
    .catch(error => {
        console.error('Error updating line items:', error);
        alert('Failed to update line items: ' + error.message);
    })
    .finally(() => {
        button.innerHTML = originalText;
        button.disabled = false;
    });
}

function clearSelectedPreparingStatus() {
    const selectedIds = getSelectedLineItemIds();
    if (selectedIds.length === 0) {
        alert('Please select at least one line item');
        return;
    }
    
    if (!currentOrderId) {
        alert('Order ID not found');
        return;
    }
    
    // Show loading state
    const button = event.target;
    const originalText = button.innerHTML;
    button.innerHTML = '⏳ Updating...';
    button.disabled = true;
    
    // Call API to clear status
    fetch(`/orders/${currentOrderId}/line-items/bulk-update-status`, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json',
            'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').getAttribute('content'),
            'X-Requested-With': 'XMLHttpRequest'
        },
        credentials: 'same-origin',
        body: JSON.stringify({
            line_item_ids: selectedIds,
            preparation_status: null
        })
    })
    .then(response => {
        if (!response.ok) {
            return response.json().then(err => {
                throw new Error(err.message || `HTTP error! status: ${response.status}`);
            });
        }
        return response.json();
    })
    .then(data => {
        if (data.success) {
            alert(`Cleared status for ${data.updated_count} item(s)`);
            // Reload order details to show updated status
            viewOrderDetails(currentOrderId);
        } else {
            alert('Failed to update: ' + (data.message || 'Unknown error'));
        }
    })
    .catch(error => {
        console.error('Error updating line items:', error);
        alert('Failed to update line items: ' + error.message);
    })
    .finally(() => {
        button.innerHTML = originalText;
        button.disabled = false;
    });
}

// View Invoice
let currentOrderId = null;

function viewInvoice() {
    if (currentOrderId) {
        window.open(ordersInvoiceUrl(currentOrderId), '_blank');
    } else {
        console.error('No order ID available for invoice');
    }
}

function downloadInvoicePdf() {
    if (currentOrderId) {
        // Show loading state on button
        const button = event.target;
        const originalText = button.innerHTML;
        button.innerHTML = 'â³ Generating PDF...';
        button.disabled = true;
        
        // Use the same approach as PNG but for PDF - open invoice page with auto-PDF generation
        window.open(ordersInvoiceUrl(currentOrderId, 'print_pdf=1'), '_blank');
        
        // Reset button after download attempt
        setTimeout(() => {
            button.innerHTML = originalText;
            button.disabled = false;
        }, 3000);
        
    } else {
        console.error('No order ID available for PDF download');
    }
}

function downloadInvoiceImage() {
    if (currentOrderId) {
        // Show loading state on button
        const button = event.target;
        const originalText = button.innerHTML;
        button.innerHTML = 'â³ Printing Invoice...';
        button.disabled = true;
        
        // Open web invoice and auto-generate a PNG from the DOM for exact visual match
        // Use 'view_and_download_png=1' instead of 'auto_png=1' to keep page open
        window.open(ordersInvoiceUrl(currentOrderId, 'view_and_download_png=1'), '_blank');
        
        // Reset button after download attempt
        setTimeout(() => {
            button.innerHTML = originalText;
            button.disabled = false;
        }, 3000);
    } else {
        console.error('No order ID available for image download');
    }
}

function printInvoicePdf() {
    if (currentOrderId) {
        // Open invoice page in new tab - it has download options
        window.open(ordersInvoiceUrl(currentOrderId), '_blank');
    } else {
        console.error('No order ID available for PDF printing');
    }
}

// Print invoice WITHOUT unit price column (hides unit price from users)
function printInvoiceWithoutUnit() {
    if (currentOrderId) {
        // Show loading state on button
        const button = event.target;
        const originalText = button.innerHTML;
        button.innerHTML = '⏳ Printing...';
        button.disabled = true;
        
        // Open invoice with hide_unit_price=1 and view_and_download_png=1 
        // This will render and auto-download PNG without unit price column
        window.open(ordersInvoiceUrl(currentOrderId, 'hide_unit_price=1&view_and_download_png=1'), '_blank');
        
        // Reset button after download attempt
        setTimeout(() => {
            button.innerHTML = originalText;
            button.disabled = false;
        }, 3000);
    } else {
        console.error('No order ID available for printing without unit');
    }
}

// Send Invoice via WhatsApp
function openFullscreenImg(src) {
    if (!src) return;
    var overlay = document.getElementById('waImgOverlay');
    if (overlay) overlay.remove();
    overlay = document.createElement('div');
    overlay.id = 'waImgOverlay';
    overlay.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.85);z-index:99999;display:flex;align-items:center;justify-content:center;cursor:zoom-out;';
    overlay.innerHTML = '<img src="' + src + '" style="max-width:92vw;max-height:92vh;border-radius:8px;box-shadow:0 8px 32px rgba(0,0,0,0.5);" /><button style="position:absolute;top:16px;right:24px;background:rgba(255,255,255,0.15);border:none;color:#fff;font-size:28px;cursor:pointer;border-radius:50%;width:44px;height:44px;display:flex;align-items:center;justify-content:center;">&times;</button>';
    overlay.addEventListener('click', function() { overlay.remove(); });
    document.body.appendChild(overlay);
}

function quickSendInvoiceWhatsApp(orderId, orderNum, total, custName, custPhone) {
    currentOrderId = orderId;
    window.currentOrder = { order_number: orderNum, total_price: total, customer_name: custName };
    window.currentOrder.customer = { phone_normalized: custPhone, phone: custPhone };
    openSendInvoiceWhatsApp();
}

// ──────────────────────────────────────────────────────────────────────────
// Send WhatsApp Message modal for regular Open Orders.
// Dual-tab: "Invoice" (existing send-invoice flow with auto-preview) and
// "Other Message" (any non-invoice regular template via /messages/send-template).
// Mirrors the Qurbani orders implementation to keep UX consistent.
// ──────────────────────────────────────────────────────────────────────────
let _regWaCustName = '';
let _regWaOrderNum = '';
// Jun-2026: the delivery ETA window (e.g. "Today, 4:10-4:40 PM") for the
// with-ETA invoice templates. Filled from the server send-plan when the dialog
// opens; blank when the order isn't out-for-delivery yet. NOTE the ETA string
// contains a comma, so it can NEVER be round-tripped through a naive
// comma-split — see the structured-params handling in sendInvoiceWhatsApp().
let _regWaEta = '';
let _regWaOrderId = '';
let _regWaOrderSource = '';
// Jul-2026 — capture lifecycle for the CURRENT dialog. previewInvoiceWhatsApp()
// flips pending → ready/failed and sendInvoiceWhatsApp() gates on it: while the
// image is still being prepared, Send keeps the dialog open with a "please
// wait" note (the running capture is never restarted or cancelled); when the
// capture failed, Send offers Refresh-Preview-to-retry or an explicit second
// press to send anyway (server may still hold the last saved image). The token
// invalidates callbacks from a previous dialog (quick-succession reopen) so a
// stale capture can't mutate the new dialog's state.
let _regWaCaptureState = 'idle';   // idle | pending | ready | failed
let _regWaCaptureToken = 0;
let _regWaCaptureReadyAt = 0;
let _regWaSendAnywayArmed = false;

function openSendInvoiceWhatsApp() {
    if (!currentOrderId) { alert('No order selected'); return; }

    const order = window.currentOrder;
    const custName = order?.customer_name || order?.name || ((order?.address_first_name || '') + ' ' + (order?.address_last_name || '')).trim() || (order?.customer ? `${order.customer.first_name || ''} ${order.customer.last_name || ''}`.trim() : '') || '';
    const custPhone = order?.customer?.phone_normalized || order?.address_phone || order?.customer?.phone || '';
    const orderNum = order?.order_number || '';
    _regWaCustName = custName;
    _regWaOrderNum = orderNum;
    _regWaEta = '';
    _regWaOrderId = currentOrderId;
    // Source-aware (Shopify-staging vs prod id collision): the send-plan must
    // resolve the order from the right table. currentOrderSource() reads
    // window.currentSource (set on every page load by initOrdersSourceContext())
    // with a ?source= URL fallback.
    _regWaOrderSource = (typeof currentOrderSource === 'function') ? currentOrderSource() : (window.currentSource || '');

    let existing = document.getElementById('waInvoiceDialog');
    if (existing) existing.remove();

    const escHtml = function(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function(c) { return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); };

    const dialog = document.createElement('div');
    dialog.id = 'waInvoiceDialog';
    dialog.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.5);z-index:10000;display:flex;align-items:center;justify-content:center;';
    dialog.innerHTML = `
        <div style="background:#fff;border-radius:12px;width:520px;max-width:95vw;max-height:90vh;overflow:auto;box-shadow:0 20px 60px rgba(0,0,0,0.3);">
            <div style="padding:16px 20px;border-bottom:1px solid #e5e7eb;display:flex;align-items:center;justify-content:space-between;">
                <div style="display:flex;align-items:center;gap:8px;">
                    <span style="font-size:20px;">📱</span>
                    <span style="font-weight:700;font-size:15px;color:#111827;">Send WhatsApp Message</span>
                </div>
                <button onclick="document.getElementById('waInvoiceDialog').remove()" style="background:none;border:none;font-size:20px;cursor:pointer;color:#6b7280;">&times;</button>
            </div>
            <div style="padding:16px 20px 6px;">
                <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:12px;">
                    <div>
                        <div style="font-size:11px;color:#6b7280;margin-bottom:2px;">Customer</div>
                        <div style="font-size:14px;font-weight:600;color:#111827;">${escHtml(custName || 'Unknown')}</div>
                    </div>
                    <div>
                        <div style="font-size:11px;color:#6b7280;margin-bottom:2px;">Order</div>
                        <div id="waInvHeaderTotal" style="font-size:14px;font-weight:600;color:#111827;">#${escHtml(orderNum)} — Rs. ${parseFloat(order?.total_price || 0).toLocaleString()}</div>
                    </div>
                </div>
                <div style="margin-bottom:12px;">
                    <label style="font-size:12px;color:#6b7280;display:block;margin-bottom:4px;">Phone Number</label>
                    <input id="waInvPhone" type="text" value="${escHtml(custPhone)}" style="width:100%;padding:8px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:14px;" placeholder="923001234567" />
                </div>

                <!-- Tab bar -->
                <div style="display:inline-flex;background:#f3f4f6;border-radius:8px;padding:3px;margin-bottom:14px;">
                    <button id="regWaTabInvoice" type="button" onclick="regWaSwitchTab('invoice')" style="padding:6px 14px;border:none;background:#fff;color:#111827;border-radius:6px;font-size:12px;font-weight:600;cursor:pointer;box-shadow:0 1px 2px rgba(0,0,0,0.08);">🧾 Invoice</button>
                    <button id="regWaTabOther" type="button" onclick="regWaSwitchTab('other')" style="padding:6px 14px;border:none;background:transparent;color:#6b7280;border-radius:6px;font-size:12px;font-weight:600;cursor:pointer;">💬 Other Message</button>
                </div>

                <!-- INVOICE TAB -->
                <div id="regWaInvoicePanel">
                    <div style="margin-bottom:12px;">
                        <label style="font-size:12px;color:#6b7280;display:block;margin-bottom:4px;">Invoice Template</label>
                        <select id="waInvTemplate" style="width:100%;padding:8px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:14px;background:#fff;" onchange="onRegularInvoiceTemplateChange(true)">
                            <option value="">Loading templates...</option>
                        </select>
                        <div style="font-size:11px;color:#9ca3af;margin-top:4px;">Templates tagged as "Invoice" in Manage Templates</div>
                    </div>
                    <div style="margin-bottom:12px;">
                        <label style="font-size:12px;color:#6b7280;display:block;margin-bottom:4px;">Body Variables (comma-separated)</label>
                        <input id="waInvBodyParams" type="text" value="${escHtml(custName)}, ${escHtml(orderNum)}" oninput="this.dataset.dirty='1'" style="width:100%;padding:8px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:14px;" />
                        <div id="waInvVarHint" style="font-size:11px;color:#9ca3af;margin-top:4px;">Variables are passed to the template in order (e.g. 1=Name, 2=Order#)</div>
                    </div>
                    <div id="waInvPreviewArea" style="margin-bottom:12px;display:none;">
                        <label style="font-size:12px;color:#6b7280;display:block;margin-bottom:4px;">Invoice Preview</label>
                        <div id="waInvPreviewBox" style="border:1px solid #e5e7eb;border-radius:8px;overflow:hidden;text-align:center;background:#f9fafb;padding:8px;">
                            <img id="waInvPreviewImg" style="max-width:100%;max-height:300px;border-radius:4px;cursor:pointer;" onclick="openFullscreenImg(this.src)" title="Click to view full size" />
                        </div>
                    </div>
                    <div style="display:flex;gap:8px;">
                        <button id="waInvPreviewBtn" onclick="previewInvoiceWhatsApp()" style="flex:1;padding:10px;border:1px solid #25D366;color:#25D366;background:#fff;border-radius:8px;font-weight:600;cursor:pointer;font-size:13px;">Refresh Preview</button>
                        <button id="waInvSendBtn" onclick="sendInvoiceWhatsApp()" style="flex:1;padding:10px;background:#25D366;color:#fff;border:none;border-radius:8px;font-weight:600;cursor:pointer;font-size:13px;">Send Invoice</button>
                    </div>
                    <div id="waInvStatus" style="margin-top:10px;font-size:13px;text-align:center;display:none;"></div>
                </div>

                <!-- OTHER TAB -->
                <div id="regWaOtherPanel" style="display:none;">
                    <div style="margin-bottom:12px;">
                        <label style="font-size:12px;color:#6b7280;display:block;margin-bottom:4px;">Message Template</label>
                        <select id="regWaOtherTpl" style="width:100%;padding:8px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:14px;background:#fff;" onchange="onRegularOtherTemplateChange()">
                            <option value="">Loading templates...</option>
                        </select>
                        <div style="font-size:11px;color:#9ca3af;margin-top:4px;">Shows templates allowed on regular orders (no invoice templates).</div>
                    </div>
                    <div style="margin-bottom:12px;">
                        <label style="font-size:12px;color:#6b7280;display:block;margin-bottom:4px;">Body Variables (comma-separated)</label>
                        <input id="regWaOtherParams" type="text" value="${escHtml(custName)}" style="width:100%;padding:8px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:14px;">
                        <div id="regWaOtherHint" style="font-size:11px;color:#9ca3af;margin-top:4px;">Variables are passed to the template in order.</div>
                    </div>
                    <div id="regWaOtherPreview" style="display:none;background:#f9fafb;border:1px dashed #e5e7eb;border-radius:6px;padding:10px;margin-bottom:12px;font-size:12px;color:#374151;white-space:pre-wrap;"></div>
                    <div style="display:flex;gap:8px;">
                        <button onclick="sendRegularOtherMessage()" style="flex:1;padding:10px;background:#25D366;color:#fff;border:none;border-radius:8px;font-weight:600;cursor:pointer;font-size:13px;">Send Message</button>
                    </div>
                    <div id="regWaOtherStatus" style="margin-top:10px;font-size:13px;text-align:center;display:none;"></div>
                </div>
            </div>
        </div>`;
    document.body.appendChild(dialog);
    // Aug-2026 — backdrop close must require the press AND the release on the
    // backdrop. A plain `click` closer fired while EDITING THE PHONE NUMBER:
    // per the DOM spec, when mousedown and mouseup land on different elements
    // the click event is dispatched to their nearest COMMON ANCESTOR. Drag-
    // selecting the number in the full-width input and releasing past the card
    // edge = mousedown(input) + mouseup(overlay) => click on the backdrop =>
    // the dialog vanished mid-edit. Tracking mousedown fixes it without
    // changing the intended behaviour (a real click on the backdrop closes).
    let _regWaDownOnBackdrop = false;
    dialog.addEventListener('mousedown', function(e) { _regWaDownOnBackdrop = (e.target === dialog); });
    dialog.addEventListener('click', function(e) {
        if (e.target === dialog && _regWaDownOnBackdrop) dialog.remove();
        _regWaDownOnBackdrop = false;
    });

    regWaLoadInvoiceTemplates(order && order.payment_method ? order.payment_method : '');
    regWaLoadOtherTemplates();

    // Auto-preview invoice on open so users always see what they're sending,
    // even if they jump straight to "Send Invoice" without pressing preview.
    previewInvoiceWhatsApp();
}

function regWaSwitchTab(tab) {
    var invTab = document.getElementById('regWaTabInvoice');
    var othTab = document.getElementById('regWaTabOther');
    var invPanel = document.getElementById('regWaInvoicePanel');
    var othPanel = document.getElementById('regWaOtherPanel');
    if (!invTab || !othTab || !invPanel || !othPanel) return;
    var activeStyle = 'padding:6px 14px;border:none;background:#fff;color:#111827;border-radius:6px;font-size:12px;font-weight:600;cursor:pointer;box-shadow:0 1px 2px rgba(0,0,0,0.08);';
    var inactiveStyle = 'padding:6px 14px;border:none;background:transparent;color:#6b7280;border-radius:6px;font-size:12px;font-weight:600;cursor:pointer;';
    if (tab === 'other') {
        invTab.setAttribute('style', inactiveStyle);
        othTab.setAttribute('style', activeStyle);
        invPanel.style.display = 'none';
        othPanel.style.display = '';
    } else {
        invTab.setAttribute('style', activeStyle);
        othTab.setAttribute('style', inactiveStyle);
        invPanel.style.display = '';
        othPanel.style.display = 'none';
    }
}

function regWaLoadInvoiceTemplates(paymentMethod) {
    window._regInvoiceTemplates = [];
    fetch('/messages/templates?context=invoice', {
        headers: {'Accept': 'application/json', 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.content || ''}
    }).then(r => r.json()).then(d => {
        var sel = document.getElementById('waInvTemplate');
        if (!sel) return;
        sel.innerHTML = '';
        var tpls = (d.templates || []);
        window._regInvoiceTemplates = tpls;
        if (tpls.length === 0) {
            sel.innerHTML = '<option value="">No invoice templates found</option>';
            return;
        }
        var defaultIdx = tpls.findIndex(function(t) { return t.is_default; });
        if (defaultIdx < 0) defaultIdx = 0;
        tpls.forEach(function(t, i) {
            var opt = document.createElement('option');
            opt.value = t.name;
            opt.textContent = t.display_name + ' (' + t.variable_count + ' vars)' + (t.is_default ? ' ⭐' : '');
            opt.dataset.varCount = t.variable_count;
            if (i === defaultIdx) opt.selected = true;
            sel.appendChild(opt);
        });
        onRegularInvoiceTemplateChange();
        // Jun-2026: pre-select the online/cash invoice template by this order's
        // payment method. Pure pre-select — the user can still change it.
        regWaPreselectInvoiceByPayment(paymentMethod, sel, tpls);
    }).catch(function() {
        var sel = document.getElementById('waInvTemplate');
        if (sel) sel.innerHTML = '<option value="">Failed to load templates</option>';
    });
}

// Classify a (possibly messy) payment_method string into 'cash' | 'online' | ''.
// Mirrors the server-side grouping; handles free-text values like
// "Regular Meat: Direct Bank Transfer" and "Cash on Delivery (COD)".
function waClassifyPayment(pm) {
    pm = String(pm || '').toLowerCase();
    if (!pm) return '';
    if (pm.indexOf('cash') !== -1 || pm.indexOf('cod') !== -1) return 'cash';
    if (pm.indexOf('bank') !== -1 || pm.indexOf('online') !== -1 || pm.indexOf('transfer') !== -1 || pm.indexOf('card') !== -1) return 'online';
    return '';
}

// Pre-select the configured invoice template for this order and pre-fill its
// body variables. Uses the server "send plan" which resolves online-vs-cash by
// payment method AND with-ETA-vs-no-ETA by whether the delivery window exists
// yet (out for delivery), returning the exact body params [name, order#, ETA].
// Falls back to the lighter online/cash map if the plan can't be fetched. Pure
// pre-fill — never breaks the picker; the operator can still change anything.
function regWaPreselectInvoiceByPayment(paymentMethod, sel, tpls) {
    if (!sel) return;
    var orderId = _regWaOrderId;
    if (!orderId) { regWaPreselectInvoiceFallback(paymentMethod, sel, tpls); return; }
    var src = _regWaOrderSource || '';
    var url = '/messages/automations/invoice-send-plan/' + encodeURIComponent(orderId)
        + (src ? ('?source=' + encodeURIComponent(src)) : '');
    fetch(url, { headers: { 'Accept': 'application/json' } })
        .then(function(r){ return r.json(); })
        .then(function(d){
            if (!d || !d.success || !d.template) { regWaPreselectInvoiceFallback(paymentMethod, sel, tpls); return; }
            // Remember the resolved delivery window so onRegularInvoiceTemplateChange
            // can fill it in for 3-var templates (now and on any later template switch).
            _regWaEta = d.eta || '';
            // Refresh the dialog header with the CURRENT server-side total. The
            // header was seeded from the orders-table row, which can be stale
            // (a barcode scan may reprice the order seconds before this dialog
            // opens). The send-plan is source-aware and just re-read the order,
            // so this is the authoritative amount. Display-only — the actual
            // invoice image is captured server-fresh at send time regardless.
            if (d.total_price != null) {
                var htotal = document.getElementById('waInvHeaderTotal');
                if (htotal) htotal.textContent = '#' + (_regWaOrderNum || '') + ' — Rs. ' + parseFloat(d.total_price).toLocaleString();
            }
            var found = (tpls || []).some(function(t){ return t.name === d.template; });
            if (found) { sel.value = d.template; }
            // Re-fill the body vars for whatever template is now selected.
            onRegularInvoiceTemplateChange();
        }).catch(function(){ regWaPreselectInvoiceFallback(paymentMethod, sel, tpls); });
}

// Lighter pre-select used when the send-plan isn't reachable: just picks the
// no-ETA online/cash template by payment method (the previous behaviour).
function regWaPreselectInvoiceFallback(paymentMethod, sel, tpls) {
    var kind = waClassifyPayment(paymentMethod);
    if (!kind || !sel) return;
    fetch('/messages/automations/invoice-template-map', { headers: { 'Accept': 'application/json' } })
        .then(function(r){ return r.json(); })
        .then(function(d){
            if (!d || !d.success) return;
            var want = kind === 'cash' ? d.cash : d.online;
            if (!want) return;
            var found = (tpls || []).some(function(t){ return t.name === want; });
            if (found) { sel.value = want; onRegularInvoiceTemplateChange(); }
        }).catch(function(){});
}

// Load non-invoice templates that are allowed on regular order pages. The
// getTemplates endpoint already:
//   - hides inactive templates,
//   - hides qurbani-only templates for non-qurbani contexts,
// so we just need to exclude invoice templates ourselves.
function regWaLoadOtherTemplates() {
    window._regOtherTemplates = [];
    fetch('/messages/templates?context=orders,messages,customers', {
        headers: {'Accept': 'application/json', 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.content || ''}
    }).then(function(r) { return r.json(); })
    .then(function(data) {
        var sel = document.getElementById('regWaOtherTpl');
        if (!sel) return;
        sel.innerHTML = '';
        var tpls = (data.templates || []).filter(function(t) {
            var raw = t.show_in;
            var showIn = Array.isArray(raw)
                ? raw.map(function(x) { return String(x).toLowerCase().trim(); })
                : String(raw || '').toLowerCase().split(',').map(function(x) { return x.trim(); });
            if (showIn.indexOf('invoice') >= 0 || showIn.indexOf('qurbani_invoice') >= 0) return false;
            return true;
        });
        window._regOtherTemplates = tpls;
        if (tpls.length === 0) {
            sel.innerHTML = '<option value="">No templates available</option>';
            return;
        }
        var defaultOpt = document.createElement('option');
        defaultOpt.value = '';
        defaultOpt.textContent = '-- Select a template --';
        sel.appendChild(defaultOpt);
        tpls.forEach(function(t, i) {
            var opt = document.createElement('option');
            opt.value = t.name;
            opt.textContent = t.display_name + ' (' + t.variable_count + ' vars)';
            opt.dataset.varCount = t.variable_count;
            opt.dataset.idx = i;
            sel.appendChild(opt);
        });
    })
    .catch(function() {
        var sel = document.getElementById('regWaOtherTpl');
        if (sel) sel.innerHTML = '<option value="">Failed to load templates</option>';
    });
}

function onRegularOtherTemplateChange() {
    var sel = document.getElementById('regWaOtherTpl');
    var paramsInput = document.getElementById('regWaOtherParams');
    var hintEl = document.getElementById('regWaOtherHint');
    var previewEl = document.getElementById('regWaOtherPreview');
    if (!sel || !paramsInput) return;
    var selectedOpt = sel.options[sel.selectedIndex];
    var idx = selectedOpt?.dataset?.idx;
    var tpls = window._regOtherTemplates || [];
    var tpl = (idx != null) ? tpls[parseInt(idx)] : null;
    var varCount = parseInt(selectedOpt?.dataset?.varCount || '0');

    if (varCount === 0) {
        paramsInput.value = '';
        if (hintEl) hintEl.textContent = 'This template has no variables';
    } else if (varCount === 1) {
        paramsInput.value = _regWaCustName;
        if (hintEl) hintEl.textContent = '1 variable: Name';
    } else {
        paramsInput.value = _regWaCustName + ', ' + _regWaOrderNum;
        if (hintEl) hintEl.textContent = varCount + ' variables (e.g. Name, Order#)';
    }

    if (previewEl) {
        if (tpl && tpl.body_text) {
            previewEl.textContent = tpl.body_text;
            previewEl.style.display = '';
        } else {
            previewEl.style.display = 'none';
        }
    }
}

function sendRegularOtherMessage() {
    var phone = document.getElementById('waInvPhone').value.trim();
    var tplSel = document.getElementById('regWaOtherTpl');
    var templateName = tplSel ? tplSel.value.trim() : '';
    var paramsStr = (document.getElementById('regWaOtherParams').value || '').trim();
    if (!phone) { alert('Please enter a phone number'); return; }
    if (!templateName) { alert('Please pick a template'); return; }
    var params = paramsStr ? paramsStr.split(',').map(function(s) { return s.trim(); }) : [];
    var statusEl = document.getElementById('regWaOtherStatus');
    var btn = document.querySelector('#regWaOtherPanel button[onclick="sendRegularOtherMessage()"]');
    if (btn) { btn.textContent = 'Sending...'; btn.disabled = true; }
    if (statusEl) statusEl.style.display = 'none';

    fetch('/messages/send-template', {
        method: 'POST',
        headers: {'Content-Type': 'application/json', 'Accept': 'application/json', 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.content || ''},
        body: JSON.stringify({phone: phone, template_name: templateName, body_params: params}),
    })
    .then(function(r) { return r.json(); })
    .then(function(data) {
        if (!statusEl || !btn) return;
        if (data.success) {
            statusEl.style.display = 'block'; statusEl.style.color = '#16a34a';
            statusEl.textContent = 'Message sent successfully!';
            btn.textContent = 'Sent!';
            setTimeout(function() { var el = document.getElementById('waInvoiceDialog'); if (el) el.remove(); }, 1500);
        } else {
            statusEl.style.display = 'block'; statusEl.style.color = '#dc2626';
            statusEl.textContent = data.message || 'Failed to send';
            btn.textContent = 'Send Message'; btn.disabled = false;
        }
    })
    .catch(function(e) {
        if (statusEl) { statusEl.style.display = 'block'; statusEl.style.color = '#dc2626'; statusEl.textContent = e.message; }
        if (btn) { btn.textContent = 'Send Message'; btn.disabled = false; }
    });
}

// userSwitched=true when the operator changed the template themselves (the
// select's onchange) — then the body vars are always rebuilt and the hand-edit
// flag cleared, because the new template genuinely needs different variables.
// The ASYNC callers (template load + the send-plan fetch, which lands hundreds
// of ms after the dialog opens) call this with no argument, and must NOT clobber
// something the operator has already typed. Aug-2026: before this guard, editing
// the variables right after opening the dialog got silently overwritten when the
// send-plan reply arrived.
function onRegularInvoiceTemplateChange(userSwitched) {
    var sel = document.getElementById('waInvTemplate');
    var paramsInput = document.getElementById('waInvBodyParams');
    var hintEl = document.getElementById('waInvVarHint');
    if (!sel || !paramsInput) return;
    if (userSwitched) {
        delete paramsInput.dataset.dirty;
    } else if (paramsInput.dataset.dirty === '1') {
        return; // operator owns this field now
    }
    var selectedOpt = sel.options[sel.selectedIndex];
    var varCount = parseInt(selectedOpt?.dataset?.varCount || '0');
    var custName = _regWaCustName || '';
    var orderNum = _regWaOrderNum || '';
    var eta = _regWaEta || '';
    // Build the body variables in the order the invoice templates expect:
    //   1 var  -> Name
    //   2 vars -> Name, Order#                (online/cash no-ETA templates)
    //   3 vars -> Name, Order#, ETA window    (with-ETA templates, out for delivery)
    var parts;
    if (varCount === 0) {
        parts = [];
        if (hintEl) hintEl.textContent = 'This template has no variables';
    } else if (varCount === 1) {
        parts = [custName];
        if (hintEl) hintEl.textContent = '1 variable: Name';
    } else if (varCount === 2) {
        parts = [custName, orderNum];
        if (hintEl) hintEl.textContent = '2 variables: Name, Order#';
    } else {
        parts = [custName, orderNum, eta];
        if (hintEl) hintEl.textContent = eta
            ? '3 variables: Name, Order#, ETA (delivery window)'
            : '3 variables: Name, Order#, ETA — not out for delivery yet, fill the window in';
    }
    // Stash the exact array so the send can use it verbatim. The ETA window
    // contains a comma ("Today, 4:10-4:40 PM"), so a naive comma-split of the
    // visible text would shatter it into extra params — the send prefers this
    // structured copy whenever the operator hasn't hand-edited the field.
    paramsInput.dataset.structured = JSON.stringify(parts);
    paramsInput.value = parts.join(', ');
}

function captureInvoiceImageOrders(invoiceUrl, orderId) {
    return new Promise((resolve, reject) => {
        const iframe = document.createElement('iframe');
        iframe.style.cssText = 'position:fixed;left:-9999px;top:0;width:900px;height:1400px;border:none;opacity:0;';
        // Aug-2026 — the capture must never steal the operator's cursor. The
        // preview runs automatically when the dialog opens, so this iframe
        // loads WHILE the phone number is being edited; a loading iframe takes
        // focus, which dropped the caret out of the field mid-typing and read
        // as "the dialog refreshed itself". tabindex=-1 keeps it out of the tab
        // order, and the caret (plus its selection range) is restored on load.
        iframe.setAttribute('tabindex', '-1');
        iframe.setAttribute('aria-hidden', 'true');
        const _focusSnap = document.activeElement;
        const _selSnap = (_focusSnap && typeof _focusSnap.selectionStart === 'number')
            ? { start: _focusSnap.selectionStart, end: _focusSnap.selectionEnd } : null;
        const restoreFocus = () => {
            try {
                if (!_focusSnap || !document.body.contains(_focusSnap)) return;
                if (document.activeElement === _focusSnap) return; // never moved
                _focusSnap.focus({ preventScroll: true });
                if (_selSnap && typeof _focusSnap.setSelectionRange === 'function') {
                    _focusSnap.setSelectionRange(_selSnap.start, _selSnap.end);
                }
            } catch (e) { /* focus restore is best-effort, never fatal */ }
        };
        document.body.appendChild(iframe);
        iframe.src = invoiceUrl;
        iframe.onload = async function() {
            restoreFocus();
            try {
                const addScript = (doc, src) => new Promise(r => { const s = doc.createElement('script'); s.src = src; s.onload = r; doc.head.appendChild(s); });
                const iDoc = iframe.contentDocument || iframe.contentWindow.document;
                await addScript(iDoc, 'https://cdn.jsdelivr.net/npm/html2canvas@1.4.1/dist/html2canvas.min.js');
                const node = iDoc.querySelector('.invoice-container');
                if (!node) { iframe.remove(); reject(new Error('Invoice container not found')); return; }
                // Aug-2026: compact ?wa=1 layout + dynamic scale. The long
                // side targets <=1600px (WhatsApp re-encodes larger images on
                // delivery, so extra pixels only slow the capture), width
                // floor 800px, cap 2.2x. JPEG keeps the explicit white
                // background (no alpha).
                const rect = node.getBoundingClientRect();
                const capScale = Math.max(800 / Math.max(rect.width, 1), Math.min(2.2, 1600 / Math.max(rect.height, 1)));
                const canvas = await iframe.contentWindow.html2canvas(node, {scale: capScale, useCORS: true, allowTaint: true, backgroundColor: '#ffffff'});
                const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
                iframe.remove();

                const csrf = document.querySelector('meta[name="csrf-token"]')?.content || '';
                const uploadRes = await fetch('/messages/upload-invoice-image', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json', 'X-CSRF-TOKEN': csrf, 'Accept': 'application/json'},
                    body: JSON.stringify({ order_id: orderId, image_data: dataUrl })
                }).then(r => r.json());
                if (uploadRes.success) { resolve(uploadRes); }
                else { reject(new Error(uploadRes.message || 'Upload failed')); }
            } catch (err) { iframe.remove(); reject(err); }
        };
        iframe.onerror = function() { iframe.remove(); reject(new Error('Failed to load invoice')); };
    });
}

// Inline status line inside the invoice tab (reuses the existing waInvStatus
// div). Pass no message to clear it. dataset.waiting marks that the user
// pressed Send while the capture was still preparing, so the capture's
// completion callback can tell them it's now safe to press Send again.
function regWaSetCaptureStatus(msg, color) {
    const el = document.getElementById('waInvStatus');
    if (!el) return;
    if (!msg) { el.style.display = 'none'; el.textContent = ''; delete el.dataset.waiting; return; }
    el.style.display = 'block';
    el.style.color = color || '#6b7280';
    el.textContent = msg;
}

function previewInvoiceWhatsApp() {
    const btn = document.getElementById('waInvPreviewBtn');
    if (!btn) return;
    btn.textContent = 'Loading...';
    btn.disabled = true;

    // Snapshot the order id — currentOrderId is mutated by other dialogs.
    const orderIdSnap = _regWaOrderId || currentOrderId;
    const token = ++_regWaCaptureToken;
    _regWaCaptureState = 'pending';
    _regWaSendAnywayArmed = false;
    const sendBtn = document.getElementById('waInvSendBtn');
    if (sendBtn) sendBtn.textContent = 'Send Invoice';
    regWaSetCaptureStatus('');

    // settled guards double-settling: the 45s watchdog below can declare the
    // capture failed while the real capture is still limping along; whichever
    // fires first wins the UI (a late success after the watchdog still
    // upgrades state to 'ready' — the upload happened, sending is safe).
    let settled = false;
    const finishOk = (imgUrl) => {
        if (token !== _regWaCaptureToken) return; // a newer dialog/preview owns the state now
        settled = true;
        _regWaCaptureState = 'ready';
        _regWaCaptureReadyAt = Date.now();
        const img = document.getElementById('waInvPreviewImg');
        const area = document.getElementById('waInvPreviewArea');
        if (img) img.src = imgUrl;
        if (area) area.style.display = 'block';
        btn.textContent = 'Refresh Preview'; btn.disabled = false;
        const statusEl = document.getElementById('waInvStatus');
        if (statusEl && statusEl.dataset.waiting === '1') {
            regWaSetCaptureStatus('✅ Invoice image ready — press Send Invoice again.', '#16a34a');
        }
    };
    const finishFail = (reason) => {
        if (token !== _regWaCaptureToken || settled) return;
        settled = true;
        _regWaCaptureState = 'failed';
        btn.textContent = 'Refresh Preview'; btn.disabled = false;
        regWaSetCaptureStatus('⚠ Invoice image failed to generate (' + reason + '). Press "Refresh Preview" to retry.', '#dc2626');
    };
    // Watchdog: a capture that never settles (hung iframe / dead connection)
    // must not brick the dialog in 'pending' — degrade to 'failed' so the
    // operator gets Refresh-Preview and Send-Anyway back.
    setTimeout(function() { finishFail('timed out — slow connection?'); }, 45000);

    fetch('/messages/invoice-image/' + orderIdSnap, {
        headers: {'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.content || '', 'Accept': 'application/json'}
    })
    .then(r => r.json())
    .then(d => {
        if (!d.success) { finishFail(d.message || 'server error'); return; }

        if (d.needs_capture) {
            captureInvoiceImageOrders(d.invoice_url, orderIdSnap).then(uploadRes => {
                finishOk(uploadRes.image_url);
            }).catch(err => { finishFail(err.message || 'capture error'); });
        } else {
            finishOk(d.image_url);
        }
    })
    .catch(e => { finishFail(e.message || 'network error'); });
}

// Non-blocking invoice send (Apr-2026). The original implementation
// kept the dialog open with a "Sending..." spinner until the WhatsApp
// API returned (often 5–15s on a flaky link) which froze the operator
// in front of a single order. The new flow:
//
//   1. Validate the form locally.
//   2. Capture the customer / order labels from the dialog so the
//      progress + result toasts can name the affected order without
//      a follow-up DB lookup.
//   3. Close the dialog immediately and show an informational toast.
//   4. Fire the actual send asynchronously. On resolution we either:
//      - success: small green toast (auto-dismiss).
//      - failure: a sticky red banner pinned to the top of the page
//        showing the order #, customer name, and error reason — the
//        operator dismisses it manually after retrying / acting on it.
//
// The fetch promise stays alive for the lifetime of the orders page,
// so navigating away will cancel an in-flight send (acceptable — this
// is page-scoped, not a queue).
function sendInvoiceWhatsApp() {
    const phone = document.getElementById('waInvPhone').value.trim();
    const templateName = document.getElementById('waInvTemplate').value.trim();
    const bodyParamsInput = document.getElementById('waInvBodyParams');
    const bodyParamsStr = bodyParamsInput.value.trim();

    if (!phone) { alert('Please enter a phone number'); return; }
    if (!templateName) { alert('Please select an invoice template'); return; }

    // ── Capture-state gate (Jul-2026) ─────────────────────────────────
    // The dialog auto-captures the invoice image on open. If that capture
    // is still running, sending now would race it — so keep the dialog
    // open with a wait note (the running capture is NOT restarted; its
    // completion callback invites a second Send press). If the capture
    // failed, the first Send press explains and arms "Send Anyway"; a
    // deliberate second press falls through to the legacy best-effort
    // path (the server may still hold the last saved image).
    if (_regWaCaptureState === 'pending') {
        regWaSetCaptureStatus('⏳ Preparing the invoice image — one moment, then press Send Invoice again.', '#b45309');
        const statusEl = document.getElementById('waInvStatus');
        if (statusEl) statusEl.dataset.waiting = '1';
        return;
    }
    if (_regWaCaptureState === 'failed' && !_regWaSendAnywayArmed) {
        _regWaSendAnywayArmed = true;
        const sendBtnEl = document.getElementById('waInvSendBtn');
        if (sendBtnEl) sendBtnEl.textContent = 'Send Anyway';
        regWaSetCaptureStatus('⚠ The invoice image could not be generated. Press "Refresh Preview" to retry, or "Send Anyway" to use the last saved image (if any).', '#dc2626');
        return;
    }

    // Prefer the structured params array stashed by onRegularInvoiceTemplateChange:
    // the ETA window ("Today, 4:10-4:40 PM") contains a comma, so a naive split of
    // the visible text would shatter it into two params. Only when the operator has
    // hand-edited the field (so it no longer matches the structured copy) do we fall
    // back to splitting the text they typed.
    let bodyParams;
    try {
        const structured = bodyParamsInput.dataset.structured ? JSON.parse(bodyParamsInput.dataset.structured) : null;
        if (Array.isArray(structured) && structured.join(', ') === bodyParamsStr) {
            bodyParams = structured;
        } else {
            bodyParams = bodyParamsStr ? bodyParamsStr.split(',').map(s => s.trim()) : [];
        }
    } catch (e) {
        bodyParams = bodyParamsStr ? bodyParamsStr.split(',').map(s => s.trim()) : [];
    }

    // Pull the human-readable labels off the body-params input (the
    // dialog seeds it as "Customer Name, ORDER#" — see waInvBodyParams
    // initialisation in the dialog template). Falls back gracefully
    // when the operator has rewritten the input.
    const labelCustomer = (bodyParams[0] || '').trim() || phone;
    const labelOrder    = (bodyParams[1] || '').trim() || ('#' + currentOrderId);

    // Snapshot the order id — currentOrderId is mutated by other
    // dialogs (view, edit, etc.) so we can't trust it inside the
    // resolved promise body. _regWaOrderId is what this dialog (and its
    // capture) was opened for, so prefer it.
    const orderIdSnap = _regWaOrderId || currentOrderId;
    const csrf = document.querySelector('meta[name="csrf-token"]')?.content || '';

    // A capture that finished in THIS dialog moments ago is definitely the
    // current invoice — skip the redundant background re-capture (faster,
    // and quick-succession sends can't trip over their own capture). Older
    // dialogs and the deliberate "Send Anyway" path fall back to the legacy
    // best-effort chain below.
    const captureFresh = _regWaCaptureState === 'ready' && (Date.now() - _regWaCaptureReadyAt) < 180000;

    // Close dialog right away and acknowledge.
    document.getElementById('waInvoiceDialog')?.remove();
    showToast(`Sending invoice ${labelOrder} to ${labelCustomer}...`, 'success');

    const ensureReady = captureFresh ? Promise.resolve() : new Promise(function(resolve) {
        fetch('/messages/invoice-image/' + orderIdSnap, {headers: {'X-CSRF-TOKEN': csrf, 'Accept': 'application/json'}})
            .then(function(r) { return r.json(); })
            .then(function(d) {
                if (d && d.success && d.needs_capture) {
                    return captureInvoiceImageOrders(d.invoice_url, orderIdSnap).then(function() { resolve(); }).catch(function() { resolve(); });
                }
                resolve();
            })
            .catch(function() { resolve(); });
    });

    const postSend = function() {
        return fetch('/messages/send-invoice', {
            method: 'POST',
            headers: {'Content-Type': 'application/json', 'X-CSRF-TOKEN': csrf, 'Accept': 'application/json'},
            body: JSON.stringify({order_id: orderIdSnap, phone: phone, template_name: templateName, body_params: bodyParams})
        }).then(function(r) { return r.json(); });
    };

    ensureReady
    .then(postSend)
    .then(d => {
        // One-shot recovery: the server reports no image on disk (e.g. the
        // order was edited after our capture, which clears the cached
        // image). Capture fresh and retry the send once before surfacing
        // a failure banner.
        if (d && !d.success && d.needs_capture) {
            return fetch('/messages/invoice-image/' + orderIdSnap, {headers: {'X-CSRF-TOKEN': csrf, 'Accept': 'application/json'}})
                .then(function(r) { return r.json(); })
                .then(function(pd) {
                    if (pd && pd.success && pd.needs_capture) {
                        return captureInvoiceImageOrders(pd.invoice_url, orderIdSnap).then(postSend);
                    }
                    return d;
                });
        }
        return d;
    })
    .then(d => {
        if (d.success) {
            showToast(`Invoice ${labelOrder} sent to ${labelCustomer}`, 'success');
            // Flip this order's tick green in place — no full-page refresh.
            markInvoiceSentLocally(orderIdSnap);
        } else {
            showInvoiceSendFailure(labelOrder, labelCustomer, d.message || 'Failed to send', orderIdSnap);
        }
    })
    .catch(e => {
        showInvoiceSendFailure(labelOrder, labelCustomer, e.message || 'Network error', orderIdSnap);
    });
}

// Sticky red banner for invoice-send failures — see sendInvoiceWhatsApp.
// We render at most one banner per (order, customer) pair; if a second
// failure arrives for the same order, the existing banner is updated
// instead of stacking. The operator dismisses manually once they've
// taken action (re-opened the order, retried via the orders table, etc.)
function showInvoiceSendFailure(orderLabel, customerLabel, reason, orderId) {
    let host = document.getElementById('waInvFailureStack');
    if (!host) {
        host = document.createElement('div');
        host.id = 'waInvFailureStack';
        host.style.cssText = 'position:fixed;top:80px;right:20px;z-index:10001;display:flex;flex-direction:column;gap:8px;max-width:380px;';
        document.body.appendChild(host);
    }
    const key = 'fail-' + (orderId || orderLabel);
    let banner = host.querySelector('[data-key="' + key + '"]');
    if (!banner) {
        banner = document.createElement('div');
        banner.dataset.key = key;
        banner.style.cssText = 'background:#fef2f2;border:1px solid #fecaca;border-left:4px solid #dc2626;padding:12px 14px;border-radius:8px;box-shadow:0 4px 12px rgba(220,38,38,0.15);font-size:13px;color:#991b1b;line-height:1.4;';
        host.appendChild(banner);
    }
    const safe = (s) => String(s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
    banner.innerHTML = `
        <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px;">
            <div style="font-weight:700;color:#991b1b;">⚠ Invoice send failed</div>
            <button onclick="this.closest('[data-key]').remove()" style="background:none;border:none;color:#991b1b;cursor:pointer;font-size:18px;line-height:1;padding:0;margin:-4px -4px 0 0;">&times;</button>
        </div>
        <div style="margin-top:6px;color:#7f1d1d;">
            Order <strong>${safe(orderLabel)}</strong> · Customer <strong>${safe(customerLabel)}</strong>
        </div>
        <div style="margin-top:6px;color:#7f1d1d;font-size:12px;">${safe(reason)}</div>
    `;
}

