                            <label style="display: block; font-size: 14px; font-weight: 500; color: #374151; margin-bottom: 4px;">Phone</label>
                            <input type="text" name="address_phone" id="editAddressPhone" value="${order.address_phone || ''}" 
                                   style="width: 100%; padding: 8px 12px; border: 1px solid #d1d5db; border-radius: 6px; font-size: 14px;">
                        </div>
                        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px;">
                            <div>
                                <label style="display: block; font-size: 14px; font-weight: 500; color: #374151; margin-bottom: 4px;">Address Line 1</label>
                                <input type="text" name="address_line1" id="editAddressLine1" value="${order.address_line1 || ''}" 
                                       style="width: 100%; padding: 8px 12px; border: 1px solid #d1d5db; border-radius: 6px; font-size: 14px;">
                            </div>
                            <div>
                                <label style="display: block; font-size: 14px; font-weight: 500; color: #374151; margin-bottom: 4px;">Address Line 2</label>
                                <input type="text" name="address_line2" id="editAddressLine2" value="${order.address_line2 || ''}" 
                                       style="width: 100%; padding: 8px 12px; border: 1px solid #d1d5db; border-radius: 6px; font-size: 14px;">
                            </div>
                        </div>
                        <div style="display: grid; grid-template-columns: 1fr; gap: 12px;">
                            <div>
                                <label style="display: block; font-size: 14px; font-weight: 500; color: #374151; margin-bottom: 4px;">City</label>
                                <input type="text" name="address_city" id="editAddressCity" value="${order.address_city || ''}" 
                                       style="width: 100%; padding: 8px 12px; border: 1px solid #d1d5db; border-radius: 6px; font-size: 14px;">
                            </div>
                        </div>
                        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px;">
                            <div>
                                <label style="display: block; font-size: 14px; font-weight: 500; color: #374151; margin-bottom: 4px;">Country</label>
                                <input type="text" name="address_country" id="editAddressCountry" value="${order.address_country || 'Pakistan'}" 
                                       style="width: 100%; padding: 8px 12px; border: 1px solid #d1d5db; border-radius: 6px; font-size: 14px;">
                            </div>
                            <div>
                                <label style="display: block; font-size: 14px; font-weight: 500; color: #374151; margin-bottom: 4px;">Payment Method</label>
                                <select name="payment_method" style="width: 100%; padding: 8px 12px; border: 1px solid #d1d5db; border-radius: 6px; font-size: 14px;">
                                    <option value="">Select Payment Method</option>
                                    <option value="cash_on_delivery" ${(order.payment_method || '').toLowerCase().includes('cash') || order.payment_method === 'cash_on_delivery' ? 'selected' : ''}>Cash on Delivery</option>
                                    <option value="bank_transfer" ${(order.payment_method || '').toLowerCase().includes('bank') || order.payment_method === 'bank_transfer' ? 'selected' : ''}>Bank Transfer</option>
                                    <option value="card" ${(order.payment_method || '').toLowerCase().includes('card') || order.payment_method === 'card' ? 'selected' : ''}>Card Payment</option>
                                    <option value="online" ${(order.payment_method || '').toLowerCase().includes('online') || order.payment_method === 'online' ? 'selected' : ''}>Online Payment</option>
                                </select>
                            </div>
                        </div>
                        
                        <!-- ⭐ Option to sync address changes to customer profile -->
                        ${order.customer_id ? `
                        <div style="margin-top: 12px; padding: 10px; background-color: #eff6ff; border: 1px solid #bfdbfe; border-radius: 6px;">
                            <label style="display: flex; align-items: center; gap: 8px; font-size: 13px; color: #1e40af; cursor: pointer;">
                                <input type="checkbox" name="sync_to_customer" id="editSyncToCustomer" value="1"
                                       style="width: 16px; height: 16px; accent-color: #2563eb;">
                                <span><strong>Also update customer profile</strong> with these address changes</span>
                            </label>
                            <p style="margin: 6px 0 0 24px; font-size: 11px; color: #6b7280;">
                                Check this to save the address/name changes to the customer's profile as well.
                                Leave unchecked for order-specific temporary changes.
                            </p>
                        </div>
                        ` : ''}
                    </div>
                </div>
            </div>
            
            </div><!-- End of orderDetailsExpanded -->

            ${order.is_qurbani && order.line_items && order.line_items.length > 0 ? `
            <!-- Qurbani Line Items Summary - Always visible -->
            <div style="padding: 12px; background-color: #f0fdf4; border: 1px solid #86efac; border-radius: 8px; margin-bottom: 12px;">
                <div style="display: flex; align-items: center; gap: 6px; margin-bottom: 8px;">
                    <span style="font-size: 14px;">📦</span>
                    <strong style="color: #166534; font-size: 13px;">Line Items (${order.line_items.length})</strong>
                </div>
                ${order.line_items.map(function(li) {
                    var chips = [];
                    if (li.qurbani_day) chips.push('<span style="padding:2px 6px; background:#fef3c7; color:#92400e; border-radius:4px; font-size:10px; font-weight:600;">' + li.qurbani_day + '</span>');
                    if (li.qurbani_slot) chips.push('<span style="padding:2px 6px; background:#dbeafe; color:#1e40af; border-radius:4px; font-size:10px; font-weight:600;">' + li.qurbani_slot + '</span>');
                    if (li.qurbani_region) chips.push('<span style="padding:2px 6px; background:#d1fae5; color:#065f46; border-radius:4px; font-size:10px; font-weight:600;">' + li.qurbani_region + '</span>');
                    if (li.qurbani_sub_region) chips.push('<span style="padding:2px 6px; background:#e0f2fe; color:#0369a1; border-radius:4px; font-size:10px; font-weight:600;">' + li.qurbani_sub_region + '</span>');
                    if (li.qurbani_delivery_type) chips.push('<span style="padding:2px 6px; background:#ede9fe; color:#5b21b6; border-radius:4px; font-size:10px; font-weight:600;">' + li.qurbani_delivery_type + '</span>');
                    return '<div style="display:flex; justify-content:space-between; align-items:center; padding:6px 8px; background:#fff; border-radius:6px; margin-bottom:4px; border:1px solid #e5e7eb;">' +
                        '<div style="display:flex; flex-direction:column; gap:2px;">' +
                            '<span style="font-size:13px; font-weight:600; color:#374151;">' + (li.name || li.title || 'Item') + '</span>' +
                            (chips.length > 0 ? '<div style="display:flex; gap:4px; flex-wrap:wrap;">' + chips.join('') + '</div>' : '') +
                            (li.instructions ? '<div style="display:inline-flex; align-items:center; gap:3px; margin-top:2px; padding:2px 6px; background:#FEF3C7; border:1px solid #FCD34D; border-radius:4px;"><span style="font-size:10px;">📝</span><span style="font-size:11px; color:#92400E; font-weight:500;">' + li.instructions + '</span></div>' : '') +
                        '</div>' +
                        '<div style="text-align:right;">' +
                            '<span style="font-size:12px; color:#6b7280;">Qty: ' + (li.quantity || 0) + '</span>' +
                            '<span style="font-size:12px; color:#374151; font-weight:600; margin-left:12px;">Rs. ' + Number(li.price || 0).toLocaleString() + '</span>' +
                        '</div>' +
                    '</div>';
                }).join('')}
            </div>
            ` : ''}
            
            ${order.is_qurbani ? `
            <!-- Qurbani Payments - Always visible, outside collapsible section -->
            <div style="padding: 12px; background-color: #fffbeb; border: 1px solid #fcd34d; border-radius: 8px; margin-bottom: 16px;">
                <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;">
                    <div style="display: flex; align-items: center; gap: 6px;">
                        <span style="font-size: 14px;">💰</span>
                        <strong style="color: #92400e; font-size: 13px;">Qurbani Payments</strong>
                    </div>
                    <button onclick="openQurbaniPaymentModal(${order.id})" style="padding: 4px 12px; background: #d97706; color: #fff; border: none; border-radius: 6px; font-size: 12px; font-weight: 600; cursor: pointer;">+ Add Payment</button>
                </div>
                <div style="display: flex; gap: 16px; font-size: 13px; margin-bottom: 8px;">
                    <span>Total: <strong>Rs. ${Number(order.total_price || 0).toLocaleString()}</strong></span>
                    <span style="color: #059669;">Paid: <strong>Rs. ${Number(order.total_paid || 0).toLocaleString()}</strong></span>
                    <span style="color: #dc2626;">Remaining: <strong>Rs. ${Math.max(0, Number(order.total_price || 0) - Number(order.total_paid || 0)).toLocaleString()}</strong></span>
                </div>
                ${(order.qurbani_payments && order.qurbani_payments.length > 0) ? order.qurbani_payments.map(function(p) {
                    var mBg = p.payment_method === 'cash' ? '#d1fae5' : '#dbeafe';
                    var mColor = p.payment_method === 'cash' ? '#065f46' : '#1e40af';
                    // Per-row ❌ voids the payment + reverses its ledger/account
                    // movements. We use a data attribute so the handler has the
                    // payment + order ids without string-escaping gymnastics.
                    return '<div style="display:flex; justify-content:space-between; align-items:center; padding:6px 8px; background:#f9fafb; border-radius:6px; margin-bottom:4px; font-size:12px;">' +
                        '<span style="font-weight:600; color:#059669;">Rs. ' + Number(p.amount).toLocaleString() + '</span>' +
                        '<span style="padding:2px 8px; background:' + mBg + '; color:' + mColor + '; border-radius:8px; font-weight:600;">' + (p.payment_method || '') + '</span>' +
                        '<span style="color:#6b7280;">' + (p.payment_date || '') + '</span>' +
                        '<span style="color:#374151; font-weight:500;">' + (p.created_by_name || '') + '</span>' +
                        '<button type="button" onclick="deleteQurbaniPayment(' + order.id + ',' + p.id + ',' + Number(p.amount) + ')" ' +
                            'title="Void this payment" ' +
                            'style="background:none; border:none; color:#dc2626; cursor:pointer; font-size:14px; padding:2px 6px; border-radius:4px;">🗑️</button>' +
                    '</div>';
                }).join('') : '<div style="text-align:center; color:#9ca3af; font-size:12px; padding:8px;">No payments recorded yet</div>'}
            </div>
            ` : ''}

            <!-- Customer Notes Display (if available) -->
            <div id="editCustomerNotesDisplay" style="margin-bottom: 20px; display: none;"></div>
            
            ${window.isPopoutMode ? `
            <!-- Pop-out Mode: Notes & Packets Summary Bar -->
            <div id="notesPacketsSummary" style="background: linear-gradient(135deg, #fefce8 0%, #fef9c3 100%); padding: 12px 16px; border-radius: 10px; margin-bottom: 16px; border: 1px solid #facc15;">
                <div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px;">
                    <div style="display: flex; align-items: center; gap: 20px; flex-wrap: wrap;">
                        <div style="display: flex; align-items: center; gap: 6px;">
                            <span style="font-size: 16px;">📝</span>
                            <div>
                                <span style="font-size: 11px; color: #854d0e; font-weight: 600;">Notes:</span>
                                <span style="font-size: 13px; color: #713f12; max-width: 200px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; display: inline-block; vertical-align: bottom;">${order.note ? order.note.substring(0, 30) + (order.note.length > 30 ? '...' : '') : 'None'}</span>
                            </div>
                        </div>
                        <div style="display: flex; align-items: center; gap: 6px;">
                            <span style="font-size: 16px;">📦</span>
                            <div>
                                <span style="font-size: 11px; color: #854d0e; font-weight: 600;">Packets:</span>
                                <span style="font-size: 13px; color: #713f12;">${order.expected_packets || '-'} expected${order.actual_packets ? ', ' + order.actual_packets + ' delivered' : ''}</span>
                            </div>
                        </div>
                    </div>
                    <button type="button" onclick="toggleNotesPackets()" id="toggleNotesPacketsBtn" 
                            style="background: #eab308; color: white; border: none; padding: 8px 14px; border-radius: 6px; cursor: pointer; font-size: 12px; font-weight: 600; display: flex; align-items: center; gap: 4px;">
                        <span id="toggleNotesIcon">▼</span> Edit
                    </button>
                </div>
            </div>
            ` : ''}
            
            <!-- Notes & Packets Section (Collapsible in pop-out mode) -->
            <div id="notesPacketsExpanded" style="${window.isPopoutMode ? 'display: none;' : ''}">
            <!-- Notes Section -->
            <div style="margin-bottom: 20px;">
                <label style="display: block; font-size: 14px; font-weight: 500; color: #374151; margin-bottom: 8px;">Order Notes</label>
                <textarea name="note" rows="3" style="width: 100%; padding: 12px; border: 1px solid #d1d5db; border-radius: 6px; font-size: 14px; resize: vertical;" placeholder="Order notes...">${order.note || ''}</textarea>
            </div>

            <!-- Packet Tracking Section (Optional) -->
            <div style="background-color: #fef3c7; padding: 16px; border-radius: 8px; margin-bottom: 20px; border: 1px solid #fbbf24;">
                <h4 style="font-weight: 600; color: #92400e; margin: 0 0 12px 0; display: flex; align-items: center; gap: 8px;">
                    <span>📦</span> Packet Tracking (Optional)
                </h4>
                <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px;">
                    <div>
                        <label style="display: block; font-size: 14px; font-weight: 500; color: #374151; margin-bottom: 4px;">
                            Expected Packets
                            <span style="font-size: 12px; color: #6b7280; font-weight: normal;">(Manager/Admin)</span>
                        </label>
                        <input type="number" name="expected_packets" value="${order.expected_packets || ''}" min="0" step="1"
                               style="width: 100%; padding: 8px 12px; border: 1px solid #d1d5db; border-radius: 6px; font-size: 14px;" 
                               placeholder="Enter number of packets">
                        <p style="font-size: 12px; color: #6b7280; margin-top: 4px;">Number of packets you're sending with this order</p>
                    </div>
                    <div>
                        <label style="display: block; font-size: 14px; font-weight: 500; color: #374151; margin-bottom: 4px;">
                            Actual Packets Delivered
                            <span style="font-size: 12px; color: #6b7280; font-weight: normal;">(Rider)</span>
                        </label>
                        <input type="number" name="actual_packets" value="${order.actual_packets || ''}" min="0" step="1"
                               style="width: 100%; padding: 8px 12px; border: 1px solid #f3f4f6; border-radius: 6px; font-size: 14px; background-color: #f9fafb; cursor: not-allowed;" 
                               placeholder="Entered by rider on delivery" readonly>
                        <p style="font-size: 12px; color: #6b7280; margin-top: 4px;">
                            ${order.actual_packets ? 
                                (order.expected_packets && order.actual_packets != order.expected_packets ? 
                                    `⚠️ <span style="color: #dc2626; font-weight: 500;">Mismatch detected!</span>` : 
                                    `✅ <span style="color: #059669; font-weight: 500;">Verified</span>`) : 
                                'Rider will enter this on delivery'}
                        </p>
                    </div>
                </div>
            </div>
            </div><!-- End of notesPacketsExpanded -->

            <!-- ⭐ MONEY PROMPTS SIT ABOVE THE LINE ITEMS ON PURPOSE.
                 Both were originally below the whole Line Items block, which on
                 a real order pushed them far below the fold — the owner opened
                 an order and could not find the payment control at all. They
                 belong with the order header, where "has this been paid / does
                 this customer have credit" is actually asked. -->

            <!-- Customer account balance ("bucket"). Filled in by
                 nfLoadCreditBanner() after the modal renders; stays empty when
                 the customer has no balance, so nothing moves for most orders. -->
            <div id="nfCreditBanner" style="display:none; margin-bottom: 16px;"></div>

            <!-- ✍️ Payments claimed against this order. This is the PREPAYMENT
                 door: money can be recorded here before the order is delivered.
                 It writes evidence (a payment signal), never an order payment,
                 so a regular order's invoicing is untouched. -->
            <div id="nfPaymentStrip" style="display:none; margin-bottom: 16px;"></div>
            <!-- Line Items Section -->
            <div style="background-color: #fefefe; border: 1px solid #e5e7eb; border-radius: 8px; margin-bottom: 20px;">
                <div style="padding: 16px; border-bottom: 1px solid #e5e7eb; display: flex; justify-content: space-between; align-items: center;">
                    <h4 style="font-weight: 600; color: #374151; margin: 0;">Line Items</h4>
                    <button type="button" onclick="(window.addLineItem||addLineItem)()" style="background-color: #10b981; color: white; padding: 8px 16px; border: none; border-radius: 6px; font-size: 14px; cursor: pointer;">
                        + Add Item
                    </button>
                </div>
                <div id="lineItemsContainer" style="padding: 16px;">
                    ${order.line_items && order.line_items.length > 0 ? 
                        order.line_items.map((item, index) => `
                        <div class="line-item" data-index="${index}" data-product-id="${item.product_id || ''}" data-product-name="${(item.name || item.title || '').replace(/"/g, '&quot;')}" style="display: grid; grid-template-columns: 3fr 70px 90px 110px auto 32px; gap: 12px; align-items: end; padding: 12px; margin-bottom: 12px; border: 1px solid ${item.is_free ? '#bbf7d0' : '#e5e7eb'}; border-radius: 6px; background-color: ${item.is_free ? '#f0fdf4' : '#f9fafb'};">
                            <div>
                                <label style="display: block; font-size: 12px; font-weight: 500; color: #6b7280; margin-bottom: 4px;">Item Name <span style="margin-left: 8px; font-size: 11px; color: #6b7280; font-weight: normal;">🔒 Locked (delete to change)</span></label>
                                <input type="text" name="items[${index}][name]" value="${item.name || item.title || ''}" 
                                       style="width: 100%; padding: 6px 8px; border: 1px solid #d1d5db; border-radius: 4px; font-size: 14px; background-color: #f3f4f6; cursor: not-allowed; color: #6b7280;" readonly>
                                ${item.sku ? `<span style="display: inline-block; margin-top: 4px; font-size: 11px; color: #0369a1; background: #dbeafe; padding: 2px 6px; border-radius: 3px;">SKU: ${item.sku}</span>` : ''}
                                <input type="hidden" name="items[${index}][id]" value="${item.id || ''}">
                                <input type="hidden" name="items[${index}][sku]" value="${item.sku || ''}">
                                <input type="hidden" name="items[${index}][variant_id]" value="${item.variant_id || ''}">
                                <input type="hidden" name="items[${index}][product_id]" value="${item.product_id || ''}">
                                <input type="hidden" name="items[${index}][is_free]" value="${item.is_free ? 1 : 0}" class="is-free-input">
                            </div>
                            <div style="position: relative;">
                                <label style="display: block; font-size: 12px; font-weight: 500; color: #6b7280; margin-bottom: 4px;">
                                    Quantity
                                    <span id="weightFactorFeedback_${index}" style="display: none; margin-left: 6px; padding: 2px 6px; background: #dbeafe; border-radius: 3px; font-size: 9px; color: #0369a1; font-weight: 500; white-space: nowrap;"></span>
                                </label>
                                <input type="number" step="0.01" name="items[${index}][quantity]" value="${item.quantity || 1}" min="0.01"
                                       data-db-original-value="${item.quantity || 1}"
                                       style="width: 100%; padding: 6px 8px; border: 1px solid #d1d5db; border-radius: 4px; font-size: 14px;" 
                                       onfocus="showWeightFactorFeedbackOnFocus(${index})"
                                       onblur="applyWeightFactorToQuantity(${index})" 
                                       onchange="updateLineTotal(${index})"
                                       onkeydown="handleQtyTabNavigation(event, ${index})">
                            </div>
                            <div>
                                <label style="display: block; font-size: 12px; font-weight: 500; color: #6b7280; margin-bottom: 4px;">Unit Price <span style="margin-left: 8px; font-size: 11px; color: #6b7280; font-weight: normal;">🔒 Locked</span></label>
                                <input type="number" step="0.01" name="items[${index}][unit_price]" value="${item.unit_price || item.price || 0}" tabindex="-1"
                                       style="width: 100%; padding: 6px 8px; border: 1px solid #d1d5db; border-radius: 4px; font-size: 14px; background-color: #f3f4f6; cursor: not-allowed;" 
                                       readonly title="Price is set from product catalog and cannot be edited" onchange="updateLineTotal(${index})">
                            </div>
                            <div>
                                <label style="display: block; font-size: 12px; font-weight: 500; color: #6b7280; margin-bottom: 4px;">Total</label>
                                <span class="line-total" style="display: block; padding: 6px 8px; background-color: ${item.is_free ? '#bbf7d0' : '#e5e7eb'}; border-radius: 4px; font-size: 14px; font-weight: 500;">${item.is_free ? 'FREE' : formatCurrency(item.line_total || ((item.unit_price || item.price || 0) * (item.quantity || 0)), order.currency)}</span>
                            </div>
                            <div>
                                <button type="button" onclick="toggleFreeItem(${index})" class="free-toggle-btn" style="padding: 6px 10px; border: 1px solid ${item.is_free ? '#16a34a' : '#d1d5db'}; border-radius: 4px; cursor: pointer; font-size: 11px; font-weight: 600; line-height: 1.2; background-color: ${item.is_free ? '#16a34a' : '#fff'}; color: ${item.is_free ? '#fff' : '#6b7280'};" title="${item.is_free ? 'Click to remove free status' : 'Click to make this item free'}">
                                    ${item.is_free ? '✓ FREE' : 'Make Free'}
                                </button>
                            </div>
                            <div>
                                <button type="button" onclick="removeLineItem(${index})" style="background-color: #ef4444; color: white; padding: 8px; border: none; border-radius: 4px; cursor: pointer; font-size: 16px; line-height: 1;">
                                    ×
                                </button>
                            </div>
                            ${item.quantity_source ? `<div style="grid-column: 2 / -1; margin-top: 2px; font-size: 11px; display: flex; align-items: center; gap: 5px; flex-wrap: wrap;">
                                <span style="font-weight: 600; color: ${item.quantity_source === 'barcode' ? '#15803d' : item.quantity_source === 'box_scan' ? '#0369a1' : '#64748b'};">${item.quantity_source === 'barcode' ? '🔖 Qty set by barcode scan' : item.quantity_source === 'box_scan' ? (orderedQtyIfChanged(item) === null ? '📦 Box scanned — qty as ordered' : '📦 Box count confirmed') : '✏️ Qty set manually'}</span>
                                ${orderedQtyBadge(item)}
                                ${scannedWeightBadge(item, index)}
                                ${item.quantity_updated_at ? `<span style="color:#9ca3af;">· ${new Date(item.quantity_updated_at).toLocaleString('en-GB',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'})}</span>` : ''}
                                ${(item.qty_updater && item.qty_updater.fullname) ? `<span style="color:#9ca3af;">· by ${item.qty_updater.fullname}</span>` : ''}
                            </div>` : ''}
                            ${(item.qurbani_day || item.qurbani_slot || item.qurbani_region || item.qurbani_sub_region || item.qurbani_delivery_type || item.qurbani_type || item.qurbani_paya || order.is_qurbani) ? `
                            <div class="qurbani-item-fields" style="grid-column: 1 / -1; display: grid; grid-template-columns: repeat(7, 1fr) auto; gap: 8px; padding: 8px; background: #fffbeb; border-radius: 6px; border: 1px solid #fcd34d;" data-item-index="${index}">
                                <div>
                                    <label style="display:block; font-size:11px; font-weight:600; color:#92400e; margin-bottom:2px;">Day</label>
                                    <select name="items[${index}][qurbani_day]" class="qurbani-item-select" data-field="qurbani_day" ${item.id ? 'disabled' : ''} style="width:100%; padding:4px 6px; border:1px solid #fcd34d; border-radius:4px; font-size:12px; background:${item.id ? '#f5f5f4' : '#fff'};">
                                        <option value="">-</option>
                                        <option value="${item.qurbani_day || ''}" selected>${item.qurbani_day || '-'}</option>
                                    </select>
                                </div>
                                <div>
                                    <label style="display:block; font-size:11px; font-weight:600; color:#92400e; margin-bottom:2px;">Slot</label>
                                    <select name="items[${index}][qurbani_slot]" class="qurbani-item-select" data-field="qurbani_slot" ${item.id ? 'disabled' : ''} style="width:100%; padding:4px 6px; border:1px solid #fcd34d; border-radius:4px; font-size:12px; background:${item.id ? '#f5f5f4' : '#fff'};">
                                        <option value="">-</option>
                                        <option value="${item.qurbani_slot || ''}" selected>${item.qurbani_slot || '-'}</option>
                                    </select>
                                </div>
                                <div>
                                    <label style="display:block; font-size:11px; font-weight:600; color:#92400e; margin-bottom:2px;">Region</label>
                                    <select name="items[${index}][qurbani_region]" class="qurbani-item-select" data-field="qurbani_region" ${item.id ? 'disabled' : ''} style="width:100%; padding:4px 6px; border:1px solid #fcd34d; border-radius:4px; font-size:12px; background:${item.id ? '#f5f5f4' : '#fff'};">
                                        <option value="">-</option>
                                        <option value="${item.qurbani_region || ''}" selected>${item.qurbani_region || '-'}</option>
                                    </select>
                                </div>
                                <div>
                                    <label style="display:block; font-size:11px; font-weight:600; color:#92400e; margin-bottom:2px;">Sub Region</label>
                                    <select name="items[${index}][qurbani_sub_region]" class="qurbani-item-select" data-field="qurbani_sub_region" ${item.id ? 'disabled' : ''} style="width:100%; padding:4px 6px; border:1px solid #fcd34d; border-radius:4px; font-size:12px; background:${item.id ? '#f5f5f4' : '#fff'};">
                                        <option value="">-</option>
                                        <option value="${item.qurbani_sub_region || ''}" selected>${item.qurbani_sub_region || '-'}</option>
                                    </select>
                                </div>
                                <div>
                                    <label style="display:block; font-size:11px; font-weight:600; color:#92400e; margin-bottom:2px;">Type</label>
                                    <select name="items[${index}][qurbani_delivery_type]" class="qurbani-item-select" data-field="qurbani_delivery_type" ${item.id ? 'disabled' : ''} style="width:100%; padding:4px 6px; border:1px solid #fcd34d; border-radius:4px; font-size:12px; background:${item.id ? '#f5f5f4' : '#fff'};">
                                        <option value="">-</option>
                                        <option value="${item.qurbani_delivery_type || ''}" selected>${item.qurbani_delivery_type || '-'}</option>
                                    </select>
                                </div>
                                <div>
                                    <label style="display:block; font-size:11px; font-weight:600; color:#92400e; margin-bottom:2px;">Qurbani Type</label>
                                    <select name="items[${index}][qurbani_type]" class="qurbani-item-select" data-field="qurbani_type" ${item.id ? 'disabled' : ''} style="width:100%; padding:4px 6px; border:1px solid #fcd34d; border-radius:4px; font-size:12px; background:${item.id ? '#f5f5f4' : '#fff'};">
                                        <option value="">-</option>
                                        <option value="${item.qurbani_type || ''}" selected>${item.qurbani_type || '-'}</option>
                                    </select>
                                </div>
                                <div>
                                    <label style="display:block; font-size:11px; font-weight:600; color:#92400e; margin-bottom:2px;">Paya</label>
                                    <select name="items[${index}][qurbani_paya]" class="qurbani-item-select" data-field="qurbani_paya" ${item.id ? 'disabled' : ''} style="width:100%; padding:4px 6px; border:1px solid #fcd34d; border-radius:4px; font-size:12px; background:${item.id ? '#f5f5f4' : '#fff'};">
                                        <option value="">-</option>
                                        <option value="${item.qurbani_paya || ''}" selected>${item.qurbani_paya || '-'}</option>
                                    </select>
                                </div>
                                ${item.id ? '<div style="display:flex; align-items:flex-end;"><button type="button" onclick="unlockQurbaniFields(this)" style="padding:4px 8px; background:#D97706; color:#fff; border:none; border-radius:4px; font-size:11px; cursor:pointer; white-space:nowrap;">✏️ Edit</button></div>' : ''}
                            </div>
                            ` : ''}
                            <div style="grid-column: 1 / -1;" class="instructions-wrapper" data-index="${index}">
                                ${item.instructions ?
                                    `<div class="instructions-badge" onclick="toggleInstructions(${index})" style="cursor:pointer; display:inline-flex; align-items:center; gap:4px; padding:3px 10px; background:#FEF3C7; border:1px solid #FCD34D; border-radius:4px; max-width:100%;">
                                        <span style="font-size:12px;">📝</span>
                                        <span style="font-size:12px; color:#92400E; font-weight:500; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${item.instructions}</span>
                                        <span style="font-size:10px; color:#B45309; margin-left:4px; flex-shrink:0;">✏️</span>
                                    </div>
                                    <div class="instructions-input-wrap" style="display:none; margin-top:4px;">
                                        <input type="text" name="items[${index}][instructions]" value="${item.instructions || ''}" placeholder="Type instructions..." style="width:100%; padding:4px 8px; border:1px solid #FCD34D; border-radius:4px; font-size:12px; color:#374151; background:#FFFBEB;" onblur="collapseInstructions(${index})">
                                    </div>` :
                                    `<div class="instructions-badge" style="display:none;"></div>
                                    <span class="instructions-add-link" onclick="toggleInstructions(${index})" style="cursor:pointer; font-size:11px; color:#9CA3AF; padding:2px 0; display:inline-flex; align-items:center; gap:3px;">📝 <span style="border-bottom:1px dashed #9CA3AF;">Add note</span></span>
                                    <div class="instructions-input-wrap" style="display:none; margin-top:4px;">
                                        <input type="text" name="items[${index}][instructions]" value="" placeholder="Type instructions..." style="width:100%; padding:4px 8px; border:1px solid #FCD34D; border-radius:4px; font-size:12px; color:#374151; background:#FFFBEB;" onblur="collapseInstructions(${index})">
                                    </div>`
                                }
                                <div class="quick-note-chips" data-index="${index}" style="display:flex; flex-wrap:wrap; gap:4px; margin-top:5px; align-items:center;">${quickNoteChipsHtml(index)}</div>
                            </div>
                        </div>
                        `).join('') : 
                        '<div style="text-align: center; color: #6b7280; padding: 20px;">No line items. Click "Add Item" to add items.</div>'
                    }
                </div>
            </div>


            <!-- Order Totals -->
            <div style="background-color: #eff6ff; padding: 16px; border-radius: 8px; margin-bottom: 20px;">
                <h4 style="font-weight: 600; color: #374151; margin: 0 0 16px 0;">Order Totals</h4>
                <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-bottom: 16px;">
                    <div>
                        <label style="display: block; font-size: 14px; font-weight: 500; color: #374151; margin-bottom: 4px;">Subtotal</label>
                        <input type="number" step="0.01" name="subtotal_price" value="${order.subtotal_price || 0}" 
                               style="width: 100%; padding: 8px 12px; border: 1px solid #d1d5db; border-radius: 6px; font-size: 14px;" readonly>
                    </div>
                    <div>
                        <label style="display: block; font-size: 14px; font-weight: 500; color: #374151; margin-bottom: 8px;">Discounts</label>
                        <div id="discountsContainer" style="display: flex; flex-direction: column; gap: 8px;">
                            <!-- Discount rows will be populated here -->
                        </div>
                        <button type="button" onclick="addDiscountRow()" 
                                style="margin-top: 8px; padding: 6px 12px; background: #10b981; color: #fff; border: 0; border-radius: 4px; cursor: pointer; font-size: 13px; font-weight: 500;">
                            + Add Discount
                        </button>
                        <div style="margin-top: 8px; padding: 8px; background: #f3f4f6; border-radius: 4px; display: flex; justify-content: space-between; align-items: center;">
                            <span style="font-weight: 600; color: #374151;">Total Discount:</span>
                            <span id="totalDiscountDisplay" style="font-weight: 700; color: #ef4444; font-size: 16px;">Rs. 0.00</span>
                        </div>
                        {{-- ⭐ Shown on its OWN line, never inside "Total Discount".
                             The customer's balance is their money being spent, not a
                             concession — and lumping it in produced a discount total
                             with no discount row to explain it. --}}
                        <div id="nfBalanceUsedRow" style="display:none; margin-top: 6px; padding: 8px; background: #ECFDF5; border: 1px solid #A7F3D0; border-radius: 4px; justify-content: space-between; align-items: center;">
                            <span style="font-weight: 600; color: #065F46;">💰 Account balance used:</span>
                            <span id="nfBalanceUsedDisplay" style="font-weight: 700; color: #059669; font-size: 16px;">Rs. 0.00</span>
                        </div>
                    </div>
                </div>
                <div style="margin-bottom: 16px;">
                    <div>
                        <label style="display: block; font-size: 14px; font-weight: 500; color: #374151; margin-bottom: 4px;">Shipping</label>
                        <input type="number" step="0.01" name="shipping_total" value="${order.shipping_total || 0}" 
                               style="width: 100%; padding: 8px 12px; border: 1px solid #d1d5db; border-radius: 6px; font-size: 14px;" onchange="updateOrderTotal()" placeholder="Enter shipping cost">
                    </div>
                </div>
                <div style="margin-bottom: 16px;">
                    <div>
                        <label style="display: block; font-size: 14px; font-weight: 500; color: #374151; margin-bottom: 4px;">Tip</label>
                        <input type="number" step="0.01" name="tip_amount" value="${order.tip_amount || 0}" 
                               style="width: 100%; padding: 8px 12px; border: 1px solid #d1d5db; border-radius: 6px; font-size: 14px;" onchange="updateOrderTotal()" placeholder="Enter tip amount">
                    </div>
                </div>
                <div style="padding-top: 12px; border-top: 1px solid #e5e7eb;">
                    <div>
                        <label style="display: block; font-size: 14px; font-weight: 500; color: #374151; margin-bottom: 4px;">Total Price</label>
                        <input type="number" step="0.01" name="total_price" value="${order.total_price || 0}" 
                               style="width: 100%; padding: 8px 12px; border: 1px solid #d1d5db; border-radius: 6px; font-size: 14px; font-weight: 600; background-color: #f3f4f6;" readonly>
                    </div>
                </div>
            </div>

            <!-- Status Timeline Section (Collapsible in pop-out mode) -->
            ${window.isPopoutMode ? `
            <div style="background-color: #f9fafb; padding: 12px 16px; border-radius: 8px; margin-bottom: 20px; border: 1px solid #e5e7eb;">
                <div style="display: flex; justify-content: space-between; align-items: center;">
                    <div style="display: flex; align-items: center; gap: 8px;">
                        <span style="font-size: 16px;">📜</span>
                        <span style="font-weight: 600; color: #374151; font-size: 14px;">Status History</span>
                        <span style="font-size: 12px; color: #6b7280;">(click to expand)</span>
                    </div>
                    <button type="button" onclick="toggleStatusHistory()" id="toggleStatusHistoryBtn" 
                            style="background: #6b7280; color: white; border: none; padding: 6px 12px; border-radius: 6px; cursor: pointer; font-size: 11px; font-weight: 600; display: flex; align-items: center; gap: 4px;">
                        <span id="toggleHistoryIcon">▼</span> Show
                    </button>
                </div>
                <div id="editOrderTimelineWrapper" style="display: none; margin-top: 12px;">
                    <div id="editOrderTimeline" style="max-height: 200px; overflow-y: auto;">
                        <div style="text-align:center;color:#6b7280;font-size:13px;padding:20px;">Loading timeline...</div>
                    </div>
                </div>
            </div>
            ` : `
            <div style="background-color: #f9fafb; padding: 16px; border-radius: 8px; margin-bottom: 20px;">
                <h4 style="font-weight: 600; color: #374151; margin: 0 0 12px 0;">Status History</h4>
                <div id="editOrderTimeline" style="max-height: 200px; overflow-y: auto;">
                    <div style="text-align:center;color:#6b7280;font-size:13px;padding:20px;">Loading timeline...</div>
                </div>
            </div>
            `}

            <!-- Activity Log (Phase 2 L1) — who changed what: edits, payments, ledger. Collapsible. -->
            <div style="background-color: #fff; padding: 12px 16px; border-radius: 8px; margin-bottom: 20px; border: 1px solid #e5e7eb;">
                <div style="display: flex; justify-content: space-between; align-items: center;">
                    <div style="display: flex; align-items: center; gap: 8px;">
                        <span style="font-size: 16px;">🧾</span>
                        <span style="font-weight: 600; color: #374151; font-size: 14px;">Activity Log</span>
                        <span style="font-size: 12px; color: #6b7280;">— who changed what</span>
                    </div>
                    <button type="button" onclick="toggleActivityLog()" id="toggleActivityLogBtn"
                            style="background: #6b7280; color: white; border: none; padding: 6px 12px; border-radius: 6px; cursor: pointer; font-size: 11px; font-weight: 600; display: flex; align-items: center; gap: 4px;">
                        <span id="toggleActivityLogIcon">▼</span> Show
                    </button>
                </div>
                <div id="editOrderActivityWrapper" style="display: none; margin-top: 12px;">
                    <div id="editOrderActivityLog" style="max-height: 260px; overflow-y: auto;">
                        <div style="text-align:center;color:#6b7280;font-size:13px;padding:20px;">Loading activity…</div>
                    </div>
                </div>
            </div>

            <!-- Form Actions -->
            <div style="display: flex; justify-content: flex-end; gap: 12px; padding-top: 20px; border-top: 1px solid #e5e7eb;">
                <button type="button" onclick="closeModal('editOrderModal')" 
                        style="padding: 10px 20px; border: 1px solid #d1d5db; border-radius: 6px; color: #374151; background-color: white; cursor: pointer; font-size: 14px;">
                    Cancel
                </button>
                <button type="submit" 
                        style="padding: 10px 20px; background-color: #10b981; color: white; border: none; border-radius: 6px; cursor: pointer; font-size: 14px;">
                    Save
                </button>
                <button type="button" onclick="saveAndCloseOrder(${order.id})" 
                        style="padding: 10px 20px; background-color: #2563eb; color: white; border: none; border-radius: 6px; cursor: pointer; font-size: 14px;">
                    Save & Close
                </button>
            </div>
        </form>
    `;
    
    // Add form submission handler
    document.getElementById('editOrderForm').addEventListener('submit', function(e) {
        e.preventDefault();
        saveOrderChanges(order.id);
    });
    
    // Initialize discounts from order data
    try {
        initializeDiscountsFromOrder(order);
    } catch (e) {
        console.warn('Failed to initialize discounts', e);
    }

    // ⭐ Customer account balance. Asks the server whether this order's customer
    // has money sitting with us — this is what makes a converted Shopify order
    // announce "Rs X available" the moment the manager opens it to edit.
    try {
        nfLoadCreditBanner(order.id);
    } catch (e) {
        console.warn('Failed to load credit banner', e);
    }

    // ✍️ Payments already claimed against this order (incl. before delivery).
    try {
        nfLoadPaymentStrip(order.id, order.order_number);
    } catch (e) {
        console.warn('Failed to load payment strip', e);
    }

    // Populate qurbani field dropdowns if this is a qurbani order (check order-level, is_qurbani flag, and line items)
    if (order.qurbani_day || order.qurbani_slot || order.qurbani_region || order.qurbani_sub_region || order.qurbani_delivery_type || order.is_qurbani || (order.line_items || []).some(li => li.qurbani_day || li.qurbani_slot || li.qurbani_region || li.qurbani_sub_region || li.qurbani_delivery_type)) {
        try { populateQurbaniEditSelects(); } catch (e) { console.warn('Failed to populate qurbani selects', e); }
    }
    
    // Immediately load status options for the dropdown, independent of totals/line items
    try {
        loadEditOrderStatuses(order.order_status);
    } catch (e) {
        console.warn('Failed to trigger status load', e);
    }
    
    // Load status timeline
    try {
        loadEditOrderTimeline(order.id);
    } catch (e) {
        console.warn('Failed to load timeline', e);
    }

    // Load the per-order Activity Log (who changed what — Phase 2 L1)
    try {
        loadEditOrderActivityLog(order.id);
    } catch (e) {
        console.warn('Failed to load activity log', e);
    }
    
    try {
        const rSel = document.getElementById('editRiderSelect');
        const rBtn = document.getElementById('editRiderAssignBtn');
        const rTimeline = document.getElementById('editOrderRiderTimeline');
        if (rSel && rBtn) {
            rSel.innerHTML = '<option value="">Loading...</option>';
            fetch('/riders/active', { headers: { 'Accept': 'application/json' }})
                .then(r=>r.json())
                .then(j=>{
                    if (j && j.success) {
                        const opts = (j.data||[]).map(r=>`<option value="${r.id}" ${r.id == (order.assigned_rider_user_id||'') ? 'selected' : ''}>${r.fullname}</option>`).join('');
                        rSel.innerHTML = '<option value="">-- Unassign rider --</option>' + opts;
                    } else {
                        rSel.innerHTML = '<option value="">No riders found</option>';
                    }
                }).catch(()=>{ rSel.innerHTML = '<option value="">Load failed</option>'; });
            rBtn.onclick = async function(){
                const val = rSel.value;
                const selectedRiderName = val ? rSel.selectedOptions[0].text : 'Unassigned';
                
                // Helper function to actually assign the rider
                const assignRider = async function(confirmed = false) {
                    try {
                        const payload = { 
                            rider_user_id: val ? parseInt(val,10) : null 
                        };
                        
                        // Add confirmation flag if this is a retry after confirmation
                        if (confirmed) {
                            payload.confirmed = true;
                        }
                        
                        rBtn.textContent = 'Assigning...'; 
                        rBtn.disabled = true;
                        
                        const response = await fetch(`/orders/${order.id}/rider/assign`, { 
                            method:'POST', 
                            headers:{ 
                                'Accept':'application/json',
                                'Content-Type':'application/json',
                                'X-CSRF-TOKEN':document.querySelector('meta[name=\'csrf-token\']').getAttribute('content') 
                            }, 
                            body: JSON.stringify(payload) 
                        });
                        const result = await response.json();
                        
                        // Check if confirmation is required (ledger will be updated)
                        if (!result.success && result.requires_confirmation && result.confirmation_data) {
                            const data = result.confirmation_data;
                            const confirmMsg = 
                                `⚠️ LEDGER WILL BE UPDATED\n\n` +
                                `This order has been posted to the ledger.\n` +
                                `Changing the rider will reverse the old ledger entry and create a new one.\n\n` +
                                `Order: ${data.order_number}\n` +
                                `Amount: Rs. ${parseFloat(data.amount).toFixed(2)}\n\n` +
                                `Old Rider: ${data.old_rider_name}\n` +
                                `New Rider: ${data.new_rider_name}\n\n` +
                                `The ledger will be moved from ${data.old_rider_name}'s account to ${data.new_rider_name}'s account.\n\n` +
                                `Do you want to proceed?`;
                            
                            rBtn.textContent = 'Assign'; 
                            rBtn.disabled = false;
                            
                            if (confirm(confirmMsg)) {
                                // User confirmed - retry with confirmation flag
                                await assignRider(true);
                            }
                            return;
                        }
                        
                        // Check for other errors
                        if (!result.success) {
                            throw new Error(result.message || 'Failed');
                        }

                        /* 🔧⭐ HIS MACHINE IS AT THE WORKSHOP — assigned anyway, and said ONCE
                             (owner ruling, 11-Sep-2026: out for delivery is not on the road).
                           ⚠⚠ This replaces a REFUSAL that could not be answered. The page used
                              to send `confirmed` while the server read `confirm`, so even the
                              hand-written override was dead code — and the store simply could
                              not give the order to the man. The stop now lives on Dispatch.
                           ⚠ Shown BEFORE the reload, because the reload throws the page away. */
                        if (result.warning && result.warning.kind === 'workshop') {
                            alert('🔧 ' + (result.warning.label || 'He is at the workshop')
                                + '\n\nOrder assign ho gaya hai. Dispatch tab karein jab woh wapas aa jaye.');
                        }

                        // Success!
                        location.reload();

                    } catch(error) {
                        alert('Assign rider failed: ' + error.message);
                        rBtn.textContent = 'Assign'; 
                        rBtn.disabled = false;
                    }
                };
                
                // Start the assignment process
                await assignRider(false);
            };
        }
        // Load rider assignment history
        if (rTimeline) {
            rTimeline.innerHTML = '<div style="color:#6b7280;padding:8px;text-align:center;">Loading history...</div>';
            fetch(`/orders/${order.id}/rider/timeline`, { headers: { 'Accept':'application/json' }})
                .then(r=>r.json())
                .then(j=>{
                    if (j && j.success && j.data && j.data.length) {
                        rTimeline.innerHTML = j.data.map(h=>`<div style="padding:6px 8px;border-left:3px solid ${h.is_current?'#10b981':'#d1d5db'};margin-bottom:4px;background:${h.is_current?'#ecfdf5':'#f9fafb'};"><div style="font-weight:500;color:#111827;">${h.rider_name||'Unassigned'} ${h.is_current?'<span style="color:#10b981;font-size:11px;">(Current)</span>':''}</div><div style="font-size:11px;color:#6b7280;">${h.assigned_at} by ${h.assigned_by_name||'System'}</div></div>`).join('');
                    } else {
                        rTimeline.innerHTML = '<div style="color:#9ca3af;padding:8px;text-align:center;font-size:12px;">No assignment history</div>';
                    }
                }).catch(()=>{ rTimeline.innerHTML = '<div style="color:#ef4444;padding:8px;text-align:center;font-size:12px;">Failed to load</div>'; });
        }
    } catch(e) { console.warn('edit rider UI wiring failed', e); }
    
    // Fetch and display customer notes if order has a customer_id
    if (order.customer_id) {
        fetch('/customers/' + order.customer_id)
            .then(response => response.json())
            .then(data => {
                if (data && data.success && data.customer && data.customer.notes && data.customer.notes.trim() !== '') {
                    const notesDisplay = document.getElementById('editCustomerNotesDisplay');
                    if (notesDisplay) {
                        notesDisplay.innerHTML = '<div style="padding: 14px; background: linear-gradient(135deg, #fef3c7 0%, #fde68a 100%); border: 2px solid #fbbf24; border-radius: 8px;">' +
                            '<div style="display: flex; align-items: center; margin-bottom: 8px;">' +
                                '<span style="font-size: 20px; margin-right: 8px;">⚠️</span>' +
                                '<strong style="color: #92400e; font-size: 15px;">Customer Instructions / Notes:</strong>' +
                            '</div>' +
                            '<div style="color: #78350f; font-size: 13px; line-height: 1.6; white-space: pre-wrap; word-wrap: break-word;">' + (data.customer.notes || '') + '</div>' +
                        '</div>';
                        notesDisplay.style.display = 'block';
                    }
                }
            })
            .catch(error => {
                console.warn('Failed to fetch customer notes:', error);
            });
    }
    
    // ========================================
    // WEIGHT FACTOR FUNCTIONALITY (EDIT MODE ONLY)
    // ========================================
    // Initialize weight factors for line items
    initializeWeightFactors(order);
    
    // Show weight factor feedback on form load for items that have weight factors
    setTimeout(() => {
        if (order.line_items) {
            order.line_items.forEach((item, index) => {
                showWeightFactorFeedbackOnLoad(index);
                populateScanConversion(index, item);
            });
        }
    }, 500); // Wait for weight factors to be loaded
}

// Global storage for weight factors
window.lineItemWeightFactors = {};       // By product name
window.lineItemWeightFactorsById = {};   // ⭐ By product_id (more reliable)
window.originalQuantityInputs = {};

function initializeWeightFactors(order) {
    if (!order.line_items || order.line_items.length === 0) {
        return;
    }
    
    // ⭐ Extract unique product IDs (primary) and names (fallback)
    const productIds = [...new Set(order.line_items.map(item => item.product_id).filter(id => id && id > 0))];
    const productNames = [...new Set(order.line_items.map(item => item.name || item.title).filter(Boolean))];
    
    if (productIds.length === 0 && productNames.length === 0) {
        return;
    }
    
    // Fetch weight factors for these products
    fetch('/api/products/weight-factors', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json',
            'X-Requested-With': 'XMLHttpRequest',
            'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || ''
        },
        body: JSON.stringify({ 
            product_ids: productIds,      // ⭐ Primary lookup
            product_names: productNames   // Fallback lookup
        })
    })
    .then(r => r.json())
    .then(data => {
        if (data.success) {
            window.lineItemWeightFactors = data.weight_factors || {};
            window.lineItemWeightFactorsById = data.weight_factors_by_id || {};
            console.log('Weight factors loaded:', {
                byName: window.lineItemWeightFactors,
                byId: window.lineItemWeightFactorsById
            });
        }
    })
    .catch(err => {
        console.warn('Could not load weight factors:', err);
    });
}

// ⭐ Helper: Get weight factor by product_id first, then by name
function getWeightFactorForLineItem(productId, productName) {
    // Try by product_id first (most reliable)
    if (productId && window.lineItemWeightFactorsById[productId]) {
        return window.lineItemWeightFactorsById[productId];
    }
    // Fallback to name matching
    if (productName && window.lineItemWeightFactors[productName]) {
        return window.lineItemWeightFactors[productName];
    }
    return 1; // Default
}

// ⭐ Barcode-qty: decode the stored weight-embedded EAN-13 (in-store flag '2' +
// 6-digit PLU + 5-digit grams + check) so the edit/view screens can show what the
// scale actually weighed. Mirrors mobile utils/barcodeDecode.js. Returns kg or null.
function decodeScannedWeightKg(raw) {
    var code = String(raw == null ? '' : raw).replace(/\D/g, '');
    if (code.length !== 13 || code.charAt(0) !== '2') return null;
    var grams = parseInt(code.substring(7, 12), 10);
    if (isNaN(grams)) return null;
    return grams / 1000;
}

// Inline badge fragment for a barcode-set line: "· scanned 2.050 kg" plus an empty
// span that populateScanConversion() later fills with "→ applied (÷factor)". Returns
// '' for non-barcode lines or a blank/unreadable barcode (e.g. older scans).
//
// ⭐ 'box_scan' lines deliberately fall into that "non-barcode" case. Their label's
// five middle digits are a PIECE COUNT, not grams, so decoding them as a weight
// would print a confident "· scanned 0.001 kg" that is pure fiction.
function scannedWeightBadge(item, index) {
    if (!item || item.quantity_source !== 'barcode') return '';
    var kg = decodeScannedWeightKg(item.quantity_scanned_barcode);
    if (kg === null) return '';
    return '<span style="color:#15803d; font-weight:600;">· scanned ' + kg.toFixed(3) + ' kg</span>' +
           '<span id="scanConv_' + index + '" style="color:#15803d; font-weight:600;"></span>';
}

// 📋 Oct-19-2026 — what the customer ORDERED, when the quantity has since changed
// (a meat weight scan, a frozen box count, a typed correction). The server keeps the
// first number in `original_quantity` and never overwrites it. Returns the plain
// number ("3", "2.5", "2.15") or null when there is nothing worth showing — never
// changed, older data, or changed back to exactly what was ordered.
// ⚠ Screen-only: the printed / PDF / PNG invoice is rendered by the server and
// never reads this.
function orderedQtyIfChanged(item) {
    if (!item || item.original_quantity === null || item.original_quantity === undefined || item.original_quantity === '') return null;
    var orig = parseFloat(item.original_quantity);
    var now = parseFloat(item.quantity);
    if (!isFinite(orig) || orig <= 0) return null;
    if (isFinite(now) && Math.abs(orig - now) < 0.0005) return null;
    return String(Math.round(orig * 1000) / 1000);
}

// Inline "· ordered 3" fragment for the Edit Invoice quantity line ('' when none).
function orderedQtyBadge(item) {
    var o = orderedQtyIfChanged(item);
    if (o === null) return '';
    var unit = item.quantity_source === 'box_scan' ? (o === '1' ? ' box' : ' boxes') : '';
    return '<span title="Quantity the customer ordered, before it was scanned / changed" style="color:#b45309; font-weight:600;">· ordered ' + o + unit + '</span>';
}

// Once weight factors have loaded (same 500ms timing as showWeightFactorFeedbackOnLoad),
// append "→ applied (÷factor)" to a barcode line whose product carries a weight factor
// ≠ 1. No-op for factor-1 or non-barcode lines. Never throws.
function populateScanConversion(index, item) {
    try {
        var span = document.getElementById('scanConv_' + index);
        if (!span || !item || item.quantity_source !== 'barcode') return;
        var wf = getWeightFactorForLineItem(item.product_id, item.name || item.title);
        if (wf && wf !== 1) {
            var applied = parseFloat(item.quantity || 0).toFixed(2);
            span.textContent = ' → ' + applied + ' applied (÷' + wf + ')';
        }
    } catch (e) {}
}

function showWeightFactorFeedbackOnLoad(index) {
    const item = document.querySelector(`.line-item[data-index="${index}"]`);
    if (!item) return;
    
    const quantityInput = item.querySelector(`input[name="items[${index}][quantity]"]`);
    const feedbackSpan = document.getElementById(`weightFactorFeedback_${index}`);
    const productId = item.getAttribute('data-product-id');
    const productName = item.getAttribute('data-product-name');
    
    if (!quantityInput || !feedbackSpan) return;
    
    // ⭐ Get weight factor by product_id first, then by name
    const weightFactor = getWeightFactorForLineItem(productId, productName);
    
    // Only show if weight factor exists and is not 1
    if (weightFactor !== 1 && weightFactor > 0) {
        feedbackSpan.style.display = 'inline';
        feedbackSpan.innerHTML = `⚖️ WF: ${weightFactor}`;
    }
}

function showWeightFactorFeedbackOnFocus(index) {
    const item = document.querySelector(`.line-item[data-index="${index}"]`);
    if (!item) return;
    
    const quantityInput = item.querySelector(`input[name="items[${index}][quantity]"]`);
    const feedbackSpan = document.getElementById(`weightFactorFeedback_${index}`);
    const productId = item.getAttribute('data-product-id');
    const productName = item.getAttribute('data-product-name');
    
    if (!quantityInput || !feedbackSpan) return;
    
    // ⭐ Get weight factor by product_id first, then by name
    const weightFactor = getWeightFactorForLineItem(productId, productName);
    
    // Only show if weight factor exists and is not 1
    if (weightFactor !== 1 && weightFactor > 0) {
        const alreadyAdjusted = quantityInput.getAttribute('data-adjusted') === 'true';
        const userEntered = quantityInput.getAttribute('data-user-entered') || '';
        const currentValue = parseFloat(quantityInput.value) || 0;
        
        // Show appropriate message based on state
        if (alreadyAdjusted && userEntered && currentValue > 0) {
            feedbackSpan.style.display = 'inline';
            feedbackSpan.innerHTML = `⚖️ ${userEntered}→${currentValue} (÷${weightFactor})`;
        } else {
            feedbackSpan.style.display = 'inline';
            feedbackSpan.innerHTML = `⚖️ WF: ${weightFactor}`;
        }
    }
}

function applyWeightFactorToQuantity(index) {
    const item = document.querySelector(`.line-item[data-index="${index}"]`);
    if (!item) return;
    
    const quantityInput = item.querySelector(`input[name="items[${index}][quantity]"]`);
    const feedbackSpan = document.getElementById(`weightFactorFeedback_${index}`);
    const productId = item.getAttribute('data-product-id');
    const productName = item.getAttribute('data-product-name');
    
    if (!quantityInput) return;
    
    // ⭐ Get weight factor by product_id first, then by name
    const weightFactor = getWeightFactorForLineItem(productId, productName);
    
    // Skip if no weight factor
    if (weightFactor === 1 || weightFactor <= 0) {
        if (feedbackSpan) {
            feedbackSpan.style.display = 'none';
        }
        updateLineTotal(index);
        return;
    }
    
    const currentValue = parseFloat(quantityInput.value) || 0;
    if (currentValue <= 0) {
        updateLineTotal(index);
        return;
    }
    
    // Check if this was already adjusted
    const alreadyAdjusted = quantityInput.getAttribute('data-adjusted') === 'true';
    const storedAdjustedValue = parseFloat(quantityInput.getAttribute('data-adjusted-value') || 0);
    
    // Determine if user entered a new value different from the adjusted one
    const userChangedFromAdjusted = alreadyAdjusted && Math.abs(currentValue - storedAdjustedValue) > 0.001;
    
    if (userChangedFromAdjusted || !alreadyAdjusted) {
        // Store what the USER ENTERED before we change it
        const userEnteredValue = currentValue;
        
        // Apply weight factor
        const adjustedValue = parseFloat((currentValue / weightFactor).toFixed(2));
        
        if (Math.abs(currentValue - adjustedValue) > 0.001) {
            // Update the input field
            quantityInput.value = adjustedValue;
            
            // Mark as adjusted and store both values
            quantityInput.setAttribute('data-adjusted', 'true');
            quantityInput.setAttribute('data-adjusted-value', adjustedValue);
            quantityInput.setAttribute('data-user-entered', userEnteredValue);
            
            // Show compact inline feedback
            if (feedbackSpan) {
                feedbackSpan.style.display = 'inline';
                feedbackSpan.innerHTML = `⚖️ ${userEnteredValue}→${adjustedValue} (÷${weightFactor})`;
            }
        }
    } else {
        // Already adjusted and value hasn't changed - keep showing the feedback
        if (feedbackSpan && alreadyAdjusted) {
            const userEntered = quantityInput.getAttribute('data-user-entered') || '';
            const adjustedValue = parseFloat(quantityInput.value) || 0;
            if (userEntered) {
                feedbackSpan.style.display = 'inline';
                feedbackSpan.innerHTML = `⚖️ ${userEntered}→${adjustedValue} (÷${weightFactor})`;
            }
        }
    }
    
    // Trigger line total update
    updateLineTotal(index);
}

function showEditError(message) {
    const content = document.getElementById('editOrderContent');
    content.innerHTML = `
        <div class="text-center py-8">
            <div class="text-red-600 mb-4">
                <svg class="mx-auto h-12 w-12" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path>
                </svg>
            </div>
            <h3 class="text-lg font-medium text-gray-900 mb-2">Error</h3>
            <p class="text-gray-500">${message}</p>
        </div>
    `;
}

function showSuccessMessage(message, duration = 3000) {
    // Remove any existing success message
    const existingMessage = document.querySelector('.order-success-message');
    if (existingMessage) {
        existingMessage.remove();
    }
    
    // Create success message element
    const successDiv = document.createElement('div');
    successDiv.className = 'order-success-message fixed top-4 right-4 bg-green-500 text-white px-4 py-2 rounded-lg shadow-lg z-50 transition-all duration-300';
    successDiv.innerHTML = `
        <div class="flex items-center">
            <svg class="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"></path>
            </svg>
            ${message}
        </div>
    `;
    
    document.body.appendChild(successDiv);
    
    // Auto-remove after duration
    setTimeout(() => {
        if (successDiv) {
            successDiv.style.opacity = '0';
            successDiv.style.transform = 'translateX(100%)';
            setTimeout(() => successDiv.remove(), 300);
        }
    }, duration);
}
// Line item management functions
let lineItemIndex = 1000; // Start high to avoid conflicts with existing items

// ⭐ Handle Tab navigation from Qty field - skip to next row's product name
function handleQtyTabNavigation(event, currentIndex) {
    if (event.key === 'Tab' && !event.shiftKey) {
        event.preventDefault();
        
        const container = document.getElementById('lineItemsContainer');
        if (!container) return;
        
        const lineItems = Array.from(container.querySelectorAll('.line-item'));
        const currentItem = document.querySelector(`.line-item[data-index="${currentIndex}"]`);
        const currentItemIndex = lineItems.indexOf(currentItem);
        
        // Find next line item
        if (currentItemIndex < lineItems.length - 1) {
            const nextItem = lineItems[currentItemIndex + 1];
            const nextNameInput = nextItem.querySelector('input[name*="[name]"]');
            if (nextNameInput && !nextNameInput.readOnly) {
                nextNameInput.focus();
                return;
            }
        }
        
        // If we're on the last row or next row's name is readonly, add new row and focus it
        addLineItem();
        setTimeout(() => {
            const newLineItems = container.querySelectorAll('.line-item');
            if (newLineItems.length > 0) {
                const newItem = newLineItems[newLineItems.length - 1];
                const newNameInput = newItem.querySelector('input[name*="[name]"]');
                if (newNameInput) {
                    newNameInput.focus();
                }
            }
        }, 50);
    }
}

function addLineItem() {
    const container = document.getElementById('lineItemsContainer');
    const emptyMessage = container.querySelector('div[style*="text-align: center"]');
    if (emptyMessage) {
        emptyMessage.remove();
    }
    
    const newItem = document.createElement('div');
    newItem.className = 'line-item';
    newItem.setAttribute('data-index', lineItemIndex);
    newItem.style.cssText = 'display: grid; grid-template-columns: 3fr 70px 90px 110px auto 32px; gap: 12px; align-items: end; padding: 12px; margin-bottom: 12px; border: 1px solid #e5e7eb; border-radius: 6px; background-color: #f9fafb;';
    
    newItem.innerHTML = `
        <div style="position: relative;">
            <label style="display: block; font-size: 12px; font-weight: 500; color: #6b7280; margin-bottom: 4px;">Item Name</label>
            <input type="text" name="items[${lineItemIndex}][name]" value="" 
                   style="width: 100%; padding: 6px 8px; border: 1px solid #d1d5db; border-radius: 4px; font-size: 14px;"
                   onkeyup="handleProductSearch(this, ${lineItemIndex}, event)" 
                   onkeydown="handleProductKeydown(this, ${lineItemIndex}, event)"
                   onfocus="showProductDropdown(${lineItemIndex})"
                   onblur="hideProductDropdown(${lineItemIndex})"
                   placeholder="Type to search products..."
                   autocomplete="off">
            <div id="productDropdown_${lineItemIndex}" class="product-dropdown" style="display: none; position: absolute; top: 100%; left: 0; right: 0; background: white; border: 1px solid #d1d5db; border-radius: 4px; max-height: 200px; overflow-y: auto; z-index: 1000; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);"></div>
            <span id="skuDisplay_${lineItemIndex}" style="display: none; margin-top: 4px; font-size: 11px; color: #0369a1; background: #dbeafe; padding: 2px 6px; border-radius: 3px;"></span>
            <input type="hidden" name="items[${lineItemIndex}][id]" value="">
            <input type="hidden" name="items[${lineItemIndex}][sku]" value="">
            <input type="hidden" name="items[${lineItemIndex}][variant_id]" value="">
            <input type="hidden" name="items[${lineItemIndex}][product_id]" value="">
            <input type="hidden" name="items[${lineItemIndex}][is_free]" value="0" class="is-free-input">
        </div>
        <div>
            <label style="display: block; font-size: 12px; font-weight: 500; color: #6b7280; margin-bottom: 4px;">Quantity</label>
            <input type="number" step="0.01" name="items[${lineItemIndex}][quantity]" value="1" min="0.01"
                   style="width: 100%; padding: 6px 8px; border: 1px solid #d1d5db; border-radius: 4px; font-size: 14px;" 
                   onchange="updateLineTotal(${lineItemIndex}); freezeProductName(${lineItemIndex})"
                   onkeydown="handleQtyTabNavigation(event, ${lineItemIndex})">
        </div>
        <div>
            <label style="display: block; font-size: 12px; font-weight: 500; color: #6b7280; margin-bottom: 4px;">Unit Price</label>
            <input type="number" step="0.01" name="items[${lineItemIndex}][unit_price]" value="0" tabindex="-1"
                   style="width: 100%; padding: 6px 8px; border: 1px solid #d1d5db; border-radius: 4px; font-size: 14px;" onchange="updateLineTotal(${lineItemIndex})">
        </div>
        <div>
            <label style="display: block; font-size: 12px; font-weight: 500; color: #6b7280; margin-bottom: 4px;">Total</label>
            <span class="line-total" style="display: block; padding: 6px 8px; background-color: #e5e7eb; border-radius: 4px; font-size: 14px; font-weight: 500;">PKR 0.00</span>
        </div>
        <div>
            <button type="button" onclick="toggleFreeItem(${lineItemIndex})" class="free-toggle-btn" style="padding: 6px 10px; border: 1px solid #d1d5db; border-radius: 4px; cursor: pointer; font-size: 11px; font-weight: 600; line-height: 1.2; background-color: #fff; color: #6b7280;" title="Click to make this item free">
                Make Free
            </button>
        </div>
        <div>
            <button type="button" onclick="removeLineItem(${lineItemIndex})" style="background-color: #ef4444; color: white; padding: 8px; border: none; border-radius: 4px; cursor: pointer; font-size: 16px; line-height: 1;">
                ×
            </button>
        </div>
        <div style="grid-column: 1 / -1;" class="instructions-wrapper" data-index="${lineItemIndex}">
            <div class="instructions-badge" style="display:none;"></div>
            <span class="instructions-add-link" onclick="toggleInstructions(${lineItemIndex})" style="cursor:pointer; font-size:11px; color:#9CA3AF; padding:2px 0; display:inline-flex; align-items:center; gap:3px;">📝 <span style="border-bottom:1px dashed #9CA3AF;">Add note</span></span>
            <div class="instructions-input-wrap" style="display:none; margin-top:4px;">
                <input type="text" name="items[${lineItemIndex}][instructions]" value="" placeholder="Type instructions..." style="width:100%; padding:4px 8px; border:1px solid #FCD34D; border-radius:4px; font-size:12px; color:#374151; background:#FFFBEB;" onblur="collapseInstructions(${lineItemIndex})">
            </div>
        </div>
    `;
    
    container.appendChild(newItem);
    lineItemIndex++;
    updateSubtotal();
}

function removeLineItem(index) {
    if (!confirm('Are you sure you want to remove this item?')) return;
    const item = document.querySelector(`.line-item[data-index="${index}"]`);
    if (item) {
        item.remove();
        updateSubtotal();
        
        // Check if no items left
        const container = document.getElementById('lineItemsContainer');
        const items = container.querySelectorAll('.line-item');
        if (items.length === 0) {
            container.innerHTML = '<div style="text-align: center; color: #6b7280; padding: 20px;">No line items. Click "Add Item" to add items.</div>';
        }
    }
}

function unlockQurbaniFields(btn) {
    if (!confirm('Are you sure you want to edit the Qurbani details for this item?')) return;
    const fieldsDiv = btn.closest('.qurbani-item-fields');
    if (!fieldsDiv) return;
    fieldsDiv.querySelectorAll('select.qurbani-item-select').forEach(sel => {
        sel.disabled = false;
        sel.style.background = '#fff';
    });
    btn.textContent = '🔓 Unlocked';
    btn.disabled = true;
    btn.style.background = '#9CA3AF';
}

function toggleInstructions(index) {
    const wrapper = document.querySelector(`.instructions-wrapper[data-index="${index}"]`);
    if (!wrapper) return;
    const inputWrap = wrapper.querySelector('.instructions-input-wrap');
    const badge = wrapper.querySelector('.instructions-badge');
    const addLink = wrapper.querySelector('.instructions-add-link');
    if (inputWrap.style.display === 'none') {
        inputWrap.style.display = 'block';
        if (badge) badge.style.display = 'none';
        if (addLink) addLink.style.display = 'none';
        const inp = inputWrap.querySelector('input');
        if (inp) inp.focus();
    } else {
        collapseInstructions(index);
    }
}

function collapseInstructions(index) {
    setTimeout(() => {
        const wrapper = document.querySelector(`.instructions-wrapper[data-index="${index}"]`);
        if (!wrapper) return;
        const inputWrap = wrapper.querySelector('.instructions-input-wrap');
        const badge = wrapper.querySelector('.instructions-badge');
        const addLink = wrapper.querySelector('.instructions-add-link');
        const inp = inputWrap ? inputWrap.querySelector('input') : null;
        const val = inp ? inp.value.trim() : '';
        if (val) {
            if (badge) {
                badge.innerHTML = `<span style="font-size:12px;">📝</span><span style="font-size:12px; color:#92400E; font-weight:500; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${val}</span><span style="font-size:10px; color:#B45309; margin-left:4px; flex-shrink:0;">✏️</span>`;
                badge.style.display = 'inline-flex';
                badge.style.cssText = 'cursor:pointer; display:inline-flex; align-items:center; gap:4px; padding:3px 10px; background:#FEF3C7; border:1px solid #FCD34D; border-radius:4px; max-width:100%;';
                badge.onclick = () => toggleInstructions(index);
            }
            if (addLink) addLink.style.display = 'none';
        } else {
            if (badge) badge.style.display = 'none';
            if (addLink) { addLink.style.display = 'inline-flex'; }
            else {
                const link = document.createElement('span');
                link.className = 'instructions-add-link';
                link.onclick = () => toggleInstructions(index);
                link.style.cssText = 'cursor:pointer; font-size:11px; color:#9CA3AF; padding:2px 0; display:inline-flex; align-items:center; gap:3px;';
                link.innerHTML = '📝 <span style="border-bottom:1px dashed #9CA3AF;">Add note</span>';
                wrapper.insertBefore(link, inputWrap);
            }
        }
        inputWrap.style.display = 'none';
    }, 200);
}

// ── Line-item quick notes (preset chips next to "Add note") ───────────────
// Shared team-wide presets fetched once from /line-item-quick-notes. Tapping a
// chip just fills the instructions input (replace) and reuses the existing
// save path — it does NOT save on its own. "📌 Pin" promotes the typed note
// to the shared list so it shows up everywhere (web + mobile).
window.__quickNotes = window.__quickNotes || [];

function escapeQuickNote(str) {
    return String(str == null ? '' : str)
        .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function quickNoteChipsHtml(index) {
    var chips = (window.__quickNotes || []).map(function (n) {
        var safe = escapeQuickNote(n.note_text);
        var attr = safe.replace(/`/g, '&#96;');
        // Each chip = label (tap to apply) + × (tap to remove from the list).
        return '<span style="display:inline-flex; align-items:center; background:#FFFBEB; border:1px solid #FCD34D; border-radius:12px; overflow:hidden; line-height:1.4;">'
            + '<button type="button" onclick="applyQuickNote(' + index + ', this.getAttribute(\'data-note\'))" data-note="' + attr + '" '
            + 'style="cursor:pointer; font-size:11px; color:#92400E; background:transparent; border:none; padding:2px 5px 2px 9px;">'
            + safe + '</button>'
            + '<span onclick="removeQuickNote(' + n.id + ', event)" title="Remove this quick note from the list" '
            + 'style="cursor:pointer; font-size:13px; color:#B45309; padding:1px 8px 1px 3px;">&times;</span>'
            + '</span>';
    }).join('');
    // "Pin current note" affordance
    chips += '<button type="button" onclick="pinCurrentQuickNote(' + index + ')" title="Save the typed note as a reusable quick note" '
        + 'style="cursor:pointer; font-size:11px; color:#2563eb; background:transparent; border:1px dashed #93c5fd; border-radius:12px; padding:2px 9px; line-height:1.4;">📌 Pin</button>';
    return chips;
}

function renderAllQuickNoteChips() {
    document.querySelectorAll('.quick-note-chips').forEach(function (box) {
        var idx = box.getAttribute('data-index');
        box.innerHTML = quickNoteChipsHtml(idx);
    });
}

function loadQuickNotes() {
    return fetch('/line-item-quick-notes', { headers: { 'Accept': 'application/json' } })
        .then(function (r) { return r.ok ? r.json() : { data: [] }; })
        .then(function (res) {
            window.__quickNotes = (res && res.data) ? res.data : [];
            renderAllQuickNoteChips();
        })
        .catch(function () { /* non-fatal: chips just stay as the Pin button */ });
}

// Apply a preset to a line item's note: fill the input (replace), then let the
// existing collapse logic show the yellow badge. Save still happens on the
// normal "Save" action.
function applyQuickNote(index, text) {
    var wrapper = document.querySelector('.instructions-wrapper[data-index="' + index + '"]');
    if (!wrapper) return;
    var inputWrap = wrapper.querySelector('.instructions-input-wrap');
    var inp = inputWrap ? inputWrap.querySelector('input') : null;
    if (!inp) return;
    inp.value = text;
    // Notify any change listeners (keeps unsaved-changes tracking honest).
    inp.dispatchEvent(new Event('input', { bubbles: true }));
    // collapseInstructions reads the (now-filled) input and renders the badge.
    collapseInstructions(index);
}

function pinCurrentQuickNote(index) {
    var wrapper = document.querySelector('.instructions-wrapper[data-index="' + index + '"]');
    if (!wrapper) return;
    var inputWrap = wrapper.querySelector('.instructions-input-wrap');
    var inp = inputWrap ? inputWrap.querySelector('input') : null;
    var text = inp ? inp.value.trim() : '';
    if (!text) {
        alert('Type a note in the box first, then tap 📌 Pin to save it as a reusable quick note.');
        return;
    }
    fetch('/line-item-quick-notes', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json',
            'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.content || ''
        },
        body: JSON.stringify({ note_text: text })
    })
    .then(function (r) { return r.json(); })
    .then(function (res) {
        if (res && res.success && res.data) {
            var exists = (window.__quickNotes || []).some(function (n) { return n.id === res.data.id; });
            if (!exists) window.__quickNotes.push(res.data);
            renderAllQuickNoteChips();
        } else {
            alert((res && res.message) ? res.message : 'Could not pin this quick note.');
        }
    })
    .catch(function () { alert('Could not pin this quick note (network error).'); });
}

// Remove (unpin) a preset from the shared list. Does NOT change any note
// already saved on an order — it only removes the chip going forward.
function removeQuickNote(id, ev) {
    if (ev) ev.stopPropagation();
    if (!confirm('Remove this quick note from the list? Notes already saved on orders are not affected.')) return;
    fetch('/line-item-quick-notes/' + id, {
        method: 'DELETE',
        headers: {
            'Accept': 'application/json',
            'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.content || ''
        }
    })
    .then(function (r) { return r.json(); })
    .then(function (res) {
        if (res && res.success) {
            window.__quickNotes = (window.__quickNotes || []).filter(function (n) { return n.id !== id; });
            renderAllQuickNoteChips();
        } else {
            alert((res && res.message) ? res.message : 'Could not remove this quick note.');
        }
    })
    .catch(function () { alert('Could not remove this quick note (network error).'); });
}

// Load the preset list once the page is ready. renderAllQuickNoteChips() is
// also called whenever line items re-render (chips read window.__quickNotes).
document.addEventListener('DOMContentLoaded', loadQuickNotes);

function toggleFreeItem(index) {
    const item = document.querySelector(`.line-item[data-index="${index}"]`);
    if (!item) return;
    
    const isFreeInput = item.querySelector('.is-free-input');
    const isFree = isFreeInput.value === '1';
    const newFreeState = !isFree;
    
    // Update hidden input
    isFreeInput.value = newFreeState ? '1' : '0';
    
    // Update toggle button appearance
    const toggleBtn = item.querySelector('.free-toggle-btn');
    if (toggleBtn) {
        toggleBtn.innerHTML = newFreeState ? '✓ FREE' : 'Make Free';
        toggleBtn.style.backgroundColor = newFreeState ? '#16a34a' : '#fff';
        toggleBtn.style.color = newFreeState ? '#fff' : '#6b7280';
        toggleBtn.style.borderColor = newFreeState ? '#16a34a' : '#d1d5db';
        toggleBtn.title = newFreeState ? 'Click to remove free status' : 'Click to make this item free';
    }
    
    // Update row styling
    item.style.borderColor = newFreeState ? '#bbf7d0' : '#e5e7eb';
    item.style.backgroundColor = newFreeState ? '#f0fdf4' : '#f9fafb';
    
    // Update total display
    const totalSpan = item.querySelector('.line-total');
    if (totalSpan) {
        totalSpan.style.backgroundColor = newFreeState ? '#bbf7d0' : '#e5e7eb';
        if (newFreeState) {
            totalSpan.textContent = 'FREE';
        } else {
            const quantity = parseFloat(item.querySelector(`input[name="items[${index}][quantity]"]`).value) || 0;
            const price = parseFloat(item.querySelector(`input[name="items[${index}][unit_price]"]`).value) || 0;
            totalSpan.textContent = formatCurrency(Math.round(quantity * price * 100) / 100, 'PKR');
        }
    }
    
    // Recalculate subtotal and order total
    updateSubtotal();
}

function updateLineTotal(index) {
    const item = document.querySelector(`.line-item[data-index="${index}"]`);
    if (item) {
        // Check if item is marked as free
        const isFreeInput = item.querySelector('.is-free-input');
        const isFree = isFreeInput && isFreeInput.value === '1';
        
        // Get quantity from input (already adjusted by applyWeightFactorToQuantity if applicable)
        const quantity = parseFloat(item.querySelector(`input[name="items[${index}][quantity]"]`).value) || 0;
        const price = parseFloat(item.querySelector(`input[name="items[${index}][unit_price]"]`).value) || 0;
        
        const totalSpan = item.querySelector('.line-total');
        if (isFree) {
            totalSpan.textContent = 'FREE';
        } else {
            // Calculate total with proper precision
            const total = Math.round(quantity * price * 100) / 100;
            totalSpan.textContent = formatCurrency(total, 'PKR');
        }
        
        updateSubtotal();
    }
}

function freezeProductName(index) {
    const item = document.querySelector(`.line-item[data-index="${index}"]`);
    if (!item) return;
    
    const productInput = item.querySelector(`input[name="items[${index}][name]"]`);
    const productIdInput = item.querySelector(`input[name="items[${index}][id]"]`);
    
    // Only freeze if product is selected (has product_id and name)
    if (productInput && productInput.value && productIdInput && productIdInput.value) {
        // Check if already frozen
        if (productInput.readOnly) return;
        
        // Freeze the product input
        productInput.readOnly = true;
        productInput.style.backgroundColor = '#f3f4f6';
        productInput.style.cursor = 'not-allowed';
        productInput.style.color = '#6b7280';
        
        // Disable the dropdown
        productInput.onkeyup = null;
        productInput.onkeydown = null;
        productInput.onfocus = null;
        
        // Add a visual indicator
        const label = productInput.previousElementSibling;
        if (label && !label.querySelector('.frozen-indicator')) {
            const indicator = document.createElement('span');
            indicator.className = 'frozen-indicator';
            indicator.style.cssText = 'margin-left: 8px; font-size: 11px; color: #6b7280; font-weight: normal;';
            indicator.innerHTML = '🔒 Locked (delete to change)';
            label.appendChild(indicator);
        }
    }
}

// Freeze all existing line items (for edit mode)
function freezeAllExistingLineItems() {
    const items = document.querySelectorAll('.line-item');
    items.forEach(item => {
        const index = item.getAttribute('data-index');
        if (!index) return;
        
        // Check if this is an existing line item (has product_id)
        const productIdInput = item.querySelector(`input[name*="[id]"]`);
        const productInput = item.querySelector(`input[name*="[name]"]`);
        
        // If line item has a product_id and product name, it's existing - freeze it
        if (productIdInput && productIdInput.value && productInput && productInput.value) {
            freezeProductName(index);
        }
    });
}

// Auto-freeze existing line items when modal/page loads
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function() {
        setTimeout(freezeAllExistingLineItems, 500);
    });
} else {
    setTimeout(freezeAllExistingLineItems, 500);
}

// Also observe for dynamically added content (edit modal)
const observeLineItems = function() {
    const container = document.getElementById('lineItemsContainer');
    if (container && !container.hasAttribute('data-observer-attached')) {
        container.setAttribute('data-observer-attached', 'true');
        
        const observer = new MutationObserver(function(mutations) {
            let shouldFreeze = false;
            mutations.forEach(function(mutation) {
                if (mutation.addedNodes.length) {
                    mutation.addedNodes.forEach(node => {
                        if (node.classList && node.classList.contains('line-item')) {
                            shouldFreeze = true;
                        }
                    });
                }
            });
            if (shouldFreeze) {
                setTimeout(freezeAllExistingLineItems, 100);
            }
        });
        
        observer.observe(container, { childList: true });
    }
};

// Try to attach observer immediately and also after delays
observeLineItems();
setTimeout(observeLineItems, 1000);
setTimeout(observeLineItems, 3000);
function updateSubtotal() {
    let subtotal = 0;
    const items = document.querySelectorAll('.line-item');
    
    items.forEach(item => {
        // Skip free items — they contribute 0 to subtotal
        const isFreeInput = item.querySelector('.is-free-input');
        if (isFreeInput && isFreeInput.value === '1') return;
        
        const index = item.getAttribute('data-index');
        const quantity = parseFloat(item.querySelector(`input[name*="[quantity]"]`).value) || 0;
        const price = parseFloat(item.querySelector(`input[name*="[unit_price]"]`).value) || 0;
        subtotal += quantity * price;
    });
    
    const subtotalInput = document.querySelector('input[name="subtotal_price"]');
    if (subtotalInput) {
        subtotalInput.value = subtotal.toFixed(2);
        updateOrderTotal();
        
        // Load dynamic statuses for the edit form (only if order exists)
        if (typeof order !== 'undefined' && order && order.order_status) {
            loadEditOrderStatuses(order.order_status);
        }
    }
}
// Cache statuses so we don't refetch repeatedly
window.__orderStatusesCache = window.__orderStatusesCache || null;

function normalizeLegacyStatus(code) {
    if (!code) return code;
    const map = {
        'pending': 'new',
        'on-hold': 'on_hold',
        'completed': 'delivered',
        'fulfilled': 'delivered',
        'approved': 'processing',
        'confirmed': 'processing'
    };
    return map[code] || code;
}

// Load available statuses for edit order form
async function loadEditOrderStatuses(currentStatus) {
    try {
        const statusSelect = document.getElementById('editOrderStatus');
        if (!statusSelect) return;

        const normalized = normalizeLegacyStatus(currentStatus);

        if (!window.__orderStatusesCache) {
            const response = await fetch('/order-status/api/statuses', {
                method: 'GET',
                headers: {
                    'Accept': 'application/json',
                    'Content-Type': 'application/json',
                    'X-Requested-With': 'XMLHttpRequest',
                    'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').getAttribute('content')
                },
                credentials: 'same-origin'
            });
            const data = await response.json();
            if (data && data.success) {
                window.__orderStatusesCache = data.data;
            }
        }

        const list = window.__orderStatusesCache;
        if (Array.isArray(list) && list.length) {
            statusSelect.innerHTML = list.map(status => 
                `<option value="${status.status_code}" ${status.status_code === normalized ? 'selected' : ''}>${status.icon} ${status.status_name}</option>`
            ).join('');
            // If nothing selected and no normalized current status, default to 'new'
            if (!statusSelect.value && list.find(s => s.status_code === 'new')) {
                statusSelect.value = 'new';
            }
            // If current status not in master (legacy), insert it at top so user sees it
            if (!list.find(s => s.status_code === normalized) && currentStatus) {
                const opt = document.createElement('option');
                opt.value = currentStatus;
                opt.textContent = currentStatus.replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
                opt.selected = true;
                statusSelect.insertBefore(opt, statusSelect.firstChild);
            }
            // Stale-status guard (Jul-2026): remember what the form LOADED so the
            // save can tell "user deliberately changed the dropdown" apart from
            // "form sat open while someone else advanced the status". The save
            // sends this as _loaded_status; the backend keeps the DB status when
            // the dropdown was untouched (no error, nothing else is lost).
            statusSelect.dataset.loadedStatus = statusSelect.value;
        } else {
            throw new Error('Statuses cache empty');
        }
    } catch (error) {
        console.error('Error loading statuses:', error);
        // Fallback to basic statuses
        const statusSelect = document.getElementById('editOrderStatus');
        if (statusSelect) {
            const normalized = normalizeLegacyStatus(currentStatus);
            statusSelect.innerHTML = `
                <option value="new" ${normalized === 'new' ? 'selected' : ''}>â³ New</option>
                <option value="processing" ${normalized === 'processing' ? 'selected' : ''}>âš¡ Processing</option>
                <option value="out_for_delivery" ${normalized === 'out_for_delivery' ? 'selected' : ''}>ðŸšš Out for Delivery</option>
                <option value="delivered" ${normalized === 'delivered' ? 'selected' : ''}>âœ… Delivered</option>
                <option value="on_hold" ${normalized === 'on_hold' ? 'selected' : ''}>â¸ On Hold</option>
                <option value="cancelled" ${normalized === 'cancelled' ? 'selected' : ''}>âœ• Cancelled</option>
                <option value="refunded" ${normalized === 'refunded' ? 'selected' : ''}>â†© Refunded</option>
            `;
            // Stale-status guard (see success path above)
            statusSelect.dataset.loadedStatus = statusSelect.value;
        }
    }
}

// Load status timeline for quick modal
async function loadQuickStatusTimeline(orderId) {
    try {
        const timelineContainer = document.getElementById('quickStatusTimeline');
        if (!timelineContainer) return;
        
        const response = await fetch(`/order-status/api/orders/${orderId}/timeline`, {
            headers: { 
                'Accept': 'application/json',
                'X-Requested-With': 'XMLHttpRequest',
                'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').getAttribute('content')
            },
            credentials: 'same-origin'
        });
        
        const data = await response.json();
        console.log('Quick Timeline API response for order', orderId, ':', data); // Debug log
        console.log('Response status:', response.status, 'Response OK:', response.ok); // Debug response
        
        if (data.success && data.data && data.data.length > 0) {
            const timelineHtml = data.data.map((item, index) => {
                const date = new Date(item.changed_at);
                const timeDisplay = formatExactTime(date);
                const isFirst = index === 0;
                
                return `
                    <div style="display:flex;align-items:start;gap:8px;margin-bottom:${index === data.data.length - 1 ? '0' : '12px'};">
                        <div style="width:8px;height:8px;border-radius:50%;background:${getStatusColor(item.color_class)};margin-top:4px;flex-shrink:0;${isFirst ? 'box-shadow:0 0 0 2px rgba(34,197,94,0.2);' : ''}"></div>
                        <div style="flex:1;min-width:0;">
                            <div style="display:flex;align-items:center;gap:4px;margin-bottom:2px;">
                                <span style="font-size:12px;font-weight:${isFirst ? '600' : '500'};color:#374151;">${item.icon} ${item.status_name}</span>
                                ${isFirst ? '<span style="font-size:10px;background:#dcfce7;color:#166534;padding:1px 4px;border-radius:3px;">Current</span>' : ''}
                            </div>
                            <div style="font-size:11px;color:#6b7280;margin-bottom:1px;">${timeDisplay}</div>
                            ${item.notes && item.notes !== 'Status changed to ' + item.status_code ? `<div style="font-size:11px;color:#9ca3af;font-style:italic;">${item.notes}</div>` : ''}
                        </div>
                    </div>
                `;
            }).join('');
            
            timelineContainer.innerHTML = timelineHtml;
        } else {
            console.log('No timeline data available:', data); // Debug log
            timelineContainer.innerHTML = '<div style="text-align:center;color:#6b7280;font-size:12px;padding:16px;">No status history available</div>';
        }
    } catch (error) {
        console.error('Failed to load timeline:', error);
        const timelineContainer = document.getElementById('quickStatusTimeline');
        if (timelineContainer) {
            timelineContainer.innerHTML = '<div style="text-align:center;color:#ef4444;font-size:12px;padding:16px;">Failed to load timeline</div>';
        }
    }
}

// Helper function to get status color
function getStatusColor(colorClass) {
    const colors = {
        'green': '#22c55e',
        'blue': '#3b82f6', 
        'yellow': '#eab308',
        'orange': '#f97316',
        'red': '#ef4444',
        'purple': '#a855f7',
        'gray': '#6b7280'
    };
    return colors[colorClass] || '#6b7280';
}

// Helper function to format exact date and time
function formatExactTime(date) {
    const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    const month = months[date.getMonth()];
    const day = date.getDate();
    const year = date.getFullYear();
    let hours = date.getHours();
    const minutes = date.getMinutes();
    const ampm = hours >= 12 ? 'PM' : 'AM';
    hours = hours % 12;
    hours = hours ? hours : 12; // the hour '0' should be '12'
    const minutesStr = minutes < 10 ? '0' + minutes : minutes;
    
    return `${month} ${day}, ${year} ${hours}:${minutesStr} ${ampm}`;
}

// Legacy function kept for compatibility (if needed elsewhere)
function getTimeAgo(date) {
    const now = new Date();
    const diffMs = now - date;
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);
    
    if (diffMins < 1) return 'Just now';
    if (diffMins < 60) return `${diffMins}m ago`;
    if (diffHours < 24) return `${diffHours}h ago`;
    if (diffDays < 7) return `${diffDays}d ago`;
    return date.toLocaleDateString();
}
// ===== AUTO-ASSIGN RIDERS BY REGION =====
async function openAutoAssignModal() {
    let modal = document.getElementById('autoAssignRidersModal');
    if (!modal) {
        modal = document.createElement('div');
        modal.id = 'autoAssignRidersModal';
        modal.style.cssText = 'display:none;position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.5);z-index:9999;';
        modal.innerHTML = `<div style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);background:#fff;border-radius:12px;padding:24px;width:440px;max-width:95%;box-shadow:0 8px 30px rgba(0,0,0,.2);">
            <h3 style="margin:0 0 8px;font-size:18px;font-weight:700;">🚴 Auto-assign Riders by Region</h3>
            <p style="margin:0 0 16px;font-size:13px;color:#6b7280;">Assigns the primary rider for each region to matching open orders. Orders with status "out_for_delivery" are never changed.</p>
            <div id="autoAssignMapping" style="background:#f9fafb;border-radius:8px;padding:12px;margin-bottom:16px;font-size:13px;color:#374151;">Loading region → rider mapping...</div>
            <div id="autoAssignResult" style="display:none;background:#ecfdf5;border:1px solid #10b981;border-radius:8px;padding:12px;margin-bottom:16px;font-size:13px;color:#065f46;"></div>
            <div style="display:flex;gap:8px;flex-wrap:wrap;">
                <button onclick="runAutoAssign('unassigned')" id="autoAssignBtn" style="flex:1;padding:10px;background:#4f46e5;color:#fff;border:none;border-radius:8px;cursor:pointer;font-size:14px;font-weight:600;">Assign Unassigned Orders</button>
                <button onclick="runAutoAssign('reassign')" id="autoReassignBtn" style="flex:1;padding:10px;background:#dc2626;color:#fff;border:none;border-radius:8px;cursor:pointer;font-size:14px;font-weight:600;">Reassign ALL Orders</button>
            </div>
            <p style="margin:8px 0 0;font-size:11px;color:#9ca3af;">Reassign ALL will change riders on all orders except "out for delivery".</p>
            <button onclick="document.getElementById('autoAssignRidersModal').style.display='none'" style="position:absolute;top:12px;right:16px;background:none;border:none;font-size:22px;color:#9ca3af;cursor:pointer;">&times;</button>
        </div>`;
        modal.addEventListener('click', (e) => { if (e.target === modal) modal.style.display = 'none'; });
        document.body.appendChild(modal);
    }
    document.getElementById('autoAssignResult').style.display = 'none';
    modal.style.display = 'block';

    // Load the current mapping
    try {
        const [regionsResp, ridersResp] = await Promise.all([
            fetch('/regions/data').then(r => r.json()),
            fetch('/regions/riders').then(r => r.json())
        ]);
        if (regionsResp.success && ridersResp.success) {
            const regionMap = {};
            regionsResp.regions.forEach(r => { regionMap[r.id] = r.name; });
            const assignments = ridersResp.assignments.filter(a => a.is_primary);
            if (assignments.length === 0) {
                document.getElementById('autoAssignMapping').innerHTML = '<span style="color:#dc2626;">No primary rider assignments found. Go to Delivery Regions → Rider Assignments to set them up.</span>';
                document.getElementById('autoAssignBtn').disabled = true;
                document.getElementById('autoReassignBtn').disabled = true;
            } else {
                let html = '<strong style="display:block;margin-bottom:6px;">Region → Rider mapping (primary):</strong>';
                assignments.forEach(a => {
                    html += `<div style="padding:3px 0;"><span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:${a.region_color};margin-right:6px;"></span>${a.region_name} → <strong>${a.rider_name}</strong></div>`;
                });
                document.getElementById('autoAssignMapping').innerHTML = html;
                document.getElementById('autoAssignBtn').disabled = false;
                document.getElementById('autoReassignBtn').disabled = false;
            }
        }
    } catch(e) {
        document.getElementById('autoAssignMapping').innerHTML = 'Error loading mapping';
    }
}

async function runAutoAssign(mode) {
    const msg = mode === 'reassign'
        ? 'This will CHANGE the assigned rider on ALL open orders (except out for delivery) based on region mapping. Continue?'
        : 'This will assign riders to open orders that currently have no rider, based on region mapping. Continue?';
    if (!confirm(msg)) return;

    const btn = document.getElementById(mode === 'reassign' ? 'autoReassignBtn' : 'autoAssignBtn');
    btn.disabled = true; btn.textContent = 'Processing...';
    const result = document.getElementById('autoAssignResult');

    try {
        const d = await (await fetch('/regions/auto-assign-riders', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.content },
            body: JSON.stringify({ mode })
        })).json();
        result.textContent = d.message || 'Done';
        result.style.display = 'block';
        if (typeof applyFilters === 'function') setTimeout(applyFilters, 500);
    } catch(e) {
        result.textContent = 'Error: ' + e.message;
        result.style.display = 'block';
        result.style.background = '#fef2f2';
        result.style.borderColor = '#dc2626';
        result.style.color = '#991b1b';
    } finally {
        btn.disabled = false;
        btn.textContent = mode === 'reassign' ? 'Reassign ALL Orders' : 'Assign Unassigned Orders';
    }
}

// ===== GET CUSTOMER LOCATIONS (bulk WhatsApp location request) =====
window._getLoc = { data: null, chunkSize: 20, sending: false };

function _getLocEsc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
        return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
}

function _getLocStatusPill(n) {
    if (n.status === 'failed') {
        return '<span style="background:#fef2f2;color:#991b1b;border:1px solid #fecaca;padding:1px 7px;border-radius:999px;font-size:11px;">⚠ Failed' + (n.last_sent_human ? ' · ' + _getLocEsc(n.last_sent_human) : '') + '</span>';
    }
    if (n.status === 'awaiting') {
        return '<span style="background:#fffbeb;color:#92400e;border:1px solid #fde68a;padding:1px 7px;border-radius:999px;font-size:11px;">⏳ Sent ' + _getLocEsc(n.last_sent_human || '') + ' · awaiting</span>';
    }
    return '<span style="background:#f3f4f6;color:#374151;border:1px solid #e5e7eb;padding:1px 7px;border-radius:999px;font-size:11px;">Never sent</span>';
}

