// ============================================
// VIEW ORDER TABS: Status vs Full Event Timeline
// ============================================
let _eventTimelineLoaded = false;

function switchViewOrderTab(tab) {
    const statusTab = document.getElementById('viewOrderTabStatus');
    const eventsTab = document.getElementById('viewOrderTabEvents');
    const statusContent = document.getElementById('viewOrderStatusContent');
    const eventsContent = document.getElementById('viewOrderEventsContent');
    
    if (!statusTab || !eventsTab || !statusContent || !eventsContent) return;
    
    if (tab === 'status') {
        statusTab.style.background = '#10b981';
        statusTab.style.color = 'white';
        statusTab.style.fontWeight = '600';
        eventsTab.style.background = '#e5e7eb';
        eventsTab.style.color = '#374151';
        eventsTab.style.fontWeight = '500';
        statusContent.style.display = 'block';
        eventsContent.style.display = 'none';
    } else {
        eventsTab.style.background = '#8b5cf6';
        eventsTab.style.color = 'white';
        eventsTab.style.fontWeight = '600';
        statusTab.style.background = '#e5e7eb';
        statusTab.style.color = '#374151';
        statusTab.style.fontWeight = '500';
        statusContent.style.display = 'none';
        eventsContent.style.display = 'block';
        
        // Load event timeline on first switch
        if (!_eventTimelineLoaded && window._viewOrderId) {
            loadViewOrderEventTimeline(window._viewOrderId);
            _eventTimelineLoaded = true;
        }
    }
}

async function loadViewOrderEventTimeline(orderId) {
    try {
        const container = document.getElementById('viewOrderEventTimeline');
        if (!container) return;
        
        container.innerHTML = '<div style="text-align:center;color:#6b7280;font-size:13px;padding:20px;">Loading full event timeline...</div>';
        
        const response = await fetch(`/orders/${orderId}/event-history`, {
            headers: { 
                'Accept': 'application/json',
                'X-Requested-With': 'XMLHttpRequest' 
            },
            credentials: 'same-origin'
        });
        
        const data = await response.json();
        
        if (data.success && data.events && data.events.length > 0) {
            const timelineHtml = data.events.map((event, index) => {
                const date = new Date(event.timestamp);
                const formattedDate = date.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
                const formattedTime = date.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true });
                
                // Build details HTML
                let detailsHtml = '';
                if (event.details) {
                    detailsHtml = '<div style="margin-top: 6px; background: #fff; padding: 8px 12px; border-radius: 6px; border-left: 3px solid ' + event.color + ';">';
                    for (const [key, value] of Object.entries(event.details)) {
                        detailsHtml += `<div style="font-size: 12px; color: #6b7280;"><span style="font-weight: 500;">${key}:</span> ${value}</div>`;
                    }
                    detailsHtml += '</div>';
                }
                
                return `
                    <div style="display: flex; align-items: start; gap: 14px; margin-bottom: ${index === data.events.length - 1 ? '0' : '16px'};">
                        <div style="width: 32px; height: 32px; border-radius: 50%; background: ${event.color}20; display: flex; align-items: center; justify-content: center; flex-shrink: 0; border: 2px solid ${event.color}; font-size: 14px;">
                            ${event.icon}
                        </div>
                        <div style="flex: 1; min-width: 0;">
                            <div style="font-size: 14px; font-weight: 600; color: #111827; margin-bottom: 2px;">${event.title}</div>
                            <div style="font-size: 13px; color: #6b7280;">${event.description}</div>
                            <div style="font-size: 12px; color: #9ca3af; margin-top: 4px;">${formattedDate} at ${formattedTime}</div>
                            ${detailsHtml}
                        </div>
                    </div>
                `;
            }).join('');
            
            container.innerHTML = timelineHtml;
        } else {
            container.innerHTML = '<div style="text-align:center;color:#6b7280;font-size:14px;padding:30px;">No event history available</div>';
        }
    } catch (error) {
        console.error('Failed to load event timeline:', error);
        const container = document.getElementById('viewOrderEventTimeline');
        if (container) {
            container.innerHTML = '<div style="text-align:center;color:#ef4444;font-size:14px;padding:30px;">Failed to load event timeline</div>';
        }
    }
}

// ============================================================================
// Per-order ACTIVITY LOG (Phase 2 L1) — "who changed what" from t_sys_audit_log.
// Rendered in the Edit Invoice pop-out's collapsible "Activity Log" section.
// All names are nf-prefixed to avoid collisions in this large file.
// ============================================================================
function nfEsc(s){ var d = document.createElement('div'); d.textContent = (s == null ? '' : String(s)); return d.innerHTML; }

function toggleActivityLog() {
    var wrap = document.getElementById('editOrderActivityWrapper');
    var btn = document.getElementById('toggleActivityLogBtn');
    if (!wrap) return;
    var showing = wrap.style.display !== 'none';
    wrap.style.display = showing ? 'none' : 'block';
    if (btn) btn.innerHTML = '<span id="toggleActivityLogIcon">' + (showing ? '▼' : '▲') + '</span> ' + (showing ? 'Show' : 'Hide');
}

async function loadEditOrderActivityLog(orderId) {
    var el = document.getElementById('editOrderActivityLog');
    if (!el || !orderId) return;
    try {
        var res = await fetch('/orders/' + orderId + '/activity-log', {
            headers: { 'Accept': 'application/json', 'X-Requested-With': 'XMLHttpRequest' },
            credentials: 'same-origin'
        });
        var data = await res.json();
        nfRenderActivityLog(el, data);
    } catch (e) {
        el.innerHTML = '<div style="text-align:center;color:#ef4444;font-size:13px;padding:20px;">Failed to load activity log</div>';
    }
}

function nfRenderActivityLog(el, data) {
    if (!el) return;
    var entries = (data && data.entries) || [];
    if (data && data.ready === false) {
        el.innerHTML = '<div style="text-align:center;color:#9ca3af;font-size:12.5px;padding:18px;">Activity logging is being set up — changes made from now on will appear here.</div>';
        return;
    }
    if (entries.length === 0) {
        el.innerHTML = '<div style="text-align:center;color:#9ca3af;font-size:12.5px;padding:18px;">No edits or payments recorded for this order yet.</div>';
        return;
    }
    el.innerHTML = entries.map(nfActivityRowHtml).join('');
}

function nfActivityFieldLabel(f) {
    var m = { payment_method:'Payment method', total_price:'Total', discount_total:'Discount',
        assigned_rider_user_id:'Rider', customer_id:'Customer', name:'Name', address_line1:'Address',
        address_city:'City', address_phone:'Phone', amount:'Amount', order_status:'Status', order_number:'Order #' };
    return m[f] || String(f).replace(/_/g, ' ').replace(/\b\w/g, function(c){ return c.toUpperCase(); });
}
function nfActivityFieldVal(f, v) {
    if (v === null || v === undefined || v === '') return '<span style="color:#9ca3af;">—</span>';
    if (f === 'total_price' || f === 'discount_total' || f === 'amount') {
        var n = Number(v); return isNaN(n) ? nfEsc(v) : ('Rs ' + n.toLocaleString('en-PK'));
    }
    return nfEsc(v);
}
function nfActivityRowHtml(e) {
    var map = {
        updated: ['✏️', 'Order edited', '#6b7280'],
        deleted: ['🗑️', 'Order deleted', '#ef4444'],
        created: ['📦', 'Created', '#3b82f6'],
        payment_recorded: ['💰', 'Payment recorded', '#10b981'],
        payment_voided: ['↩️', 'Payment voided', '#ef4444'],
        payment_deleted: ['↩️', 'Payment removed', '#ef4444'],
        // Acceptance messaging decision (Aug-2026). Amber, not grey: "the customer
        // was never told" is the thing you want to catch while scanning this list.
        accepted_no_message: ['🔕', 'Accepted — no message sent', '#f59e0b'],
        accepted_with_message: ['📩', 'Accepted — confirmation sent', '#10b981'],
        accepted_message_failed: ['⚠️', 'Accepted — confirmation FAILED to send', '#ef4444']
    };
    var m = map[e.action];
    if (!m) {
        if (/ledger/i.test(e.entity || '')) m = ['🏦', 'Ledger ' + String(e.action || '').replace(/_/g, ' '), '#8b5cf6'];
        else m = ['📝', String(e.action || 'change').replace(/_/g, ' '), '#6b7280'];
    }
    var d = new Date(String(e.at || '').replace(' ', 'T'));
    var when = isNaN(d.getTime()) ? (e.at || '')
        : (d.toLocaleDateString('en-GB', { day:'2-digit', month:'short', year:'numeric' }) + ' · ' + d.toLocaleTimeString('en-US', { hour:'2-digit', minute:'2-digit', hour12:true }));
    var srcColors = { web:['#eff6ff','#1d4ed8'], mobile:['#f0fdf4','#15803d'], customer_app:['#fef3c7','#92400e'], system:['#f3f4f6','#6b7280'] };
    var sc = srcColors[e.source] || ['#f3f4f6','#6b7280'];
    var srcBadge = e.source ? '<span style="font-size:10px;font-weight:600;padding:1px 6px;border-radius:999px;background:' + sc[0] + ';color:' + sc[1] + ';text-transform:capitalize;">' + nfEsc(String(e.source).replace('_',' ')) + '</span>' : '';
    var diffs = '';
    if (e.changes && typeof e.changes === 'object') {
        diffs = Object.keys(e.changes).map(function(f) {
            var c = e.changes[f] || {};
            return '<div style="font-size:12px;color:#4b5563;margin-top:2px;"><span style="font-weight:600;">' + nfEsc(nfActivityFieldLabel(f)) + ':</span> '
                + nfActivityFieldVal(f, c.old) + ' <span style="color:#9ca3af;">→</span> ' + nfActivityFieldVal(f, c.new) + '</div>';
        }).join('');
    }
    var note = e.note ? '<div style="font-size:12px;color:#6b7280;font-style:italic;margin-top:2px;">' + nfEsc(e.note) + '</div>' : '';
    return '<div style="display:flex;gap:12px;padding:10px 0;border-bottom:1px solid #f1f5f9;">'
        + '<div style="width:28px;height:28px;border-radius:50%;flex-shrink:0;display:flex;align-items:center;justify-content:center;background:' + m[2] + '1a;border:1.5px solid ' + m[2] + ';font-size:13px;">' + m[0] + '</div>'
        + '<div style="flex:1;min-width:0;">'
        + '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;"><span style="font-size:13.5px;font-weight:600;color:#111827;">' + nfEsc(m[1]) + '</span>' + srcBadge + '</div>'
        + '<div style="font-size:12px;color:#6b7280;">by ' + nfEsc(e.user || '—') + ' · ' + nfEsc(when) + '</div>'
        + diffs + note
        + '</div></div>';
}

// Quick Status Change Modal
function openQuickStatusChange(orderId, currentStatus) {
    console.log('Opening quick status change for order ID:', orderId, 'Current status:', currentStatus); // Debug log
    // Build a simple modal lazily
    let modal = document.getElementById('quickStatusModal');
    if (!modal) {
        modal = document.createElement('div');
        modal.id = 'quickStatusModal';
        modal.style.cssText = 'position:fixed;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.5);z-index:10200;';
        modal.innerHTML = `<div style="background:#fff;border-radius:10px;min-width:420px;max-width:520px;padding:16px;border:1px solid #e5e7eb;">
            <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;">
                <h3 style="margin:0;font-weight:600;color:#111827;font-size:16px;">Change Status</h3>
                <button onclick="document.getElementById('quickStatusModal').remove()" style="background:none;border:0;font-size:20px;color:#6b7280;cursor:pointer">×</button>
            </div>
            <div style="display:flex;gap:16px;">
                <div style="flex:1;display:flex;flex-direction:column;gap:12px;">
                    <select id="quickStatusSelect" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;"></select>
                    <textarea id="quickStatusNotes" placeholder="Reason (optional)" style="width:100%;min-height:70px;padding:8px;border:1px solid #d1d5db;border-radius:6px;"></textarea>
                    <div style="display:flex;gap:8px;justify-content:flex-end;">
                        <button onclick="document.getElementById('quickStatusModal').remove()" style="padding:8px 12px;border:1px solid #d1d5db;background:#fff;border-radius:6px;cursor:pointer;">Cancel</button>
                        <button id="quickStatusSave" style="padding:8px 12px;background:#2563eb;color:#fff;border:0;border-radius:6px;cursor:pointer;">Save</button>
                    </div>
                </div>
                <div style="flex:1;border-left:1px solid #e5e7eb;padding-left:16px;">
                    <h4 style="margin:0 0 8px 0;font-size:14px;font-weight:600;color:#374151;">Recent Changes</h4>
                    <div id="quickStatusTimeline" style="max-height:140px;overflow-y:auto;">
                        <div style="text-align:center;color:#6b7280;font-size:13px;padding:20px;">Loading timeline...</div>
                    </div>
                </div>
            </div>
        </div>`;
        document.body.appendChild(modal);
    }
    // Load statuses and preselect
    (async function(){
        try {
            const resp = await fetch('/order-status/api/statuses', { headers: { 'Accept': 'application/json','X-Requested-With':'XMLHttpRequest' }, credentials:'same-origin' });
            const data = await resp.json();
            const sel = document.getElementById('quickStatusSelect');
            if (sel) {
                sel.innerHTML = data.success ? data.data.map(s=>`<option value="${s.status_code}">${s.icon} ${s.status_name}</option>`).join('') : '';
                sel.value = currentStatus || 'new';
                // Status Hub: if the order's current status isn't in the picker (a legacy/retired
                // status like 'completed'), insert it selected so the dropdown doesn't silently
                // fall back to the first option and a blind Save can't demote the order.
                if (currentStatus && sel.value !== currentStatus) {
                    const opt = document.createElement('option');
                    opt.value = currentStatus;
                    opt.textContent = currentStatus.replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase()) + ' (legacy)';
                    sel.insertBefore(opt, sel.firstChild);
                    sel.value = currentStatus;
                }
            }
            
            // Load timeline
            loadQuickStatusTimeline(orderId);
            const btn = document.getElementById('quickStatusSave');
            
            // Helper function to actually change the status
            const changeStatus = async function(confirmed = false, bringBack = undefined, creditStranded = undefined) {
                try {
                const status_code = document.getElementById('quickStatusSelect').value;
                const notes = document.getElementById('quickStatusNotes').value;

                    // BRING-BACK: if this move takes the order back across the "out the door" line
                    // (was auto-prepared, now going to a status that counts in Quantities), ask the
                    // operator whether to return its items to the "to prepare" queue. Only asked once.
                    if (bringBack === undefined) {
                        const list = (data && data.data) || [];
                        const byCode = c => list.find(s => s.status_code === c);
                        const fromS = byCode(currentStatus), toS = byCode(status_code);
                        const toCounts = toS && !(toS.counts_in_quantities === false || toS.counts_in_quantities === 0);
                        if (fromS && toS && fromS.auto_prepares && !toS.auto_prepares && toCounts) {
                            bringBack = confirm(
                                'This order was dispatched, so its items are marked prepared.\n\n' +
                                'Bring them back to the "to prepare" list?\n\n' +
                                'OK = bring back (returns items to the queue + restores stock)\n' +
                                'Cancel = keep them prepared'
                            );
                        }
                    }

                    const payload = {
                        order_id: orderId,
                        status_code,
                        notes
                    };

                    // Add confirmation flag if this is a retry after confirmation
                    if (confirmed) {
                        payload.confirmed = true;
                    }
                    if (bringBack === true) {
                        payload.bring_back = true;
                    }
                    // Cancellation: the manager's answer to "move the money we
                    // already received to this customer's balance?". Only ever
                    // sent when they were actually asked.
                    if (creditStranded !== undefined) {
                        payload.credit_stranded_payment = creditStranded === true;
                    }

                    btn.textContent = 'Saving...';
                    btn.disabled = true;
                    
                const res = await fetch('/order-status/api/change-status', {
                    method:'POST',
                        headers:{ 
                            'Accept':'application/json',
                            'Content-Type':'application/json',
                            'X-Requested-With':'XMLHttpRequest',
                            'X-CSRF-TOKEN':document.querySelector('meta[name=\'csrf-token\']').getAttribute('content') 
                        },
                    credentials:'same-origin',
                        body: JSON.stringify(payload)
                });
                const j = await res.json();

                    // RETURNS (Sep-2026): "Returned" picked from this list on a delivered
                    // order that has NO invoice (auto-post off) — the only delivered case
                    // that reaches this picker. The server refuses and names the form;
                    // open it here so the picker is a door, not a dead end.
                    if (!j.success && j.error_type === 'use_return_form' && typeof window.nfOpenReturnForm === 'function') {
                        document.getElementById('quickStatusModal')?.remove();
                        window.nfOpenReturnForm(orderId);
                        return;
                    }

                    // Check if confirmation is required (ledger will be reversed)
                    if (!j.success && j.requires_confirmation && j.confirmation_data) {
                        const data = j.confirmation_data;
                        const stranded = data.stranded || {};
                        const strandedAmt = parseFloat(stranded.amount || 0);
                        const creditApplied = parseFloat(data.credit_applied || 0);

                        let confirmMsg;
                        if (data.ledger_id && data.account_name) {
                            confirmMsg =
                                `⚠️ LEDGER REVERSAL REQUIRED\n\n` +
                                `This order has been posted to the ledger.\n` +
                                `Cancelling will reverse the ledger entry.\n\n` +
                                `Order: ${data.order_number}\n` +
                                `Amount: Rs. ${parseFloat(data.amount).toFixed(2)}\n` +
                                `Posted to: ${data.account_name}\n` +
                                `Mode: ${data.ledger_mode === 'cash' ? 'Cash' : 'Online'}\n\n` +
                                `The ledger entry will be reversed and account balances will be updated.\n\n`;
                        } else {
                            confirmMsg =
                                `⚠️ THIS ORDER HAS PAYMENTS RECORDED\n\n` +
                                `Order: ${data.order_number}\n` +
                                `Amount: Rs. ${parseFloat(data.amount).toFixed(2)}\n\n`;
                        }

                        if (creditApplied > 0) {
                            confirmMsg += `Rs. ${creditApplied.toFixed(2)} of account balance was used on this ` +
                                          `order — it will be returned to the customer automatically.\n\n`;
                        }
                        if (strandedAmt > 0) {
                            confirmMsg += `Rs. ${strandedAmt.toFixed(2)} already received stays in our account.\n\n`;
                        }

                        confirmMsg += `Do you want to proceed with cancellation?`;

                        btn.textContent = 'Save';
                        btn.disabled = false;

                        if (!confirm(confirmMsg)) {
                            return;
                        }

                        // Second, separate question — never assumed either way.
                        let creditChoice = undefined;
                        if (strandedAmt > 0 && stranded.can_credit) {
                            creditChoice = confirm(
                                `Rs. ${strandedAmt.toFixed(2)} was already received for this order.\n\n` +
                                `Add it to ${stranded.customer_name || 'the customer'}'s account balance so it ` +
                                `can pay for a future order?\n\n` +
                                `OK = add to their balance\n` +
                                `Cancel = leave it as it is`
                            );
                        } else if (strandedAmt > 0 && stranded.reason) {
                            alert(`Note: Rs. ${strandedAmt.toFixed(2)} was received on this order, but it cannot ` +
                                  `become an account balance.\n\n${stranded.reason}`);
                        }

                        await changeStatus(true, bringBack, creditChoice);
                        return;
                    }
                    
                    // Check for other errors
                if (j && j.success) {
                    // Tell the user what happened to the customer's money rather
                    // than leaving it to the log.
                    const notes = [];
                    if (j.credit_released) {
                        notes.push(`Rs. ${parseFloat(j.credit_released).toFixed(2)} of account balance was returned to the customer.`);
                    }
                    if (j.credited_to_balance) {
                        notes.push(j.credited_status === 'active'
                            ? `Rs. ${parseFloat(j.credited_to_balance).toFixed(2)} was added to the customer's balance.`
                            : `Rs. ${parseFloat(j.credited_to_balance).toFixed(2)} was sent for approval to be added to the customer's balance.`);
                    }
                    if (notes.length) { alert(notes.join('\n\n')); }

                    document.getElementById('quickStatusModal').remove();
                    location.reload();
                } else {
                    alert(j.message || 'Failed to change status');
                        btn.textContent = 'Save';
                        btn.disabled = false;
                    }
                } catch(e) {
                    console.error('Status change failed:', e);
                    alert('Failed to change status: ' + e.message);
                    btn.textContent = 'Save';
                    btn.disabled = false;
                }
            };
            
            btn.onclick = async function(){
                await changeStatus(false);
            };
        } catch(e) {
            console.warn('Quick status fetch failed', e);
        }
    })();
}
// ⭐ Concurrency guard (barcode-qty): before saving an existing order, re-fetch it and
// detect line-item quantities changed (e.g. by a mobile barcode scan) since this page
// loaded. Two cases:
//   • "scan won"  — the DB qty changed but the user did NOT touch that line here:
//                   adopt the scanned value into the form (so we don't overwrite it)
//                   and show a NON-blocking heads-up.
//   • "conflict"  — the user changed the SAME line a scan changed: BLOCK and offer reload.
// Returns 'proceed' or 'blocked'. On any fetch trouble it returns 'proceed' (the backend
// optimistic guard is the safety net).
async function concurrencyGate(orderId) {
    if (!orderId) return 'proceed';
    let fresh;
    try {
        const resp = await fetch(ordersDetailUrl(orderId), {
            method: 'GET',
            headers: {'Accept': 'application/json', 'Content-Type': 'application/json', 'X-Requested-With': 'XMLHttpRequest'}
        });
        fresh = await resp.json();
    } catch (e) {
        return 'proceed';
    }
    if (!fresh || !fresh.success || !fresh.order) return 'proceed';
    const dbItems = fresh.lineItems || (fresh.order && fresh.order.line_items) || [];
    const dbById = {};
    dbItems.forEach(li => { dbById[String(li.id)] = li; });
    // Sync the load timestamp to the freshest value so the save's optimistic check passes
    // for everything we've now seen; only a change AFTER this point will 409.
    window.editOrderLoadedUpdatedAt = (fresh.order.updated_at) || window.editOrderLoadedUpdatedAt;

    const conflicts = [];
    const scanWon = [];
    document.querySelectorAll('.line-item').forEach((row) => {
        const idInput = row.querySelector('input[name*="[id]"]');
        const id = idInput ? String(idInput.value || '') : '';
        if (!id) return; // newly-added line, nothing to compare
        const qtyInput = row.querySelector('input[name*="[quantity]"]');
        if (!qtyInput) return;
        const db = dbById[id];
        if (!db) return; // line removed in DB elsewhere — let the normal save handle it
        const loaded = parseFloat(qtyInput.getAttribute('data-db-original-value'));
        const current = parseFloat(qtyInput.value);
        const dbQty = parseFloat(db.quantity);
        if (isNaN(loaded) || isNaN(dbQty)) return;
        if (Math.abs(dbQty - loaded) <= 0.0005) return; // DB unchanged since load
        const userChanged = !isNaN(current) && Math.abs(current - loaded) > 0.0005;
        const name = db.product_name || db.name || row.getAttribute('data-product-name') || 'item';
        if (userChanged && Math.abs(current - dbQty) > 0.0005) {
            conflicts.push({name, yours: current, scanned: dbQty});
        } else if (!userChanged) {
            // scan won — adopt the scanned value so the save keeps it (not the stale value)
            qtyInput.value = dbQty;
            qtyInput.setAttribute('data-db-original-value', String(dbQty));
            try { updateLineTotal(parseInt(row.getAttribute('data-index'))); } catch (e) {}
            scanWon.push({name, scanned: dbQty});
        }
    });

    if (conflicts.length) {
        const lines = conflicts.map(c => `• ${c.name}: you set ${c.yours}, scanned ${c.scanned}`).join('\n');
        const reload = confirm(`⚠️ These items were changed since you opened this page (e.g. by a barcode scan), and you also edited them here:\n\n${lines}\n\nYour edits can't be saved over the newer values. Reload to see the latest, then redo your changes?`);
        if (reload) { editOrderDetails(orderId); }
        return 'blocked';
    }
    if (scanWon.length) {
        const lines = scanWon.map(s => `• ${s.name} → ${s.scanned} kg`).join('\n');
        const go = confirm(`ℹ️ These quantities were updated since you opened this page (e.g. by a barcode scan):\n\n${lines}\n\nThe newer values will be kept (your other changes will still be saved).\n\nContinue saving?`);
        if (!go) return 'blocked';
    }
    return 'proceed';
}

async function saveOrderChanges(orderId) {
    const form = document.getElementById('editOrderForm');
    const formData = new FormData(form);
    const submitBtn = form.querySelector('button[type="submit"]');
    
    // Validate customer information if creating new order
    if (!orderId) {
        const existingSection = document.getElementById('existingCustomerSection');
        const newSection = document.getElementById('newCustomerSection');
        
        // Check which mode is active by looking at display style
        const isExistingMode = existingSection && (existingSection.style.display === 'block' || existingSection.style.display === '');
        const isNewMode = newSection && (newSection.style.display === 'block' || newSection.style.display === '');
        
        console.log('Validation check:', { isExistingMode, isNewMode });
        
        if (isExistingMode) {
            // Existing customer mode - must have selected a customer
            const customerId = document.getElementById('selectedCustomerId')?.value;
            if (!customerId || customerId === '') {
                alert('Please select an existing customer or switch to "New Customer" mode to create a new one.');
                return;
            }
        } else if (isNewMode) {
            // New customer mode - validate required fields
            const firstName = form.querySelector('input[name="customer_first_name"]')?.value?.trim();
            const lastName = form.querySelector('input[name="customer_last_name"]')?.value?.trim();
            const phone = form.querySelector('input[name="customer_phone"]')?.value?.trim();
            const address1 = form.querySelector('input[name="customer_address1"]')?.value?.trim();
            
            if (!firstName) {
                alert('First Name is required for new customer');
                form.querySelector('input[name="customer_first_name"]')?.focus();
                return;
            }
            if (!lastName) {
                alert('Last Name is required for new customer');
                form.querySelector('input[name="customer_last_name"]')?.focus();
                return;
            }
            if (!phone) {
                alert('Phone Number is required for new customer');
                form.querySelector('input[name="customer_phone"]')?.focus();
                return;
            }
            if (!address1) {
                alert('Address Line 1 is required for new customer');
                form.querySelector('input[name="customer_address1"]')?.focus();
                return;
            }
        } else {
            // Neither mode is visible - shouldn't happen, but handle gracefully
            alert('Please select customer information');
            return;
        }
    }
    
    if (submitBtn) {
    submitBtn.textContent = 'Saving...';
    submitBtn.disabled = true;
    }

    // ⭐ Concurrency guard for existing orders — keep any quantity changed by a barcode
    // scan since this page loaded (and block true conflicts) before we overwrite anything.
    if (orderId) {
        const gate = await concurrencyGate(orderId);
        if (gate === 'blocked') {
            if (submitBtn) { submitBtn.textContent = 'Save'; submitBtn.disabled = false; }
            return;
        }
    }

    // Collect line items (including per-item qurbani fields)
    const items = [];
    document.querySelectorAll('.line-item').forEach((item) => {
        const name = item.querySelector('input[name*="[name]"]')?.value;
        const quantity = parseFloat(item.querySelector('input[name*="[quantity]"]')?.value) || 0;
        const unitPrice = parseFloat(item.querySelector('input[name*="[unit_price]"]')?.value) || 0;
        const sku = item.querySelector('input[name*="[sku]"]')?.value || null;
        const variantId = item.querySelector('input[name*="[variant_id]"]')?.value || null;
        const productId = item.querySelector('input[name*="[product_id]"]')?.value || null;
        const isFreeInput = item.querySelector('.is-free-input');
        const isFree = isFreeInput && isFreeInput.value === '1';
        
        if (name && quantity > 0 && unitPrice >= 0) {
            var itemObj = {
                name: name,
                quantity: quantity,
                unit_price: unitPrice,
                line_total: isFree ? 0 : quantity * unitPrice,
                is_free: isFree ? 1 : 0,
                sku: sku,
                variant_id: variantId,
                product_id: productId
            };
            // Per-item qurbani fields. NOTE: qurbani_type and qurbani_paya
            // use suffix-anchored ([name$=...]) selectors because "name*"
            // would also match "qurbani_delivery_type" (substring hit).
            var qDay = item.querySelector('select[name*="qurbani_day"]')?.value;
            var qSlot = item.querySelector('select[name*="qurbani_slot"]')?.value;
            var qRegion = item.querySelector('select[name*="qurbani_region"]')?.value;
            var qSubRegion = item.querySelector('select[name*="qurbani_sub_region"]')?.value;
            var qDT = item.querySelector('select[name*="qurbani_delivery_type"]')?.value;
            var qType = item.querySelector('select[name$="[qurbani_type]"]')?.value;
            var qPaya = item.querySelector('select[name$="[qurbani_paya]"]')?.value;
            if (qDay) itemObj.qurbani_day = qDay;
            if (qSlot) itemObj.qurbani_slot = qSlot;
            if (qRegion) itemObj.qurbani_region = qRegion;
            if (qSubRegion) itemObj.qurbani_sub_region = qSubRegion;
            if (qDT) itemObj.qurbani_delivery_type = qDT;
            if (qType) itemObj.qurbani_type = qType;
            if (qPaya) itemObj.qurbani_paya = qPaya;
            var instr = item.querySelector('input[name*="instructions"]')?.value;
            itemObj.instructions = instr || '';
            items.push(itemObj);
        }
    });
    
    // Collect discounts
    const discounts = [];
    document.querySelectorAll('.discount-row').forEach((row) => {
        const title = row.querySelector('[name$="[title]"]')?.value || '';
        const amount = parseFloat(row.querySelector('[name$="[amount]"]')?.value) || 0;
        
        // ⭐ Allow discounts with just amount - default title to "Discount" if empty
        if (amount > 0) {
            discounts.push({
                title: title.trim() || 'Discount',
                amount: amount,
                type: 'fixed'
            });
        }
    });
    
    // Prepare data for update (matching the existing update endpoint structure)
    const rawOrderDate = formData.get('order_date');
    const formattedOrderDate = rawOrderDate ? rawOrderDate.replace('T', ' ') + ':00' : getCurrentLocalDateTime().replace('T', ' ') + ':00';
    
    // ================================================================
    // POP-OUT MODE: PARTIAL UPDATE
    // ================================================================
    // In pop-out mode, we ONLY send line items, totals, discounts, tips, notes, and order date
    // We do NOT send: order_status, expected_packets, payment_method, customer info, rider, address
    // This prevents long-running pop-out windows from overwriting changes made via mobile app
    const isPopoutMode = window.isPopoutMode === true;
    
    // Debug: Log pop-out mode status
    console.log('🔍 Save check - isPopoutMode:', isPopoutMode, 'orderId:', orderId, 'window.isPopoutMode:', window.isPopoutMode);
    
    let orderData;
    
    if (isPopoutMode) {
        // POP-OUT MODE: Invoice/line item data + customer (safe to change in pop-out)
        console.log('📋 Pop-out mode detected - sending partial update (line items + totals + customer)');
        orderData = {
            order_date: formattedOrderDate,
            subtotal_price: parseFloat(formData.get('subtotal_price')) || 0,
            shipping_total: parseFloat(formData.get('shipping_total')) || 0,
            tip_amount: parseFloat(formData.get('tip_amount')) || 0,
            total_price: parseFloat(formData.get('total_price')) || 0,
            note: formData.get('note'),
            items: items,
            discounts: discounts,
            customer_id: formData.get('customer_id'),
            name: formData.get('name'),
            
            // ❌ NOT INCLUDED (managed via mobile/quick actions):
            // - order_status (set via mobile Store/Rider mode)
            // - expected_packets (set via mobile Store mode)
            // - payment_method (set via mobile or dedicated button)
            // - assigned_rider_user_id (set via mobile Store mode or web quick action)
            
            _partial_update: true,
            _popout_mode: true
        };
    } else {
        // REGULAR MODE: Full update with all fields
        orderData = {
            customer_id: formData.get('customer_id'), // ✅ CRITICAL: Include customer_id for linking
            order_status: formData.get('order_status'),
            // Stale-status guard (Jul-2026): what the dropdown showed when the form
            // OPENED. Backend rule: dropdown untouched -> keep the DB's current
            // status (a status advanced on mobile while this form sat open is never
            // reverted); dropdown deliberately changed -> proper changeStatus()
            // pipeline (history + webhook + ledger + inventory).
            _loaded_status: (document.getElementById('editOrderStatus')?.dataset?.loadedStatus) || null,
            order_date: formattedOrderDate,
            contact_email: formData.get('contact_email'),
            subtotal_price: parseFloat(formData.get('subtotal_price')) || 0,
            shipping_total: parseFloat(formData.get('shipping_total')) || 0,
            tip_amount: parseFloat(formData.get('tip_amount')) || 0,
            total_price: parseFloat(formData.get('total_price')) || 0,
            payment_method: formData.get('payment_method'),
            note: formData.get('note'),
            expected_packets: formData.get('expected_packets') ? parseInt(formData.get('expected_packets')) : null, // Packet tracking
            items: items,
            discounts: discounts,
            // ⭐ Order's name field - stores customer display name directly on order
            // This must be updated when customer is changed to keep order list/modal in sync
            name: formData.get('name'),
            // Address fields
            address_first_name: formData.get('address_first_name'),
            address_last_name: formData.get('address_last_name'),
            address_email: formData.get('address_email'),
            address_phone: formData.get('address_phone'),
            address_line1: formData.get('address_line1'),
            address_line2: formData.get('address_line2'),
            address_city: formData.get('address_city'),
            address_country: formData.get('address_country'),
            // ⭐ Sync address to customer profile checkbox
            sync_to_customer: formData.get('sync_to_customer') === '1' ? true : false,
        };
    }
    
    // ================================================================
    // LEDGER ADJUSTMENT CONFIRMATION
    // ================================================================
    // Debug: Log order data
    console.log('📦 Order Data Being Sent:', {
        customer_id: orderData.customer_id,
        order_status: orderData.order_status,
        total_price: orderData.total_price
    });
    console.log('🔍 Ledger Adjustment Check:', {
        hasCurrentOrder: !!window.currentOrder,
        ledger_transaction_id: window.currentOrder?.ledger_transaction_id,
        order_status: window.currentOrder?.order_status,
        oldTotal: window.currentOrder?.total_price,
        newTotal: orderData.total_price
    });
    
    // Check if order is delivered and has ledger entry, and if price changed
    if (window.currentOrder && window.currentOrder.ledger_transaction_id && window.currentOrder.order_status === 'delivered') {
        const oldTotal = parseFloat(window.currentOrder.total_price) || 0;
        const newTotal = orderData.total_price;
        
        console.log('✅ Ledger adjustment conditions met - checking price difference');
        
        // Check if there's a significant change (more than 1 cent to account for floating point)
        if (Math.abs(oldTotal - newTotal) > 0.01) {
            const difference = newTotal - oldTotal;
            const confirmed = confirm(
                `⚠️ LEDGER ADJUSTMENT REQUIRED\n\n` +
                `This order has already been posted to the ledger.\n\n` +
                `Old Amount: Rs. ${oldTotal.toFixed(2)}\n` +
                `New Amount: Rs. ${newTotal.toFixed(2)}\n` +
                `Difference: ${difference >= 0 ? '+' : ''}Rs. ${difference.toFixed(2)}\n\n` +
                `The ledger adjustment will be sent for L1→L2 approval.\n` +
                `The order will be updated immediately, but the ledger will only be updated after approval.\n\n` +
                `Do you want to proceed?`
            );
            
            if (!confirmed) {
                submitBtn.textContent = 'Save';
                submitBtn.disabled = false;
                return; // Cancel the save
            }
        }
    }
    
    // Determine endpoint and method based on whether this is a create or update
    const isNewOrder = !orderId;
    const endpoint = isNewOrder ? '/orders' : `/orders/${orderId}`;
    const method = isNewOrder ? 'POST' : 'PUT';
    
    // For new orders, always include customer_id and customer creation fields
    if (isNewOrder) {
        orderData.customer_id = formData.get('customer_id');
        orderData.order_status = formData.get('order_status');
        orderData.contact_email = formData.get('contact_email');
        orderData.payment_method = formData.get('payment_method');
        // Aug-2026 — "Set as default for this customer" tick beside the payment
        // picker. Create-only on purpose: editing an existing order must not
        // silently rewrite the customer's standing preference.
        orderData.set_default_payment_method = formData.get('set_default_payment_method') ? 1 : 0;
        orderData.customer_phone = formData.get('customer_phone');
        orderData.customer_first_name = formData.get('customer_first_name');
        orderData.customer_last_name = formData.get('customer_last_name');
        orderData.customer_company = formData.get('customer_company');
        orderData.customer_address1 = formData.get('customer_address1');
        orderData.customer_address2 = formData.get('customer_address2');
        orderData.customer_city = formData.get('customer_city');
        orderData.customer_notes = formData.get('customer_notes');
    }
    
    // ⭐ Optimistic concurrency: tell the backend which order version this form is based on.
    if (!isNewOrder) { orderData.expected_updated_at = window.editOrderLoadedUpdatedAt || null; }

    // Submit to appropriate endpoint
    fetch(endpoint, {
        method: method,
        headers: {
            'Content-Type': 'application/json',
            'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').getAttribute('content'),
            'Accept': 'application/json'
        },
        body: JSON.stringify(orderData)
    })
    .then(response => response.json())
    .then(data => {
        if (data.success) {
            if (isNewOrder) {
                // Show success and reload page to see new order
                showSuccessMessage('Order created successfully!');
                setTimeout(() => {
                    closeModal('editOrderModal');
                    location.reload();
                }, 1000);
            } else {
                // Show appropriate message based on whether adjustment was created
                if (data.requires_approval) {
                    showSuccessMessage(data.message + ' (Adjustment ID: #' + data.adjustment_id + ')');
                } else {
                    showSuccessMessage(data.message || 'Order updated successfully!');
                }
                // ⚠ The save succeeded but the STATUS CHANGE did not — an order on
                //   the van needs the handover scan, an invoice failed to post, or
                //   the transition was refused. This used to be swallowed by a
                //   hard-coded "Order updated successfully!", so staff believed a
                //   status change had happened when it had not. A toast is too easy
                //   to miss for something the user explicitly asked for.
                if (data.status_warning) {
                    alert('⚠️ ' + data.status_warning);
                }
                submitBtn.textContent = 'Save';
                submitBtn.disabled = false;
                // Keep modal open for regular save - no page reload
            }
        } else {
            alert('Error ' + (isNewOrder ? 'creating' : 'updating') + ' order: ' + (data.message || 'Unknown error'));
            submitBtn.textContent = 'Save';
            submitBtn.disabled = false;
        }
    })
    .catch(error => {
        console.error('Error ' + (isNewOrder ? 'creating' : 'updating') + ' order:', error);
        alert('Error ' + (isNewOrder ? 'creating' : 'updating') + ' order. Please try again.');
        submitBtn.textContent = 'Save Changes';
        submitBtn.disabled = false;
    });
}
async function saveAndCloseOrder(orderId) {
