                unit_price: unitPrice,
                line_total: isFree ? 0 : quantity * unitPrice,
                is_free: isFree ? 1 : 0,
                sku: sku,
                variant_id: variantId,
                product_id: productId
            };
            var qDay = item.querySelector('select[name*="qurbani_day"]')?.value;
            var qSlot = item.querySelector('select[name*="qurbani_slot"]')?.value;
            var qRegion = item.querySelector('select[name*="qurbani_region"]')?.value;
            var qSubRegion = item.querySelector('select[name*="qurbani_sub_region"]')?.value;
            var qDT = item.querySelector('select[name*="qurbani_delivery_type"]')?.value;
            // Suffix-anchored selectors — see note in saveOrderChanges.
            var qType = item.querySelector('select[name$="[qurbani_type]"]')?.value;
            var qPaya = item.querySelector('select[name$="[qurbani_paya]"]')?.value;
            if (qDay) itemObj.qurbani_day = qDay;
            if (qSlot) itemObj.qurbani_slot = qSlot;
            if (qRegion) itemObj.qurbani_region = qRegion;
            if (qSubRegion) itemObj.qurbani_sub_region = qSubRegion;
            if (qDT) itemObj.qurbani_delivery_type = qDT;
            if (qType) itemObj.qurbani_type = qType;
            if (qPaya) itemObj.qurbani_paya = qPaya;
            var instr = item.querySelector('input[name*="instructions"]')?.value;
            itemObj.instructions = instr || '';
            items.push(itemObj);
        }
    });
    
    // Collect discounts (same as saveOrderChanges)
    const discounts = [];
    document.querySelectorAll('.discount-row').forEach((row) => {
        const title = row.querySelector('[name$="[title]"]')?.value || '';
        const amount = parseFloat(row.querySelector('[name$="[amount]"]')?.value) || 0;
        
        // ⭐ Allow discounts with just amount - default title to "Discount" if empty
        if (amount > 0) {
            discounts.push({
                title: title.trim() || 'Discount',
                amount: amount,
                type: 'fixed'
            });
        }
    });
    
    // Prepare data for update (same as saveOrderChanges)
    const rawOrderDate = formData.get('order_date');
    const formattedOrderDate = rawOrderDate ? rawOrderDate.replace('T', ' ') + ':00' : getCurrentLocalDateTime().replace('T', ' ') + ':00';
    
    // ================================================================
    // POP-OUT MODE: PARTIAL UPDATE (same as saveOrderChanges)
    // ================================================================
    const isPopoutMode = window.isPopoutMode === true;
    
    // Debug: Log pop-out mode status
    console.log('🔍 Save & Close check - isPopoutMode:', isPopoutMode, 'orderId:', orderId, 'window.isPopoutMode:', window.isPopoutMode);
    
    let orderData;
    
    if (isPopoutMode) {
        // POP-OUT MODE: Invoice/line item data + customer (safe to change in pop-out)
        console.log('📋 Pop-out mode (Save & Close) - sending partial update (line items + totals + customer)');
        orderData = {
            order_date: formattedOrderDate,
            subtotal_price: parseFloat(formData.get('subtotal_price')) || 0,
            shipping_total: parseFloat(formData.get('shipping_total')) || 0,
            tip_amount: parseFloat(formData.get('tip_amount')) || 0,
            total_price: parseFloat(formData.get('total_price')) || 0,
            note: formData.get('note'),
            items: items,
            discounts: discounts,
            customer_id: formData.get('customer_id'),
            name: formData.get('name'),
            _partial_update: true,
            _popout_mode: true
        };
    } else {
        // REGULAR MODE: Full update with all fields
        orderData = {
            customer_id: formData.get('customer_id'),
            order_status: formData.get('order_status'),
            // Stale-status guard (Jul-2026) — same contract as saveOrderChanges:
            // dropdown untouched -> backend keeps the DB's current status.
            _loaded_status: (document.getElementById('editOrderStatus')?.dataset?.loadedStatus) || null,
            order_date: formattedOrderDate,
            contact_email: formData.get('contact_email'),
            subtotal_price: parseFloat(formData.get('subtotal_price')) || 0,
            shipping_total: parseFloat(formData.get('shipping_total')) || 0,
            tip_amount: parseFloat(formData.get('tip_amount')) || 0,
            total_price: parseFloat(formData.get('total_price')) || 0,
            payment_method: formData.get('payment_method'),
            note: formData.get('note'),
            expected_packets: formData.get('expected_packets') ? parseInt(formData.get('expected_packets')) : null,
            items: items,
            discounts: discounts,
            // ⭐ Order's name field - stores customer display name directly on order
            // This must be updated when customer is changed to keep order list/modal in sync
            name: formData.get('name'),
            address_first_name: formData.get('address_first_name'),
            address_last_name: formData.get('address_last_name'),
            address_email: formData.get('address_email'),
            address_phone: formData.get('address_phone'),
            address_line1: formData.get('address_line1'),
            address_line2: formData.get('address_line2'),
            address_city: formData.get('address_city'),
            address_country: formData.get('address_country'),
            // ⭐ Sync address to customer profile checkbox
            sync_to_customer: formData.get('sync_to_customer') === '1' ? true : false
        };
    }
    
    // ================================================================
    // LEDGER ADJUSTMENT CONFIRMATION (same as saveOrderChanges)
    // ================================================================
    if (window.currentOrder && window.currentOrder.ledger_transaction_id && window.currentOrder.order_status === 'delivered') {
        const oldTotal = parseFloat(window.currentOrder.total_price) || 0;
        const newTotal = orderData.total_price;
        
        if (Math.abs(oldTotal - newTotal) > 0.01) {
            const difference = newTotal - oldTotal;
            const confirmed = confirm(
                `⚠️ LEDGER ADJUSTMENT REQUIRED\n\n` +
                `This order has already been posted to the ledger.\n\n` +
                `Old Amount: Rs. ${oldTotal.toFixed(2)}\n` +
                `New Amount: Rs. ${newTotal.toFixed(2)}\n` +
                `Difference: ${difference >= 0 ? '+' : ''}Rs. ${difference.toFixed(2)}\n\n` +
                `The ledger adjustment will be sent for L1→L2 approval.\n` +
                `The order will be updated immediately, but the ledger will only be updated after approval.\n\n` +
                `Do you want to proceed?`
            );
            
            if (!confirmed) {
                saveAndCloseBtn.textContent = 'Save & Close';
                saveAndCloseBtn.disabled = false;
                return; // Cancel the save
            }
        }
    }
    
    // ⭐ Optimistic concurrency: tell the backend which order version this form is based on.
    orderData.expected_updated_at = window.editOrderLoadedUpdatedAt || null;

    // Submit to existing update endpoint (carry source so a Shopify-staging edit
    // saves to the staging table, not the colliding live order id).
    fetch(ordersDetailUrl(orderId), {
        method: 'PUT',
        headers: {
            'Content-Type': 'application/json',
            'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').getAttribute('content'),
            'Accept': 'application/json'
        },
        body: JSON.stringify(orderData)
    })
    .then(response => response.json())
    .then(data => {
        if (data.success) {
            // Show appropriate message based on whether adjustment was created
            if (data.requires_approval) {
                showSuccessMessage(data.message + ' (Adjustment ID: #' + data.adjustment_id + ')');
            } else {
                showSuccessMessage(data.message || 'Order updated successfully!');
            }
            // ⚠ Save succeeded, status change refused — say so before the reload
            //   takes the message away with it (see the Save handler above).
            if (data.status_warning) {
                alert('⚠️ ' + data.status_warning);
            }
            closeModal('editOrderModal');
            // If this editor is running in its own tab, close the tab; otherwise just refresh
            if (window.opener && !window.opener.closed) {
                window.opener.location.reload();
                window.close();
            } else {
                window.location.reload();
            }
        } else {
            alert('Error updating order: ' + (data.message || 'Unknown error'));
            saveAndCloseBtn.textContent = 'Save & Close';
            saveAndCloseBtn.disabled = false;
        }
    })
    .catch(error => {
        console.error('Error updating order:', error);
        alert('Error updating order. Please try again.');
        saveAndCloseBtn.textContent = 'Save & Close';
        saveAndCloseBtn.disabled = false;
    });
}
