        } catch (e) {}
        // Override save functions for popup behavior
        newWindow.saveOrderChanges = function(orderId) {
            const form = newWindow.document.getElementById('editOrderForm');
            if (!form) return;
            
            const formData = new FormData(form);
            const submitBtn = form.querySelector('button[type="submit"]');
            
            if (submitBtn) {
                submitBtn.textContent = 'Saving...';
                submitBtn.disabled = true;
            }
            
            // Collect line items
            const items = [];
            newWindow.document.querySelectorAll('.line-item').forEach((item) => {
                const name = item.querySelector('input[name*="[name]"]')?.value;
                const quantity = parseFloat(item.querySelector('input[name*="[quantity]"]')?.value) || 0;
                const unitPrice = parseFloat(item.querySelector('input[name*="[unit_price]"]')?.value) || 0;
                const sku = item.querySelector('input[name*="[sku]"]')?.value || null;
                const variantId = item.querySelector('input[name*="[variant_id]"]')?.value || null;
                const productId = item.querySelector('input[name*="[product_id]"]')?.value || null;
                const isFreeInput = item.querySelector('.is-free-input');
                const isFree = isFreeInput && isFreeInput.value === '1';
                
                if (name && quantity > 0 && unitPrice >= 0) {
                    var itemObj = {
                        name: name,
                        quantity: quantity,
                        unit_price: unitPrice,
                        line_total: isFree ? 0 : quantity * unitPrice,
                        is_free: isFree ? 1 : 0,
                        sku: sku,
                        variant_id: variantId,
                        product_id: productId
                    };
                    var qDay = item.querySelector('select[name*="qurbani_day"]')?.value;
                    var qSlot = item.querySelector('select[name*="qurbani_slot"]')?.value;
                    var qRegion = item.querySelector('select[name*="qurbani_region"]')?.value;
                    var qSubRegion = item.querySelector('select[name*="qurbani_sub_region"]')?.value;
                    var qDT = item.querySelector('select[name*="qurbani_delivery_type"]')?.value;
                    // Suffix-anchored selectors — see note in saveOrderChanges.
                    var qType = item.querySelector('select[name$="[qurbani_type]"]')?.value;
                    var qPaya = item.querySelector('select[name$="[qurbani_paya]"]')?.value;
                    if (qDay) itemObj.qurbani_day = qDay;
                    if (qSlot) itemObj.qurbani_slot = qSlot;
                    if (qRegion) itemObj.qurbani_region = qRegion;
                    if (qSubRegion) itemObj.qurbani_sub_region = qSubRegion;
                    if (qDT) itemObj.qurbani_delivery_type = qDT;
                    if (qType) itemObj.qurbani_type = qType;
                    if (qPaya) itemObj.qurbani_paya = qPaya;
                    var instr = item.querySelector('input[name*="instructions"]')?.value;
                    itemObj.instructions = instr || '';
                    items.push(itemObj);
                }
            });
            
            const rawOrderDate = formData.get('order_date');
            const formattedOrderDate = rawOrderDate ? rawOrderDate.replace('T', ' ') + ':00' : newWindow.getCurrentLocalDateTime().replace('T', ' ') + ':00';
            
            const orderData = {
                order_status: formData.get('order_status'),
                // Stale-status guard (Jul-2026) — same contract as saveOrderChanges.
                // The popup's select carries the copied data-loaded-status attribute.
                _loaded_status: (newWindow.document.getElementById('editOrderStatus')?.dataset?.loadedStatus) || null,
                order_date: formattedOrderDate,
                contact_email: formData.get('contact_email'),
                subtotal_price: parseFloat(formData.get('subtotal_price')) || 0,
                discount_total: parseFloat(formData.get('discount_total')) || 0,
                shipping_total: parseFloat(formData.get('shipping_total')) || 0,
                total_price: parseFloat(formData.get('total_price')) || 0,
                coupon_code: formData.get('coupon_code'),
                payment_method: formData.get('payment_method'),
                note: formData.get('note'),
                items: items,
                // ⭐ Order's name field - customer display name on order
                name: formData.get('name'),
                address_first_name: formData.get('address_first_name'),
                address_last_name: formData.get('address_last_name'),
                address_email: formData.get('address_email'),
                address_phone: formData.get('address_phone'),
                address_line1: formData.get('address_line1'),
                address_line2: formData.get('address_line2'),
                address_city: formData.get('address_city'),
                address_province: formData.get('address_province'),
                address_postal_code: formData.get('address_postal_code'),
                address_country: formData.get('address_country'),
                // ⭐ Sync address to customer profile checkbox
                sync_to_customer: formData.get('sync_to_customer') === '1' ? true : false
            };
            
            fetch(currentOrigin + ordersDetailUrl(orderId), {
                method: 'PUT',
                headers: {
                    'Content-Type': 'application/json',
                    'X-CSRF-TOKEN': csrfToken,
                    'Accept': 'application/json'
                },
                body: JSON.stringify(orderData)
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    newWindow.showSuccessMessage('Order updated successfully!');
                    if (submitBtn) {
                        submitBtn.textContent = 'Save';
                        submitBtn.disabled = false;
                    }
                } else {
                    alert('Error updating order: ' + (data.message || 'Unknown error'));
                    if (submitBtn) {
                        submitBtn.textContent = 'Save';
                        submitBtn.disabled = false;
                    }
                }
            })
            .catch(error => {
                console.error('Error updating order:', error);
                alert('Error updating order. Please try again.');
                if (submitBtn) {
                    submitBtn.textContent = 'Save';
                    submitBtn.disabled = false;
                }
            });
        };
        
        newWindow.saveAndCloseOrder = function(orderId) {
            // Same as saveOrderChanges but closes window on success
            newWindow.saveOrderChanges(orderId);
            // For save and close, we'll close after a short delay
            setTimeout(() => {
                if (window.opener) {
                    window.opener.location.reload();
                }
                newWindow.close();
            }, 2000);
        };
    };
}

