// Product search functionality
let productSearchTimeout = null;

// Global variables for keyboard navigation
// Global variables for keyboard navigation in product dropdown
let currentDropdownIndex = -1;
let currentLineItemIndex = -1;
let currentProducts = [];

// Expose functions globally for inline event handlers and pop-out windows
window.currentDropdownIndex = -1;
window.currentLineItemIndex = -1;
window.currentProducts = [];

function searchProducts(input, index) {
    clearTimeout(productSearchTimeout);
    const query = input.value.trim();
    
    if (query.length < 2) {
        hideProductDropdown(index);
        return;
    }
    
    productSearchTimeout = setTimeout(() => {
        const urlParams = new URLSearchParams(window.location.search);
        const qurbaniParam = urlParams.get('qurbani_mode') === '1' ? '&qurbani=1' : '';
        fetch(`/api/products/search?q=${encodeURIComponent(query)}&limit=20${qurbaniParam}`, {
            method: 'GET',
            headers: {
                'Accept': 'application/json',
                'Content-Type': 'application/json',
                'X-Requested-With': 'XMLHttpRequest'
            }
        })
        .then(response => response.json())
        .then(data => {
            if (data.success) {
                console.log('Product search debug:', data.debug);
                showProductResults(data.products, index);
            }
        })
        .catch(error => {
            console.error('Product search error:', error);
        });
    }, 300);
}

// Enhanced search with keyboard navigation support
function handleProductSearch(input, index, event) {
    // Don't search on arrow key presses
    if (event.key === 'ArrowUp' || event.key === 'ArrowDown' || event.key === 'Enter' || event.key === 'Escape') {
        return;
    }
    
    currentLineItemIndex = index;
    searchProducts(input, index);
}

// Handle keyboard navigation in product dropdown
function handleProductKeydown(input, index, event) {
    const dropdown = document.getElementById(`productDropdown_${index}`);
    if (!dropdown || dropdown.style.display === 'none') {
        return;
    }
    
    const items = dropdown.querySelectorAll('[data-product-index]');
    
    switch(event.key) {
        case 'ArrowDown':
            event.preventDefault();
            currentDropdownIndex = Math.min(currentDropdownIndex + 1, items.length - 1);
            updateDropdownHighlight(items);
            break;
            
        case 'ArrowUp':
            event.preventDefault();
            currentDropdownIndex = Math.max(currentDropdownIndex - 1, -1);
            updateDropdownHighlight(items);
            break;
            
        case 'Enter':
            event.preventDefault();
            if (currentDropdownIndex >= 0 && items[currentDropdownIndex]) {
                items[currentDropdownIndex].click();
            }
            break;
            
        case 'Escape':
            event.preventDefault();
            hideProductDropdown(index);
            break;
    }
}

// Update visual highlighting in dropdown
function updateDropdownHighlight(items) {
    items.forEach((item, idx) => {
        if (idx === currentDropdownIndex) {
            item.style.backgroundColor = '#3b82f6';
            item.style.color = 'white';
            item.scrollIntoView({ block: 'nearest' });
        } else {
            item.style.backgroundColor = 'white';
            item.style.color = 'inherit';
        }
    });
}

function showProductResults(products, index) {
    const dropdown = document.getElementById(`productDropdown_${index}`);
    if (!dropdown) return;
    
    // Reset dropdown navigation
    currentDropdownIndex = -1;
    currentProducts = products;
    
    if (products.length === 0) {
        dropdown.innerHTML = '<div style="padding: 8px; color: #6b7280; font-size: 12px;">No products found</div>';
    } else {
        dropdown.innerHTML = products.map((product, idx) => {
            // Extract variant_id and product_id from the product.id (format: "variant_123")
            const variantId = product.id && product.id.startsWith('variant_') ? product.id.replace('variant_', '') : '';
            const sku = (product.sku || '').replace(/'/g, "\\'");
            const attr1 = (product.attribute_1 || '').replace(/'/g, "\\'");
            const attr2 = (product.attribute_2 || '').replace(/'/g, "\\'");
            const attr3 = (product.attribute_3 || '').replace(/'/g, "\\'");
            // 📦 Bundled product (Oct-2026): picking it adds every product INSIDE,
            // packets × the packet price entered on the bundle — selectBundle() below,
            // ProductBundle on the server.
            const b = product.bundle || null;
            if (b && Array.isArray(b.items) && b.items.length) {
                const key = rememberBundlePick(b, product.sku);
                const what = b.items.map(it => `${it.qty} × ${it.name} @ PKR ${it.unit_price}`).join(' + ');
                return `
            <div onclick="selectBundle(${index}, '${key}')"
                 data-product-index="${idx}"
                 style="padding: 8px; cursor: pointer; border-bottom: 1px solid #f3f4f6; transition: background-color 0.1s;"
                 onmouseover="this.style.backgroundColor='#f9fafb'; currentDropdownIndex=${idx};"
                 onmouseout="this.style.backgroundColor='white';">
                <div style="font-weight: 500; font-size: 13px;">${product.name}</div>
                <div style="font-size: 11px; color: #92400e;">
                    📦 Bundle${product.sku ? ' ' + product.sku : ''} (PKR ${b.total}) → adds ${what}
                </div>
            </div>
        `;
            }
            return `
            <div onclick="selectProduct(${index}, '${product.id}', '${product.name.replace(/'/g, "\\'")}', ${product.price}, '${sku}', '${variantId}', '${attr1}', '${attr3}', '${attr2}')"
                 data-product-index="${idx}"
                 style="padding: 8px; cursor: pointer; border-bottom: 1px solid #f3f4f6; transition: background-color 0.1s;"
                 onmouseover="this.style.backgroundColor='#f9fafb'; currentDropdownIndex=${idx};" 
                 onmouseout="this.style.backgroundColor='white';">
                <div style="font-weight: 500; font-size: 13px;">${product.name}</div>
                <div style="font-size: 11px; color: #6b7280;">
                    ${product.sku ? 'SKU: ' + product.sku + ' | ' : ''}Price: PKR ${product.price}${product.sku ? '' : ' | Stock: ' + (product.inventory || 0)}
                </div>
            </div>
        `}).join('');
    }
    
    dropdown.style.display = 'block';
}
// 📦 Bundled product (Oct-2026): the dropdown remembers each bundle result by key so a
// click can add EVERY product inside — the first fills this line, each other one gets a
// new line. Every line is an ordinary product line (sku / variant / packet price).
var nfBundlePicks = {};
var nfBundlePickSeq = 0;
function rememberBundlePick(bundle, bundleSku) {
    const key = 'b' + (++nfBundlePickSeq);
    nfBundlePicks[key] = { items: bundle.items, bundle_sku: bundle.bundle_sku || bundleSku || '' };
    return key;
}
function selectBundle(index, key) {
    const b = nfBundlePicks[key];
    if (!b || !Array.isArray(b.items) || !b.items.length) return;
    b.items.forEach((it, k) => {
        let target = index;
        if (k > 0) {
            addLineItem();
            target = lineItemIndex - 1; // addLineItem() used lineItemIndex, then advanced it
        }
        selectProduct(target, it.id, it.name, it.unit_price, it.sku || '', String(it.variant_id), '', '', '', parseInt(it.qty, 10) || 0, b.bundle_sku);
    });
}

function selectProduct(index, productId, productName, price, sku = '', variantId = '', attribute1 = '', attribute3 = '', attribute2 = '', bundleQty = 0, bundleSku = '') {
    const lineItem = document.querySelector(`.line-item[data-index="${index}"]`);
    if (!lineItem) {
        console.error('Line item not found for index:', index);
        return;
    }
    
    // Fill in the product details using the specific line item context
    const nameInput = lineItem.querySelector(`input[name="items[${index}][name]"]`);
    const priceInput = lineItem.querySelector(`input[name="items[${index}][unit_price]"]`);
    const qtyInput = lineItem.querySelector(`input[name="items[${index}][quantity]"]`);
    const idInput = lineItem.querySelector(`input[name="items[${index}][id]"]`);
    const skuInput = lineItem.querySelector(`input[name="items[${index}][sku]"]`);
    const variantIdInput = lineItem.querySelector(`input[name="items[${index}][variant_id]"]`);
    const productIdInput = lineItem.querySelector(`input[name="items[${index}][product_id]"]`);
    const skuDisplay = lineItem.querySelector(`#skuDisplay_${index}`) || document.getElementById(`skuDisplay_${index}`);
    
    if (nameInput) nameInput.value = productName;
    if (idInput) idInput.value = productId;
    if (skuInput) skuInput.value = sku || '';
    if (variantIdInput) variantIdInput.value = variantId || '';
    // product_id will be resolved on backend from variant_id
    if (productIdInput) productIdInput.value = '';
    
    // ⭐ Display SKU if available
    if (skuDisplay && sku) {
        // 📦 A bundle pick names the bundle it came from, so "3" next to it reads as packets.
        skuDisplay.textContent = bundleQty > 0
            ? `SKU: ${sku} · 📦 ${bundleSku ? 'bundle ' + bundleSku : 'bundle'} = ${bundleQty} packets`
            : `SKU: ${sku}`;
        skuDisplay.style.display = 'inline-block';
    } else if (skuDisplay) {
        skuDisplay.style.display = 'none';
    }

    if (priceInput) {
        priceInput.value = price;
        // Make price readonly when selected from product dropdown
        priceInput.readOnly = true;
        priceInput.style.backgroundColor = '#f3f4f6';
        priceInput.style.cursor = 'not-allowed';
        priceInput.setAttribute('data-from-product', 'true');
        priceInput.title = 'Price is set from product catalog and cannot be edited';
    }

    // 📦 Bundle: one bundle = bundleQty packets of the product inside.
    if (bundleQty > 0 && qtyInput) {
        qtyInput.value = bundleQty;
    }

    // Update the line total
    updateLineTotal(index);

    // Hide dropdown
    hideProductDropdown(index);

    // Freeze the product name immediately after selection
    setTimeout(() => {
        freezeProductName(index);
    }, 50);

    // ⭐ Focus on quantity field after product selection
    // (not for a bundle: typing "1" over the pre-filled packets would sell ONE packet)
    setTimeout(() => {
        if (qtyInput && !(bundleQty > 0)) {
            qtyInput.focus();
            qtyInput.select(); // Select the value so user can type new qty directly
        }
    }, 60);
    
    // Auto-add new line item after a short delay to allow current selection to complete
    setTimeout(() => {
        autoAddNextLineItem();
    }, 100);

    if (attribute1 && attribute1.toLowerCase() === 'qurbani') {
        showQurbaniFields();
        // Stash attribute_2 (category, e.g. "Goat (Bakra)") on the row so the
        // target-remaining hint (qurbaniTargets*) can look up the right cell
        // when the user picks day / delivery_type without an extra API call.
        if (attribute2) {
            lineItem.setAttribute('data-product-category', attribute2);
        }
        addQurbaniFieldsToLineItem(lineItem, index);
        if (attribute3) {
            waitForDayOptionsAndAutoFill(lineItem, attribute3);
        }
    }
}

function waitForDayOptionsAndAutoFill(lineItem, attribute3Value) {
    var attempts = 0;
    var maxAttempts = 30;
    function tryFill() {
        attempts++;
        var fieldsDiv = lineItem.querySelector('.qurbani-item-fields');
        if (!fieldsDiv) { if (attempts < maxAttempts) setTimeout(tryFill, 100); return; }
        var daySel = fieldsDiv.querySelector('select[data-field="qurbani_day"]');
        if (!daySel) { if (attempts < maxAttempts) setTimeout(tryFill, 100); return; }
        if (daySel.options.length <= 1) {
            if (attempts < maxAttempts) setTimeout(tryFill, 100);
            return;
        }
        for (var i = 0; i < daySel.options.length; i++) {
            if (daySel.options[i].value === attribute3Value) {
                daySel.value = attribute3Value;
                var slotSel = fieldsDiv.querySelector('select[data-field="qurbani_slot"]');
                if (slotSel) {
                    slotSel.value = '';
                    populateItemSlotSelect(slotSel, 'qurbani_slot', qurbaniFieldOptionsCache);
                }
                return;
            }
        }
    }
    tryFill();
}

