let qurbaniFieldOptionsCache = null;
// Admin-configured default payment method for new qurbani orders
// (cash/online). Seeded from /qurbani-settings/api/options the first time
// Qurbani fields are shown and re-used by the Add Qurbani Payment modal
// so it opens on the right radio instead of hard-coding 'cash'.
let qurbaniDefaultPaymentMethod = 'cash';
function showQurbaniFields() {
    const section = document.getElementById('qurbaniFieldsSection');
    if (!section) return;
    if (section.style.display !== 'none' && section.offsetParent !== null) return;
    section.style.display = '';

    if (qurbaniFieldOptionsCache) {
        populateQurbaniSelects(qurbaniFieldOptionsCache);
        return;
    }
    fetch('/qurbani-settings/api/options', {
        headers: { 'Accept': 'application/json', 'X-Requested-With': 'XMLHttpRequest' }
    })
    .then(r => r.json())
    .then(data => {
        qurbaniFieldOptionsCache = data.options || {};
        if (data.qurbani_default_payment_method === 'online' || data.qurbani_default_payment_method === 'cash') {
            qurbaniDefaultPaymentMethod = data.qurbani_default_payment_method;
        }
        populateQurbaniSelects(qurbaniFieldOptionsCache);
    });
}

function populateQurbaniSelects(optionsGrouped) {
    // qurbani_type + qurbani_paya are simple flat dropdowns (no parent),
    // so the default branch inside populateItemSlotSelect handles them
    // exactly the same way as qurbani_delivery_type.
    const fields = ['qurbani_day', 'qurbani_slot', 'qurbani_region', 'qurbani_sub_region', 'qurbani_delivery_type', 'qurbani_type', 'qurbani_paya'];
    fields.forEach(fieldKey => {
        const fieldOpts = optionsGrouped[fieldKey] || [];
        document.querySelectorAll(`select[name="${fieldKey}"]`).forEach(sel => {
            const currentVal = sel.getAttribute('data-current') || sel.value;
            while (sel.options.length > 1) sel.remove(1);
            fieldOpts.forEach(o => {
                if (!o.is_active) return;
                const opt = document.createElement('option');
                opt.value = o.option_value;
                opt.textContent = o.option_value;
                if (o.option_value === currentVal) opt.selected = true;
                sel.appendChild(opt);
            });
        });
        document.querySelectorAll(`select.qurbani-item-select[data-field="${fieldKey}"]`).forEach(sel => {
            populateItemSlotSelect(sel, fieldKey, optionsGrouped);
        });
    });
    document.querySelectorAll('select.qurbani-item-select[data-field="qurbani_day"]').forEach(daySel => {
        daySel.removeEventListener('change', handleDayChangeForSlots);
        daySel.addEventListener('change', handleDayChangeForSlots);
    });
    document.querySelectorAll('select.qurbani-item-select[data-field="qurbani_delivery_type"]').forEach(dtSel => {
        dtSel.removeEventListener('change', handleDeliveryTypeChangeForSlots);
        dtSel.addEventListener('change', handleDeliveryTypeChangeForSlots);
    });
    document.querySelectorAll('select.qurbani-item-select[data-field="qurbani_region"]').forEach(regionSel => {
        regionSel.removeEventListener('change', handleRegionChangeForSubRegions);
        regionSel.addEventListener('change', handleRegionChangeForSubRegions);
    });
}

function populateItemSlotSelect(sel, fieldKey, optionsGrouped) {
    const currentVal = sel.value;
    const isNewItem = sel.hasAttribute('data-is-new');
    while (sel.options.length > 1) sel.remove(1);

    let fieldOpts = (optionsGrouped || qurbaniFieldOptionsCache)[fieldKey] || [];

    if (fieldKey === 'qurbani_slot') {
        const container = sel.closest('.qurbani-item-fields');
        const daySel = container ? container.querySelector('select[data-field="qurbani_day"]') : null;
        const dtSel = container ? container.querySelector('select[data-field="qurbani_delivery_type"]') : null;
        const selectedDay = daySel ? daySel.value : '';
        const selectedDT = dtSel ? dtSel.value : '';

        let dayObj = null, dtObj = null;
        if (selectedDay) {
            const dayOpts = (optionsGrouped || qurbaniFieldOptionsCache)['qurbani_day'] || [];
            dayObj = dayOpts.find(o => o.option_value === selectedDay);
        }
        if (selectedDT) {
            const dtOpts = (optionsGrouped || qurbaniFieldOptionsCache)['qurbani_delivery_type'] || [];
            dtObj = dtOpts.find(o => o.option_value === selectedDT);
        }

        if (dayObj && dtObj) {
            const filtered = fieldOpts.filter(o => o.is_active && o.parent_id === dayObj.id && o.delivery_type_parent_id === dtObj.id);
            if (filtered.length > 0) fieldOpts = filtered;
            else if (dayObj) {
                const dayOnly = fieldOpts.filter(o => o.is_active && o.parent_id === dayObj.id);
                if (dayOnly.length > 0) fieldOpts = dayOnly;
            }
        } else if (dayObj) {
            const filtered = fieldOpts.filter(o => o.is_active && o.parent_id === dayObj.id);
            if (filtered.length > 0) fieldOpts = filtered;
        }
    }

    if (fieldKey === 'qurbani_sub_region') {
        const container = sel.closest('.qurbani-item-fields');
        const regionSel = container ? container.querySelector('select[data-field="qurbani_region"]') : null;
        const selectedRegion = regionSel ? regionSel.value : '';
        if (selectedRegion) {
            const regionOpts = (optionsGrouped || qurbaniFieldOptionsCache)['qurbani_region'] || [];
            const regionObj = regionOpts.find(o => o.option_value === selectedRegion);
            if (regionObj) {
                const filtered = fieldOpts.filter(o => o.is_active && o.parent_id === regionObj.id);
                if (filtered.length > 0) fieldOpts = filtered;
            }
        }
    }

    // For qurbani_type and qurbani_paya, resolve category-specific defaults
    const lineItem = sel.closest('.line-item') || sel.closest('[data-product-category]');
    const productCategory = lineItem ? (lineItem.getAttribute('data-product-category') || '') : '';
    const hasCatDefaults = (fieldKey === 'qurbani_type' || fieldKey === 'qurbani_paya');

    let defaultVal = null;
    let categoryDefaultVal = null;
    fieldOpts.forEach(o => {
        if (!o.is_active) return;
        const opt = document.createElement('option');
        opt.value = o.option_value;
        opt.textContent = o.option_value;
        if (o.option_value === currentVal) opt.selected = true;
        if (o.is_default) {
            if (hasCatDefaults && o.category_override && productCategory && o.category_override === productCategory) {
                categoryDefaultVal = o.option_value;
            } else if (!o.category_override) {
                defaultVal = o.option_value;
            }
        }
        sel.appendChild(opt);
    });

    const resolvedDefault = categoryDefaultVal || defaultVal;
    if (isNewItem && !currentVal && resolvedDefault) {
        sel.value = resolvedDefault;
    }
}

function handleDayChangeForSlots(e) {
