function populateQurbaniEditSelects() {
    if (qurbaniFieldOptionsCache) {
        populateQurbaniSelects(qurbaniFieldOptionsCache);
        return;
    }
    fetch('/qurbani-settings/api/options', {
        headers: { 'Accept': 'application/json', 'X-Requested-With': 'XMLHttpRequest' }
    })
    .then(r => r.json())
    .then(data => {
        qurbaniFieldOptionsCache = data.options || {};
        if (data.qurbani_default_payment_method === 'online' || data.qurbani_default_payment_method === 'cash') {
            qurbaniDefaultPaymentMethod = data.qurbani_default_payment_method;
        }
        populateQurbaniSelects(qurbaniFieldOptionsCache);
    });
}

// Qurbani payment modal for web
var qurbaniPaymentOrderId = null;
function openQurbaniPaymentModal(orderId) {
    qurbaniPaymentOrderId = orderId;
    // Seed the default payment method from the Qurbani settings config if
    // we haven't loaded it yet. Non-blocking — if this is a fresh page
    // load and the cache is cold we'll fall back to the JS default
    // ('cash') and the modal just opens on that.
    if (!qurbaniFieldOptionsCache) {
        fetch('/qurbani-settings/api/options', {
            headers: { 'Accept': 'application/json', 'X-Requested-With': 'XMLHttpRequest' }
        })
        .then(r => r.json())
        .then(data => {
            qurbaniFieldOptionsCache = data.options || qurbaniFieldOptionsCache || {};
            if (data.qurbani_default_payment_method === 'online' || data.qurbani_default_payment_method === 'cash') {
                qurbaniDefaultPaymentMethod = data.qurbani_default_payment_method;
            }
        })
        .catch(() => {});
    }
    // Build modal
    var existing = document.getElementById('qurbaniPaymentOverlay');
    if (existing) existing.remove();

    var overlay = document.createElement('div');
    overlay.id = 'qurbaniPaymentOverlay';
    overlay.style.cssText = 'position:fixed; top:0; left:0; right:0; bottom:0; background:rgba(0,0,0,0.5); z-index:10000; display:flex; align-items:center; justify-content:center;';
    overlay.innerHTML = `
        <div style="background:#fff; border-radius:12px; padding:24px; width:400px; max-width:90vw; box-shadow:0 20px 60px rgba(0,0,0,0.3);">
            <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:16px;">
                <h3 style="margin:0; font-size:18px; font-weight:700;">Add Qurbani Payment</h3>
                <button onclick="document.getElementById('qurbaniPaymentOverlay').remove()" style="background:none; border:none; font-size:20px; cursor:pointer; color:#6b7280;">&times;</button>
            </div>
            <div style="margin-bottom:12px;">
                <label style="font-size:13px; font-weight:600; color:#374151;">Amount (Rs.) *</label>
                <input type="number" id="qpAmount" step="0.01" min="0.01" style="width:100%; padding:8px 12px; border:1px solid #d1d5db; border-radius:6px; margin-top:4px; font-size:14px;" placeholder="Enter amount">
            </div>
            <div style="margin-bottom:12px;">
                <label style="font-size:13px; font-weight:600; color:#374151;">Payment Method *</label>
                
                @php
                    $_qpmDefault = \App\Models\FIN\ConfigModel::get('qurbani_default_payment_method', 'cash');
                    if (!in_array($_qpmDefault, ['cash','online'], true)) { $_qpmDefault = 'cash'; }
                    $_qpmCashActive = $_qpmDefault === 'cash';
                @endphp
                <div style="display:flex; gap:8px; margin-top:4px;">
                    <button id="qpCashBtn" onclick="selectQPMethod('cash')" style="flex:1; padding:8px; border-radius:6px; font-weight:700; cursor:pointer; background:{{ $_qpmCashActive ? '#10b981' : '#f3f4f6' }}; color:{{ $_qpmCashActive ? '#fff' : '#374151' }}; border:2px solid {{ $_qpmCashActive ? '#10b981' : '#d1d5db' }};">Cash</button>
                    <button id="qpOnlineBtn" onclick="selectQPMethod('online')" style="flex:1; padding:8px; border-radius:6px; font-weight:700; cursor:pointer; background:{{ !$_qpmCashActive ? '#3b82f6' : '#f3f4f6' }}; color:{{ !$_qpmCashActive ? '#fff' : '#374151' }}; border:2px solid {{ !$_qpmCashActive ? '#3b82f6' : '#d1d5db' }};">Online</button>
                </div>
            </div>
            <input type="hidden" id="qpMethod" value="{{ $_qpmDefault }}">
            <div style="margin-bottom:12px;">
                <label style="font-size:13px; font-weight:600; color:#374151;">Reference (optional)</label>
                <input type="text" id="qpReference" style="width:100%; padding:8px 12px; border:1px solid #d1d5db; border-radius:6px; margin-top:4px; font-size:13px;" placeholder="Transaction ID / receipt #">
            </div>
            <div style="margin-bottom:16px;">
                <label style="font-size:13px; font-weight:600; color:#374151;">Notes (optional)</label>
                <input type="text" id="qpNotes" style="width:100%; padding:8px 12px; border:1px solid #d1d5db; border-radius:6px; margin-top:4px; font-size:13px;" placeholder="Any notes...">
            </div>
            <button id="qpSubmitBtn" onclick="submitQurbaniPayment()" style="width:100%; padding:10px; background:#d97706; color:#fff; border:none; border-radius:8px; font-size:14px; font-weight:700; cursor:pointer;">Submit Payment</button>
        </div>
    `;
    document.body.appendChild(overlay);
    // Sync the modal's selected method with the current qurbaniDefault
    // in case the admin changed the setting after the page loaded.
    try {
        selectQPMethod(qurbaniDefaultPaymentMethod === 'online' ? 'online' : 'cash');
    } catch (e) { /* defensive: server-side blade fallback already painted */ }
}

var qpSelectedMethod = 'cash';
function selectQPMethod(method) {
    qpSelectedMethod = method;
    document.getElementById('qpMethod').value = method;
    var cashBtn = document.getElementById('qpCashBtn');
    var onlineBtn = document.getElementById('qpOnlineBtn');
    if (method === 'cash') {
        cashBtn.style.background = '#10b981'; cashBtn.style.color = '#fff'; cashBtn.style.borderColor = '#10b981';
        onlineBtn.style.background = '#f3f4f6'; onlineBtn.style.color = '#374151'; onlineBtn.style.borderColor = '#d1d5db';
    } else {
        onlineBtn.style.background = '#3b82f6'; onlineBtn.style.color = '#fff'; onlineBtn.style.borderColor = '#3b82f6';
        cashBtn.style.background = '#f3f4f6'; cashBtn.style.color = '#374151'; cashBtn.style.borderColor = '#d1d5db';
    }
}

function submitQurbaniPayment() {
    var amount = parseFloat(document.getElementById('qpAmount').value);
    if (!amount || amount <= 0) { alert('Please enter a valid amount'); return; }
    var btn = document.getElementById('qpSubmitBtn');
    btn.disabled = true; btn.textContent = 'Submitting...';

    fetch('/orders/' + qurbaniPaymentOrderId + '/qurbani-payments', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json',
            'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').getAttribute('content'),
            'X-Requested-With': 'XMLHttpRequest'
        },
        body: JSON.stringify({
            amount: amount,
            payment_method: document.getElementById('qpMethod').value,
            reference: document.getElementById('qpReference').value || null,
            notes: document.getElementById('qpNotes').value || null,
        })
    })
    .then(r => r.json())
    .then(data => {
        if (data.success) {
            document.getElementById('qurbaniPaymentOverlay').remove();
            alert(data.message || 'Payment recorded');
            // Refresh the current order view
            if (typeof loadEditForm === 'function' && qurbaniPaymentOrderId) {
                loadEditForm(qurbaniPaymentOrderId);
            }
        } else {
            alert(data.message || 'Failed to add payment');
            btn.disabled = false; btn.textContent = 'Submit Payment';
        }
    })
    .catch(err => {
        alert('Error: ' + err.message);
        btn.disabled = false; btn.textContent = 'Submit Payment';
    });
}

// Void a qurbani payment and reverse its ledger + account movements.
// Soft-delete (status='voided') so audits are preserved but the payment
// no longer counts toward paid totals or the PAID stamp.
function deleteQurbaniPayment(orderId, paymentId, amount) {
    if (!confirm('Void this payment of Rs. ' + Number(amount || 0).toLocaleString()
        + '?\n\nThe ledger entry and account balance will be reversed. '
        + 'Voided payments stay on file for audit but no longer count.')) {
        return;
    }

    fetch('/orders/' + orderId + '/qurbani-payments/' + paymentId, {
        method: 'DELETE',
        headers: {
            'Accept': 'application/json',
            'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').getAttribute('content'),
            'X-Requested-With': 'XMLHttpRequest'
        }
    })
    .then(function (r) { return r.json(); })
    .then(function (data) {
        if (data && data.success) {
            // Reload the edit form so totals, remaining, payments list, and
            // the invoice preview all reflect the reversal.
            if (typeof loadEditForm === 'function') {
                loadEditForm(orderId);
            }
        } else {
            alert((data && data.message) || 'Failed to void payment');
        }
    })
    .catch(function (err) { alert('Error: ' + err.message); });
}

// Create new order with preloaded customer
function createNewOrderWithCustomer(customerId) {
    // Fetch customer data by ID (reuses customers show endpoint that returns JSON)
    fetch(`/customers/${customerId}`)
    .then(response => response.json())
    .then(data => {
        if (data && data.success && data.customer) {
            const customer = data.customer;
            const fullName = [customer.first_name || '', customer.last_name || ''].join(' ').trim() || (customer.name || '');
            
            // Open create order modal
            createNewOrder();
            
            // Switch to existing customer mode and preload data
            setTimeout(() => {
                selectCustomerMode('existing');
                document.getElementById('customerSearch').value = fullName;
                document.getElementById('selectedCustomerId').value = customer.id;
                
                // Show customer details using the enhanced display
                const customerData = {
                    name: fullName,
                    phone: customer.phone_original || customer.phone || '',
                    email: customer.email || '',
                    notes: customer.notes || '',
                    address: {
                        address1: customer.address1 || '',
                        address2: customer.address2 || '',
                        city: customer.city || '',
                        province: customer.province || '',
                        postal_code: customer.postal_code || '',
                        country: customer.country || ''
                    }
                };
                showSelectedCustomerDetails(customerData);
                
                // Auto-fill contact email
                const emailInput = document.querySelector('input[name="contact_email"]');
                if (emailInput && customer.email) {
                    emailInput.value = customer.email;
                }
                
                // Hide the customer selection buttons since customer is already selected
                const existingBtn = document.getElementById('existingCustomerBtn');
                const newBtn = document.getElementById('newCustomerBtn');
                if (existingBtn && newBtn) {
                    existingBtn.style.display = 'none';
                    newBtn.style.display = 'none';
                }
                
                // Add a note showing which customer was preloaded
                const customerSection = document.querySelector('#existingCustomerSection');
                if (customerSection) {
                    const note = document.createElement('div');
                    note.style.cssText = 'margin-top: 8px; padding: 8px; background-color: #ecfdf5; border: 1px solid #d1fae5; border-radius: 4px; font-size: 12px; color: #065f46;';
                    note.innerHTML = `✅ Customer pre-selected from customers page: ${fullName}`;
                    customerSection.appendChild(note);
                }
            }, 100);
        } else {
            // Fallback to regular create order
            createNewOrder();
        }
    })
    .catch(error => {
        console.error('Error loading customer:', error);
        // Fallback to regular create order
        createNewOrder();
    });
}
