function renderTableHeader() {
    const header = document.getElementById('table-header');
    const colgroup = document.getElementById('table-colgroup');
    header.innerHTML = '';
    if (colgroup) colgroup.innerHTML = '';
    
    // Add checkbox column first (only for non-Shopify orders) - Hidden by default until Select Multiple is clicked
    const isShopifyView = window.location.search.includes('source=shopify');
    if (!isShopifyView) {
        const checkboxTh = document.createElement('th');
        // ⭐ Add checkbox-column class - hidden by default via CSS
        checkboxTh.className = 'checkbox-column px-3 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider w-12';
        checkboxTh.innerHTML = '<input type="checkbox" id="selectAllOrders" onchange="toggleAllOrdersSelection()" class="rounded" title="Select all on page">';
        header.appendChild(checkboxTh);
        
        if (colgroup) {
            const checkboxCol = document.createElement('col');
            checkboxCol.className = 'checkbox-column';
            checkboxCol.style.width = '48px';
            colgroup.appendChild(checkboxCol);
        }
    }
    
    // ⭐ Render actions column FIRST (after checkbox) for better visibility
    const actionsColumn = currentColumns.find(c => c.id === 'actions');
    if (actionsColumn && actionsColumn.visible) {
        const actionsConfig = availableColumns['actions'];
        if (actionsConfig) {
            const actionsTh = document.createElement('th');
            actionsTh.className = `px-2 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider`;
            actionsTh.textContent = actionsConfig.label;
            header.appendChild(actionsTh);
            
            if (colgroup) {
                const actionsCol = document.createElement('col');
                actionsCol.style.width = '110px'; // Width for action buttons
                colgroup.appendChild(actionsCol);
            }
        }
    }
    
    // Render other columns (excluding actions which is already rendered)
    currentColumns.forEach(column => {
        if (column.visible && column.id !== 'actions') {
            const columnConfig = availableColumns[column.id];
            if (columnConfig) {
                const th = document.createElement('th');
                // Use compact padding for status, matching padding for address columns
                let headerPx = 'px-6';
                if (column.id === 'order_status') headerPx = 'px-2';
                else if (column.id === 'address1' || column.id === 'address2') headerPx = 'px-4';
                th.className = `${headerPx} py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider ${columnConfig.width}`;
                th.textContent = columnConfig.label;
                header.appendChild(th);

                // Also render a matching <col> for consistent widths even with custom columns
                if (colgroup) {
                    const col = document.createElement('col');
                    // Translate Tailwind width shorthands to pixel values for reliability
                    const tw = String(columnConfig.width || '').trim();
                    const map = {
                        'w-16': 64,
                        'w-20': 80,
                        'w-24': 96,
                        'w-28': 112,
                        'w-32': 128,
                        'w-36': 144,
                        'w-40': 160,
                        'w-44': 176,
                        'w-48': 192,
                        'w-56': 224,
                        'w-64': 256
                    };
                    let px = map[tw] || null;
                    // Handle arbitrary like w-[150px]
                    const match = tw.match(/w-\[(\d+)px\]/);
                    if (!px && match) px = parseInt(match[1], 10);
                    // Address column uses its configured width (w-56 = 224px)
                    if (px) col.style.width = px + 'px';
                    colgroup.appendChild(col);
                }
            }
        }
    });
}

function renderTableBody() {
    const tbody = document.getElementById('table-body');
    tbody.innerHTML = '';
    
    
    if (!window.ordersData || window.ordersData.length === 0) {
        // Show a message in the table
        const row = document.createElement('tr');
        const td = document.createElement('td');
        td.colSpan = 10;
        td.className = 'text-center py-8 text-gray-500';
        td.innerHTML = 'No orders found';
        row.appendChild(td);
        tbody.appendChild(row);
        return;
    }
    window.ordersData.forEach((order, index) => {
        try {
            const row = document.createElement('tr');
            row.className = 'hover:bg-gray-50 transition-colors duration-150 cursor-pointer';
            row.setAttribute('data-order-id', order.id); // ⭐ SMART SYNC: For row updates
            
            // Make entire row clickable to pop out order in background tab
            row.onclick = function(e) {
                // Don't trigger row click if user clicked on action buttons, customer name, or checkboxes
                if (e.target.closest('.sticky-actions') || e.target.closest('.action-buttons') || e.target.closest('.customer-name-link') || e.target.closest('input[type="checkbox"]') || e.target.closest('button')) {
                    return;
                }
                popOutOrder(order.id);
            };
            
            // Add checkbox column first (only for non-Shopify orders) - Hidden by default
            const isShopifyView = window.location.search.includes('source=shopify');
            if (!isShopifyView) {
                const checkboxTd = document.createElement('td');
                // ⭐ Add checkbox-column class - hidden by default via CSS
                checkboxTd.className = 'checkbox-column px-3 py-4 whitespace-nowrap text-sm';
                if (window.currentSource === 'shopify' && (order.external_source === 'shopify' || order.external_source === 'khaas_storage')) {
                    checkboxTd.innerHTML = ''; // No checkbox for approval queue orders
                } else {
                    checkboxTd.innerHTML = `<input type=\"checkbox\" class=\"order-checkbox rounded\" id=\"order_${order.id}\" value=\"${order.id}\" onchange=\"toggleOrderSelection(${order.id})\" onclick=\"event.stopPropagation()\">`;
                }
                row.appendChild(checkboxTd);
            }
            
            // ⭐ Render actions column FIRST (after checkbox) for better visibility
            const actionsColumn = currentColumns.find(c => c.id === 'actions');
            if (actionsColumn && actionsColumn.visible) {
                try {
                    const actionsTd = document.createElement('td');
                    actionsTd.className = 'px-2 py-2 whitespace-nowrap text-sm';
                    actionsTd.innerHTML = getCellContent(order, 'actions');
                    row.appendChild(actionsTd);
                } catch (cellError) {
                    console.error('Error rendering actions cell:', cellError);
                }
            }
            
            // Render other columns (excluding actions which is already rendered)
            currentColumns.forEach(column => {
                if (column.visible && column.id !== 'actions') {
                    try {
                        const td = document.createElement('td');
                        // Use compact padding for status column, allow wrapping for address columns
                        if (column.id === 'order_status') {
                            td.className = 'px-2 py-2 whitespace-nowrap text-sm';
                        } else if (column.id === 'address1' || column.id === 'address2') {
                            td.className = 'px-4 py-3 text-sm';
                            td.style.whiteSpace = 'normal';
                            td.style.wordBreak = 'break-word';
                        } else {
                            td.className = 'px-6 py-4 whitespace-nowrap text-sm';
                        }
                        // ⭐ SMART SYNC: Mark rider cell for updates
                        if (column.id === 'rider') {
                            td.className += ' order-rider-cell';
                        }
                        const cellContent = getCellContent(order, column.id);
                        td.innerHTML = cellContent;
                        row.appendChild(td);
                    } catch (cellError) {
                        console.error(`Error rendering cell ${column.id}:`, cellError);
                        const td = document.createElement('td');
                        td.className = 'px-6 py-4 whitespace-nowrap text-sm';
                        td.innerHTML = '<span class="text-red-500">Error</span>';
                        row.appendChild(td);
                    }
                }
            });
            
            tbody.appendChild(row);
        } catch (rowError) {
            console.error(`Error rendering row ${index}:`, rowError, order);
        }
    });
}

// Build the "Send Invoice via WhatsApp" action button. When an invoice template
// has already been successfully sent via the API for this order, show a small
// green ✓ corner badge (the button stays clickable → resend) plus a tooltip with
// when it was sent. When the LATEST send attempt failed per the delivery
// webhook (order.invoice_send_failed), a red ! badge takes precedence so the
// operator sees the failure and can click to resend. Driven by
// order.invoice_sent / invoice_sent_at / invoice_send_failed / invoice_send_error
// from OrderController::filter. Used in every action-button row (identical markup).
function sendInvoiceButtonHtml(order) {
    const onum  = (order.order_number||'').replace(/'/g,"\\'");
    const cname = (order.name || (order.customer ? ((order.customer.first_name||'')+' '+(order.customer.last_name||'')).trim() : '') || ((order.address_first_name||'')+' '+(order.address_last_name||'')).trim() || '').replace(/'/g,"\\'");
    const phone = (order.customer_phone||order.address_phone||'').replace(/'/g,"\\'");
    const total = parseFloat(order.total_price||0);
    const sent  = !!order.invoice_sent;
    const failed = !!order.invoice_send_failed;
    let when = '';
    if (sent && order.invoice_sent_at) {
        try {
            const d = new Date(String(order.invoice_sent_at).replace(' ', 'T'));
            if (!isNaN(d.getTime())) when = ' · ' + d.toLocaleDateString('en-GB',{day:'2-digit',month:'short'}) + ' ' + d.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});
        } catch (e) {}
    }
    // Tooltip text lands inside a double-quoted title attribute — strip
    // characters that could break out of it.
    const failReason = String(order.invoice_send_error || 'delivery failed').replace(/["<>]/g, '');
    const title = failed
        ? ('⚠ Last invoice send FAILED: ' + failReason + ' · click to resend')
        : (sent ? ('Invoice sent'+when+' · click to resend') : 'Send Invoice via WhatsApp');
    const ring  = failed ? ' ring-1 ring-red-400' : (sent ? ' ring-1 ring-green-400' : '');
    const badge = failed
        ? '<span style="position:absolute;top:-4px;right:-4px;width:14px;height:14px;background:#dc2626;border:2px solid #fff;border-radius:9999px;display:flex;align-items:center;justify-content:center;color:#fff;font-size:10px;font-weight:800;line-height:1;">!</span>'
        : (sent
            ? '<span style="position:absolute;top:-4px;right:-4px;width:14px;height:14px;background:#16a34a;border:2px solid #fff;border-radius:9999px;display:flex;align-items:center;justify-content:center;"><svg width="8" height="8" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"><path d="M5 13l4 4L19 7"/></svg></span>'
            : '');
    return `<button onclick="event.stopPropagation(); quickSendInvoiceWhatsApp(${order.id}, '${onum}', ${total}, '${cname}', '${phone}' )" class="relative inline-flex items-center justify-center w-7 h-7 text-green-600 bg-green-50 border border-green-200 rounded hover:bg-green-100 hover:border-green-300 transition-all duration-200${ring}" title="${title}"><svg class="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347z"/><path d="M12 2C6.477 2 2 6.477 2 12c0 1.89.525 3.66 1.438 5.168L2 22l4.832-1.438A9.955 9.955 0 0012 22c5.523 0 10-4.477 10-10S17.523 2 12 2z"/></svg>${badge}</button>`;
}

// Optimistic badge update (Jul-2026): after a successful invoice send, turn this
// order's send-button tick green immediately — no page reload, no server refetch.
// The outbound message row is written synchronously by the send, so "sent" is
// already true on the server; this just reflects it instantly. The authoritative
// status from the delivery webhook still lands on the next natural list refetch
// (an async delivery failure would show red there). We MUTATE the shared order
// object rather than replace an array slot: window.ordersData / allOrders /
// filteredOrders are shallow-copy arrays over the SAME instances, so a later
// in-memory re-render (search / filter / tab) keeps the tick too. Fully guarded —
// a cosmetic hiccup must never disturb the already-successful send.
function markInvoiceSentLocally(orderId) {
    try {
        const idStr = String(orderId);
        const n = new Date();
        const pad = x => ('0' + x).slice(-2);
        const stamp = n.getFullYear() + '-' + pad(n.getMonth() + 1) + '-' + pad(n.getDate())
            + ' ' + pad(n.getHours()) + ':' + pad(n.getMinutes()) + ':' + pad(n.getSeconds());

        let updatedOrder = null;
        [window.ordersData, window.allOrders, window.filteredOrders].forEach(function(arr) {
            if (!Array.isArray(arr)) return;
            arr.forEach(function(o) {
                if (o && String(o.id) === idStr) {
                    o.invoice_sent = true;
                    o.invoice_sent_at = stamp;
                    o.invoice_send_failed = false;
                    o.invoice_send_error = null;
                    updatedOrder = o;
                }
            });
        });
        if (!updatedOrder) return; // order not in the current in-memory set

        // Re-render just this row's send button (no table rebuild → no scroll
        // jump, nothing else touched). The row may be absent (filtered out / tab
        // switched away) — the object mutation above still keeps it green when
        // the row next renders.
        const row = document.querySelector('#table-body tr[data-order-id="' + idStr + '"]');
        if (!row) return;
        const btn = row.querySelector('button[onclick*="quickSendInvoiceWhatsApp"]');
        if (!btn) return;
        const holder = document.createElement('span');
        holder.innerHTML = sendInvoiceButtonHtml(updatedOrder);
        const fresh = holder.firstElementChild;
        if (fresh) btn.replaceWith(fresh);
    } catch (e) { /* cosmetic only — never disturb the completed send */ }
}

// Small "source channel" pill shown under the order number: distinguishes
// orders placed via the customer app (iOS / Android) from the website. Driven by
// order.order_source_channel = Shopify's source_name (ios_app / android_app / web),
// captured on ingest by OrderModel::mapShopifyOrder(). Inline styles (not tailwind)
// so it renders even on pages affected by the CSS purge. Empty string when the
// channel is unknown — every pre-existing order, and any source without source_name.
function orderChannelBadge(order){
    var raw = (order && order.order_source_channel != null) ? String(order.order_source_channel) : '';
    var ch = raw.toLowerCase().trim();
    if(!ch) return '';
    // Self-contained escaper — the page's esc() helpers live inside private
    // IIFE scopes and are NOT visible here; do not call esc() from this scope.
    var e = function(s){ return String(s).replace(/[&<>"']/g, function(c){ return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]; }); };
    var label, bg, fg, icon;
    if(ch.indexOf('ios')!==-1){ label='iOS'; bg='#eff6ff'; fg='#1d4ed8'; icon='📱'; }
    else if(ch.indexOf('android')!==-1){ label='Android'; bg='#ecfdf5'; fg='#047857'; icon='📱'; }
    else if(ch==='web'){ label='Web'; bg='#f3f4f6'; fg='#4b5563'; icon='🌐'; }
    else if(ch.indexOf('app')!==-1){ label='App'; bg='#eff6ff'; fg='#1d4ed8'; icon='📱'; }
    else { label=raw; bg='#f3f4f6'; fg='#4b5563'; icon=''; }
    return '<span title="Order source: '+e(raw)+'" style="display:inline-flex;align-items:center;gap:3px;margin-top:3px;padding:1px 7px;border-radius:9999px;background:'+bg+';color:'+fg+';font-size:10px;font-weight:600;line-height:1.5;white-space:nowrap;">'+(icon?icon+' ':'')+e(label)+'</span>';
}

function getCellContent(order, columnId) {
    const formatDate = (dateStr) => {
        if (!dateStr) return '<span class="text-gray-400">-</span>';
        try {
            // Parse the date string
            const date = new Date(dateStr);
            
            // Format with both date and time
            const formatted = date.toLocaleDateString('en-US', {
                year: 'numeric',
                month: 'short',
                day: 'numeric',
                hour: '2-digit',
                minute: '2-digit',
                hour12: false
            });
            return formatted;
        } catch (error) {
            console.error('Date parsing error:', error, 'for date:', dateStr);
            return `<span class="text-sm text-gray-600">${dateStr}</span>`;
        }
    };
    
    const formatCurrency = (amount, currency = 'PKR') => {
        if (!amount) return '0.00';
        return parseFloat(amount).toFixed(2);
    };
    try {
        switch (columnId) {
        // Basic Info
        case 'id':
            return `<div class="table-cell-id">${order.id}</div>`;
        case 'order_number':
            return `<div class="table-cell-order-number">${order.order_number || ''}</div>${orderChannelBadge(order)}${window.nfSplitChipHtml ? window.nfSplitChipHtml(order) : ''}`;
        case 'order_date':
            return `<div class="table-cell-date">${formatDate(order.order_date)}</div>`;
        case 'delivery_date':
            // Get delivery date from status history if available
            const deliveryHist = order.current_status_history || order.statusHistory;
            let deliveryDateVal = '-';
            if (deliveryHist && deliveryHist.status_code === 'delivered' && deliveryHist.changed_at) {
                deliveryDateVal = formatDate(deliveryHist.changed_at);
            } else if (order.delivery_date) {
                deliveryDateVal = formatDate(order.delivery_date);
            }
            return `<div class="table-cell-date">${deliveryDateVal}</div>`;
        case 'order_status':
            const status = order.order_status || 'pending';
            const statusConfig = {
                'pending': { bg: 'bg-yellow-50', border: 'border-yellow-200', text: 'text-yellow-700', icon: '' },
                'processing': { bg: 'bg-blue-50', border: 'border-blue-200', text: 'text-blue-700', icon: '' },
                'completed': { bg: 'bg-green-50', border: 'border-green-200', text: 'text-green-700', icon: '' },
                'cancelled': { bg: 'bg-red-50', border: 'border-red-200', text: 'text-red-700', icon: '' },
                // 'refunded' is the code behind the label "Returned" (Sep-2026) —
                // reused because it already sits in every closed-status list.
                'refunded': { bg: 'bg-purple-50', border: 'border-purple-200', text: 'text-purple-700', icon: '↩' },
                'on-hold': { bg: 'bg-orange-50', border: 'border-orange-200', text: 'text-orange-700', icon: '' },
                'new': { bg: 'bg-gray-50', border: 'border-gray-200', text: 'text-gray-700', icon: '' },
                'out_for_delivery': { bg: 'bg-indigo-50', border: 'border-indigo-200', text: 'text-indigo-700', icon: '' },
                'delivered': { bg: 'bg-green-50', border: 'border-green-200', text: 'text-green-700', icon: '' }
            };
            const config = statusConfig[status] || { bg: 'bg-gray-50', border: 'border-gray-200', text: 'text-gray-700', icon: '' };
            
            // Check if quick status change should be disabled (delivered orders with ledger)
            const hasLedgerForStatus = order.ledger_transaction_id && order.ledger_transaction_id > 0;
            const isDeliveredForStatus = order.order_status === 'delivered';
            const restrictStatusChange = hasLedgerForStatus && isDeliveredForStatus;
            
            if (restrictStatusChange) {
                // A delivered, invoiced order is locked out of the status picker on
                // purpose. Sep-2026: there is now exactly ONE thing that may still
                // happen to it — the customer brings it back — so for the people
                // allowed to take a return the lock becomes that door instead of a
                // dead end. Everyone else keeps the plain locked badge.
                const label = status === 'refunded'
                    ? 'Returned'
                    : status.replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
                if (window.nfCanReturnOrders) {
                    return `<button type="button" onclick="event.stopPropagation(); nfOpenReturnForm(${order.id})" class="inline-flex items-center rounded text-xs font-medium border ${config.bg} ${config.border} ${config.text} hover:opacity-80 transition cursor-pointer" style="padding: 2px 6px; gap: 2px; line-height: 1.3;" title="Delivered and invoiced — click to return this order">
                                ${label}
                                <span style="font-size: 10px;">↩</span>
                            </button>`;
                }
                return `<span class="inline-flex items-center rounded text-xs font-medium border ${config.bg} ${config.border} ${config.text} opacity-75" style="padding: 2px 6px; gap: 2px; line-height: 1.3;" title="Status change restricted for delivered orders with ledger entry">
                            ${config.icon ? '<span style="font-size: 10px;">' + config.icon + '</span>' : ''}
                            ${label}
                            <span style="font-size: 10px;">🔒</span>
                        </span>`;
            }

            // A returned order is never re-opened from the pill either.
            if (status === 'refunded') {
                return `<span class="inline-flex items-center rounded text-xs font-medium border ${config.bg} ${config.border} ${config.text}" style="padding: 2px 6px; gap: 2px; line-height: 1.3;" title="This order was returned">
                            <span style="font-size: 10px;">↩</span> Returned
                        </span>`;
            }
            
            return `<button type="button" onclick="event.stopPropagation(); openQuickStatusChange(${order.id}, '${status}')" class="inline-flex items-center rounded text-xs font-medium border ${config.bg} ${config.border} ${config.text} hover:opacity-80 transition cursor-pointer" style="padding: 2px 6px; gap: 2px; line-height: 1.3;" title="Click to change status">
                        ${config.icon ? '<span style="font-size: 10px;">' + config.icon + '</span>' : ''}
                        ${status.replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase())}
                    </button>`;
        case 'external_source':
            const source = order.external_source || 'manual';
            const sourceColors = {
                'shopify': 'bg-green-50 border-green-200 text-green-700',
                'woocommerce': 'bg-purple-50 border-purple-200 text-purple-700',
                'khaas_storage': 'bg-sky-50 border-sky-200 text-sky-700',
                'manual': 'bg-orange-50 border-orange-200 text-orange-700'
            };
            const sourceColor = sourceColors[source] || 'bg-gray-50 border-gray-200 text-gray-700';
            const srcLabel = source === 'khaas_storage' ? 'Frozen Meat' : source.charAt(0).toUpperCase() + source.slice(1);
            return `<span class="inline-flex items-center px-2 py-1 rounded-md text-xs font-medium border ${sourceColor}">${srcLabel}</span>`;
        case 'external_id':
            return order.external_id || '';
            
        // Customer Info
        case 'customer_name':
            // Priority: order.name (from address) -> customer.full_name -> address fields
            let customerName = '';
            if (order.name && order.name.trim()) {
                customerName = order.name.trim();
            } else if (order.customer && order.customer.full_name && order.customer.full_name.trim()) {
                customerName = order.customer.full_name.trim();
            } else {
                // Fallback to address fields
                const firstName = order.address_first_name || '';
                const lastName = order.address_last_name || '';
                customerName = (firstName + ' ' + lastName).trim();
            }
            if (!customerName) {
                return '<span class="table-text-small">N/A</span>';
            }
            
            // Make customer name clickable if customer_id exists
            if (order.customer_id && order.customer_id !== 'N/A' && order.customer_id !== null) {
                // Aug-2026 — empty slot for the "location pin waiting" badge. It is
                // filled by paintPinPendingBadges() once the map arrives, rather
                // than re-rendering the table (which would drop checkbox state) or
                // making all three order-list payloads carry the flag.
                return `<div class="table-text-primary"><span class="customer-name-link text-blue-600 hover:text-blue-800 hover:underline font-medium cursor-pointer" onclick="openCustomerDetails(${order.customer_id})" title="View customer details">${customerName}</span><span class="pin-pending-slot" data-cust="${order.customer_id}"></span></div>`;
            } else {
                return `<div class="table-text-primary">${customerName}</div>`;
            }
        case 'contact_email':
            return order.contact_email || '';
        case 'customer_phone':
            const phone = order.customer_phone || order.address_phone || '';
            return phone ? `<div class="table-text-secondary">${phone}</div>` : '<span class="table-text-small">N/A</span>';
            
        // Address Info
        case 'address_first_name':
            // Show full name from address fields
            const addrFirstName = order.address_first_name || '';
            const addrLastName = order.address_last_name || '';
            const addrFullName = (addrFirstName + ' ' + addrLastName).trim();
            return addrFullName || '';
        case 'address_email':
            return order.address_email || '';
        case 'address_phone':
            return order.address_phone || '';
        case 'address_city':
            return order.address_city || '';
        case 'address_province':
            return order.address_province || '';
        case 'address_country':
            return order.address_country || '';
        case 'address_last_name':
            return order.address_last_name || '';
        case 'address_full_name':
            const fullAddrFirstName = order.address_first_name || '';
            const fullAddrLastName = order.address_last_name || '';
            const fullAddrName = (fullAddrFirstName + ' ' + fullAddrLastName).trim();
            return fullAddrName || '';
        case 'address1':
            // Show full wrapped address
            const addressParts = [];
            if (order.address_line1) addressParts.push(order.address_line1);
            if (order.address_line2) addressParts.push(order.address_line2);
            if (order.address_city) addressParts.push(order.address_city);
            if (order.address_province) addressParts.push(order.address_province);
            
            if (addressParts.length === 0) return '<span class="table-text-small">N/A</span>';
            
            const fullAddress = addressParts.join(', ');
            
            return `<div style="max-width: 240px; line-height: 1.4;">
                        <div class="text-xs text-gray-700">${fullAddress}</div>
                    </div>`;
        case 'address2':
            const addr2 = order.address_line2 || '';
            return addr2 ? `<div style="max-width: 200px; line-height: 1.4;"><div class="text-xs text-gray-700">${addr2}</div></div>` : '';
        case 'postal_code':
            return order.postal_code || '';
            
        // Financial Info
        case 'currency':
            return order.currency || 'PKR';
        case 'subtotal_price':
            return formatCurrency(order.subtotal_price);
        case 'discount_total':
            return formatCurrency(order.discount_total);
        case 'shipping_total':
            return formatCurrency(order.shipping_total);
        case 'total_price': {
            // S1b (2026-07): clean money format "Rs 11,140" — comma-grouped, drops
            // trailing .00 for whole amounts but KEEPS decimals when present (never
            // misstate money). Self-contained (no dependency on the scope-shadowed
            // formatCurrency); only this cell's display changes.
            const _n = parseFloat(order.total_price) || 0;
            const _s = Number.isInteger(_n)
                ? _n.toLocaleString('en-US')
                : _n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
            return `<div class="table-cell-total">Rs ${_s}</div>`;
        }
        case 'total_weight':
            return order.total_weight || '0';
            
        // Payment & Other Info
        case 'payment_method':
            const paymentMethod2 = order.payment_method || 'cash';
            const normalizedMethod2 = paymentMethod2.toLowerCase().trim();
            
            // Determine display text and styling
            let displayText2 = 'Cash';
            let pmConfig2 = { bg: 'bg-green-50', border: 'border-green-300', text: 'text-green-800' };
            
            if (normalizedMethod2.includes('online') || normalizedMethod2.includes('bank') || normalizedMethod2.includes('card')) {
                displayText2 = 'Online';
                pmConfig2 = { bg: 'bg-purple-50', border: 'border-purple-300', text: 'text-purple-800' };
            } else if (normalizedMethod2.includes('cash') || normalizedMethod2.includes('cod')) {
                displayText2 = 'Cash';
                pmConfig2 = { bg: 'bg-green-50', border: 'border-green-300', text: 'text-green-800' };
            }
            
            // Shopify approval queue (Jul-2026): payment method LOCKED until converted
            // (staging ids collide with production ids — see the other renderer copy).
            if (currentOrderSource() === 'shopify') {
                return `<div class="order-payment-method-cell"><span class="inline-flex items-center px-2 py-1 rounded ${pmConfig2.bg} ${pmConfig2.border} border ${pmConfig2.text} text-xs font-medium opacity-75" title="Payment method is locked until the order is converted">${displayText2} <span class="ml-1">🔒</span></span></div>`;
            }

            // Check if quick payment method change should be disabled (delivered orders with ledger)
            const hasLedgerForPM2 = order.ledger_transaction_id && order.ledger_transaction_id > 0;
            const isDeliveredForPM2 = order.order_status === 'delivered';
            const restrictPMChange2 = hasLedgerForPM2 && isDeliveredForPM2;

            if (restrictPMChange2) {
                // Show non-clickable badge with lock indicator
                return `<div class="order-payment-method-cell"><span class="inline-flex items-center px-2 py-1 rounded ${pmConfig2.bg} ${pmConfig2.border} border ${pmConfig2.text} text-xs font-medium opacity-75" title="Payment method change restricted for delivered orders with ledger entry">${displayText2} <span class="ml-1">🔒</span></span></div>`;
            }
            
            return `<div class="order-payment-method-cell"><button type="button" onclick="event.stopPropagation(); openQuickPaymentMethodChange(${order.id}, '${paymentMethod2}')" class="inline-flex items-center px-2 py-1 rounded ${pmConfig2.bg} ${pmConfig2.border} border ${pmConfig2.text} text-xs font-medium hover:opacity-80 cursor-pointer transition" title="Click to change payment method">${displayText2}</button></div>`;
        case 'coupon_code':
            return order.coupon_code || '';
        case 'note':
            const note = order.note || '';
            return `<div class="table-cell-note" title="${note}">${note}</div>`;
        // Line Items
        case 'line_items_count':
            const itemCount = order.line_items ? order.line_items.length : 0;
            return `<div class="text-center">
                        <span class="text-sm font-medium text-blue-600 cursor-pointer hover:text-blue-800 hover:underline transition-colors" onclick="viewOrderDetails(${order.id})" title="Click to view order details">
                            ${itemCount}
                        </span>
                        <div class="text-xs text-gray-400 mt-0.5">items</div>
                    </div>`;
            
        // Timestamps
        case 'created_at':
            return formatDate(order.created_at);
        case 'updated_at':
            return formatDate(order.updated_at);
            
        // Rider columns
        case 'rider_id':
            const riderId = order.assigned_rider_user_id;
            if (riderId == null || riderId === undefined) {
                return '<span class="text-gray-400 text-xs">-</span>';
            }
            return `<span class="text-gray-900 font-mono text-xs font-semibold">${riderId}</span>`;
        case 'rider':
            const rid = order.assigned_rider_user_id || order.rider_user_id || null;
            const rname = order.rider_name || (order.assigned_rider && (order.assigned_rider.fullname || order.assigned_rider.name)) || null;
            
            // Check if quick rider assignment should be disabled (delivered orders with ledger)
            const hasLedgerForRider = order.ledger_transaction_id && order.ledger_transaction_id > 0;
            const isDeliveredForRider = order.order_status === 'delivered';
            const restrictRiderChange = hasLedgerForRider && isDeliveredForRider;
            
            if (restrictRiderChange) {
                // Show non-clickable badge with lock indicator
                if (!rname && rid) {
                    return `<span class="inline-flex items-center px-2 py-1 rounded bg-amber-50 text-amber-800 border border-amber-300 text-xs font-medium opacity-75" title="Rider assignment restricted for delivered orders with ledger entry">User #${rid} <span class="ml-1">🔒</span></span>`;
                }
                if (!rname && !rid) {
                    return `<span class="inline-flex items-center px-2 py-1 rounded bg-gray-100 text-gray-700 text-xs opacity-75" title="Rider assignment restricted for delivered orders with ledger entry">Unassigned <span class="ml-1">🔒</span></span>`;
                }
                return `<span class="inline-flex items-center px-2 py-1 rounded bg-blue-50 text-blue-800 border border-blue-300 text-xs font-medium opacity-75" title="Rider assignment restricted for delivered orders with ledger entry">${String(rname)} <span class="ml-1">🔒</span></span>`;
            }
            
            // GUARANTEED FALLBACK: If we have an ID but no name, show "User #ID" in amber (clickable)
            if (!rname && rid) {
                return `<button type="button" onclick="event.stopPropagation(); openQuickRiderAssign(${order.id}, ${rid}, 'User #${rid}')" class="inline-flex items-center px-2 py-1 rounded bg-amber-50 text-amber-800 border border-amber-300 text-xs font-medium hover:bg-amber-100 cursor-pointer transition" title="Click to assign rider">User #${rid}</button>`;
            }
            
            // No rider assigned at all (clickable)
            if (!rname && !rid) {
                return `<button type="button" onclick="event.stopPropagation(); openQuickRiderAssign(${order.id}, null, 'Unassigned')" class="inline-flex items-center px-2 py-1 rounded bg-gray-100 text-gray-700 text-xs hover:bg-gray-200 cursor-pointer transition" title="Click to assign rider">Unassigned</button>`;
            }
            
            // We have a name - show it in blue (clickable)
            return `<button type="button" onclick="event.stopPropagation(); openQuickRiderAssign(${order.id}, ${rid}, '${String(rname).replace(/'/g, "\\'")}')" class="inline-flex items-center px-2 py-1 rounded bg-blue-50 text-blue-800 border border-blue-300 text-xs font-medium hover:bg-blue-100 cursor-pointer transition" title="Click to change rider">${String(rname)}</button>`;
        // Delivery Region
        case 'delivery_region':
            const regionName = order.delivery_region_name;
            const regionId = order.delivery_region_id;
            if (regionName) {
                return `<button type="button" onclick="event.stopPropagation(); openQuickRegionChange(${order.id}, ${regionId})" class="inline-flex items-center px-2 py-1 rounded bg-indigo-50 text-indigo-800 border border-indigo-300 text-xs font-medium hover:bg-indigo-100 cursor-pointer transition" title="Click to change region">${regionName}</button>`;
            }
            return `<button type="button" onclick="event.stopPropagation(); openQuickRegionChange(${order.id}, null)" class="inline-flex items-center px-2 py-1 rounded bg-gray-100 text-gray-500 text-xs hover:bg-gray-200 cursor-pointer transition" title="Click to assign region">No region</button>`;

        // Actions
        case 'actions':
            // Only show approve/ignore for orders in the approval queue tab
            const isInApprovalQueue = window.currentSource === 'shopify' && (order.external_source === 'shopify' || order.external_source === 'khaas_storage');
            
            if (isInApprovalQueue) {
                // For Shopify orders, check if already converted/approved
                const isConverted = order.converted && order.converted !== 0 && order.converted !== 3;
                const isIgnored = order.converted === 2;
                // Jun-2026: "options received" marker — the customer's latest WhatsApp
                // button reply (Confirm/Split/Cancel). Tooltip shows the exact text;
                // the full reply also appears in the order detail/approve modal.
                let replyMarker = '';
                if (order.customer_reply && order.customer_reply.text) {
                    const _escRt = s => String(s||'').replace(/[<>&"]/g, c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;'}[c]));
                    const _rt = String(order.customer_reply.text);
                    const _short = _rt.length > 28 ? _rt.slice(0, 26) + '…' : _rt;
                    // Show the EXACT choice on the chip (e.g. "Split: Chicken Wed / Meat Thu"),
                    // full text in the tooltip — a button action needs to be read, not guessed.
                    replyMarker = `<span title="Customer chose: ${_escRt(_rt)}" style="display:inline-flex;align-items:center;gap:3px;padding:2px 7px;background:#dcfce7;border:1px solid #86efac;border-radius:10px;font-size:10px;color:#166534;font-weight:700;cursor:help;white-space:nowrap;max-width:190px;overflow:hidden;text-overflow:ellipsis;">💬 ${_escRt(_short)}</span>`;
                }

                if (isConverted || isIgnored) {
                    // Already processed - show only view details
                    return `
                        <div class="action-buttons flex items-center gap-1">
                            ${replyMarker}
                            <button onclick="event.stopPropagation(); viewOrderDetails(${order.id})" class="inline-flex items-center justify-center w-7 h-7 text-blue-600 bg-blue-50 border border-blue-200 rounded hover:bg-blue-100 hover:border-blue-300 transition-all duration-200" title="View Order Details">
                                <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"/></svg>
                            </button>
                            ${sendInvoiceButtonHtml(order)}
                        </div>`;
                } else {
                    // Pending approval - show approve/ignore/view
                return `
                    <div class="action-buttons flex items-center gap-1">
                        ${replyMarker}
                        <button onclick="event.stopPropagation(); convertOrder(${order.id})" class="inline-flex items-center justify-center w-7 h-7 text-emerald-600 bg-emerald-50 border border-emerald-200 rounded hover:bg-emerald-100 hover:border-emerald-300 transition-all duration-200" title="Approve (Convert)">
                            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"/></svg>
                        </button>
                        <button onclick="event.stopPropagation(); ignoreOrder(${order.id})" class="inline-flex items-center justify-center w-7 h-7 text-rose-600 bg-rose-50 border border-rose-200 rounded hover:bg-rose-100 hover:border-rose-300 transition-all duration-200" title="Ignore">
                            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/></svg>
                        </button>
                        <button onclick="event.stopPropagation(); viewOrderDetails(${order.id})" class="inline-flex items-center justify-center w-7 h-7 text-blue-600 bg-blue-50 border border-blue-200 rounded hover:bg-blue-100 hover:border-blue-300 transition-all duration-200" title="View Order Details">
                            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"/></svg>
                        </button>
                    </div>`;
            }
            }
            
            // Default full actions for non-Shopify orders (webapp, manual, etc.)
            // ⭐ 3 action buttons: View Details, Invoice, WhatsApp
            return `
                <div class="action-buttons flex items-center gap-1">
                    <button onclick="event.stopPropagation(); viewOrderDetails(${order.id})" class="inline-flex items-center justify-center w-7 h-7 text-blue-600 bg-blue-50 border border-blue-200 rounded hover:bg-blue-100 hover:border-blue-300 transition-all duration-200" title="View Order Details">
                        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"/></svg>
                    </button>
                    <button onclick="event.stopPropagation(); openInBackground(ordersInvoiceUrl(${order.id}))" class="inline-flex items-center justify-center w-7 h-7 text-emerald-600 bg-emerald-50 border border-emerald-200 rounded hover:bg-emerald-100 hover:border-emerald-300 transition-all duration-200" title="View Invoice (PDF)">
                        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
                    </button>
                    ${sendInvoiceButtonHtml(order)}
                    ${window.nfSplitButtonHtml ? window.nfSplitButtonHtml(order) : ''}
                </div>`;
        default:
            return '';
        }
    } catch (error) {
        console.error(`Error in getCellContent for column ${columnId}:`, error, order);
        return `<span class="text-red-500">Error</span>`;
    }
}

// ==================== END COLUMN CUSTOMIZATION ====================

// ==================== SEARCH AND FILTER FUNCTIONALITY ====================

window.allOrders = []; // Store all orders for filtering
window.filteredOrders = []; // Store filtered results
// Initialize search and filters
document.addEventListener('DOMContentLoaded', function() {
    // Store original data from current page only
    window.allOrders = [...window.ordersData];
    window.filteredOrders = [...window.ordersData];
    
    // Initialize status filter with current data
    initStatusFilter();
    
    // Initialize month filter dropdowns
    initMonthFilters();
    
    // Initialize status cards if on open orders tab
    const currentTab = new URLSearchParams(window.location.search).get('tab');
    const currentSource = new URLSearchParams(window.location.search).get('source');
    
    // Restore date filter mode from URL
    const urlParams = new URLSearchParams(window.location.search);
    if (urlParams.get('order_month') || urlParams.get('delivery_month')) {
        setDateFilterMode('month', false);
        if (urlParams.get('order_month')) {
            document.getElementById('orderMonthFilter').value = urlParams.get('order_month');
        }
        if (urlParams.get('delivery_month')) {
            document.getElementById('deliveryMonthFilter').value = urlParams.get('delivery_month');
        }
    }
    
    // Load status cards for open orders tab
    const statusCardsSection = document.getElementById('openOrdersStatusCards');
    if (statusCardsSection) {
        const isVisible = statusCardsSection.style.display !== 'none' && 
                         statusCardsSection.offsetParent !== null;
        
        if ((currentSource === 'other' && currentTab === 'open') || isVisible) {
            console.log('Initializing status cards on page load...'); // Debug log
            setTimeout(() => {
                loadOpenOrdersStatusCards();
            }, 200);
        }
    }

    // Rider Live Board — show on initial load if we're on the Open Orders tab.
    setTimeout(() => { updateRiderLiveBoardVisibility(); }, 250);
    
    // Load rider cards for riders tab
    const ridersCardsSection = document.getElementById('ridersCards');
    if (ridersCardsSection) {
        const isVisible = ridersCardsSection.style.display !== 'none' && 
                         ridersCardsSection.offsetParent !== null;
        
        if ((currentSource === 'other' && currentTab === 'riders') || isVisible) {
            console.log('Initializing rider cards on page load...'); // Debug log
            setTimeout(() => {
                loadRiderCards();
            }, 200);
        }
    }
    
    // Set up search with debouncing
    const searchInput = document.getElementById('orderSearch');
    const statusFilter = document.getElementById('statusFilter');
    const dateFilter = document.getElementById('dateFilter');
    const deliveryDateFilter = document.getElementById('deliveryDateFilter');
    const orderMonthFilter = document.getElementById('orderMonthFilter');
    const deliveryMonthFilter = document.getElementById('deliveryMonthFilter');
    
    let searchTimeout;
    
    // Search functionality - make API call for full dataset
    searchInput.addEventListener('input', function() {
        clearTimeout(searchTimeout);
        searchTimeout = setTimeout(() => {
            const searchTerm = searchInput.value.trim();
            if (searchTerm.length > 2) {
                fetchFilteredOrders();
            } else if (searchTerm.length === 0) {
                // Auto-clear when search box is empty
                clearFilters();
            } else {
                // Reset to current page data if search is too short but not empty
                window.filteredOrders = [...window.ordersData];
                window.searchPage = 1;
                applyFilteredRender();
            }
        }, 300); // Reduced timeout for better responsiveness
    });
    
    // Filter functionality - reload page with filter parameters to preserve pagination
    statusFilter.addEventListener('change', function() {
        applyFiltersToUrl();
    });
    
    dateFilter.addEventListener('change', function() { applyFiltersToUrl(); });
    if (deliveryDateFilter) deliveryDateFilter.addEventListener('change', function() { applyFiltersToUrl(); });
    
    // Month filter event listeners
    if (orderMonthFilter) orderMonthFilter.addEventListener('change', function() { applyFiltersToUrl(); });
    if (deliveryMonthFilter) deliveryMonthFilter.addEventListener('change', function() { applyFiltersToUrl(); });
    
    // Per-page selector functionality
    const perPageSelector = document.getElementById('per-page-selector');
    if (perPageSelector) {
        perPageSelector.addEventListener('change', function() {
            // NF: If a search is active, re-paginate client-side instead of reloading
            // (a reload would drop the search term and go back to the full dataset).
            const activeSearch = ((document.getElementById('orderSearch') || {}).value || '').trim();
            if (activeSearch.length > 2 && typeof applyFilteredRender === 'function') {
                window.searchPage = 1;
                applyFilteredRender();
                return;
            }
            const perPage = this.value;
            const currentUrl = new URL(window.location.href);
            currentUrl.searchParams.set('per_page', perPage);
            currentUrl.searchParams.set('page', '1'); // Reset to first page
            window.location.href = currentUrl.toString();
        });
    }
});

    // Auto-open Import modal when requested via query param
    try {
        const params = new URLSearchParams(window.location.search);
        if (params.get('open') === 'import') {
            if (typeof openImportModal === 'function') {
                setTimeout(() => openImportModal(), 200);
            }
        }
    } catch (e) {
        console.warn('Failed to process open=import param', e);
    }
// Initialize month filter dropdowns with last 12 months
function initMonthFilters() {
    const orderMonthFilter = document.getElementById('orderMonthFilter');
    const deliveryMonthFilter = document.getElementById('deliveryMonthFilter');
    
    if (!orderMonthFilter || !deliveryMonthFilter) return;
    
    const months = [];
    const now = new Date();
    
    for (let i = 0; i < 12; i++) {
        const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
        const value = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
        const label = d.toLocaleDateString('en-US', { month: 'short', year: 'numeric' });
        months.push({ value, label });
    }
    
    const optionsHtml = '<option value="">All months</option>' + 
        months.map(m => `<option value="${m.value}">${m.label}</option>`).join('');
    
    orderMonthFilter.innerHTML = optionsHtml;
    deliveryMonthFilter.innerHTML = optionsHtml;
}

// Set date filter mode (date or month)
window.dateFilterMode = 'date';
function setDateFilterMode(mode, applyFilter = false) {
    window.dateFilterMode = mode;
    
    const dateFiltersContainer = document.getElementById('dateFiltersContainer');
    const monthFiltersContainer = document.getElementById('monthFiltersContainer');
    const dateBtn = document.getElementById('dateModeDateBtn');
    const monthBtn = document.getElementById('dateModeMonthBtn');
    
    if (mode === 'month') {
        dateFiltersContainer.classList.add('hidden');
        monthFiltersContainer.classList.remove('hidden');
        dateBtn.classList.remove('bg-white', 'shadow');
        dateBtn.classList.add('text-gray-600');
        monthBtn.classList.add('bg-white', 'shadow');
        monthBtn.classList.remove('text-gray-600');
        
        // Clear date filters when switching to month mode (but don't reload)
        document.getElementById('dateFilter').value = '';
        document.getElementById('deliveryDateFilter').value = '';
    } else {
        dateFiltersContainer.classList.remove('hidden');
        monthFiltersContainer.classList.add('hidden');
        dateBtn.classList.add('bg-white', 'shadow');
        dateBtn.classList.remove('text-gray-600');
        monthBtn.classList.remove('bg-white', 'shadow');
        monthBtn.classList.add('text-gray-600');
        
        // Clear month filters when switching to date mode (but don't reload)
        document.getElementById('orderMonthFilter').value = '';
        document.getElementById('deliveryMonthFilter').value = '';
    }
    
    // Only apply filters to URL if explicitly requested (e.g., when clearing filters)
    // Switching modes should NOT trigger a page reload - user needs to select a value first
    if (applyFilter) {
        applyFiltersToUrl();
    }
}

// Apply filters to URL and reload page (for status, date, and month filters)
// This preserves proper server-side pagination
function applyFiltersToUrl() {
    const statusFilter = document.getElementById('statusFilter').value;
    const dateFilter = document.getElementById('dateFilter').value;
    const deliveryDateFilter = document.getElementById('deliveryDateFilter') ? document.getElementById('deliveryDateFilter').value : '';
    const orderMonthFilter = document.getElementById('orderMonthFilter') ? document.getElementById('orderMonthFilter').value : '';
    const deliveryMonthFilter = document.getElementById('deliveryMonthFilter') ? document.getElementById('deliveryMonthFilter').value : '';
    
    const currentUrl = new URL(window.location);
    
    // Update status filter
    if (statusFilter) {
        currentUrl.searchParams.set('status', statusFilter);
    } else {
        currentUrl.searchParams.delete('status');
    }
    
    // Date filters
    if (dateFilter) currentUrl.searchParams.set('date', dateFilter); else currentUrl.searchParams.delete('date');
    if (deliveryDateFilter) currentUrl.searchParams.set('delivery_date', deliveryDateFilter); else currentUrl.searchParams.delete('delivery_date');
    
    // Month filters
    if (orderMonthFilter) currentUrl.searchParams.set('order_month', orderMonthFilter); else currentUrl.searchParams.delete('order_month');
    if (deliveryMonthFilter) currentUrl.searchParams.set('delivery_month', deliveryMonthFilter); else currentUrl.searchParams.delete('delivery_month');
    
    // Reset to page 1 when filters change
    currentUrl.searchParams.set('page', '1');
    
    // Reload page with new parameters
    window.location.href = currentUrl.toString();
}

// Fetch filtered orders from backend (for search only - returns up to 100 results)
function fetchFilteredOrders() {
    const searchTerm = document.getElementById('orderSearch').value.trim();
    const statusFilter = document.getElementById('statusFilter').value;
    const dateFilter = document.getElementById('dateFilter').value;
    const deliveryDateFilter = document.getElementById('deliveryDateFilter') ? document.getElementById('deliveryDateFilter').value : '';
    
    // Show loading state
    showLoadingState();
    
    // Build query parameters
    const params = new URLSearchParams();
    if (searchTerm) params.append('search', searchTerm);
    if (statusFilter) params.append('status', statusFilter);
    if (dateFilter) params.append('date', dateFilter);
    if (deliveryDateFilter) params.append('delivery_date', deliveryDateFilter);
    
    // Get current source (shopify/other)
    const currentUrl = new URL(window.location);
    const source = currentUrl.searchParams.get('source') || 'other';
    params.append('source', source);
    // NF (Jul-2026): scope the search to the CURRENT tab. Without this the search
    // dropped the tab and searched ALL orders even while on Open Orders. The
    // backend filter() honours ?tab=open|riders (excludes delivered/completed/
    // cancelled/refunded + qurbani), so passing it makes search match the tab.
    const tab = window.currentTab || currentUrl.searchParams.get('tab') || 'all';
    params.append('tab', tab);

    // Make API call
    fetch(`/orders/filter?${params.toString()}`, {
        method: 'GET',
        headers: {
            'Content-Type': 'application/json',
            'X-Requested-With': 'XMLHttpRequest'
        }
    })
    .then(response => response.json())
    .then(data => {
        if (data.success) {
            window.filteredOrders = data.orders;
            window.searchPage = 1; // new result set → start at first page
            applyFilteredRender();
        } else {
            console.error('Filter error:', data.message);
            // Show empty state instead of fallback data when search fails
            window.filteredOrders = [];
            window.searchPage = 1;
            applyFilteredRender();
        }
    })
    .catch(error => {
        console.error('Filter request failed:', error);
        // Show empty state instead of fallback data when search fails
        window.filteredOrders = [];
        window.searchPage = 1;
        applyFilteredRender();
    })
    .finally(() => {
        hideLoadingState();
    });
}

// Apply all filters and search (legacy function - keeping for compatibility)
function applyFilters() {
    // Show loading state
    showLoadingState();
    
    // Small delay to show loading animation
    setTimeout(() => {
        const searchTerm = document.getElementById('orderSearch').value.toLowerCase();
        const statusFilter = document.getElementById('statusFilter').value;
        const dateFilter = document.getElementById('dateFilter').value;
        
        window.filteredOrders = window.allOrders.filter(order => {
        // Search filter
        const matchesSearch = !searchTerm || 
            (order.customer && order.customer.name && order.customer.name.toLowerCase().includes(searchTerm)) ||
            (order.order_number && order.order_number.toLowerCase().includes(searchTerm)) ||
            (order.customer && order.customer.phone && order.customer.phone.includes(searchTerm)) ||
            (order.customer && order.customer.email && order.customer.email.toLowerCase().includes(searchTerm));
        
        // Status filter
        const matchesStatus = !statusFilter || 
            (order.order_status && order.order_status.toLowerCase() === statusFilter);
        
        // Date filter
        const matchesDate = !dateFilter || 
            (order.order_date && order.order_date.startsWith(dateFilter));
        
        return matchesSearch && matchesStatus && matchesDate;
    });
    
        // Update the display
        renderOrdersWithFilters(window.filteredOrders);
        updateResultsCount();
        hideLoadingState();
    }, 100);
}

// Update results count display
function updateResultsCount() {
    const totalCount = window.allOrders.length;
    const filteredCount = window.filteredOrders.length;
    
    // Update our custom results count element
    const resultsElement = document.getElementById('results-count');
    if (resultsElement) {
        if (filteredCount === totalCount) {
            resultsElement.textContent = `Showing ${filteredCount} orders`;
        } else {
            resultsElement.textContent = `Showing ${filteredCount} of ${totalCount} orders`;
        }
    }
    
    // Also update pagination info if it exists
    const infoElement = document.querySelector('[data-kt-datatable-info="true"]');
    if (infoElement) {
        infoElement.textContent = `${filteredCount} orders`;
    }
    
    // Update pagination info element (for search results only)
    const paginationInfo = document.getElementById('pagination-info');
    if (paginationInfo) {
        paginationInfo.textContent = `Showing ${filteredCount} search results`;
    }
    
    // Hide pagination controls when showing search results (limited to 100)
    const pagerWrap = document.getElementById('pager-wrap');
    const numericPager = document.getElementById('numeric-pager');
    
    // Only hide pagination for search results (not for status/date filters)
    const searchTerm = document.getElementById('orderSearch').value.trim();
    
    if (searchTerm.length > 2 && pagerWrap) {
        // Hide pagination when showing search results (not paginated, max 100)
        pagerWrap.style.display = 'none';
        if (numericPager) numericPager.style.display = 'none';
    } else if (pagerWrap) {
        // Show pagination for normal view and filtered views
        pagerWrap.style.display = '';
        if (numericPager) numericPager.style.display = '';
    }
}

/* NF: Client-side pagination for search results.
   Backend caps search at 100 matches (single request). We used to dump them all into the table and hide the pager,
   which left users with no way to navigate. This slices window.filteredOrders by the per-page-selector value
   and rebuilds Previous / numeric / Next buttons on the existing #pager-wrap element.
   Safe: does not touch server-side pagination (used when no search is active). */
window.searchPage = window.searchPage || 1;
function _nfSearchPerPage() {
    const sel = document.getElementById('per-page-selector');
    const v = sel ? parseInt(sel.value, 10) : 25;
    return (isFinite(v) && v > 0) ? v : 25;
}
function applyFilteredRender() {
    const searchTerm = ((document.getElementById('orderSearch') || {}).value || '').trim();
    const list = window.filteredOrders || [];
    if (searchTerm.length <= 2) {
        window.searchPage = 1;
        renderOrdersWithFilters(list);
        updateResultsCount();
        return;
    }
    const perPage = _nfSearchPerPage();
    const total = list.length;
    const totalPages = Math.max(1, Math.ceil(total / perPage));
    if (!Number.isFinite(window.searchPage) || window.searchPage < 1) window.searchPage = 1;
    if (window.searchPage > totalPages) window.searchPage = totalPages;
    const page = window.searchPage;
    const start = (page - 1) * perPage;
    const end = Math.min(start + perPage, total);
    renderOrdersWithFilters(list.slice(start, end));
    // Let updateResultsCount hide the pager first, then we re-show & rebuild it for search mode.
    updateResultsCount();
    const paginationInfo = document.getElementById('pagination-info');
    if (paginationInfo) {
        paginationInfo.textContent = total === 0
            ? '0 search results'
            : `${start + 1}-${end} of ${total} search results`;
    }
    const pagerWrap = document.getElementById('pager-wrap');
    if (pagerWrap) {
        pagerWrap.style.display = '';
        pagerWrap.innerHTML = _nfBuildSearchPagerHtml(totalPages, page);
    }
    const container = document.querySelector('.orders-table-container');
    if (container) container.scrollTop = 0;
}
function _nfBuildSearchPagerHtml(totalPages, current) {
    const navBase = 'px-3 py-2 text-sm bg-white border border-gray-300 rounded-md';
    const navOn = 'text-gray-700 hover:bg-gray-50';
    const navOff = 'text-gray-400 cursor-not-allowed';
    const numBtn = 'px-3 py-2 text-sm text-gray-700 bg-white border border-gray-300 rounded-md hover:bg-gray-50';
    const numActive = 'px-3 py-2 text-sm bg-blue-600 text-white rounded-md font-medium';
    let html = '';
    html += current > 1
        ? `<a href="javascript:void(0)" onclick="goToSearchPage(${current - 1})" class="${navBase} ${navOn}">Previous</a>`
        : `<button type="button" disabled class="${navBase} ${navOff}">Previous</button>`;
    html += '<div class="flex items-center gap-1" id="numeric-pager">';
    const s = Math.max(1, current - 2);
    const e = Math.min(totalPages, current + 2);
    if (s > 1) {
        html += `<a href="javascript:void(0)" onclick="goToSearchPage(1)" class="px-3 py-1.5 text-sm pagination-btn">1</a>`;
        if (s > 2) html += '<span class="px-2 py-1.5 text-sm text-gray-400">...</span>';
    }
    for (let p = s; p <= e; p++) {
        html += (p === current)
            ? `<span class="${numActive}">${p}</span>`
            : `<a href="javascript:void(0)" onclick="goToSearchPage(${p})" class="${numBtn}">${p}</a>`;
    }
    if (e < totalPages) {
        if (e < totalPages - 1) html += '<span class="px-2 py-1.5 text-sm text-gray-400">...</span>';
        html += `<a href="javascript:void(0)" onclick="goToSearchPage(${totalPages})" class="px-3 py-1.5 text-sm pagination-btn">${totalPages}</a>`;
    }
    html += '</div>';
    html += current < totalPages
        ? `<a href="javascript:void(0)" onclick="goToSearchPage(${current + 1})" class="${navBase} ${navOn}">Next</a>`
        : `<button type="button" disabled class="${navBase} ${navOff}">Next</button>`;
    return html;
}
window.goToSearchPage = function(p) {
    window.searchPage = p;
    applyFilteredRender();
};

// Render table with filtered data
function renderOrdersWithFilters(data) {
    // Update the global ordersData
    window.ordersData = data;
    
    if (data.length === 0) {
        showEmptyState();
        // Also clear the table body to ensure nothing shows
        const tbody = document.getElementById('table-body');
        if (tbody) tbody.innerHTML = '';
    } else {
        hideEmptyState();
        renderOrdersTable(); // Re-render the table
    }
}

// Clear all filters
function clearFilters() {
    document.getElementById('orderSearch').value = '';
    document.getElementById('statusFilter').value = '';
    document.getElementById('dateFilter').value = '';
    document.getElementById('deliveryDateFilter').value = '';
    document.getElementById('orderMonthFilter').value = '';
    document.getElementById('deliveryMonthFilter').value = '';
    
    // Reset to date filter mode
    setDateFilterMode('date', false);
    
    // Remove filter parameters from URL and reset to page 1
    const currentUrl = new URL(window.location);
    currentUrl.searchParams.delete('search');
    currentUrl.searchParams.delete('status');
    currentUrl.searchParams.delete('date');
    currentUrl.searchParams.delete('delivery_date');
    currentUrl.searchParams.delete('order_month');
    currentUrl.searchParams.delete('delivery_month');
    currentUrl.searchParams.set('page', '1');
    
    // Navigate to the clean URL to reload with default data
    window.location.href = currentUrl.toString();
}
// Loading state functions
function showLoadingState() {
    const tbody = document.getElementById('table-body');
    const noResults = document.getElementById('no-results-state');
    const loading = document.getElementById('loading-state');
    if (tbody) tbody.style.display = 'none';
    if (noResults) noResults.classList.add('hidden');
    if (loading) loading.classList.remove('hidden');
}

function hideLoadingState() {
    const loading = document.getElementById('loading-state');
    const tbody = document.getElementById('table-body');
    if (loading) loading.classList.add('hidden');
    if (tbody) tbody.style.display = '';
}

function showEmptyState() {
    const tbody = document.getElementById('table-body');
    const loading = document.getElementById('loading-state');
    const noResults = document.getElementById('no-results-state');
    if (tbody) tbody.style.display = 'none';
    if (loading) loading.classList.add('hidden');
    if (noResults) noResults.classList.remove('hidden');
}
function hideEmptyState() {
    const noResults = document.getElementById('no-results-state');
    const tbody = document.getElementById('table-body');
    if (noResults) noResults.classList.add('hidden');
    if (tbody) tbody.style.display = '';
}
