                sel.innerHTML = data.data.map(s => `<option value="${s.status_code}">${s.icon} ${s.status_name}</option>`).join('');
                if (data.data.find(s => s.status_code === 'new')) sel.value = 'new';
            }
        } catch (e) {
            const sel = document.getElementById('createOrderStatus');
