}

// DUPLICATE FUNCTION REMOVED - Original exists at line 1402

// Save new order (with validation)
function saveNewOrder() {
    const form = document.getElementById('editOrderForm');
    const formData = new FormData(form);
    
    // VALIDATE CUSTOMER INFORMATION FIRST
    const existingSection = document.getElementById('existingCustomerSection');
    const newSection = document.getElementById('newCustomerSection');
    
    // Check which mode is active
    const isExistingMode = existingSection && (existingSection.style.display === 'block' || existingSection.style.display === '');
    const isNewMode = newSection && (newSection.style.display === 'block' || newSection.style.display === '');
    
    console.log('Validation check in saveNewOrder:', { isExistingMode, isNewMode });
    
    if (isExistingMode) {
        // Existing customer mode - must have selected a customer
        const customerId = document.getElementById('selectedCustomerId')?.value;
        if (!customerId || customerId === '') {
            alert('Please select an existing customer or switch to "New Customer" mode to create a new one.');
            return;
        }
    } else if (isNewMode) {
        // New customer mode - validate required fields
        const firstName = form.querySelector('input[name="customer_first_name"]')?.value?.trim();
        const lastName = form.querySelector('input[name="customer_last_name"]')?.value?.trim();
        const phone = form.querySelector('input[name="customer_phone"]')?.value?.trim();
        const address1 = form.querySelector('input[name="customer_address1"]')?.value?.trim();
        
        if (!firstName) {
            alert('First Name is required for new customer');
            form.querySelector('input[name="customer_first_name"]')?.focus();
            return;
        }
        if (!lastName) {
            alert('Last Name is required for new customer');
            form.querySelector('input[name="customer_last_name"]')?.focus();
            return;
        }
        if (!phone) {
            alert('Phone Number is required for new customer');
            form.querySelector('input[name="customer_phone"]')?.focus();
            return;
        }
        if (!address1) {
            alert('Address Line 1 is required for new customer');
            form.querySelector('input[name="customer_address1"]')?.focus();
            return;
        }
    } else {
        // Neither mode is visible
        alert('Please select customer information');
        return;
    }
    
    // Collect line items (ignore empty ones)
    const items = [];
    document.querySelectorAll('.line-item').forEach((item, index) => {
        const name = item.querySelector(`input[name*="[name]"]`)?.value?.trim();
        const quantity = parseFloat(item.querySelector(`input[name*="[quantity]"]`)?.value) || 0;
        const unitPrice = parseFloat(item.querySelector(`input[name*="[unit_price]"]`)?.value) || 0;
        const sku = item.querySelector('input[name*="[sku]"]')?.value || null;
        const variantId = item.querySelector('input[name*="[variant_id]"]')?.value || null;
        const productId = item.querySelector('input[name*="[product_id]"]')?.value || null;
        const isFreeInput = item.querySelector('.is-free-input');
        const isFree = isFreeInput && isFreeInput.value === '1';
        
        // Only add items that have a name and valid quantity/price
        if (name && quantity > 0 && unitPrice >= 0) {
            var itemObj = {
                name: name,
                quantity: quantity,
                unit_price: unitPrice,
                line_total: isFree ? 0 : quantity * unitPrice,
                is_free: isFree ? 1 : 0,
                sku: sku,
                variant_id: variantId,
                product_id: productId
            };
            var qDay = item.querySelector('select[name*="qurbani_day"]')?.value;
            var qSlot = item.querySelector('select[name*="qurbani_slot"]')?.value;
            var qRegion = item.querySelector('select[name*="qurbani_region"]')?.value;
            var qDT = item.querySelector('select[name*="qurbani_delivery_type"]')?.value;
            // Suffix-anchored selectors — see note in saveOrderChanges.
            var qType = item.querySelector('select[name$="[qurbani_type]"]')?.value;
            var qPaya = item.querySelector('select[name$="[qurbani_paya]"]')?.value;
            if (qDay) itemObj.qurbani_day = qDay;
            if (qSlot) itemObj.qurbani_slot = qSlot;
            if (qRegion) itemObj.qurbani_region = qRegion;
            if (qDT) itemObj.qurbani_delivery_type = qDT;
            if (qType) itemObj.qurbani_type = qType;
            if (qPaya) itemObj.qurbani_paya = qPaya;
            var instr = item.querySelector('input[name*="instructions"]')?.value;
            itemObj.instructions = instr || '';
            items.push(itemObj);
        }
    });
    
    if (items.length === 0) {
        alert('Please add at least one line item with valid details');
        return;
    }
    
    // Collect discounts
    const discounts = [];
    document.querySelectorAll('.discount-row').forEach((row) => {
        const title = row.querySelector('[name$="[title]"]')?.value || '';
        const amount = parseFloat(row.querySelector('[name$="[amount]"]')?.value) || 0;
        
        // ⭐ Allow discounts with just amount - default title to "Discount" if empty
        if (amount > 0) {
            discounts.push({
                title: title.trim() || 'Discount',
                amount: amount,
                type: 'fixed'
            });
        }
    });
    
    // Prepare data
    const orderData = {
        customer_id: formData.get('customer_id'),
        order_status: formData.get('order_status'),
        order_date: formData.get('order_date') ? formData.get('order_date').replace('T', ' ') + ':00' : getCurrentLocalDateTime().replace('T', ' ') + ':00',
        contact_email: formData.get('contact_email'),
        subtotal_price: parseFloat(formData.get('subtotal_price')) || 0,
        shipping_total: parseFloat(formData.get('shipping_total')) || 0,
        total_price: parseFloat(formData.get('total_price')) || 0,
        payment_method: formData.get('payment_method'),
        // Aug-2026 — tick means "remember this method on the customer". Sent as a
        // real boolean; the server ignores it when no customer resolves.
        set_default_payment_method: formData.get('set_default_payment_method') ? 1 : 0,
        note: formData.get('note'),
        items: items,
        discounts: discounts, // NEW: Include discounts array
        // Customer creation fields
        customer_phone: formData.get('customer_phone'),
        customer_first_name: formData.get('customer_first_name'),
        customer_last_name: formData.get('customer_last_name'),
        customer_address1: formData.get('customer_address1'),
        customer_address2: formData.get('customer_address2'),
        customer_city: formData.get('customer_city'),
        customer_country: formData.get('customer_country')
    };
    
    // Submit to server
    fetch('/orders', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').getAttribute('content'),
            'Accept': 'application/json'
        },
        body: JSON.stringify(orderData)
    })
    .then(response => response.json())
    .then(async data => {
        if (data.success) {
            // 💰 Customer credit: if this customer has a balance, offer to open
            // the new order right away so it can be applied. The balance is
            // re-fetched HERE (not reused from the selection-time hint) so a
            // balance spent in the meantime never produces a stale prompt.
            const newOrderId = data.order?.id;
            const custId = document.getElementById('selectedCustomerId')?.value;
            if (newOrderId && custId) {
                try {
                    const res = await fetch(`/customer-credit/${custId}/summary?limit=1`, {
                        headers: { 'Accept': 'application/json', 'X-Requested-With': 'XMLHttpRequest' },
                        credentials: 'same-origin'
                    });
                    const cj = await res.json();
                    const cd = cj && cj.success ? cj.data : null;
                    if (cd && cd.eligible && cd.has_balance) {
                        if (confirm(`Order created!\n\nThis customer has Rs. ${cd.balance_display} account balance.\nOpen the order now to apply it?`)) {
                            // Reload WITH edit_order_id so the fresh page auto-opens
                            // the edit modal, where the green balance banner offers
                            // the apply. Reusing that one flow keeps a single path.
                            const url = new URL(window.location.href);
                            url.searchParams.set('edit_order_id', newOrderId);
                            // ⚠ id-collision guard: the new order is a PRODUCTION
                            // order — never let a lingering ?source=shopify resolve
                            // its id against the staging table.
                            url.searchParams.delete('source');
                            url.searchParams.delete('tab');
                            window.location.href = url.toString();
                            return;
                        }
                    }
                } catch (e) { /* fall through to the normal flow */ }
            }

            alert('Order created successfully!');
            closeModal('editOrderModal');
            // Refresh the page to show the new order
            location.reload();
        } else {
            alert('Error creating order: ' + data.message);
        }
    })
    .catch(error => {
        console.error('Error:', error);
        alert('Error creating order');
    });
}

// Load default shipping price for order forms
function loadDefaultShippingPrice(modalId = null) {
    const urlParams = new URLSearchParams(window.location.search);
    const isQurbani = urlParams.get('qurbani_mode') === '1';

    const applyPrice = (price) => {
        let shippingInput;
        if (modalId) {
            shippingInput = document.querySelector(`#${modalId} input[name="shipping_total"]`);
        } else {
            shippingInput = document.querySelector('input[name="shipping_total"]');
        }
        if (shippingInput) {
            shippingInput.value = price;
            if (typeof updateOrderTotal === 'function') updateOrderTotal();
        }
    };

    // Pre-select the Payment Method dropdown on the Create-Order form to
    // match the admin's Qurbani default (cash/online). Only runs when
    // qurbani_mode=1 so regular orders keep their historical default.
    // The dropdown's options are 'cash' / 'online' / 'bank_transfer' / 'card';
    // we only nudge it for those two values the qurbani config exposes.
    const applyPaymentMethod = (method) => {
        if (method !== 'cash' && method !== 'online') return;
        let pmSelect;
        if (modalId) {
            pmSelect = document.querySelector(`#${modalId} select[name="payment_method"]`);
        } else {
            pmSelect = document.querySelector('select[name="payment_method"]');
        }
        if (!pmSelect) return;
        // Only override when user hasn't already picked something different
        // (defensive: saveOrderChanges is called immediately after this, so
        // in practice the form is still fresh).
        const optionExists = Array.from(pmSelect.options).some(o => o.value === method);
        if (optionExists) {
            pmSelect.value = method;
            // Clear any stale "selected" attr from the cash hard-default.
            Array.from(pmSelect.options).forEach(o => { o.selected = (o.value === method); });
        }
    };

    if (isQurbani) {
        fetch('/qurbani-settings/api/options', { headers: { 'Accept': 'application/json' } })
            .then(r => r.json())
            .then(data => {
                if (data.success && data.qurbani_shipping_price != null) {
                    applyPrice(data.qurbani_shipping_price);
                }
                if (data.success && data.qurbani_default_payment_method) {
                    applyPaymentMethod(data.qurbani_default_payment_method);
                }
            })
            .catch(() => applyPrice(1000));
    } else {
        fetch('/api/shipping/price')
            .then(response => response.json())
            .then(data => {
                if (data.success && data.shipping_price) applyPrice(data.shipping_price);
            })
            .catch(error => console.log('Could not load default shipping price:', error));
    }
}
// ==================== CUSTOMER SELECTION HELPERS (single source of truth) ====================
let customerSearchTimeout;

function selectCustomerMode(mode) {
    const existingSection = document.getElementById('existingCustomerSection');
    const newSection = document.getElementById('newCustomerSection');
    const existingBtn = document.getElementById('existingCustomerBtn');
    const newBtn = document.getElementById('newCustomerBtn');
    const detailsDiv = document.getElementById('selectedCustomerDetails');

    if (!existingSection || !newSection || !existingBtn || !newBtn) return;

    // Customer credit: the hint belongs to a picked existing customer — a mode
    // switch (or switching to a brand-new customer) makes it stale, so drop it.
    document.getElementById('nfCreateCreditHint')?.remove();

    if (mode === 'existing') {
        existingSection.style.display = '';
        newSection.style.display = 'none';
        existingBtn.style.backgroundColor = '#10b981';
        existingBtn.style.color = '#ffffff';
        existingBtn.style.borderColor = '#10b981';
        newBtn.style.backgroundColor = '#f9fafb';
        newBtn.style.color = '#374151';
        newBtn.style.borderColor = '#d1d5db';
        
        // Focus on search input when switching to existing customer mode
        setTimeout(() => {
            const searchInput = document.getElementById('customerSearch');
            if (searchInput) searchInput.focus();
        }, 100);
    } else {
        existingSection.style.display = 'none';
        newSection.style.display = '';
        newBtn.style.backgroundColor = '#10b981';
        newBtn.style.color = '#ffffff';
        newBtn.style.borderColor = '#10b981';
        existingBtn.style.backgroundColor = '#f9fafb';
        existingBtn.style.color = '#374151';
        existingBtn.style.borderColor = '#d1d5db';
        
        // Hide customer details when switching to new customer mode
        if (detailsDiv) detailsDiv.style.display = 'none';
        
        // Clear search input and selected customer
        const searchInput = document.getElementById('customerSearch');
        const hiddenId = document.getElementById('selectedCustomerId');
        if (searchInput) searchInput.value = '';
        if (hiddenId) hiddenId.value = '';
    }
}

function showCustomerDropdown() {
    const dd = document.getElementById('customerDropdown');
    if (dd) dd.style.display = 'block';
}

function hideCustomerDropdown() {
    const dd = document.getElementById('customerDropdown');
