        if (toggleBtn) {
            toggleBtn.innerHTML = '<span id="toggleHistoryIcon">▼</span> Show';
            toggleBtn.style.background = '#6b7280';
        }
    }
}

function searchCustomersForEdit(inputEl) {
    const query = (inputEl && inputEl.value) ? inputEl.value.trim() : '';
    clearTimeout(customerSearchTimeout);
    if (!query) { hideEditCustomerDropdown(); return; }

    customerSearchTimeout = setTimeout(function() {
        fetch('/api/customers/search?q=' + encodeURIComponent(query) + '&limit=10', {
            headers: { 'Accept': 'application/json' }
        })
        .then(function(r) { return r.json(); })
        .then(function(data) {
            const customers = (data && data.success && data.customers) ? data.customers : [];
            showEditCustomerResults(customers);
        })
        .catch(function() {});
    }, 250);
}

function showEditCustomerResults(customers) {
    const dd = document.getElementById('editCustomerDropdown');
    if (!dd) return;
    if (!customers || customers.length === 0) { 
        dd.innerHTML = '<div style="padding:8px;color:#6b7280;font-size:12px;">No customers found</div>'; 
        showEditCustomerDropdown(); 
        return; 
    }

    // Store customers globally for access
    window.editCustomerResults = customers;

    let html = '';
    customers.forEach((c, idx) => {
        const addressParts = [];
        if (c.address && c.address.address1) addressParts.push(c.address.address1);
        if (c.address && c.address.city) addressParts.push(c.address.city);
        const addressStr = addressParts.length > 0 ? addressParts.join(', ') : 'No address';
        
        const safeName = escapeHtml(c.name || '');
        const safePhone = escapeHtml(c.phone || 'No phone');
        const safeAddress = escapeHtml(addressStr);
        
        html += `
            <div onclick="selectEditCustomer(${idx})" 
                 style="padding:10px; cursor:pointer; border-bottom:1px solid #f3f4f6; font-size:13px;">
                <div style="font-weight:500; color:#111827;">${safeName}</div>
                <div style="font-size:11px; color:#6b7280; margin-top:2px;">${safePhone} • ${safeAddress}</div>
            </div>
        `;
    });
    
    dd.innerHTML = html;
    showEditCustomerDropdown();
}

function showEditCustomerDropdown() {
    const dd = document.getElementById('editCustomerDropdown');
    if (dd) dd.style.display = 'block';
}

function hideEditCustomerDropdown() {
    const dd = document.getElementById('editCustomerDropdown');
    if (dd) dd.style.display = 'none';
}

function selectEditCustomer(customerIndex) {
    try {
        // Get customer from global storage
        if (!window.editCustomerResults || !window.editCustomerResults[customerIndex]) {
            console.error('Customer not found at index:', customerIndex);
            alert('Error: Customer data not found');
            return;
        }
        
        const customer = window.editCustomerResults[customerIndex];
        console.log('Selected customer:', customer);
        
        // ✅ CRITICAL: Update customer_id hidden field
        const customerIdField = document.getElementById('editCustomerId');
        if (customerIdField) {
            customerIdField.value = customer.id || '';
            console.log('Set customer_id to:', customer.id);
        }
        
        // Update all customer fields
        if (customer.address) {
            const firstNameField = document.getElementById('editAddressFirstName');
            const lastNameField = document.getElementById('editAddressLastName');
            const emailField = document.getElementById('editAddressEmail');
            const phoneField = document.getElementById('editAddressPhone');
            const line1Field = document.getElementById('editAddressLine1');
            const line2Field = document.getElementById('editAddressLine2');
            const cityField = document.getElementById('editAddressCity');
            const countryField = document.getElementById('editAddressCountry');
            
            if (firstNameField) firstNameField.value = customer.address.first_name || '';
            if (lastNameField) lastNameField.value = customer.address.last_name || '';
            if (emailField) emailField.value = customer.address.email || '';
            if (phoneField) phoneField.value = customer.address.phone || customer.phone || '';
            if (line1Field) line1Field.value = customer.address.address1 || '';
            if (line2Field) line2Field.value = customer.address.address2 || '';
            if (cityField) cityField.value = customer.address.city || '';
            if (countryField) countryField.value = customer.address.country || 'Pakistan';
        }
        
        // Update customer name field if it exists
        const customerNameField = document.querySelector('input[name="customer_name"]');
        if (customerNameField) customerNameField.value = customer.name || '';
        
        // ⭐ ALSO update the order's `name` field (which stores customer name on the order itself)
        // This ensures the order table shows the correct customer name immediately
        const orderNameField = document.getElementById('editOrderName');
        if (orderNameField) {
            orderNameField.value = customer.name || '';
            console.log('Updated order name field to:', customer.name);
        }
        
        // Update the pop-out summary bar if it exists
        const summaryBar = document.getElementById('orderDetailsSummary');
        if (summaryBar) {
            const newName = customer.name || ((customer.address?.first_name || '') + ' ' + (customer.address?.last_name || '')).trim() || 'N/A';
            const newPhone = customer.address?.phone || customer.phone || 'N/A';
            const addrParts = [customer.address?.address1, customer.address?.city].filter(Boolean);
            const newAddress = addrParts.length > 0 ? addrParts.join(', ') : 'N/A';
            
            const nameEl = summaryBar.querySelectorAll('div[style*="font-weight: 600"][style*="color: #0c4a6e"]')[0];
            const phoneEl = summaryBar.querySelectorAll('div[style*="font-size: 14px"][style*="color: #0c4a6e"]')[0];
            const addressEl = summaryBar.querySelectorAll('div[style*="font-size: 14px"][style*="color: #0c4a6e"]')[1];
            if (nameEl) nameEl.textContent = newName;
            if (phoneEl) phoneEl.textContent = newPhone;
            if (addressEl) addressEl.textContent = newAddress;
        }
        
        // Hide the selector
        hideCustomerSelector();
        
        alert('Customer information updated successfully!');
    } catch (e) {
        console.error('Error selecting customer:', e);
        alert('Error updating customer information');
    }
}

function escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text || '';
    return div.innerHTML;
}

// Escape string for use in JavaScript onclick handlers
function escapeForJs(text) {
    if (!text) return '';
    return String(text).replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/"/g, '\\"');
}

// ========================================
// WhatsApp Messaging Functions
// ========================================
let whatsappData = { customerName: '', phone: '', orderNumber: '' };

var _orderTemplatesCache = null;
function openWhatsAppMenu(customerName, phone, orderNumber) {
    whatsappData = { customerName, phone, orderNumber };
    document.getElementById('whatsappRecipient').textContent = 'To: ' + customerName + ' (' + phone + ')';
    document.getElementById('whatsappModal').style.display = 'block';
    loadOrderTemplates();
}

function closeWhatsAppModal() {
    document.getElementById('whatsappModal').style.display = 'none';
    whatsappData = { customerName: '', phone: '', orderNumber: '' };
}

function loadOrderTemplates() {
    var container = document.getElementById('orderTemplatesContainer');
    if (_orderTemplatesCache) { renderOrderTemplates(_orderTemplatesCache); return; }
    container.innerHTML = '<div style="font-size:12px;color:#9ca3af;padding:8px;">Loading templates...</div>';
    fetch('/messages/templates?context=orders,shopify', { headers: { 'Accept': 'application/json', 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.content || '' } })
    .then(function(r) { return r.json(); })
    .then(function(d) {
        _orderTemplatesCache = d.templates || [];
        renderOrderTemplates(_orderTemplatesCache);
    })
    .catch(function() {
        container.innerHTML = '<div style="font-size:12px;color:#ef4444;padding:8px;">Could not load templates</div>';
    });
}

function renderOrderTemplates(tpls) {
    var container = document.getElementById('orderTemplatesContainer');
    if (!tpls.length) { container.innerHTML = '<div style="font-size:12px;color:#9ca3af;padding:8px;">No templates configured for orders. Add them in Messages > Manage Templates.</div>'; return; }
    var html = '';
    tpls.forEach(function(t, idx) {
        var bodyPreview = (t.body_text || '').replace(/\\n/g, '\n');
        if (whatsappData.customerName) bodyPreview = bodyPreview.replace('{{ 1 }}', whatsappData.customerName);
        if (whatsappData.orderNumber) bodyPreview = bodyPreview.replace('{{ 2 }}', whatsappData.orderNumber);
        html += '<div id="orderTpl_' + idx + '" style="width:100%;margin-bottom:10px;background:#f0fdf4;border:1px solid #bbf7d0;border-radius:8px;overflow:hidden;">';
        html += '<div onclick="toggleOrderTplDetail(' + idx + ')" style="padding:14px 16px;cursor:pointer;display:flex;align-items:center;gap:12px;">';
        html += '<span style="font-size:24px;">📋</span>';
        html += '<div style="flex:1;text-align:left;">';
        html += '<div style="font-weight:600;color:#111827;">' + (t.display_name || t.name || '').replace(/_/g, ' ') + '</div>';
        html += '<div style="font-size:12px;color:#6b7280;">Send via WhatsApp API</div>';
        html += '</div>';
        html += '<span id="orderTplArrow_' + idx + '" style="color:#9ca3af;font-size:16px;">&#9660;</span>';
        html += '</div>';
        html += '<div id="orderTplBody_' + idx + '" style="display:none;padding:0 16px 14px;border-top:1px solid #dcfce7;">';
        html += '<div style="margin-top:10px;padding:10px;background:#fff;border-radius:6px;border:1px solid #e5e7eb;font-size:12px;color:#374151;white-space:pre-wrap;line-height:1.5;">' + escapeHtml(bodyPreview) + '</div>';
        if (t.variable_count > 0) {
            html += '<div style="margin-top:8px;">';
            for (var i = 1; i <= t.variable_count; i++) {
                var defVal = '';
                if (i === 1) defVal = whatsappData.customerName || '';
                if (i === 2) defVal = whatsappData.orderNumber || '';
                html += '<input id="orderTplVar_' + idx + '_' + i + '" style="width:100%;padding:8px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:13px;margin-bottom:4px;" placeholder="Variable {{ ' + i + ' }}" value="' + escapeHtml(defVal) + '" />';
            }
            html += '</div>';
        }
        html += '<button onclick="sendOrderTemplate(' + idx + ')" style="margin-top:8px;width:100%;padding:10px;background:#16A34A;color:#fff;border:none;border-radius:6px;font-weight:600;font-size:13px;cursor:pointer;">Send Template</button>';
        html += '</div>';
        html += '</div>';
    });
    container.innerHTML = html;
}

function toggleOrderTplDetail(idx) {
    var body = document.getElementById('orderTplBody_' + idx);
    var arrow = document.getElementById('orderTplArrow_' + idx);
    if (body.style.display === 'none') { body.style.display = 'block'; arrow.innerHTML = '&#9650;'; }
    else { body.style.display = 'none'; arrow.innerHTML = '&#9660;'; }
}

function sendOrderTemplate(idx) {
    var t = _orderTemplatesCache[idx];
    if (!t) return;
    var params = [];
    for (var i = 1; i <= (t.variable_count || 0); i++) {
        var input = document.getElementById('orderTplVar_' + idx + '_' + i);
        var val = input ? input.value.trim() : '';
        if (!val) { alert('Please fill in all template variables.'); return; }
        params.push(val);
    }
    var btn = event.target; btn.disabled = true; btn.textContent = 'Sending...';
    fetch('/messages/send-template', {
        method: 'POST',
        headers: { 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.content || '', 'Content-Type': 'application/json', 'Accept': 'application/json' },
        body: JSON.stringify({ phone: whatsappData.phone, template_name: t.name, body_params: params })
    })
    .then(function(r) { return r.json(); })
    .then(function(d) {
        btn.disabled = false; btn.textContent = 'Send Template';
        if (d.success) { alert('Template sent successfully!'); closeWhatsAppModal(); }
        else { alert(d.message || 'Failed to send template'); }
    })
    .catch(function() { btn.disabled = false; btn.textContent = 'Send Template'; alert('Network error - try again'); });
}

function escapeHtml(str) {
    if (!str) return '';
    return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

function formatPhoneForWhatsApp(phone) {
    if (!phone) return null;
    
    // Remove all non-digit characters
    let cleaned = phone.replace(/\D/g, '');
    
    // If starts with 92, already has country code
    if (cleaned.startsWith('92') && cleaned.length >= 11) {
        return cleaned;
    }
    
    // If starts with 0, remove it
    if (cleaned.startsWith('0')) {
        cleaned = cleaned.substring(1);
    }
    
    // Take last 10 digits
    if (cleaned.length > 10) {
        cleaned = cleaned.slice(-10);
    }
    
    // Add Pakistan country code
    return '92' + cleaned;
}

var _whatsappWindow = null;
function openWhatsAppWeb(phone, message) {
    var formattedPhone = formatPhoneForWhatsApp(phone);
    if (!formattedPhone) {
        alert('Invalid phone number');
        return;
    }
    
    var url = 'https://web.whatsapp.com/send?phone=' + formattedPhone;
    if (message) {
        url += '&text=' + encodeURIComponent(message);
    }
    
    // Try to reuse existing WhatsApp window by navigating it
    if (_whatsappWindow && !_whatsappWindow.closed) {
        try {
            _whatsappWindow.location.href = url;
            _whatsappWindow.focus();
            closeWhatsAppModal();
            return;
        } catch(e) {
            // location assignment blocked - fall through to window.open
        }
    }
    
    _whatsappWindow = window.open(url, 'whatsapp_web');
    if (_whatsappWindow) _whatsappWindow.focus();
    closeWhatsAppModal();
}

function sendWhatsAppDefault() {
    openWhatsAppWeb(whatsappData.phone);
}

function searchCustomers(inputEl) {
    const query = (inputEl && inputEl.value) ? inputEl.value.trim() : '';
    clearTimeout(customerSearchTimeout);
    if (!query) { hideCustomerDropdown(); return; }

    customerSearchTimeout = setTimeout(function() {
        fetch('/api/customers/search?q=' + encodeURIComponent(query) + '&limit=10', {
            headers: { 'Accept': 'application/json' }
        })
        .then(function(r) { return r.json(); })
        .then(function(data) {
            const customers = (data && data.success && data.customers) ? data.customers : [];
            showCustomerResults(customers);
        })
        .catch(function() {});
    }, 250);
}
// Store customer data for selection (avoids issues with special characters in onclick)
window._customerSearchResults = {};

function showCustomerResults(customers) {
    const dd = document.getElementById('customerDropdown');
    if (!dd) return;
    if (!customers || customers.length === 0) { 
        dd.innerHTML = '<div style="padding:8px;color:#6b7280;font-size:12px;">No customers found</div>'; 
        showCustomerDropdown(); 
        return; 
    }
    
    // Store customer data in a global object for safe retrieval
    window._customerSearchResults = {};
    
    // Local escape helper (escapeHtml may not be defined yet at this point in the file)
    const safeEscape = (str) => {
        if (!str) return '';
        const div = document.createElement('div');
        div.textContent = str;
        return div.innerHTML;
    };

    let html = '';
    customers.forEach(c => {
        const addressParts = [];
        if (c.address && c.address.address1) addressParts.push(c.address.address1);
        if (c.address && c.address.city) addressParts.push(c.address.city);
        if (c.address && c.address.province) addressParts.push(c.address.province);
        const addressDisplay = addressParts.length > 0 ? safeEscape(addressParts.join(', ')) : 'No address';
        
        // Store customer data using ID as key
        window._customerSearchResults[c.id] = {
            id: c.id,
            name: c.name || '',
            phone: c.phone || '',
            email: c.email || '',
            notes: c.notes || '',
            customer_type: c.customer_type || 'regular',
            address: c.address || {}
        };
        
        html += `
            <div class="customer-dropdown-item" data-customer-id="${c.id}"
                 style="padding:10px 12px; cursor:pointer; border-bottom:1px solid #f3f4f6; transition: background-color 0.15s ease;"
                 onmouseover="this.style.backgroundColor='#f8fafc'" 
                 onmouseout="this.style.backgroundColor='white'">
                <div style="font-weight: 500; color: #374151; font-size: 14px; margin-bottom: 2px;">
                    ${safeEscape(c.name) || 'No name'}
                </div>
                <div style="font-size: 12px; color: #6b7280; margin-bottom: 2px;">
                    📞 ${safeEscape(c.phone) || 'No phone'} ${c.email ? '• ✉️ ' + safeEscape(c.email) : ''}
                </div>
                <div style="font-size: 12px; color: #9ca3af;">
                    📍 ${addressDisplay}
                </div>
            </div>
        `;
    });
    dd.innerHTML = html;
    
    // Add click handlers using event delegation (safer than inline onclick)
    dd.querySelectorAll('.customer-dropdown-item').forEach(item => {
        item.addEventListener('click', function(e) {
            e.stopPropagation();
            const customerId = this.getAttribute('data-customer-id');
            const customerData = window._customerSearchResults[customerId];
            if (customerData) {
                selectCustomerFromData(customerData);
            }
        });
    });
    
    showCustomerDropdown();
}

// New function that accepts customer data object directly
// Aug-2026 — ONE rule for which payment method a NEW order starts on.
// Priority: the customer's remembered default -> the Qurbani admin default
// (qurbani mode only) -> shop customers settle online -> cash.
//
// The customer's own default wins deliberately: it is the most specific
// statement anyone has made about this customer, and it is set by a human
// (Edit Customer, or the tick on this form) rather than inferred. The last
// three steps are exactly the behaviour that existed before this function,
// so a customer with no default set sees no change at all.
//
// ⚠ Mirrored in the mobile app's New Order sheet (CustomersScreen.js,
// resolveNewOrderPaymentMethod). Change both or they drift apart.
function resolveNewOrderPaymentMethod(customerData) {
    var pm = (customerData && customerData.default_payment_method) || '';
    if (pm === 'cash' || pm === 'online') return pm;

    try {
        var urlParams = new URLSearchParams(window.location.search);
        if (urlParams.get('qurbani_mode') === '1'
            && typeof qurbaniDefaultPaymentMethod !== 'undefined'
            && (qurbaniDefaultPaymentMethod === 'cash' || qurbaniDefaultPaymentMethod === 'online')) {
            return qurbaniDefaultPaymentMethod;
        }
    } catch (e) { /* non-fatal — fall through to the customer-type rule */ }

    if (customerData && customerData.customer_type === 'shop') return 'online';
    return 'cash';
}

function selectCustomerFromData(customerData) {
    const searchInput = document.getElementById('customerSearch');
    const hiddenId = document.getElementById('selectedCustomerId');
    
    // Update the search input with customer name
    if (searchInput) searchInput.value = customerData.name || '';
    if (hiddenId) hiddenId.value = customerData.id || '';
    hideCustomerDropdown();

    // Show detailed customer information after selection
    showSelectedCustomerDetails(customerData);

    // 💰 Customer credit: tell the manager NOW, while they are placing the
    // order, that this customer has money with us. Re-fetched on every
    // selection so a spent balance never shows a stale hint.
    try { nfShowCreateCreditHint(customerData.id); } catch (e) { console.warn('credit hint failed', e); }

    // ⭐ Pre-select the payment method for this customer (user can still change it).
    try {
        // Scope to the form holding the customer search (the Create-Order form)
        // so we don't touch unrelated/hidden payment_method selects.
        const scope = (searchInput && searchInput.closest('form')) || document;
        const pmSelect = scope.querySelector('select[name="payment_method"]');
        const method = resolveNewOrderPaymentMethod(customerData);
        if (pmSelect) {
            const opt = Array.from(pmSelect.options).find(o => o.value === method);
            if (opt) {
                pmSelect.value = method;
                Array.from(pmSelect.options).forEach(o => { o.selected = (o.value === method); });
            }
        }
        // Untick "set as default" whenever the customer changes — the tick means
        // "remember this for THIS customer", so carrying it across a customer
        // switch would silently write a preference onto the wrong person.
        const setDefaultBox = scope.querySelector('input[name="set_default_payment_method"]');
        if (setDefaultBox) setDefaultBox.checked = false;

        // Aug-2026 — show whose choice the existing default is, and confirm before
        // overwriting it (same rule as the quick-change and mobile modals).
        const info = customerData.default_payment_info || null;
        window._createOrderCustomerDefault = info;
        const note = document.getElementById('createOrderDefaultPmNote');
        const lbl = document.getElementById('setDefaultPaymentMethodLabel');
        if (note) {
            if (info) {
                note.style.display = 'block';
                note.style.color = '#15803d';
                note.textContent = '⭐ Customer default: ' + info.label
                    + (info.set_by_name ? ' — set by ' + info.set_by_name : '')
                    + (info.set_at_short ? ' · ' + info.set_at_short : '');
            } else {
                note.style.display = 'none';
                note.textContent = '';
            }
        }
        if (lbl) lbl.textContent = info ? 'Update default for this customer' : 'Set as default for this customer';
        if (setDefaultBox && !setDefaultBox._nfDefaultGuard) {
            setDefaultBox._nfDefaultGuard = true;
            setDefaultBox.addEventListener('click', function (e) {
                const existing = window._createOrderCustomerDefault;
                if (!this.checked || !existing) return;
                const pm = scope.querySelector('select[name="payment_method"]');
                const picked = pm && pm.value === 'online' ? 'Online' : 'Cash';
                const who = existing.set_by_name || 'someone else';
                const when = existing.set_at_short ? (' on ' + existing.set_at_short) : '';
                if (!confirm(`This customer's default is ${existing.label}, set by ${who}${when}.\n\n`
                        + `Save ${picked} as the new default and record it under your name?`)) {
                    this.checked = false;
                    e.preventDefault();
                }
            });
        }
    } catch (e) { /* non-fatal */ }

    // Pre-fill address fields if visible
    if (customerData.address) {
        const fields = [
            ['input[name="customer_address1"]', 'address1'],
            ['input[name="customer_address2"]', 'address2'],
            ['input[name="customer_city"]', 'city']
        ];
        fields.forEach(([sel, key]) => {
            const el = document.querySelector(sel);
            if (el && customerData.address[key]) el.value = customerData.address[key];
        });
    }
}
// Legacy function for backwards compatibility (if called from elsewhere)
function selectCustomer(customerId, customerName, encodedData) {
    try {
        const customerData = encodedData ? JSON.parse(decodeURIComponent(encodedData)) : { id: customerId, name: customerName };
        selectCustomerFromData(customerData);
    } catch (e) {
        // Fallback if JSON parsing fails
        selectCustomerFromData({ id: customerId, name: customerName });
    }
}
/**
 * 💰 Green hint in the CREATE-order form: "this customer has Rs X with us."
 * Purely informational — credit can only attach to an order that exists, so
 * the actual apply happens right after save (saveNewOrder offers to open the
 * new order, where the full banner does the work). Removed and re-fetched on
 * every customer selection so it can never show a stale balance.
 */
async function nfShowCreateCreditHint(customerId) {
    document.getElementById('nfCreateCreditHint')?.remove();
    if (!customerId) return;

    let d;
    try {
        const res = await fetch(`/customer-credit/${customerId}/summary?limit=3`, {
            headers: { 'Accept': 'application/json', 'X-Requested-With': 'XMLHttpRequest' },
            credentials: 'same-origin'
        });
        const json = await res.json();
        if (!json || !json.success) return;
        d = json.data;
    } catch (e) { return; }

    if (!d.eligible || !d.has_balance) return;

    // Guard against a slow response landing after the manager switched customer.
    const currentSel = document.getElementById('selectedCustomerId')?.value;
    if (String(currentSel) !== String(customerId)) return;

    const details = document.getElementById('selectedCustomerDetails');
    if (!details) return;

    const src = (d.history || []).find(h => h.is_credit && h.counts);
    const from = src ? ` (from ${src.order_number ? 'order ' + src.order_number : src.type_label.toLowerCase()} · ${src.date || ''})` : '';

    const hint = document.createElement('div');
    hint.id = 'nfCreateCreditHint';
    hint.style.cssText = 'margin-top:8px;padding:10px 12px;background:#ecfdf5;border:1px solid #6ee7b7;border-left:4px solid #059669;border-radius:6px;font-size:13px;color:#065f46;';
    hint.innerHTML = `💰 <strong>Rs. ${nfEsc(d.balance_display)}</strong> account balance available${nfEsc(from)}.
        After saving, you'll be asked whether to use it on this order.`;
    details.insertAdjacentElement('afterend', hint);
}

function showSelectedCustomerDetails(customerData) {
    // Find or create customer details display area
    let detailsDiv = document.getElementById('selectedCustomerDetails');
    
    if (!detailsDiv) {
        // Create the details display area below the search input
        const searchContainer = document.getElementById('existingCustomerSection');
        if (searchContainer) {
            detailsDiv = document.createElement('div');
            detailsDiv.id = 'selectedCustomerDetails';
            detailsDiv.style.cssText = `
                margin-top: 12px;
                padding: 12px;
                background: linear-gradient(135deg, #f0f9ff 0%, #e0f2fe 100%);
                border: 1px solid #bae6fd;
                border-radius: 8px;
                font-size: 13px;
                display: none;
            `;
            searchContainer.appendChild(detailsDiv);
        }
    }

    if (detailsDiv && customerData.name) {
        // Build address display
        const addressParts = [];
        if (customerData.address) {
            if (customerData.address.address1) addressParts.push(customerData.address.address1);
            if (customerData.address.address2) addressParts.push(customerData.address.address2);
            if (customerData.address.city) addressParts.push(customerData.address.city);
            if (customerData.address.province) addressParts.push(customerData.address.province);
            if (customerData.address.postal_code) addressParts.push(customerData.address.postal_code);
        }
        const fullAddress = addressParts.length > 0 ? addressParts.join(', ') : 'No address provided';

        // Build customer notes display if they exist
        let notesHtml = '';
        if (customerData.notes && customerData.notes.trim() !== '') {
            notesHtml = `
                <div style="margin-top: 12px; padding: 10px; background: linear-gradient(135deg, #fef3c7 0%, #fde68a 100%); border: 2px solid #fbbf24; border-radius: 6px;">
                    <div style="display: flex; align-items: center; margin-bottom: 6px;">
                        <span style="font-size: 18px; margin-right: 6px;">⚠️</span>
                        <strong style="color: #92400e; font-size: 13px;">Customer Instructions / Notes:</strong>
                    </div>
                    <div style="color: #78350f; font-size: 12px; line-height: 1.5; white-space: pre-wrap; word-wrap: break-word;">${customerData.notes}</div>
                </div>
            `;
        }

        detailsDiv.innerHTML = `
            <div style="display: flex; align-items: center; margin-bottom: 8px;">
                <span style="font-size: 16px; margin-right: 8px;">👤</span>
                <h4 style="margin: 0; color: #0369a1; font-weight: 600;">Selected Customer</h4>
            </div>
            <div style="margin-bottom: 6px;">
                <strong style="color: #374151;">${customerData.name}</strong>
            </div>
            <div style="margin-bottom: 4px; color: #6b7280;">
                📞 ${customerData.phone || 'No phone'} ${customerData.email ? '• ✉️ ' + customerData.email : ''}
            </div>
            <div style="color: #6b7280; line-height: 1.4;">
                📍 ${fullAddress}
            </div>
            ${notesHtml}
        `;
        detailsDiv.style.display = 'block';
    } else if (detailsDiv) {
        detailsDiv.style.display = 'none';
    }
}
// ==================== END CUSTOMER SELECTION HELPERS ====================

// Remove any stray duplicate "+ Create Order" label rendered outside the toolbar
document.addEventListener('DOMContentLoaded', function() {
    const containers = document.querySelectorAll('.kt-container-fixed');
    containers.forEach(container => {
        const suspects = Array.from(container.querySelectorAll('span, a, button, div'));
        suspects.forEach(el => {
            const t = (el.textContent || '').trim();
            if ((t === '+ Create Order' || t === 'Create Order') && !el.closest('[title="Create Order"]')) {
                // Hide only if it's not the actual toolbar button
                if (!el.className || !/border-emerald-500|create-order-btn/.test(el.className)) {
                    el.style.display = 'none';
                }
            }
        });
    });
});
// Shopify tab switching function
function switchShopifyTab(tab) {
    const tableContainer = document.querySelector('.orders-table-container');
    if (tableContainer) tableContainer.classList.add('opacity-60');

    fetch(`/orders/filter?source=shopify&tab=${encodeURIComponent(tab)}`)
        .then(r => r.json())
        .then(data => {
            if (!data || !data.success) return;

            // Update URL without reload
            const url = new URL(window.location);
            url.searchParams.set('source', 'shopify');
            url.searchParams.set('tab', tab);
            window.history.pushState({}, '', url);

            // Update tab styles
            const allTab = document.getElementById('tab-all');
            const approvalsTab = document.getElementById('tab-approvals');
            if (allTab && approvalsTab) {
                if (tab === 'all') {
                    allTab.className = 'px-3 py-1.5 rounded-md text-sm font-medium transition-all duration-200 bg-white text-blue-600 shadow-sm';
                    approvalsTab.className = 'px-3 py-1.5 rounded-md text-sm font-medium transition-all duration-200 text-gray-600 hover:text-gray-800 hover:bg-gray-50';
                } else {
                    approvalsTab.className = 'px-3 py-1.5 rounded-md text-sm font-medium transition-all duration-200 bg-white text-blue-600 shadow-sm';
                    allTab.className = 'px-3 py-1.5 rounded-md text-sm font-medium transition-all duration-200 text-gray-600 hover:text-gray-800 hover:bg-gray-50';
                }
            }

            // Rebuild table with fresh dataset and mark current tab
            rebuildTableWithOrders(data.orders, 'shopify', tab);
            // Update badges and pagination for this dataset
            refreshPaginationInfo({
                shopify_all_count: data.shopify_all_count,
                shopify_approvals_count: data.shopify_approvals_count,
                other_count: data.other_count
            });
        })
        .catch(err => console.error('Failed to switch Shopify tab:', err))
        .finally(() => {
            if (tableContainer) tableContainer.classList.remove('opacity-60');
        });
}

// Filter table content based on selected tab
function filterTableByTab(tab) {
    const tbody = document.getElementById('table-body');
    const rows = tbody.querySelectorAll('tr');
    
    rows.forEach(row => {
        if (tab === 'all') {
            // Show all Shopify orders
            row.style.display = '';
        } else if (tab === 'approvals') {
            // Show only unconverted orders - look for convertOrder function calls (approval buttons)
            const actionsCell = row.querySelector('td:last-child');
            if (
                actionsCell &&
                (
                    actionsCell.innerHTML.includes('convertOrder(') ||
                    actionsCell.innerHTML.includes('title="Approve') ||
                    actionsCell.innerHTML.toLowerCase().includes('approve (convert)')
                )
            ) {
                row.style.display = '';
            } else {
                row.style.display = 'none';
            }
        }
    });
}

// Function to switch to Open Orders tab
function switchToOpenOrders() {
    const tableContainer = document.querySelector('.orders-table-container');
    if (tableContainer) tableContainer.classList.add('opacity-60');

    fetch('/orders/filter?source=other&tab=open')
        .then(res => res.json())
        .then(data => {
            if (!data || !data.success) return false;

            // Update URL
            const url = new URL(window.location);
            url.searchParams.set('source', 'other');
            url.searchParams.set('tab', 'open');
            window.history.pushState({}, '', url);

            // Keep the runtime tab context in sync BEFORE anything reads it. Without
            // this, updateTabsForOpenOrders() -> updateRiderLiveBoardVisibility() runs
            // while window.currentTab is still the previous tab ('all'), so the board's
            // should-show check fails and the Riders-Live panel never re-appears when
            // returning to Open Orders (rebuildTableWithOrders sets these too, but that
            // runs AFTER the visibility check). See riderBoardShouldShow().
            window.currentSource = 'other';
            window.currentTab = 'open';

            // Update page title
            const pageTitle = document.querySelector('h1');
            if (pageTitle) pageTitle.textContent = 'Orders';

            // Update tabs
            updateTabsForOpenOrders(data);

            // Load status cards after a short delay to ensure DOM is updated
            console.log('Switching to Open Orders - loading status cards...'); // Debug log
            setTimeout(() => {
                loadOpenOrdersStatusCards();
            }, 200);

            // Render open orders dataset
            rebuildTableWithOrders(data.orders, 'other', 'open');
            
            // Update pagination for filtered results
            updatePaginationForTab(data.orders, 'other', 'open', data.open_count);
            
            refreshPaginationInfo({
                shopify_all_count: data.shopify_all_count,
                shopify_approvals_count: data.shopify_approvals_count,
                other_count: data.other_count,
                open_count: data.open_count
            });
        })
        .catch(err => console.error('Failed to load open orders:', err))
        .finally(() => {
            if (tableContainer) tableContainer.classList.remove('opacity-60');
        });

    return false;
}
// Update tabs for open orders view
function updateTabsForOpenOrders(data) {
    const tabsContainer = document.querySelector('.flex.space-x-1.bg-gray-100');
    if (tabsContainer) {
        tabsContainer.innerHTML = `
            <a href="#" onclick="return switchToInvoices()" class="px-3 py-1.5 rounded-md text-sm font-medium transition-all duration-200 text-gray-600 hover:text-gray-800 hover:bg-gray-50">
                Invoices
                <span class="ml-1.5 px-1.5 py-0.5 bg-blue-100 text-blue-800 text-xs rounded-full font-semibold" id="badge-invoices">${data.other_count || '-'}</span>
            </a>
            <button class="px-3 py-1.5 rounded-md text-sm font-medium transition-all duration-200 bg-white text-blue-600 shadow-sm">
                Open Orders
                <span class="ml-1.5 px-1.5 py-0.5 bg-blue-100 text-blue-800 text-xs rounded-full font-semibold" id="badge-open">${data.open_count || '-'}</span>
            </button>
            <button onclick="switchToRiders()" class="px-3 py-1.5 rounded-md text-sm font-medium transition-all duration-200 text-gray-600 hover:text-gray-800 hover:bg-gray-50">
                Riders
                <span class="ml-1.5 px-1.5 py-0.5 bg-blue-100 text-blue-800 text-xs rounded-full font-semibold" id="badge-riders">${data.open_count || '-'}</span>
            </button>
            <button onclick="switchToShopifyApprovals()" class="px-3 py-1.5 rounded-md text-sm font-medium transition-all duration-200 text-gray-600 hover:text-gray-800 hover:bg-gray-50">
                Order Approvals
                <span class="ml-1.5 px-1.5 py-0.5 bg-blue-100 text-blue-800 text-xs rounded-full font-semibold" id="badge-approvals">${data.shopify_approvals_count || '-'}</span>
            </button>
        `;
    }

    // Show status cards section, hide riders cards
    const statusCardsSection = document.getElementById('openOrdersStatusCards');
    const ridersCards = document.getElementById('ridersCards');
    if (statusCardsSection) {
        statusCardsSection.style.display = 'block';
    }
    if (ridersCards) {
        ridersCards.style.display = 'none';
    }

    // Rider Live Board — only on the Open Orders tab.
    updateRiderLiveBoardVisibility();
}

// Load and display open orders status cards
async function loadOpenOrdersStatusCards() {
    console.log('Loading open orders status cards...'); // Debug log
    try {
        const response = await fetch('/orders/open-status-counts', {
            headers: { 
                'Accept': 'application/json',
                'X-Requested-With': 'XMLHttpRequest' 
            },
            credentials: 'same-origin'
        });
        
        const data = await response.json();
        console.log('Status cards API response:', data); // Debug log
        
        if (data.success) {
            // Store verified/unverified counts globally for filtering
            window.verifiedLocationCounts = {
                all_open_verified: data.all_open_verified || 0,
                all_open_unverified: data.all_open_unverified || 0,
                out_for_delivery_verified: data.out_for_delivery_verified || 0,
                out_for_delivery_unverified: data.out_for_delivery_unverified || 0
            };
            
            renderStatusCards(data.status_counts, data.total_open_count, data.delivered_today || 0, window.verifiedLocationCounts);
        } else {
            console.error('Failed to load status counts:', data.message);
        }
    } catch (error) {
        console.error('Error loading status cards:', error);
    }
}
// Render status cards with compact design
function renderStatusCards(statusCounts, totalOpenCount, deliveredTodayCount = 0, verifiedCounts = null) {
    console.log('Rendering status cards:', statusCounts, 'Total:', totalOpenCount, 'Verified counts:', verifiedCounts); // Debug log
    const container = document.getElementById('statusCardsContainer');
    if (!container) {
        console.log('Status cards container not found!'); // Debug log
        return;
    }

    // NF (Jul-2026): mockup-style stat cards — big tabular number, small uppercase
    // label, colored LEFT ACCENT instead of the old mixed borders + meaningless
    // status-master emoji icons. All click handlers (filterByStatus,
    // filterByVerifiedLocation) and data-status attrs preserved verbatim.
    const nfscAccent = (c) => ({ blue:'#2563eb', green:'#15803d', yellow:'#b45309', orange:'#c2410c', red:'#b91c1c', purple:'#6d28d9', indigo:'#4f46e5', gray:'#475569' }[c] || '#475569');
    const nfscChips = (scope, v, uv) => `
        <div class="nfsc-chips">
            <span class="nfsc-chip nfsc-chip-ok" onclick="event.stopPropagation(); filterByVerifiedLocation('${scope}', 'verified');" title="Verified location — click to filter">✓ ${v}</span>
            <span class="nfsc-chip nfsc-chip-warn" onclick="event.stopPropagation(); filterByVerifiedLocation('${scope}', 'unverified');" title="Unverified location — click to filter">✗ ${uv}</span>
        </div>`;

    let cardsHtml = `
        <div class="status-card active flex-shrink-0" data-status="all" onclick="filterByStatus('all')">
            <div class="nfsc-box" style="border-left-color:${nfscAccent('blue')};">
                <div class="nfsc-n" style="color:${nfscAccent('blue')};">${totalOpenCount}</div>
                <div class="nfsc-l">All Open</div>
                ${verifiedCounts ? nfscChips('all', verifiedCounts.all_open_verified, verifiedCounts.all_open_unverified) : ''}
            </div>
        </div>
    `;

    cardsHtml += `
        <div class="status-card flex-shrink-0" data-status="delivered_today">
            <div class="nfsc-box" style="border-left-color:${nfscAccent('green')};cursor:default;">
                <div class="nfsc-n" style="color:${nfscAccent('green')};">${deliveredTodayCount}</div>
                <div class="nfsc-l">Delivered Today</div>
            </div>
        </div>
    `;

    statusCounts.forEach(status => {
        const colorClass = getStatusColorClass(status.color_class);
        const isOutForDelivery = status.status_code === 'out_for_delivery';
        cardsHtml += `
            <div class="status-card flex-shrink-0" data-status="${status.status_code}" onclick="filterByStatus('${status.status_code}')">
                <div class="nfsc-box" style="border-left-color:${nfscAccent(colorClass)};">
                    <div class="nfsc-n" style="color:${nfscAccent(colorClass)};">${status.count}</div>
                    <div class="nfsc-l">${status.status_name}</div>
                    ${isOutForDelivery && verifiedCounts ? nfscChips('out_for_delivery', verifiedCounts.out_for_delivery_verified, verifiedCounts.out_for_delivery_unverified) : ''}
                </div>
            </div>
        `;
    });

    container.innerHTML = cardsHtml;
}

// Get appropriate color class for status
function getStatusColorClass(colorClass) {
    const colorMap = {
        'yellow': 'yellow',
        'orange': 'orange', 
        'blue': 'blue',
        'purple': 'purple',
        'green': 'green',
        'red': 'red',
        'gray': 'gray'
    };
    return colorMap[colorClass] || 'gray';
}

// Filter orders by status
function filterByStatus(statusCode) {
    // Remember the active funnel status so it composes with the rider filter
    // (the unified chip + the rider-filter refetch both read window.__nfStatusCard).
    window.__nfStatusCard = (statusCode === 'all') ? null : statusCode;
    // Update active card
    document.querySelectorAll('.status-card').forEach(card => {
        card.classList.remove('active');
        const cardDiv = card.querySelector('div');
        if (statusCode === 'all') {
            cardDiv.className = cardDiv.className.replace(/border-\w+-200/, 'border-gray-200');
        }
    });
    
    const activeCard = document.querySelector(`[data-status="${statusCode}"]`);
    if (activeCard) {
        activeCard.classList.add('active');
        const cardDiv = activeCard.querySelector('div');
        if (statusCode === 'all') {
            cardDiv.className = cardDiv.className.replace(/border-gray-200/, 'border-blue-200');
        } else {
            // Add active border color for specific status
            const status = statusCode;
            cardDiv.className = cardDiv.className.replace(/border-gray-200/, `border-blue-200`);
        }
    }

    // Filter table data
    const tableContainer = document.querySelector('.orders-table-container');
    if (tableContainer) tableContainer.classList.add('opacity-60');

    const params = new URLSearchParams({
        source: 'other',
        tab: 'open'
    });
    
    if (statusCode !== 'all') {
        params.append('status', statusCode);
    }

    fetch(`/orders/filter?${params.toString()}`)
        .then(res => res.json())
        .then(data => {
            if (data && data.success) {
                rebuildTableWithOrders(data.orders, 'other', 'open');
                // Update pagination for filtered results
                updatePaginationForTab(data.orders, 'other', 'open');
                // Re-apply the rider overlay on the freshly rebuilt rows so rider +
                // status compose (the rebuild renders every row visible, wiping it).
                if (window.__nfRiderFilter != null && typeof window.nfReapplyRiderFilter === 'function') {
                    window.nfReapplyRiderFilter();
                }
                // Refresh the unified "active filters" chip.
                if (typeof window.nfRenderActiveFilters === 'function') window.nfRenderActiveFilters();
            }
        })
        .catch(err => console.error('Failed to filter by status:', err))
        .finally(() => {
            if (tableContainer) tableContainer.classList.remove('opacity-60');
    });
}

// Filter orders by verified location status
function filterByVerifiedLocation(statusCode, verificationType) {
    console.log('Filtering by verified location:', statusCode, verificationType);
    
    // Show loading state
    const tableContainer = document.querySelector('.orders-table-container');
    if (tableContainer) tableContainer.classList.add('opacity-60');

    // Build filter params
    const params = new URLSearchParams({
        source: 'other',
        tab: 'open'
    });
    
    // Add status filter if not 'all'
    if (statusCode !== 'all') {
        params.append('status', statusCode);
    }

    // Fetch orders
    fetch(`/orders/filter?${params.toString()}`)
        .then(res => res.json())
        .then(data => {
            if (data && data.success) {
                // Filter orders based on verified location
                let filteredOrders = data.orders;
                
                if (verificationType === 'verified') {
                    // Show only orders with verified location
                    filteredOrders = filteredOrders.filter(order => {
                        // Check if customer has verified location
                        if (order.customer_id && window.ordersData) {
                            const fullOrder = window.ordersData.find(o => o.id === order.id);
                            if (fullOrder && fullOrder.customer) {
                                return fullOrder.customer.verified_location_url || 
                                       (fullOrder.customer.latitude && fullOrder.customer.longitude);
                            }
                        }
                        return false;
                    });
                } else if (verificationType === 'unverified') {
                    // Show only orders without verified location
                    filteredOrders = filteredOrders.filter(order => {
                        // Check if customer does NOT have verified location
                        if (order.customer_id && window.ordersData) {
                            const fullOrder = window.ordersData.find(o => o.id === order.id);
                            if (fullOrder && fullOrder.customer) {
                                return !fullOrder.customer.verified_location_url && 
                                       !(fullOrder.customer.latitude && fullOrder.customer.longitude);
                            }
                        }
                        return true; // If no customer data, assume unverified
                    });
                }
                
                rebuildTableWithOrders(filteredOrders, 'other', 'open');
                // Update pagination for filtered results
                updatePaginationForTab(filteredOrders, 'other', 'open');
                
                // Show toast message
                const message = verificationType === 'verified' 
                    ? `Showing ${filteredOrders.length} orders with verified addresses`
                    : `Showing ${filteredOrders.length} orders without verified addresses`;
                showToast('Filtered', message, 'info');
            }
        })
        .catch(err => console.error('Failed to filter by verified location:', err))
        .finally(() => {
            if (tableContainer) tableContainer.classList.remove('opacity-60');
        });
}

// Function to switch to Order Approvals from main orders page
function switchToShopifyApprovals() {
