// Function to rebuild table with new orders data
function rebuildTableWithOrders(orders, source, tab) {
    const tableContainer = document.querySelector('.orders-table-container');
    if (!tableContainer) return;

    // If a table already exists, reuse its structure and just re-render data
    if (!tableContainer.querySelector('table')) {
        const tableHTML = `
            <table class="min-w-full divide-y divide-gray-200" style="width: max-content; min-width: 100%;">
                <colgroup id="table-colgroup"></colgroup>
                <thead class="bg-gray-50 sticky top-0 z-20">
                    <tr id="table-header"></tr>
                </thead>
                <tbody class="bg-white divide-y divide-gray-200" id="table-body"></tbody>
            </table>
        `;
        tableContainer.innerHTML = tableHTML;
    }

    // Set runtime context so rendering logic can detect Order Approvals
    window.currentSource = source;
    window.currentTab = tab;

    // Feed data into existing render pipeline
    window.ordersData = orders || [];
    window.allOrders = [...window.ordersData];
    window.filteredOrders = [...window.ordersData];

    // Update status filter with new data (safe for Shopify: will show only All status)
    initStatusFilter();

    // Render using existing helpers to avoid duplication
    renderOrdersTable();
    refreshPaginationInfo();
}

// Update badges and pagination info if response provided counts
function refreshPaginationInfo(counts) {
    try {
        const perPageSelect = document.getElementById('per-page-selector');
        const perPage = perPageSelect ? parseInt(perPageSelect.value, 10) : 25;
        const total = (window.ordersData || []).length;
        const info = document.getElementById('pagination-info');
        if (info) info.textContent = `1-${Math.min(total, perPage)} of ${total}`;

        // Hide numbered pagination when single page
        const pager = document.getElementById('numeric-pager');
        if (pager) {
            if (total <= perPage) {
                pager.classList.add('hidden');
            } else {
                pager.classList.remove('hidden');
            }
        }

        // Update badges when counts provided
        if (counts) {
            const bAll = document.getElementById('badge-all');
            const bApp = document.getElementById('badge-approvals');
            const bInv = document.getElementById('badge-invoices');
            const bOpen = document.getElementById('badge-open');
            if (bAll && counts.shopify_all_count != null) bAll.textContent = counts.shopify_all_count;
            if (bApp && counts.shopify_approvals_count != null) bApp.textContent = counts.shopify_approvals_count;
            if (bInv && counts.other_count != null) bInv.textContent = counts.other_count;
            if (bOpen && counts.open_count != null) bOpen.textContent = counts.open_count;
        }
    } catch (e) { console.warn('refreshPaginationInfo failed', e); }
}
// Update pagination for filtered/tab-switched data
function updatePaginationForTab(orders, source, tab, totalCount = null) {
    try {
        const paginationInfo = document.getElementById('pagination-info');
        const numericPager = document.getElementById('numeric-pager');
        const pagerWrap = document.getElementById('pager-wrap');
        
        if (!orders || !Array.isArray(orders)) return;
        
        const perPageSelect = document.getElementById('per-page-selector');
        const perPage = perPageSelect ? parseInt(perPageSelect.value, 10) : 25;
        const displayedCount = Math.min(orders.length, perPage);
        const total = totalCount || orders.length;
        
        // Update pagination info
        if (paginationInfo) {
            paginationInfo.textContent = `1-${displayedCount} of ${total}`;
        }
        
        // Hide numeric pagination for single page results
        if (numericPager) {
            if (total <= perPage) {
                numericPager.classList.add('hidden');
            } else {
                numericPager.classList.remove('hidden');
                // For now, just show page 1 since we're loading limited results
                numericPager.innerHTML = '<span class="px-3 py-2 text-sm bg-blue-600 text-white rounded-md font-medium">1</span>';
            }
        }
        
        // Update Previous/Next buttons to be disabled since we're showing filtered results
        if (pagerWrap) {
            const prevBtn = pagerWrap.querySelector('a[href*="page"], button:first-child');
            const nextBtn = pagerWrap.querySelector('a[href*="page"]:last-child, button:last-child');
            
            if (prevBtn) {
                prevBtn.outerHTML = '<button class="px-3 py-2 text-sm text-gray-400 bg-white border border-gray-300 rounded-md cursor-not-allowed" disabled>Previous</button>';
            }
            if (nextBtn && nextBtn !== prevBtn) {
                nextBtn.outerHTML = '<button class="px-3 py-2 text-sm text-gray-400 bg-white border border-gray-300 rounded-md cursor-not-allowed" disabled>Next</button>';
            }
        }
        
    } catch (e) { 
        console.warn('updatePaginationForTab failed', e); 
    }
}

// Bulk Status Change Functions
let availableStatuses = [];
let selectedOrderIds = [];

// Load available statuses for bulk change
async function loadAvailableStatuses() {
    try {
        const response = await fetch('/order-status/api/statuses', {
            method: 'GET',
            headers: {
                'Accept': 'application/json',
                'Content-Type': 'application/json',
                'X-Requested-With': 'XMLHttpRequest',
                'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').getAttribute('content')
            },
            credentials: 'same-origin'
        });
        const data = await response.json();
        
        if (data.success) {
            availableStatuses = data.data;
            populateStatusSelect();
        }
    } catch (error) {
        console.error('Error loading statuses:', error);
    }
}
// Populate status select dropdown
function populateStatusSelect() {
    const select = document.getElementById('bulkNewStatus');
    if (!select) return;
    
    select.innerHTML = '<option value="">Select new status...</option>';
    
    availableStatuses.forEach(status => {
        const option = document.createElement('option');
        option.value = status.status_code;
        option.textContent = `${status.icon} ${status.status_name}`;
        select.appendChild(option);
    });
}

// Open bulk status modal
// Note: openBulkStatusModal function is defined later with enhanced checkbox functionality

// Populate orders list for bulk selection
function populateBulkOrdersList() {
    const container = document.getElementById('bulkOrdersList');
    if (!container || !window.currentOrders) return;
    
    // Filter out orders in approval queue
    const eligibleOrders = window.currentOrders.filter(order => 
        order.external_source !== 'shopify' && order.external_source !== 'khaas_storage'
    );
    
    if (eligibleOrders.length === 0) {
        container.innerHTML = '<div style="color: #6b7280; font-style: italic;">No eligible orders found on this page</div>';
        return;
    }
    
    container.innerHTML = eligibleOrders.map(order => `
        <div style="display: flex; align-items: center; gap: 8px; padding: 8px; background: white; border: 1px solid #e5e7eb; border-radius: 6px; margin-bottom: 4px;">
            <input type="checkbox" id="order_${order.id}" value="${order.id}" onchange="toggleOrderSelection(${order.id})" style="border-radius: 4px;">
            <label for="order_${order.id}" style="flex: 1; font-size: 14px; cursor: pointer;">
                <span style="font-weight: 500;">#${order.order_number || order.id}</span>
                <span style="color: #6b7280; margin-left: 8px;">$${parseFloat(order.total_price || 0).toFixed(2)}</span>
                <span style="color: #6b7280; margin-left: 8px;">${order.order_status || 'unknown'}</span>
            </label>
        </div>
    `).join('');
}
// Toggle individual order selection
function toggleOrderSelection(orderId) {
    const checkbox = document.getElementById(`order_${orderId}`);
    if (!checkbox) return;
    
    if (checkbox.checked) {
        if (!selectedOrderIds.includes(orderId)) {
            selectedOrderIds.push(orderId);
        }
    } else {
        selectedOrderIds = selectedOrderIds.filter(id => id !== orderId);
    }
    
    updateSelectedCount();
    updateSelectAllCheckbox();
    updateBulkActionButtons(); // Add this line to update bulk status button
}

// Toggle all orders selection
function toggleAllOrders() {
    const selectAllCheckbox = document.getElementById('selectAllOrders');
    const orderCheckboxes = document.querySelectorAll('#bulkOrdersList input[type="checkbox"]');
    
    orderCheckboxes.forEach(checkbox => {
        checkbox.checked = selectAllCheckbox.checked;
        const orderId = parseInt(checkbox.value);
        
        if (selectAllCheckbox.checked) {
            if (!selectedOrderIds.includes(orderId)) {
                selectedOrderIds.push(orderId);
            }
        } else {
            selectedOrderIds = selectedOrderIds.filter(id => id !== orderId);
        }
    });
    
    updateSelectedCount();
}

// Update selected orders count
function updateSelectedCount() {
    const countElement = document.getElementById('selectedOrdersCount');
    const executeBtn = document.getElementById('executeBulkStatusBtn');
    
    if (countElement) {
        countElement.textContent = `${selectedOrderIds.length} orders selected`;
    }
    
    if (executeBtn) {
        executeBtn.disabled = selectedOrderIds.length === 0;
    }
}

// Update select all checkbox state
function updateSelectAllCheckbox() {
    const selectAllCheckbox = document.getElementById('selectAllOrders');
    const orderCheckboxes = document.querySelectorAll('#bulkOrdersList input[type="checkbox"]');
    const checkedBoxes = document.querySelectorAll('#bulkOrdersList input[type="checkbox"]:checked');
    
    if (checkedBoxes.length === 0) {
        selectAllCheckbox.checked = false;
        selectAllCheckbox.indeterminate = false;
    } else if (checkedBoxes.length === orderCheckboxes.length) {
        selectAllCheckbox.checked = true;
        selectAllCheckbox.indeterminate = false;
    } else {
        selectAllCheckbox.checked = false;
        selectAllCheckbox.indeterminate = true;
    }
}

// Execute bulk status change
async function executeBulkStatusChange() {
    const newStatus = document.getElementById('bulkNewStatus').value;
    const notes = document.getElementById('bulkStatusNotes').value;
    
    console.log('Bulk update debug:');
    console.log('- newStatus:', newStatus);
    console.log('- selectedOrderIds:', selectedOrderIds);
    console.log('- selectedOrderIds.length:', selectedOrderIds.length);
    
    if (!newStatus) {
        showBulkStatusAlert('Please select a new status', 'error');
        return;
    }
    
    if (selectedOrderIds.length === 0) {
        showBulkStatusAlert('Please select at least one order', 'error');
        return;
    }
    
    const executeBtn = document.getElementById('executeBulkStatusBtn');
    const originalText = executeBtn.textContent;
    
    try {
        executeBtn.disabled = true;
        executeBtn.innerHTML = '<div style="width: 16px; height: 16px; border: 2px solid #ffffff; border-top: 2px solid transparent; border-radius: 50%; animation: spin 1s linear infinite; margin-right: 8px;"></div>Updating...';
        
        const requestBody = {
            order_ids: selectedOrderIds,
            status_code: newStatus,
            notes: notes
        };
        
        console.log('Bulk update request body:', requestBody);
        
        const response = await fetch('/order-status/api/bulk-change', {
            method: 'POST',
            headers: {
                'Accept': 'application/json',
                'Content-Type': 'application/json',
                'X-Requested-With': 'XMLHttpRequest',
                'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').getAttribute('content')
            },
            body: JSON.stringify(requestBody),
            credentials: 'same-origin'
        });
        
        console.log('Bulk update response status:', response.status);
        
        if (!response.ok) {
            const errorText = await response.text();
            console.error('Bulk update API failed:', response.status, errorText);
            showBulkStatusAlert(`API Error: ${response.status} - ${errorText}`, 'error');
            return;
        }
        
        const data = await response.json();
        console.log('Bulk update response data:', data);
        
        if (data.success) {
            const successCount = data.summary ? data.summary.success : data.updated_count || 0;
            showBulkStatusAlert(`Successfully updated ${successCount} orders`, 'success');
            
            // Refresh the orders table
            setTimeout(() => {
                closeModal('bulkStatusModal');
                location.reload(); // Simple refresh for now
            }, 2000);
        } else {
            showBulkStatusAlert(data.message || 'Failed to update orders', 'error');
        }
    } catch (error) {
        console.error('Error updating orders:', error);
        showBulkStatusAlert('An error occurred while updating orders', 'error');
    } finally {
        executeBtn.disabled = false;
        executeBtn.textContent = originalText;
    }
}

// Show alert in bulk status modal
function showBulkStatusAlert(message, type) {
    const alertContainer = document.getElementById('bulkStatusAlert');
    if (!alertContainer) return;
    
    const alertClass = type === 'success' ? 'background: #d1fae5; color: #065f46; border: 1px solid #34d399;' : 'background: #fee2e2; color: #dc2626; border: 1px solid #f87171;';
    
    alertContainer.innerHTML = `
        <div style="padding: 12px 16px; border-radius: 8px; font-size: 14px; ${alertClass}">
            ${message}
        </div>
    `;
    alertContainer.style.display = 'block';
    
    // Auto-hide success messages
    if (type === 'success') {
        setTimeout(() => {
            alertContainer.style.display = 'none';
        }, 5000);
    }
}

// View order status history
async function viewOrderStatusHistory(orderId) {
    document.getElementById('statusHistoryModal').style.display = 'flex';
    
    try {
        const response = await fetch(`/order-status/api/orders/${orderId}/history`);
        const data = await response.json();
        
        if (data.success && data.data.length > 0) {
            renderStatusHistory(data.data);
        } else {
            document.getElementById('statusHistoryContent').innerHTML = `
                <div style="text-align: center; padding: 40px; color: #6b7280;">
                    No status history found for this order
                </div>
            `;
        }
    } catch (error) {
        console.error('Error loading status history:', error);
        document.getElementById('statusHistoryContent').innerHTML = `
            <div style="text-align: center; padding: 40px; color: #ef4444;">
                Error loading status history
            </div>
        `;
    }
}
// Render status history
function renderStatusHistory(history) {
    const content = document.getElementById('statusHistoryContent');
    
    content.innerHTML = `
        <div style="space-y: 16px;">
            ${history.map((entry, index) => `
                <div style="display: flex; gap: 16px; ${index < history.length - 1 ? 'border-bottom: 1px solid #e5e7eb; padding-bottom: 16px;' : ''}">
                    <div style="flex-shrink: 0; width: 40px; height: 40px; border-radius: 50%; background: ${getStatusColor(entry.status_code)}; display: flex; align-items: center; justify-content: center; color: white; font-weight: 600; font-size: 12px;">
                        ${entry.status ? entry.status.icon : '?'}
                    </div>
                    <div style="flex: 1;">
                        <div style="font-weight: 600; color: #111827; margin-bottom: 4px;">
                            ${entry.status ? entry.status.status_name : entry.status_code}
                        </div>
                        <div style="font-size: 14px; color: #6b7280; margin-bottom: 4px;">
                            ${formatDate(entry.changed_at)} by ${entry.changed_by ? entry.changed_by.name : 'System'}
                        </div>
                        ${entry.notes ? `<div style="font-size: 14px; color: #374151; background: #f9fafb; padding: 8px; border-radius: 6px; border-left: 3px solid ${getStatusColor(entry.status_code)};">${entry.notes}</div>` : ''}
                    </div>
                </div>
            `).join('')}
        </div>
    `;
}
// Get status color for history display
function getStatusColor(statusCode) {
    const colorMap = {
        'new': '#eab308',
        'on_hold': '#f97316', 
        'processing': '#3b82f6',
        'out_for_delivery': '#8b5cf6',
        'delivered': '#10b981',
        'cancelled': '#ef4444',
        'refunded': '#8b5cf6'
    };
    return colorMap[statusCode] || '#6b7280';
}

// Bulk selection functions for checkbox-based selection
function toggleAllOrdersSelection() {
    const selectAllCheckbox = document.getElementById('selectAllOrders');
    const orderCheckboxes = document.querySelectorAll('.order-checkbox');
    
    orderCheckboxes.forEach(checkbox => {
        checkbox.checked = selectAllCheckbox.checked;
    });
    
    updateBulkActionButtons();
}

function updateBulkActionButtons() {
    // Use selectedOrderIds array as source of truth instead of DOM queries
    const selectedCount = selectedOrderIds ? selectedOrderIds.length : 0;
    const bulkStatusBtn = document.querySelector('button[onclick="openBulkStatusModal()"]');
    const selectAllCheckbox = document.getElementById('selectAllOrders');
    const totalCheckboxes = document.querySelectorAll('.order-checkbox');
    
    // Update bulk status button
    if (bulkStatusBtn) {
        if (selectedCount > 0) {
            // Update button text while preserving the SVG icon
            const svgIcon = `<svg class="w-4 h-4 mr-2 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v10a2 2 0 002 2h8a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"></path>
                            </svg>`;
            bulkStatusBtn.innerHTML = svgIcon + `Bulk Status (${selectedCount})`;
            bulkStatusBtn.disabled = false;
            bulkStatusBtn.classList.remove('opacity-50', 'cursor-not-allowed');
        } else {
            // Reset button text while preserving the SVG icon
            const svgIcon = `<svg class="w-4 h-4 mr-2 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v10a2 2 0 002 2h8a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"></path>
                            </svg>`;
            bulkStatusBtn.innerHTML = svgIcon + 'Bulk Status';
            bulkStatusBtn.disabled = true;
            bulkStatusBtn.classList.add('opacity-50', 'cursor-not-allowed');
        }
    }
    
    // Update select all checkbox state based on actual checked checkboxes (for visual consistency)
    const selectedCheckboxes = document.querySelectorAll('.order-checkbox:checked');
    if (selectAllCheckbox && totalCheckboxes.length > 0) {
        if (selectedCheckboxes.length === 0) {
            selectAllCheckbox.checked = false;
            selectAllCheckbox.indeterminate = false;
        } else if (selectedCheckboxes.length === totalCheckboxes.length) {
            selectAllCheckbox.checked = true;
            selectAllCheckbox.indeterminate = false;
        } else {
            selectAllCheckbox.checked = false;
            selectAllCheckbox.indeterminate = true;
        }
    }
}

function getSelectedOrderIds() {
    // Source of truth is selectedOrderIds so table and modal stay in sync
    if (selectedOrderIds && selectedOrderIds.length) return [...selectedOrderIds];
    const selectedCheckboxes = document.querySelectorAll('.order-checkbox:checked');
    return Array.from(selectedCheckboxes).map(cb => parseInt(cb.value));
}
// Enhanced bulk status modal for checkbox-based selection
function openBulkStatusModal() {
    const selectedIds = selectedOrderIds && selectedOrderIds.length ? selectedOrderIds : getSelectedOrderIds();
    
    if (selectedIds.length === 0) {
        alert('Please select orders first by checking the checkboxes.');
        return;
    }
    
    // Load available statuses
    loadAvailableStatuses();
    
    // Reset form
    document.getElementById('bulkNewStatus').value = '';
    document.getElementById('bulkStatusNotes').value = '';
    
    // Update modal content to show selected orders
    const container = document.getElementById('bulkOrdersList');
    const selectedOrders = (window.ordersData || []).filter(order => selectedIds.includes(order.id));
    
    container.innerHTML = selectedOrders.map(order => `
        <div style="display: flex; align-items: center; gap: 8px; padding: 8px; background: #e0f2fe; border: 1px solid #0284c7; border-radius: 6px; margin-bottom: 4px;">
            <span style="color: #0284c7;">[âœ“]</span>
            <label style="flex: 1; font-size: 14px;">
                <span style="font-weight: 500;">#${order.order_number || order.id}</span>
                <span style="color: #6b7280; margin-left: 8px;">$${parseFloat(order.total_price || 0).toFixed(2)}</span>
                <span style="color: #6b7280; margin-left: 8px;">${order.order_status || 'unknown'}</span>
            </label>
        </div>
    `).join('');
    
    // Update selected count
    document.getElementById('selectedOrdersCount').textContent = `${selectedIds.length} orders selected`;
    document.getElementById('executeBulkStatusBtn').disabled = false;
    
    // Store selected IDs globally
    selectedOrderIds = selectedIds;
    
    document.getElementById('bulkStatusModal').style.display = 'flex';
}

// Initialize bulk status functionality when page loads
document.addEventListener('DOMContentLoaded', function() {
    // Store current orders globally for bulk operations
    window.currentOrders = [];
    
    // Initialize bulk action buttons state
    setTimeout(() => {
        updateBulkActionButtons();
    }, 1000);
});

// Bulk Rider Assignment Functions
function openBulkRiderModal() {
    const selectedIds = selectedOrderIds && selectedOrderIds.length ? selectedOrderIds : getSelectedOrderIds();
    
    if (selectedIds.length === 0) {
        alert('Please select orders first by checking the checkboxes.');
        return;
    }
    
    // Load riders
    fetch('/riders/active', { headers: { 'Accept': 'application/json' }})
        .then(r => r.json())
        .then(j => {
            const sel = document.getElementById('bulkRiderSelect');
            if (j && j.success && j.data) {
                sel.innerHTML = '<option value="">-- Select a rider to assign --</option>' + 
                    j.data.map(r => `<option value="${r.id}">${r.fullname}</option>`).join('');
            } else {
                sel.innerHTML = '<option value="">No riders found</option>';
            }
        })
        .catch(() => {
            document.getElementById('bulkRiderSelect').innerHTML = '<option value="">Failed to load riders</option>';
        });
    
    // Show selected orders
    const container = document.getElementById('bulkRiderOrdersList');
    const selectedOrders = (window.ordersData || []).filter(order => selectedIds.includes(order.id));
    
    container.innerHTML = selectedOrders.map(order => `
        <div style="display: flex; align-items: center; gap: 8px; padding: 8px; background: #e0f2fe; border: 1px solid #0891b2; border-radius: 6px; margin-bottom: 4px;">
            <span style="color: #0891b2;">[✓]</span>
            <label style="flex: 1; font-size: 14px;">
                <span style="font-weight: 500;">#${order.order_number || order.id}</span>
                <span style="color: #6b7280; margin-left: 8px;">${order.rider_name || 'No rider'}</span>
            </label>
        </div>
    `).join('');
    
    // Update count
    document.getElementById('selectedRiderOrdersCount').textContent = `${selectedIds.length} orders selected`;
    document.getElementById('executeBulkRiderBtn').disabled = false;
    
    // Store selected IDs
    selectedOrderIds = selectedIds;
    
    document.getElementById('bulkRiderModal').style.display = 'flex';
}

async function executeBulkRiderAssign() {
    const riderId = document.getElementById('bulkRiderSelect').value;
    const selectedIds = selectedOrderIds && selectedOrderIds.length ? selectedOrderIds : getSelectedOrderIds();
    
    if (selectedIds.length === 0) {
        alert('No orders selected');
        return;
    }
    
    if (!riderId) {
        alert('Please select a rider');
        return;
    }
    
    const btn = document.getElementById('executeBulkRiderBtn');
    const originalText = btn.textContent;
    btn.textContent = 'Assigning...';
    btn.disabled = true;
    
    try {
        // Assign rider to each order
        let successCount = 0;
        let failCount = 0;
        
        for (const orderId of selectedIds) {
            try {
                const response = await fetch(`/orders/${orderId}/rider/assign`, {
                    method: 'POST',
                    headers: {
                        'Accept': 'application/json',
                        'Content-Type': 'application/json',
                        'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').getAttribute('content')
                    },
                    body: JSON.stringify({ rider_user_id: parseInt(riderId, 10) })
                });
                
                const data = await response.json();
                if (data.success) {
                    successCount++;
                } else {
                    failCount++;
                }
            } catch (error) {
                failCount++;
            }
        }
        
        // Show results
        alert(`Bulk assignment complete!\nSuccess: ${successCount}\nFailed: ${failCount}`);
        
        // Close modal and refresh
        closeModal('bulkRiderModal');
        location.reload();
        
    } catch (error) {
        alert('Bulk assignment failed: ' + error.message);
        btn.textContent = originalText;
        btn.disabled = false;
    }
}

// ============================================
// RIDERS TAB FUNCTIONS
// ============================================

/**
 * Switch to Riders tab - shows rider-wise breakdown
 */
function switchToRiders() {
    const tableContainer = document.querySelector('.orders-table-container');
    if (tableContainer) tableContainer.classList.add('opacity-60');

    // Hide other cards
    hideAllCardSections();

    fetch('/orders/filter?source=other&tab=riders')
        .then(res => res.json())
        .then(data => {
            if (!data || !data.success) return false;

            // Update URL
            const url = new URL(window.location);
            url.searchParams.set('source', 'other');
            url.searchParams.set('tab', 'riders');
            window.history.pushState({}, '', url);

            // Update page title
            const pageTitle = document.querySelector('h1');
            if (pageTitle) pageTitle.textContent = 'Orders';

            // Update tabs
            updateTabsForRiders(data);

            // Load rider cards after a short delay
            console.log('Switching to Riders - loading rider cards...');
            setTimeout(() => {
                loadRiderCards();
            }, 200);

            // Render open orders dataset (same as open orders tab)
            rebuildTableWithOrders(data.orders, 'other', 'riders');
            
            // Update pagination for filtered results
            updatePaginationForTab(data.orders, 'other', 'riders', data.open_count);
            
            // Remove opacity
            if (tableContainer) tableContainer.classList.remove('opacity-60');
        })
        .catch(err => {
            console.error('Error switching to riders:', err);
            if (tableContainer) tableContainer.classList.remove('opacity-60');
        });
}

/**
 * Update tabs for riders view
 */
function updateTabsForRiders(data) {
    const tabsContainer = document.querySelector('.flex.space-x-1.bg-gray-100');
    if (tabsContainer) {
        tabsContainer.innerHTML = `
            <a href="#" onclick="return switchToInvoices()" class="px-3 py-1.5 rounded-md text-sm font-medium transition-all duration-200 text-gray-600 hover:text-gray-800 hover:bg-gray-50">
                Invoices
                <span class="ml-1.5 px-1.5 py-0.5 bg-blue-100 text-blue-800 text-xs rounded-full font-semibold" id="badge-invoices">${data.other_count || '-'}</span>
            </a>
            <button onclick="switchToOpenOrders()" class="px-3 py-1.5 rounded-md text-sm font-medium transition-all duration-200 text-gray-600 hover:text-gray-800 hover:bg-gray-50">
                Open Orders
                <span class="ml-1.5 px-1.5 py-0.5 bg-blue-100 text-blue-800 text-xs rounded-full font-semibold" id="badge-open">${data.open_count || '-'}</span>
            </button>
            <button class="px-3 py-1.5 rounded-md text-sm font-medium transition-all duration-200 bg-white text-blue-600 shadow-sm">
                Riders
                <span class="ml-1.5 px-1.5 py-0.5 bg-blue-100 text-blue-800 text-xs rounded-full font-semibold" id="badge-riders">${data.open_count || '-'}</span>
            </button>
            <button onclick="switchToShopifyApprovals()" class="px-3 py-1.5 rounded-md text-sm font-medium transition-all duration-200 text-gray-600 hover:text-gray-800 hover:bg-gray-50">
                Order Approvals
                <span class="ml-1.5 px-1.5 py-0.5 bg-blue-100 text-blue-800 text-xs rounded-full font-semibold" id="badge-approvals">${data.shopify_approvals_count || '-'}</span>
            </button>
        `;
    }

    // Show riders cards section, hide status cards
    const ridersCards = document.getElementById('ridersCards');
    const statusCards = document.getElementById('openOrdersStatusCards');
    if (ridersCards) ridersCards.style.display = 'block';
    if (statusCards) statusCards.style.display = 'none';

    // Hide the Open-Orders Rider Live Board on other tabs.
    updateRiderLiveBoardVisibility();
}

/**
 * Load rider cards from API
 */
async function loadRiderCards() {
    console.log('Loading rider cards...');
    const container = document.getElementById('ridersCardsContainer');
    
    try {
        const response = await fetch('/orders/rider-counts', {
            headers: { 
                'Accept': 'application/json',
                'X-Requested-With': 'XMLHttpRequest' 
            },
            credentials: 'same-origin'
        });
        
        const data = await response.json();
        console.log('Rider cards API response:', data);
        
        if (data.success) {
            renderRiderCards(data);
        } else {
            console.error('Failed to load rider counts:', data.message);
            if (container) {
                container.innerHTML = '<div class="flex items-center justify-center py-8 text-red-500">Failed to load rider data: ' + (data.message || 'Unknown error') + '</div>';
            }
        }
    } catch (error) {
        console.error('Error loading rider cards:', error);
        if (container) {
            container.innerHTML = '<div class="flex items-center justify-center py-8 text-red-500">Error loading rider cards. Please refresh the page.</div>';
        }
    }
}

/**
 * Render rider cards with modern design
 */
function renderRiderCards(data) {
    console.log('Rendering rider cards:', data);
    const container = document.getElementById('ridersCardsContainer');
    if (!container) {
        console.log('Rider cards container not found!');
        return;
    }

    const { riders, unassigned_count, unassigned_breakdown, total_open_count, assigned_count, riders_count } = data;

    // Start with summary cards
    let cardsHtml = '';

    // Card 1: Total Open Orders
    cardsHtml += `
        <div class="rider-card">
            <div class="flex items-center justify-between p-4 bg-white rounded-lg border-2 border-blue-200 shadow-sm hover:shadow-md transition-all duration-200 cursor-default min-w-[160px]">
                <div>
                    <div class="text-2xl font-bold text-blue-600">${total_open_count}</div>
                    <div class="text-sm font-medium text-gray-700">Total Open</div>
                </div>
                <div class="text-2xl">📦</div>
            </div>
        </div>
    `;

    // Card 2: Assigned Orders
    cardsHtml += `
        <div class="rider-card">
            <div class="flex items-center justify-between p-4 bg-white rounded-lg border-2 border-green-200 shadow-sm hover:shadow-md transition-all duration-200 cursor-default min-w-[160px]">
                <div>
                    <div class="text-2xl font-bold text-green-600">${assigned_count}</div>
                    <div class="text-sm font-medium text-gray-700">Assigned</div>
                    <div class="text-xs text-gray-500 mt-1">${riders_count} Riders</div>
                </div>
                <div class="text-2xl">✅</div>
            </div>
        </div>
    `;

    // Card 3: Unassigned Orders
    const unassignedBreakdownText = formatStatusBreakdown(unassigned_breakdown);
    cardsHtml += `
        <div class="rider-card" onclick="filterByRider(null)">
            <div class="flex items-center justify-between p-4 bg-white rounded-lg border-2 border-amber-200 shadow-sm hover:shadow-md transition-all duration-200 cursor-pointer min-w-[160px]">
                <div>
                    <div class="text-2xl font-bold text-amber-600">${unassigned_count}</div>
                    <div class="text-sm font-medium text-gray-700">Unassigned</div>
                    ${unassignedBreakdownText ? `<div class="text-xs text-gray-500 mt-1">${unassignedBreakdownText}</div>` : ''}
                </div>
                <div class="text-2xl">❓</div>
            </div>
        </div>
    `;

    // Add individual rider cards
    riders.forEach(rider => {
        const breakdownText = formatStatusBreakdown(rider.status_breakdown);
        const safeName = (rider.rider_name || '').replace(/'/g, "\\'");
        cardsHtml += `
            <div class="rider-card" onclick="filterByRider(${rider.rider_id})">
                <div class="relative flex items-center justify-between p-4 bg-white rounded-lg border border-gray-200 shadow-sm hover:shadow-md hover:border-blue-300 transition-all duration-200 cursor-pointer min-w-[200px]" data-rider-live-id="${rider.rider_id}">
                    <div class="flex-1 pr-6">
                        <div class="text-2xl font-bold text-gray-800">${rider.total_count}</div>
                        <div class="text-sm font-semibold text-gray-900 flex items-center gap-1">
                            <span id="gpsDot_${rider.rider_id}" class="inline-block w-2 h-2 rounded-full bg-gray-300" title="GPS status"></span>
                            <span>${rider.rider_name}</span>
                            <span id="gpsAge_${rider.rider_id}" class="text-[10px] font-normal text-gray-400"></span>
                        </div>
                        ${breakdownText ? `<div class="text-xs text-gray-500 mt-1 leading-relaxed">${breakdownText}</div>` : ''}
                        <div id="dispatchStatus_${rider.rider_id}" class="text-[11px] font-semibold mt-1 leading-tight"></div>
                    </div>
                    <button onclick="event.stopPropagation(); openRiderDispatchPopup(${rider.rider_id}, '${safeName}')"
                            class="absolute top-2 right-2 text-base leading-none hover:scale-110 transition-transform"
                            title="Open dispatch tracker for ${rider.rider_name}">🚀</button>
                </div>
            </div>
        `;
    });

    container.innerHTML = cardsHtml;

    // ⭐ Enrich cards with live GPS freshness + dispatch status (non-blocking).
    enrichRiderCardsLive();
    // ⭐ Keep them fresh silently (no full page / card re-render).
    startRiderLiveAutoRefresh();
}

/**
 * Silent auto-refresh of the live GPS + dispatch status on the rider cards.
 * Only updates the small live elements in place (dot / age / status line) so
 * there is no flicker or full re-render. Pauses when the cards are off-screen
 * (different tab) or the browser tab is hidden.
 */
function startRiderLiveAutoRefresh() {
    if (window._riderLiveInterval) clearInterval(window._riderLiveInterval);
    window._riderLiveInterval = setInterval(() => {
        const container = document.getElementById('ridersCardsContainer');
        if (!container || container.offsetParent === null) return; // hidden / other tab
        if (document.hidden) return;                                 // browser tab not visible
        if (!document.querySelector('[data-rider-live-id]')) return; // no rider cards rendered
        enrichRiderCardsLive();
    }, 30000);
}

/**
 * Fetch live per-rider GPS freshness + dispatch status and update the cards
 * in place. Reuses the same logic as the Dispatch Tracker (backend).
 */
async function enrichRiderCardsLive() {
    try {
        const res = await fetch('/orders/riders-map/live-status', {
            headers: { 'Accept': 'application/json', 'X-Requested-With': 'XMLHttpRequest' },
            credentials: 'same-origin'
        });
        const data = await res.json();
        if (!data || !data.success) return;
        document.querySelectorAll('[data-rider-live-id]').forEach(el => {
            const id = el.getAttribute('data-rider-live-id');
            updateRiderCardLive(id, (data.gps || {})[id], (data.dispatch || {})[id]);
        });
    } catch (e) {
        /* non-fatal — cards still work without live status */
    }
}

function updateRiderCardLive(id, gps, dispatch) {
    const dot = document.getElementById('gpsDot_' + id);
    const age = document.getElementById('gpsAge_' + id);
    // "Active" = we have a GPS fix within the last hour. No GPS, or older than
    // an hour, is shown as "Not active" so every rider stays trackable.
    const ageMin = (gps && gps.age_minutes !== null && gps.age_minutes !== undefined) ? gps.age_minutes : null;
    const isFresh = !!(gps && gps.is_fresh);
    const isActive = ageMin !== null && ageMin <= 60;

    if (dot) {
        if (isFresh) {
            dot.style.background = '#10b981'; // green — live GPS
            dot.title = 'GPS active · ' + (gps.age_text || '');
        } else if (isActive) {
            dot.style.background = '#f59e0b'; // amber — seen within the hour
            dot.title = 'GPS · ' + (gps.age_text || '');
        } else {
            dot.style.background = '#9ca3af'; // grey — not active
            dot.title = gps ? ('GPS · ' + (gps.age_text || '')) : 'No GPS signal';
        }
    }
    if (age) {
        if (isFresh) {
            age.textContent = 'now';
            age.style.color = '#16a34a';
        } else if (isActive) {
            age.textContent = gps.age_text || '';
            age.style.color = '#9ca3af';
        } else {
            age.textContent = 'Not active';
            age.style.color = '#9ca3af';
        }
    }

    const statusEl = document.getElementById('dispatchStatus_' + id);
    if (statusEl) statusEl.innerHTML = dispatch ? formatLiveDispatchStatus(dispatch) : '';
}

/**
 * One-line dispatch status for a rider card.
 */
function formatLiveDispatchStatus(d) {
    const rto = d.return_to_office;
    switch (d.status) {
        case 'left_without_dispatch':
            return `<span style="color:#dc2626;">⚠️ Left without dispatch · ${d.undispatched_count} order${d.undispatched_count !== 1 ? 's' : ''}</span>`;
        case 'waiting_at_office':
            return `<span style="color:#b45309;">🏠 At office · ${d.undispatched_count} to dispatch</span>`;
        case 'on_route':
            return `<span style="color:#15803d;">🚚 On route · ${d.dispatched_count} left</span>`;
        case 'returning':
            return `<span style="color:#0369a1;">🏠 Back by ${rto ? rto.arrival_display : '—'}${rto ? ` (~${rto.minutes} min)` : ''}${d.undispatched_count > 0 ? ` · ${d.undispatched_count} to dispatch` : ''}</span>`;
        case 'at_office':
            return `<span style="color:#6b7280;">🏠 At office</span>`;
        case 'away_unknown':
            return `<span style="color:#6b7280;">📍 Away</span>`;
        default:
            return '';
    }
}

/* ============ Rider Live Board (Open Orders tab quick-glance) ============ */
let _riderBoardInterval = null;

function riderBoardShouldShow() {
    // The default /orders landing renders the Open Orders tab server-side WITHOUT
    // any ?source/?tab query params, so reading the URL alone wrongly hides the
    // board on a fresh load / hard refresh. Trust the runtime context
    // (window.currentSource / window.currentTab) which is set from the server on
    // first render and kept in sync on every client-side tab switch; fall back to
    // the URL params only if those globals are somehow missing.
    const params = new URLSearchParams(window.location.search);
    const source = window.currentSource || params.get('source') || 'other';
    const tab = window.currentTab || params.get('tab') || 'open';
    const onOpen = (source === 'other' && tab === 'open');
    return onOpen && window.innerWidth >= 1024;
}

/* ====== Live WhatsApp-automation strips (Open Orders tab) ======
   Server-rendered from OrderController::liveAutomationBanners() — no polling.
   Two independent hide paths:
     • ✕  = dismissed for TODAY, remembered in localStorage per rule + date, so
            it returns on the next calendar day (the point of the reminder).
     • Turn off = actually disables the rule; the strip goes for good because
            the server stops rendering it on the next load.
   Visibility follows the Open Orders tab via nfSyncAutomationBanners(), called
   from the same places the rider board's visibility is updated. */
function nfAutoBannerToday() {
    const d = new Date();
    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
}

function nfAutoBannerDismissed(key) {
    try {
        return localStorage.getItem('nfAutoBannerDismissed:' + key) === nfAutoBannerToday();
    } catch (e) {
        return false; // private mode / storage blocked — just show it
    }
}

window.nfDismissAutomationBanner = function(key) {
    try { localStorage.setItem('nfAutoBannerDismissed:' + key, nfAutoBannerToday()); } catch (e) {}
    nfSyncAutomationBanners();
};

window.nfTurnOffAutomation = function(key, btn) {
    if (!confirm('Turn this automation off?\n\nNo further messages will be sent until you switch it back on in Messages → 🤖.')) return;
    if (btn) { btn.disabled = true; btn.textContent = 'Turning off…'; }
    fetch('/messages/automations/rules/' + encodeURIComponent(key) + '/enabled', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Accept': 'application/json', 'X-Requested-With': 'XMLHttpRequest', 'X-CSRF-TOKEN': csrf() },
        credentials: 'same-origin',
        body: JSON.stringify({ enabled: false })
    })
    .then(r => r.json())
    .then(d => {
        if (d && d.success) {
            const row = document.querySelector('.nf-auto-banner[data-rule="' + key + '"]');
            if (row) row.remove();
            nfSyncAutomationBanners();
        } else {
            alert((d && d.message) || 'Could not turn it off. Try Messages → 🤖.');
            if (btn) { btn.disabled = false; btn.textContent = 'Turn off'; }
        }
    })
    .catch(() => {
        alert('Could not turn it off. Try Messages → 🤖.');
        if (btn) { btn.disabled = false; btn.textContent = 'Turn off'; }
    });
};

function nfSyncAutomationBanners() {
    const host = document.getElementById('nfAutomationBanners');
    if (!host) return;

    // Same runtime-context read as riderBoardShouldShow() — the default /orders
    // landing renders Open Orders with no ?source/?tab params, so trust the
    // globals first. No width test: the strip is one line and fits anywhere.
    const params = new URLSearchParams(window.location.search);
    const source = window.currentSource || params.get('source') || 'other';
    const tab = window.currentTab || params.get('tab') || 'open';
    const onOpenOrders = (source === 'other' && tab === 'open');

    let visible = 0;
    host.querySelectorAll('.nf-auto-banner').forEach(row => {
        const show = onOpenOrders && !nfAutoBannerDismissed(row.dataset.rule);
        row.style.display = show ? 'flex' : 'none';
        if (show) visible++;
    });
    host.style.display = visible > 0 ? 'block' : 'none';
}

document.addEventListener('DOMContentLoaded', nfSyncAutomationBanners);

function updateRiderLiveBoardVisibility() {
    // Keep the automation strips in step with every client-side tab switch
    // (this runs from updateTabsForOpenOrders / updateTabsForRiders).
    nfSyncAutomationBanners();

    const col = document.getElementById('riderLiveBoardCol');
    if (!col) return;
    var nfc = document.getElementById('nfRiderCards'); // S3: keep the new cards row visible in lockstep with the board
    if (riderBoardShouldShow()) {
        col.style.display = 'flex';
        if (nfc) nfc.style.display = 'block';
        loadRiderLiveBoard();
        startRiderBoardAutoRefresh();
    } else {
        col.style.display = 'none';
        if (nfc) nfc.style.display = 'none';
        if (_riderBoardInterval) { clearInterval(_riderBoardInterval); _riderBoardInterval = null; }
    }
}

function startRiderBoardAutoRefresh() {
    if (_riderBoardInterval) clearInterval(_riderBoardInterval);
    _riderBoardInterval = setInterval(() => {
        const col = document.getElementById('riderLiveBoardCol');
        if (!col || col.style.display === 'none' || document.hidden) return;
        loadRiderLiveBoard();
    }, 30000);
}

/* Delivery-rider roster (t_ops_rider_profile.active), cached for the page.
   Why it is needed: t_ops_attendance covers EVERY member of staff, so "checked in
   today" on its own would put office and store people on a riders board. The roster
   is what makes a check-in mean "a rider is on duty". It only changes when someone
   ticks Delivery Rider in Attendance → People, so one fetch per page load is plenty
   — and caching on success only means a failed fetch simply retries on the next poll
   instead of poisoning the cache. Fail-soft: no roster ⇒ the board still lists every
   rider holding open orders, it just can't add the idle on-duty ones. */
let _riderRosterCache = null;
async function riderRosterList() {
    if (_riderRosterCache) return _riderRosterCache;
    try {
        const res = await fetch('/riders/active', { headers: {'Accept':'application/json','X-Requested-With':'XMLHttpRequest'}, credentials:'same-origin' });
        const j = await res.json();
        if (j && j.success && Array.isArray(j.data)) _riderRosterCache = j.data;
    } catch (e) { /* fail-soft — see above */ }
    return _riderRosterCache || [];
}

async function loadRiderLiveBoard() {
    const body = document.getElementById('riderLiveBoardBody');
    const meta = document.getElementById('riderLiveBoardMeta');
    if (!body) return;
    try {
        const [countsRes, liveRes, roster] = await Promise.all([
            fetch('/orders/rider-counts', { headers: {'Accept':'application/json','X-Requested-With':'XMLHttpRequest'}, credentials:'same-origin' }),
            fetch('/orders/riders-map/live-status', { headers: {'Accept':'application/json','X-Requested-With':'XMLHttpRequest'}, credentials:'same-origin' }),
            riderRosterList(),   // cached after the first call, so this is free from poll 2 on
        ]);
        const counts = await countsRes.json();
        const live = await liveRes.json();
        if (!counts || !counts.success) { body.innerHTML = '<div class="px-3 py-3 text-xs text-gray-400">No rider data.</div>'; return; }
        const gps = (live && live.gps) || {};
        const disp = (live && live.dispatch) || {};
        const checkedIn = new Set((live && live.checked_in ? live.checked_in : []).map(String));

        // Aug-2026 — who the board lists. It used to be the INTERSECTION (checked in
        // AND holding an order), which quietly dropped the case that matters most: a
        // rider who never checked in but has orders sitting in the table below. It is
        // now the union of two rules:
        //   1. holds ≥1 open order  — counts.riders IS that list, so no filter at all;
        //   2. is a delivery rider who checked in today, even with nothing assigned,
        //      so you can see who is free (roster ∩ checked-in — attendance alone is
        //      not enough, it covers all staff).
        // Every row carries is_checked_in so the renderers can mark the off-duty ones.
        // A rider in (1) but not on the roster still shows — he is holding real work.
        let riders = (counts.riders || []).slice();
        const listed = new Set(riders.map(r => String(r.rider_id)));
        (roster || []).forEach(u => {
            const rid = String(u.id);
            if (listed.has(rid) || !checkedIn.has(rid)) return;
            listed.add(rid);
            riders.push({ rider_id: u.id, rider_name: u.fullname, total_count: 0, status_breakdown: {} });
        });
        riders.forEach(r => { r.is_checked_in = checkedIn.has(String(r.rider_id)); });

        if (riders.length === 0) {
            body.innerHTML = '<div class="px-3 py-3 text-xs text-gray-400">No riders on duty or holding orders.</div>';
            if (meta) meta.textContent = '';
            if (window.nfRenderRiderCards) nfRenderRiderCards([], {}, {}); // S3: keep the new cards row in sync (shows just the Unassigned card)
            return;
        }
        // Sort so the riders that need attention surface first:
        //   0 = left office without dispatching, 1 = lost GPS while mid-delivery,
        //   then the normal flow (waiting → returning → on route → at office).
        // Off duty is only the TIE-BREAKER, never the primary key: a rider out
        // delivering without having checked in must not be buried at the bottom.
        const sorted = riders.slice().sort((a, b) => {
            const pa = riderBoardPriority(gps[a.rider_id], disp[a.rider_id]);
            const pb = riderBoardPriority(gps[b.rider_id], disp[b.rider_id]);
            if (pa !== pb) return pa - pb;
            if (a.is_checked_in !== b.is_checked_in) return a.is_checked_in ? -1 : 1;
            return 0;
        });
        body.innerHTML = sorted.map(r => renderRiderBoardRow(r, gps[r.rider_id], disp[r.rider_id])).join('');
        if (window.nfRenderRiderCards) nfRenderRiderCards(sorted, gps, disp); // S3: feed the new full-width cards from the SAME data (no extra fetch)
        if (meta) meta.textContent = 'updated ' + new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'});
    } catch (e) {
        body.innerHTML = '<div class="px-3 py-3 text-xs text-gray-400">Live status unavailable.</div>';
    }
}

// True when a rider is actively delivering (on a dispatch) but his GPS has
// gone stale — i.e. he "lost GPS" mid-delivery. We treat >15 min old, or no
// fix at all, as lost.
function riderGpsLostMidDelivery(gps, dispatch) {
    const status = (dispatch || {}).status;
    if (status !== 'on_route') return false;
    const ageMin = (gps && gps.age_minutes !== null && gps.age_minutes !== undefined) ? gps.age_minutes : null;
    return (ageMin === null) || (ageMin > 15);
}

// Lower number = higher up the board (needs attention first).
function riderBoardPriority(gps, dispatch) {
    const status = (dispatch || {}).status;
    if (status === 'left_without_dispatch') return 0;
    if (riderGpsLostMidDelivery(gps, dispatch)) return 1;
    const rank = { waiting_at_office: 3, returning: 4, on_route: 5, at_office: 6, away_unknown: 7 };
    return rank[status] ?? 9;
}

function renderRiderBoardRow(rider, gps, dispatch) {
    const id = rider.rider_id;
    const name = (rider.rider_name || ('Rider #' + id));
    const safeName = name.replace(/'/g, "\\'");
    const status = (dispatch || {}).status;

    const leftNoDispatch = (status === 'left_without_dispatch');
    const gpsLost = riderGpsLostMidDelivery(gps, dispatch);

    // GPS column
    const ageMin = (gps && gps.age_minutes !== null && gps.age_minutes !== undefined) ? gps.age_minutes : null;
    let dotColor = '#9ca3af', gpsTxt = 'Not active';
    if (gps && gps.is_fresh) { dotColor = '#10b981'; gpsTxt = 'now'; }
    else if (ageMin !== null && ageMin <= 60) { dotColor = '#f59e0b'; gpsTxt = gps.age_text || (ageMin + 'm ago'); }
    // A rider who dropped GPS while delivering gets a red GPS cell so it's obvious.
    if (gpsLost) { dotColor = '#ef4444'; gpsTxt = (ageMin === null) ? 'GPS lost' : ('lost · ' + (gps.age_text || (ageMin + 'm ago'))); }

    // Off duty = listed because he holds open orders, but no attendance check-in
    // today. Same flag and same wording as the cards (nfRiderCardHtml) — this board
    // is CSS-hidden on the orders page but still rendered, so it must not disagree.
    const offDuty = (rider.is_checked_in === false);
    const openCount = rider.total_count || 0;

    // Status column (without the return-ETA — that gets its own column)
    let statusHtml = dispatch ? formatBoardStatus(dispatch) : '';
    if (!statusHtml) {
        statusHtml = offDuty
            ? `<span style="color:#64748b;">${openCount} order${openCount === 1 ? '' : 's'} waiting</span>`
            : (openCount > 0
                ? `<span style="color:#6b7280;">📋 ${openCount} assigned</span>`
                : '<span style="color:#9ca3af;">✓ On duty · free</span>');
    }

    // Back-to-office column
    const rto = dispatch && dispatch.return_to_office;
    const backHtml = rto
        ? `🏠 ${rto.arrival_display}<div style="font-size:9px;font-weight:500;color:#94a3b8;">~${rto.minutes} min</div>`
        : '<span style="color:#cbd5e1;">—</span>';

    // Row highlight: red for left-without-dispatch, amber for lost-GPS. Off duty is
    // checked LAST so neither alert can be softened by it.
    let rowStyle = '', nameStyle = '';
    if (leftNoDispatch) { rowStyle = 'background:#fef2f2;box-shadow:inset 3px 0 0 #ef4444;'; nameStyle = 'color:#b91c1c;font-weight:700;'; }
    else if (gpsLost) { rowStyle = 'background:#fff7ed;box-shadow:inset 3px 0 0 #f59e0b;'; nameStyle = 'color:#b45309;font-weight:700;'; }
    else if (offDuty) { rowStyle = 'background:#fcfcfd;'; nameStyle = 'color:#64748b;'; }

    const offTag = offDuty
        ? '<span title="No attendance check-in today" style="font-size:8.5px;font-weight:800;letter-spacing:.03em;text-transform:uppercase;color:#64748b;background:#f1f5f9;border:1px solid #e2e8f0;border-radius:999px;padding:1px 5px;margin-left:5px;">off duty</span>'
        : '';

    return `
      <div class="riderboard-row riderboard-data" style="${rowStyle}" onclick="openRiderDispatchPopup(${id}, '${safeName}')" title="Open dispatch tracker">
        <div class="riderboard-cell-name">
          <span class="riderboard-dot" style="background:${dotColor};"></span>
          <span class="nm" style="${nameStyle}">${name}</span>${offTag}
        </div>
        <div class="riderboard-gps"${gpsLost ? ' style="color:#ef4444;font-weight:600;"' : ''}>${gpsTxt}</div>
        <div class="riderboard-status">${statusHtml}</div>
        <div class="riderboard-back">${backHtml}</div>
      </div>`;
}

/**
 * Status text for the board's Status column — same wording as the card status
 * line but WITHOUT the return-ETA (the board shows that in its own column).
 */
function formatBoardStatus(d) {
    switch (d.status) {
        case 'left_without_dispatch':
            return `<span style="color:#dc2626;">⚠️ Left w/o dispatch · ${d.undispatched_count}</span>`;
        case 'waiting_at_office':
            return `<span style="color:#b45309;">🏠 At office · ${d.undispatched_count} to dispatch</span>`;
        case 'on_route':
            return `<span style="color:#15803d;">🚚 On route · ${d.dispatched_count} left</span>`;
        case 'returning':
            return `<span style="color:#0369a1;">↩️ Returning${d.undispatched_count > 0 ? ` · ${d.undispatched_count} to dispatch` : ''}</span>`;
        case 'at_office':
            return `<span style="color:#6b7280;">🏠 At office</span>`;
        case 'away_unknown':
            return `<span style="color:#6b7280;">📍 Away</span>`;
        default:
            return '';
    }
}

let _riderBoardResizeTimer = null;
window.addEventListener('resize', () => {
    clearTimeout(_riderBoardResizeTimer);
    _riderBoardResizeTimer = setTimeout(updateRiderLiveBoardVisibility, 250);
});

/**
 * Per-rider Dispatch Tracker popup — reuses the dispatch-report data
 * (live ongoing + today's delivered summary).
 */
async function openRiderDispatchPopup(riderId, riderName) {
    let modal = document.getElementById('riderDispatchModal');
    if (!modal) {
        modal = document.createElement('div');
        modal.id = 'riderDispatchModal';
        modal.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,0.5); z-index:9999; display:flex; align-items:center; justify-content:center; padding:16px;';
        modal.onclick = (e) => { if (e.target === modal) closeRiderDispatchPopup(); };
        modal.innerHTML = '<div id="riderDispatchModalBox" style="background:#fff; border-radius:12px; max-width:680px; width:100%; max-height:85vh; overflow:auto; box-shadow:0 20px 50px rgba(0,0,0,0.3);"></div>';
        document.body.appendChild(modal);
    }
    const box = document.getElementById('riderDispatchModalBox');
    box.innerHTML = `<div style="padding:40px; text-align:center; color:#6b7280;">Loading dispatch tracker for ${riderName}...</div>`;
    modal.style.display = 'flex';

    // Tear down any mini-map from a previously opened rider (its DOM node is about
    // to be replaced) so we never leave a stale Leaflet instance bound to a dead node.
    if (_riderMiniMapInstance) { try { _riderMiniMapInstance.remove(); } catch (e) {} _riderMiniMapInstance = null; }

    try {
        // Use the LOCAL date, not toISOString() (which is UTC). Between midnight and
        // ~5am PKT the UTC date is still "yesterday", and the live ongoing-dispatch
        // data is only computed for today — so the UTC date made the tracker wrongly
        // show "No active dispatch" for riders dispatched in the early hours.
        const today = localTodayStr();
        const res = await fetch(`/orders/riders-map/dispatch-report?date=${today}`, {
            headers: { 'Accept': 'application/json', 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').getAttribute('content') }
        });
        const data = await res.json();
        if (!data.success) throw new Error(data.message || 'Failed');
        const ongoing = (data.ongoing || []).find(o => String(o.rider_id) === String(riderId)) || null;
        const delivered = (data.riders || []).find(r => String(r.id) === String(riderId)) || null;
        box.innerHTML = renderRiderDispatchPopup(riderId, riderName, ongoing, delivered);
    } catch (err) {
        box.innerHTML = `<div style="padding:24px;"><div style="color:#ef4444;">Failed to load: ${err.message}</div><div style="text-align:right; margin-top:12px;"><button onclick="closeRiderDispatchPopup()" style="padding:6px 14px; border:1px solid #d1d5db; border-radius:6px; background:#fff; cursor:pointer;">Close</button></div></div>`;
    }
}

function closeRiderDispatchPopup() {
    const modal = document.getElementById('riderDispatchModal');
    if (modal) modal.style.display = 'none';
    // Release the Leaflet map so it doesn't keep timers/tiles alive while hidden.
    if (_riderMiniMapInstance) { try { _riderMiniMapInstance.remove(); } catch (e) {} _riderMiniMapInstance = null; }
}

function renderRiderDispatchPopup(riderId, riderName, ongoing, delivered) {
    // Stash context so the mini-map + its refresh button can act without re-fetching
    // the dispatch report.
    window._riderDispatchCtx = { riderId: riderId, riderName: riderName, ongoing: ongoing, delivered: delivered };
    const meta = {
        left_without_dispatch: { label: '⚠️ Left without dispatch', color: '#991b1b', bg: '#fee2e2' },
        waiting_at_office:     { label: '🏠 Waiting at office',      color: '#854d0e', bg: '#fef9c3' },
        returning:             { label: '🏠 Returning to office',    color: '#075985', bg: '#e0f2fe' },
        on_route:              { label: '🚚 On route',               color: '#166534', bg: '#dcfce7' },
        at_office:             { label: '🏠 At office',              color: '#374151', bg: '#f3f4f6' },
        away_unknown:          { label: '📍 Away (GPS stale)',       color: '#6b7280', bg: '#f3f4f6' },
        idle:                  { label: '• Idle',                    color: '#6b7280', bg: '#f3f4f6' },
    };
    const badge = (txt, color, bg) => `<span style="background:${bg}; color:${color}; padding:3px 8px; border-radius:6px; font-size:11px; font-weight:700;">${txt}</span>`;

    let liveHtml;
    if (ongoing) {
        const m = meta[ongoing.status] || meta.idle;
        const rto = ongoing.return_to_office;
        const officeEta = rto ? badge(`🏠 Back in ~${rto.minutes} min · by ${rto.arrival_display}${rto.source !== 'google_maps' ? ' (approx)' : ''}`, '#075985', '#e0f2fe') : '';
        const dist = ongoing.distance_to_office_display ? badge(`📍 ${ongoing.distance_to_office_display} from office`, '#374151', '#f3f4f6') : '';
        const agm = (ongoing.gps_age_minutes !== null && ongoing.gps_age_minutes !== undefined) ? ongoing.gps_age_minutes : null;
        const gpsBadge = agm === null
            ? badge('⚪ No GPS', '#6b7280', '#f3f4f6')
            : (agm <= 6 ? badge('🟢 GPS now', '#166534', '#dcfce7')
            : (agm <= 60 ? badge(`🟠 GPS ${ongoing.gps_age_text || (agm + ' min ago')}`, '#854d0e', '#fef9c3')
            : badge(`⚪ GPS ${ongoing.gps_age_text || (agm + ' min ago')}`, '#6b7280', '#f3f4f6')));
        const waves = (ongoing.dispatch_batches || []).map(b => {
            const orders = (b.orders || []).map(o => `
                <div style="display:flex; justify-content:space-between; gap:8px; padding:4px 0; border-bottom:1px dashed #f0f0f0; font-size:12px;">
                    <span style="color:#374151;">${o.priority ? `<b>${o.priority}.</b> ` : ''}${o.order_number} — ${o.customer_name}</span>
                    <span style="white-space:nowrap; color:${o.payment_type === 'cash' ? '#166534' : '#1d4ed8'};">${o.eta_window ? `🕒 ${o.eta_window}` : ''}</span>
                </div>`).join('');
            return `<div style="margin-top:8px; border:1px solid #e5e7eb; border-radius:8px; overflow:hidden;">
                <div style="background:#f9fafb; padding:6px 10px; font-size:12px; font-weight:600; color:#374151; display:flex; justify-content:space-between;">
                    <span>🚀 Dispatched ${b.dispatch_time_display}</span>
                    <span style="color:#6b7280;">${b.delivered_count}/${b.total_count} delivered · ${b.pending_count} pending</span>
                </div>
                <div style="padding:4px 10px;">${orders}</div>
            </div>`;
        }).join('');
        let undisp = '';
        if ((ongoing.undispatched_orders || []).length > 0) {
            const list = ongoing.undispatched_orders.map(o => `
                <div style="display:flex; justify-content:space-between; gap:8px; padding:4px 0; border-bottom:1px dashed #fde0e0; font-size:12px;">
                    <span style="color:#7f1d1d;">${o.priority ? `<b>${o.priority}.</b> ` : ''}${o.order_number} — ${o.customer_name}</span>
                    <span style="color:${o.payment_type === 'cash' ? '#166534' : '#1d4ed8'};">Rs. ${Math.round(o.amount).toLocaleString()}</span>
                </div>`).join('');
            undisp = `<div style="margin-top:8px; border:1px solid #fca5a5; border-radius:8px; overflow:hidden;">
                <div style="background:#fef2f2; padding:6px 10px; font-size:12px; font-weight:700; color:#991b1b;">📋 Not dispatched yet · ${ongoing.undispatched_orders.length}</div>
                <div style="padding:4px 10px;">${list}</div>
            </div>`;
        }
        liveHtml = `<div style="padding:12px 16px;">
            <div style="display:flex; gap:6px; flex-wrap:wrap; align-items:center; margin-bottom:4px;">
                ${badge(m.label, m.color, m.bg)}${gpsBadge}${dist}${officeEta}${badge(`📦 ${ongoing.ofd_total} out for delivery`, '#374151', '#f3f4f6')}
            </div>
            ${waves || ''}${undisp || ''}
            ${(!waves && !undisp && ongoing.status === 'returning') ? `<div style="font-size:12px; color:#6b7280; margin-top:6px;">✅ All dispatched orders delivered — heading back to office.</div>` : ''}
        </div>`;
    } else {
        liveHtml = `<div style="padding:16px; font-size:13px; color:#6b7280;">No active dispatch right now.</div>`;
    }

    let deliveredHtml = '';
    if (delivered) {
        deliveredHtml = `<div style="padding:10px 16px; border-top:1px solid #f3f4f6; display:flex; gap:6px; flex-wrap:wrap;">
            ${badge(`📦 ${delivered.total_orders} orders`, '#1e40af', '#dbeafe')}
            ${badge(`${delivered.dispatch_compliance_pct}% dispatched`, '#374151', '#f3f4f6')}
            ${delivered.eta_accuracy_pct !== null ? badge(`⏱️ ${delivered.eta_on_time}/${delivered.eta_total} on-time`, '#166534', '#dcfce7') : ''}
            ${badge(`💵 Rs.${Math.round(delivered.cash_total).toLocaleString()}`, '#166534', '#dcfce7')}
            ${badge(`💳 Rs.${Math.round(delivered.online_total).toLocaleString()}`, '#1e40af', '#dbeafe')}
        </div>`;
    }

    return `
        <div style="position:sticky; top:0; background:#fff; display:flex; justify-content:space-between; align-items:center; padding:14px 16px; border-bottom:1px solid #eee; z-index:1;">
            <div style="font-weight:700; font-size:15px; color:#1f2937;">🏍️ ${riderName} — Dispatch Tracker</div>
            <div style="display:flex; align-items:center; gap:8px;">
                <button id="riderMiniMapBtn" onclick="toggleRiderMiniMap()" style="font-size:12px; font-weight:600; color:#2563eb; background:#eff6ff; border:1px solid #bfdbfe; padding:5px 10px; border-radius:6px; cursor:pointer;">🗺️ Map</button>
                <button onclick="closeRiderDispatchPopup()" style="background:none; border:none; font-size:20px; cursor:pointer; color:#6b7280; line-height:1;">✕</button>
            </div>
        </div>
        <div id="riderMiniMapPanel" style="display:none; border-bottom:1px solid #f3f4f6;">
            <div style="display:flex; justify-content:space-between; align-items:center; padding:6px 16px;">
                <div id="riderMiniMapLegend" style="font-size:11px; color:#6b7280;">🔵 Rider · 🔴 Next stop · 🟠 Pending · 🟢 Delivered</div>
                <button onclick="loadRiderMiniMap(window._riderDispatchCtx.riderId, window._riderDispatchCtx.ongoing)" style="font-size:11px; color:#374151; background:#f3f4f6; border:1px solid #e5e7eb; padding:3px 8px; border-radius:5px; cursor:pointer;">↻ Refresh</button>
            </div>
            <div id="riderMiniMap" style="height:320px; width:100%; background:#eef2f7;"></div>
            <div id="riderMiniMapNote" style="padding:6px 16px; font-size:11px; color:#6b7280;"></div>
        </div>
        ${liveHtml}
        ${deliveredHtml}
        ${renderDeliveredDetail(delivered, !!ongoing)}
        <div style="padding:10px 16px; text-align:right; border-top:1px solid #f3f4f6;">
            <a href="/riders-map#day-review" style="font-size:12px; color:#2563eb; text-decoration:none;">Open full Day Review →</a>
        </div>
    `;
}

/* ============ Dispatch Tracker popup: delivered-detail + mini-map ============ */

// Leaflet map instance for the popup's mini-map (torn down on close / re-open).
let _riderMiniMapInstance = null;

// Local YYYY-MM-DD (device timezone), unlike toISOString() which is UTC.
function localTodayStr() {
    const d = new Date();
    const p = n => String(n).padStart(2, '0');
    return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}

// Collapsible "Delivered today" section showing, per order: delivery time, whether
// it was on time vs the dispatched ETA, and whether it was delivered at the
// customer's verified location (with distance). All fields already come back from
// the dispatch-report endpoint — this is presentation only.
function renderDeliveredDetail(delivered, hasOngoing) {
    if (!delivered || !delivered.total_orders) return '';

    const onTime = delivered.eta_total > 0
        ? `${delivered.eta_on_time}/${delivered.eta_total} on time`
        : 'no ETAs set';
    const atVerified = delivered.has_verified_count > 0
        ? `${delivered.delivered_at_verified_count}/${delivered.has_verified_count} at verified location`
        : 'no saved locations';

    // Default collapsed while a dispatch is still live (keeps the live view on top);
    // expanded once the rider is done for the day — that's when you review it.
    const collapsed = !!hasOngoing;
    const caret = collapsed ? '▸' : '▾';
    const bodyDisplay = collapsed ? 'none' : 'block';

    const batches = delivered.dispatch_batches || [];
    let wavesHtml = batches.map((b, i) => {
        const rows = (b.orders || []).map(o => deliveredOrderRow(o)).join('');
        const waveOnTime = b.eta_total > 0 ? ` · ${b.eta_on_time}/${b.eta_total} on time` : '';
        return `<div style="margin-top:8px; border:1px solid #e5e7eb; border-radius:8px; overflow:hidden;">
            <div style="background:#f9fafb; padding:5px 10px; font-size:11px; font-weight:600; color:#374151;">Wave ${i + 1} · dispatched ${b.dispatch_time_display || '—'}${waveOnTime}</div>
            <div style="padding:2px 10px;">${rows}</div>
        </div>`;
    }).join('');

    // Orders delivered that were never dispatched (a compliance gap worth seeing).
    if (delivered.undispatched_group && delivered.undispatched_group.order_count > 0) {
        const rows = (delivered.undispatched_group.orders || []).map(o => deliveredOrderRow(o)).join('');
        wavesHtml += `<div style="margin-top:8px; border:1px solid #fed7aa; border-radius:8px; overflow:hidden;">
            <div style="background:#fff7ed; padding:5px 10px; font-size:11px; font-weight:700; color:#9a3412;">⚠️ Delivered without dispatch · ${delivered.undispatched_group.order_count}</div>
            <div style="padding:2px 10px;">${rows}</div>
        </div>`;
    }

    return `<div style="padding:8px 16px 12px; border-top:1px solid #f3f4f6;">
        <div onclick="toggleDeliveredBody(this)" style="cursor:pointer; display:flex; align-items:center; gap:6px; font-size:13px; font-weight:700; color:#166534;">
            <span class="dt-caret">${caret}</span>
            <span>✅ Delivered today — ${delivered.total_orders} orders · ${onTime} · ${atVerified}</span>
        </div>
        <div class="dt-delivered-body" style="display:${bodyDisplay};">${wavesHtml}</div>
    </div>`;
}

function deliveredOrderRow(o) {
    const seq = o.actual_sequence ? `<b>${o.actual_sequence}.</b> ` : '';
    const name = (o.customer_name || '');
    const time = o.delivered_at_display || '';

    // On-time vs the dispatched ETA.
    let etaChip;
    if (o.eta_comparison) {
        const on = o.eta_comparison.on_time;
        etaChip = `<span style="font-size:10px; font-weight:700; padding:2px 6px; border-radius:5px; background:${on ? '#dcfce7' : '#fee2e2'}; color:${on ? '#166534' : '#991b1b'};">${on ? '✓ ' : '⏰ '}${o.eta_comparison.label}</span>`;
    } else {
        etaChip = `<span style="font-size:10px; padding:2px 6px; border-radius:5px; background:#f3f4f6; color:#6b7280;">no ETA</span>`;
    }

    // Delivered at the customer's verified location?
    let locChip;
    if (o.has_verified_location && o.has_delivery_gps) {
        const d = o.verification_distance_m;
        const dTxt = (d == null) ? '' : (d < 1000 ? `${d}m` : `${(d / 1000).toFixed(1)}km`);
        if (o.delivered_at_verified) {
            locChip = `<span style="font-size:10px; font-weight:700; padding:2px 6px; border-radius:5px; background:#dcfce7; color:#166534;">📍 verified${dTxt ? ` (${dTxt})` : ''}</span>`;
        } else {
            locChip = `<span style="font-size:10px; font-weight:700; padding:2px 6px; border-radius:5px; background:#fee2e2; color:#991b1b;">⚠️ ${dTxt} off</span>`;
        }
    } else if (o.has_verified_location && !o.has_delivery_gps) {
        locChip = `<span style="font-size:10px; padding:2px 6px; border-radius:5px; background:#f3f4f6; color:#6b7280;">no GPS at delivery</span>`;
    } else {
        locChip = `<span style="font-size:10px; padding:2px 6px; border-radius:5px; background:#f3f4f6; color:#6b7280;">no saved location</span>`;
    }

    return `<div style="display:flex; justify-content:space-between; align-items:center; gap:8px; padding:5px 0; border-bottom:1px dashed #f0f0f0; font-size:12px;">
        <div style="color:#374151; min-width:0; flex:1; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${seq}${o.order_number} — ${name}</div>
        <div style="display:flex; align-items:center; gap:5px; white-space:nowrap;">
            <span style="color:#6b7280; font-size:11px;">${time}</span>${etaChip}${locChip}
        </div>
    </div>`;
}

function toggleDeliveredBody(headerEl) {
    const body = headerEl.parentElement.querySelector('.dt-delivered-body');
    const caret = headerEl.querySelector('.dt-caret');
    if (!body) return;
    const hidden = body.style.display === 'none';
    body.style.display = hidden ? 'block' : 'none';
    if (caret) caret.textContent = hidden ? '▾' : '▸';
}

// Lazily load Leaflet (not on the orders page by default) using the SAME version +
// integrity hashes the full riders-map page uses. Resolves once window.L is ready.
function ensureLeafletLoaded() {
    return new Promise((resolve, reject) => {
        if (window.L && window.L.map) return resolve();
        if (!document.getElementById('leaflet-css')) {
            const link = document.createElement('link');
            link.id = 'leaflet-css';
            link.rel = 'stylesheet';
            link.href = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';
            link.integrity = 'sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=';
            link.crossOrigin = '';
            document.head.appendChild(link);
        }
        const existing = document.getElementById('leaflet-js');
        if (existing) {
            const t0 = Date.now();
            const check = setInterval(() => {
                if (window.L && window.L.map) { clearInterval(check); resolve(); }
                else if (Date.now() - t0 > 8000) { clearInterval(check); reject(new Error('map library load timeout')); }
            }, 100);
            return;
        }
        const s = document.createElement('script');
        s.id = 'leaflet-js';
        s.src = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
        s.integrity = 'sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=';
        s.crossOrigin = '';
        s.onload = () => resolve();
        s.onerror = () => reject(new Error('could not load map library'));
        document.body.appendChild(s);
    });
}

async function toggleRiderMiniMap() {
    const panel = document.getElementById('riderMiniMapPanel');
    const btn = document.getElementById('riderMiniMapBtn');
    if (!panel) return;
    const showing = panel.style.display !== 'none';
    if (showing) {
        panel.style.display = 'none';
        if (btn) btn.textContent = '🗺️ Map';
        return;
    }
    panel.style.display = 'block';
    if (btn) btn.textContent = '🗺️ Hide map';
    const ctx = window._riderDispatchCtx || {};
    const note = document.getElementById('riderMiniMapNote');
    if (note) note.textContent = 'Loading map…';
    try {
        await ensureLeafletLoaded();
        await loadRiderMiniMap(ctx.riderId, ctx.ongoing);
    } catch (e) {
        if (note) note.textContent = 'Map unavailable: ' + e.message;
    }
}

// Next stop = the first still-pending order (lowest priority) in the earliest live
// dispatch wave. The ongoing batches only carry orders still out for delivery, so
// the first order of the first batch is the rider's next drop.
function computeNextStopOrderNumber(ongoing) {
    if (!ongoing) return null;
    const batches = ongoing.dispatch_batches || [];
    for (const b of batches) {
        const orders = b.orders || [];
        if (orders.length) return orders[0].order_number;
    }
    return null;
}

async function loadRiderMiniMap(riderId, ongoing) {
    const note = document.getElementById('riderMiniMapNote');
    const mapDiv = document.getElementById('riderMiniMap');
    if (!mapDiv) return;
    try {
        await ensureLeafletLoaded();
    } catch (e) {
        if (note) note.textContent = 'Map unavailable: ' + e.message;
        return;
    }
    if (note) note.textContent = 'Loading…';

    let data;
    try {
        const res = await fetch(`/orders/riders-map/${riderId}`, {
            headers: { 'Accept': 'application/json', 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').getAttribute('content') }
        });
        data = await res.json();
        if (!data.success) throw new Error(data.message || 'Failed');
    } catch (e) {
        if (note) note.textContent = 'Could not load location data.';
        return;
    }

    if (_riderMiniMapInstance) { try { _riderMiniMapInstance.remove(); } catch (e) {} _riderMiniMapInstance = null; }
    _riderMiniMapInstance = L.map(mapDiv).setView([33.6844, 73.0479], 12);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { attribution: '© OpenStreetMap contributors' }).addTo(_riderMiniMapInstance);

    const bounds = [];
    const nextStop = computeNextStopOrderNumber(ongoing);
    let riderLL = null, nextLL = null, pendingWithLoc = 0;

    const rc = data.rider && data.rider.current_location;
    if (rc) {
        riderLL = [rc.latitude, rc.longitude];
        const riderIcon = L.divIcon({
            className: '',
            html: `<div style="width:22px; height:22px; background:#3b82f6; border:3px solid #fff; border-radius:50%; box-shadow:0 2px 8px rgba(59,130,246,0.5);"></div>`,
            iconSize: [22, 22], iconAnchor: [11, 11]
        });
        L.marker(riderLL, { icon: riderIcon }).addTo(_riderMiniMapInstance)
            .bindPopup(`<b>🏍️ ${data.rider.name}</b><br>Last seen: ${rc.age || ''}`);
        bounds.push(riderLL);
    }

    (data.orders || []).forEach(o => {
        if (!o.location) return;
        const delivered = ['delivered', 'completed'].includes(o.status);
        const isNext = nextStop && o.order_number === nextStop;
        if (!delivered) pendingWithLoc++;
        let color = delivered ? '#10b981' : '#f59e0b';
        if (isNext) color = '#ef4444';
        const ll = [o.location.latitude, o.location.longitude];
        const label = isNext ? 'NEXT' : (delivered ? '✓' : '📦');
        const icon = L.divIcon({
            className: '',
            html: `<div style="min-width:26px; height:26px; padding:0 4px; background:${color}; border:2px solid #fff; border-radius:6px; display:flex; align-items:center; justify-content:center; color:#fff; font-size:${isNext ? '9px' : '13px'}; font-weight:700; box-shadow:0 2px 6px rgba(0,0,0,0.25);">${label}</div>`,
            iconSize: [30, 30], iconAnchor: [15, 15]
        });
        const eta = o.estimated_delivery_at_display ? `<br>🕒 ETA ${o.estimated_delivery_at_display}` : '';
        L.marker(ll, { icon }).addTo(_riderMiniMapInstance)
            .bindPopup(`<b>${o.order_number}</b>${isNext ? ' · <span style="color:#ef4444;">NEXT</span>' : ''}<br>${o.customer_name}<br>${o.total || ''}${eta}`);
        bounds.push(ll);
        if (isNext) nextLL = ll;
    });

    // Straight guide-line from the rider to the next stop (no Google routing call).
    if (riderLL && nextLL) {
        L.polyline([riderLL, nextLL], { color: '#ef4444', weight: 2, dashArray: '6,6', opacity: 0.7 }).addTo(_riderMiniMapInstance);
    }

    if (bounds.length >= 2) _riderMiniMapInstance.fitBounds(bounds, { padding: [30, 30], maxZoom: 15 });
    else if (bounds.length === 1) _riderMiniMapInstance.setView(bounds[0], 14);

    // The panel was hidden when the map initialised; recompute tile layout now visible.
    setTimeout(() => { if (_riderMiniMapInstance) _riderMiniMapInstance.invalidateSize(); }, 60);

    if (note) {
        const bits = [];
        if (!rc) bits.push('No live GPS for this rider.');
        if (pendingWithLoc === 0) bits.push('No pending orders with a mapped location.');
        note.textContent = bits.join(' ');
    }
}

/**
 * Format status breakdown for display in rider cards
 */
function formatStatusBreakdown(breakdown) {
    if (!breakdown || Object.keys(breakdown).length === 0) {
        return '';
    }

    const statusNames = {
        'new': 'New',
        'pending': 'Pending',
        'processing': 'Processing',
        'on_hold': 'On Hold',
        'out_for_delivery': 'Out',
        'delivered': 'Delivered'
    };

    const parts = [];
    for (const [status, count] of Object.entries(breakdown)) {
        const name = statusNames[status] || status;
        parts.push(`${name}: ${count}`);
    }

    return parts.join(' • ');
}

/**
 * Filter orders by rider
 */
function filterByRider(riderId) {
    console.log('Filtering by rider:', riderId);
    
    // Use the orders data directly instead of parsing HTML
    if (!window.allOrders || window.allOrders.length === 0) {
        console.warn('No orders data available for filtering');
        return;
    }
    
    let filtered;

        if (riderId === null) {
        // Show unassigned orders only
        filtered = window.allOrders.filter(order => {
            const assignedRider = order.assigned_rider_user_id || order.rider_user_id;
            return !assignedRider || assignedRider === null || assignedRider === undefined;
        });
        console.log(`Filtered ${filtered.length} unassigned orders`);
            } else {
        // Show orders for specific rider
        filtered = window.allOrders.filter(order => {
            const assignedRider = order.assigned_rider_user_id || order.rider_user_id;
            return assignedRider && parseInt(assignedRider) === parseInt(riderId);
        });
        console.log(`Filtered ${filtered.length} orders for rider ID ${riderId}`);
    }
    
    // Update filtered orders and re-render table
    window.filteredOrders = filtered;
    renderOrdersWithFilters(filtered);
    updateResultsCount();
}

/**
 * Helper function to hide all card sections
 */
function hideAllCardSections() {
    const ridersCards = document.getElementById('ridersCards');
    const statusCards = document.getElementById('openOrdersStatusCards');
    if (ridersCards) ridersCards.style.display = 'none';
    if (statusCards) statusCards.style.display = 'none';
    // Automation strips are Open-Orders-only. Hidden UNCONDITIONALLY here (not
    // via nfSyncAutomationBanners) because this runs BEFORE the caller updates
    // window.currentSource/currentTab, so a context-based check would still read
    // the old tab and leave the strip on screen. Coming back to Open Orders
    // re-shows it through updateRiderLiveBoardVisibility().
    const autoBanners = document.getElementById('nfAutomationBanners');
    if (autoBanners) autoBanners.style.display = 'none';
    const board = document.getElementById('riderLiveBoardCol');
    if (board) board.style.display = 'none';
    if (_riderBoardInterval) { clearInterval(_riderBoardInterval); _riderBoardInterval = null; }
}

</script>
